(177, 37, 180, 'Bài 1: Chào hỏi lần đầu gặp khách hàng', 'Buổi kick-off dự án, BrSE lần đầu gặp khách hàng và trao danh thiếp.', 1, 20, 'CURRICULUM', 'LISTENING', 'BA', 0, 'DRAFT'),
(178, 37, 181, 'Bài 2: Nghe điện thoại khi người được tìm vắng mặt', 'Khách hàng gọi tìm PM nhưng PM đang họp, BrSE nhận lời nhắn.', 2, 20, 'CURRICULUM', 'LISTENING', 'BA', 0, 'DRAFT'),
(179, 37, 182, 'Bài 3: Xác nhận điểm chưa rõ trong đặc tả', 'BrSE phát hiện tài liệu đặc tả thiếu thông tin và hỏi lại khách hàng.', 3, 20, 'CURRICULUM', 'LISTENING', 'BA', 0, 'DRAFT'),
(180, 37, 183, 'Bài 4: Báo cáo tiến độ trong họp định kỳ', 'BrSE báo cáo tiến độ tuần, trong đó có một hạng mục đang chậm.', 4, 20, 'CURRICULUM', 'LISTENING', 'BA', 0, 'DRAFT'),
(181, 37, 184, 'Bài 5: Báo chậm bàn giao và xin lỗi', 'Test tích hợp phát sinh nhiều lỗi, BrSE phải báo lùi ngày bàn giao, nêu nguyên nhân và biện pháp.', 5, 20, 'CURRICULUM', 'LISTENING', 'BA', 0, 'DRAFT'),
(182, 37, 185, 'Bài 6: Tiếp nhận báo lỗi từ khách hàng', 'Khách hàng phát hiện lỗi trên môi trường staging, BrSE hỏi bước tái hiện và hẹn thời gian phản hồi.', 6, 20, 'CURRICULUM', 'LISTENING', 'BA', 0, 'DRAFT'),
(183, 37, 186, 'Bài 7: Xử lý yêu cầu thay đổi đặc tả', 'Khách hàng muốn thêm chức năng ngoài phạm vi, BrSE làm rõ yêu cầu và đề nghị ước tính công số.', 7, 20, 'CURRICULUM', 'LISTENING', 'BA', 0, 'DRAFT'),
(184, 37, 187, 'Bài 8: Sắp xếp lịch họp', 'BrSE đề xuất lịch họp review, có tính tới chênh lệch múi giờ Nhật - Việt.', 8, 20, 'CURRICULUM', 'LISTENING', 'BA', 0, 'DRAFT'),
(185, 37, 188, 'Bài 9: Nhờ khách hàng hỗ trợ', 'Sắp tới test tích hợp nhưng khách chưa cấp tài khoản test, BrSE nhờ khách chuẩn bị.', 9, 20, 'CURRICULUM', 'LISTENING', 'BA', 0, 'DRAFT'),
(186, 37, 189, 'Bài 10: Chốt nội dung cuối buổi họp', 'Cuối buổi họp, BrSE nhắc lại các quyết định và hẹn gửi biên bản.', 10, 20, 'CURRICULUM', 'LISTENING', 'BA', 0, 'DRAFT'),
(187, 37, 190, 'Bài 11: Tiếp nhận góp ý code review', 'Trưởng nhóm kỹ thuật phía khách hàng review pull request và góp ý, developer tiếp nhận và hẹn sửa.', 11, 20, 'CURRICULUM', 'LISTENING', 'BA', 0, 'DRAFT'),
(188, 37, 191, 'Bài 12: Báo cáo kết quả kiểm thử', 'Kết thúc đợt test tích hợp, BrSE báo cáo số liệu và kế hoạch xử lý các case không đạt.', 12, 20, 'CURRICULUM', 'LISTENING', 'BA', 0, 'DRAFT'),
(189, 37, 192, 'Bài 13: Báo cáo sơ bộ sự cố production', 'Production gặp sự cố sau đợt release buổi sáng, BrSE gọi báo khách ngay và xin phê duyệt rollback.', 13, 20, 'CURRICULUM', 'LISTENING', 'BA', 0, 'DRAFT'),
