INSERT INTO grammar_point (id, lesson_id, tag_id, pattern, meaning, example, note, order_index) VALUES
(1, 1, NULL, 'N1 は N2 です', 'N1 là N2\nCâu khẳng định cơ bản. N1 là thứ đang nói tới, N2 là điều muốn nói về nó.', 'わたしは グエンです。\nTôi là Nguyễn.', 'Chữ は ở vị trí này đọc thành wa, không đọc ha. です đứng cuối làm câu thành lịch sự.', 1),
(2, 1, NULL, 'N1 は N2 じゃ ありません', 'N1 không phải là N2\nPhủ định của mẫu trên. Nói thường ngày dùng じゃ, viết trang trọng dùng では.', 'わたしの かいしゃは とうきょうです。\nCông ty của tôi ở Tokyo.', 'Người mới hay quên じゃ. Nói nhanh tới đâu vẫn phải đủ じゃ ありません.', 2),
(3, 1, NULL, 'N1 は N2 ですか', 'N1 có phải là N2 không\nMuốn hỏi thì giữ nguyên câu khẳng định rồi thêm か vào cuối, không đảo trật tự như tiếng Anh.', 'ちちは かいしゃいんです。\nBố tôi là nhân viên công ty.', 'Trả lời ngắn: はい、そうです。 hoặc いいえ、ちがいます。', 3),
(4, 1, NULL, 'N1 も N2 です', 'N1 cũng là N2\nĐiều vừa nói về người này cũng đúng với người kia thì thay は bằng も.', 'あのひとは せんせいじゃ ありません。\nNgười kia không phải giáo viên.', 'Đã có も thì bỏ は, không dùng cả hai cùng lúc.', 4),
(5, 1, NULL, 'N1 の N2', 'N2 của N1, N2 thuộc về N1\nNối hai danh từ. Danh từ đứng sau mới là cái đang nói tới, danh từ trước bổ nghĩa cho nó.', 'おなまえは。\nBạn tên là gì?', 'にほんごの せんせい là giáo viên, không phải tiếng Nhật. Người Việt hay hiểu ngược thứ tự này.', 5),
(6, 1, NULL, 'Tên người + さん', 'Cách gọi người khác\nGắn さん sau tên người khác, cả nam lẫn nữ, cả họ lẫn tên đều được.', 'あねは ぎんこういんです。\nChị tôi là nhân viên ngân hàng.', 'Không bao giờ gắn さん sau tên mình. Nói về mình thì dùng わたし.', 6),
(7, 1, NULL, 'N は なんさい ですか', 'Hỏi tuổi\nHỏi tuổi trẻ con hoặc người thân quen. Lịch sự hơn thì hỏi おいくつですか.', 'あのひとは だれですか。\nNgười kia là ai vậy?', 'Hỏi tuổi người lạ, nhất là phụ nữ, bị coi là bất lịch sự.', 7),
(8, 1, NULL, 'はじめまして … どうぞ よろしく', 'Khung câu chào lần đầu\nMở đầu bằng はじめまして, xưng tên và vài thông tin, kết bằng どうぞ よろしく.', 'キムさんも かんこくじんです。\nAnh Kim cũng là người Hàn Quốc.', 'Đây là khung cố định của màn tự giới thiệu, thiếu câu kết là nghe cụt.', 8),
(9, 2, NULL, 'これ／それ／あれ は N です', 'Chỉ một đồ vật và gọi tên nó\nChọn これ khi đồ ở gần mình, それ khi ở gần người nghe, あれ khi ở xa cả hai.', 'これは ほん です。\nCái này là sách.', 'Ba từ này đứng một mình, không gắn thêm tên đồ vật ngay phía sau.', 1),
(10, 2, NULL, 'N1 は N2 じゃ ありません', 'Nói không phải\nPhủ nhận điều người kia vừa đoán, rồi thường nói tiếp thứ đúng.', 'あ、ちょっと。これは わたしの じゃ ありません。\nÀ khoan. Cái này không phải của tôi.', 'Lối nói lịch sự hằng ngày. Trong văn viết trang trọng dùng では ありません.', 2),
(11, 2, NULL, 'N1 は N2 ですか', 'Hỏi có phải không\nThêm か ở cuối câu là thành câu hỏi, không đảo trật tự gì cả.', 'それは ノート ですか。\nCái đó có phải là vở không?', 'Cuối câu lên giọng nhẹ. Trả lời gọn: はい、そうです hoặc いいえ、ちがいます.', 3),
(12, 2, NULL, 'N は なん／どれ ですか', 'Hỏi cái gì, cái nào\nHỏi để người ta gọi tên đồ vật hoặc chỉ ra đúng cái mình cần: それは なんですか.', 'グエンさんの かばんは どれですか。\nCặp của anh Nguyễn là cái nào?', 'Khác mẫu hỏi có/không: câu này KHÔNG đáp はい／いいえ được, phải trả lời bằng tên đồ vật hoặc chỉ vào cái nào.', 4),
(13, 2, NULL, 'N1 の N2', 'Của ai, thuộc về đâu\nの nối hai danh từ: người hoặc nơi đứng trước, đồ vật đứng sau.', 'これは にほんご の ほん です。\nCái này là sách tiếng Nhật.', 'Khi đã rõ đang nói đồ gì thì bỏ luôn đồ vật: わたしのです (của tôi).', 5),
(14, 2, NULL, 'この／その／あの N は …', 'Gọi tên đồ vật kèm chỉ trỏ\nKhác với これ, ba từ này phải có tên đồ vật đi ngay sau.', 'この ほんは わたし の です。\nCuốn sách này là của tôi.', 'Nhớ cặp: これ đứng một mình, この phải kèm đồ vật.', 6),
(15, 2, NULL, 'N は だれ の N ですか', 'Hỏi của ai\nDùng khi nhặt được đồ hoặc thấy đồ lạ, muốn tìm chủ.', 'この じしょは だれ の じしょ ですか。\nCuốn từ điển này là từ điển của ai?', 'Đáp lại chỉ cần nói tên người kèm の: リンさんのです.', 7),
(16, 3, NULL, 'ここ／そこ／あそこ は N です', 'Chỉ một chỗ và gọi tên chỗ đó\nChọn ここ khi đứng ngay chỗ đó, そこ khi chỗ gần người nghe, あそこ khi xa cả hai người.', 'ここは じむしょです。\nChỗ này là văn phòng.', 'Ba từ này tự nó đã là chỗ rồi, không gắn thêm tên nơi ngay phía sau.', 1),
(17, 3, NULL, 'N は どこ ですか ／ どちら ですか', 'Hỏi một nơi ở đâu\nCách hỏi đường quen nhất: nói tên nơi cần tìm trước, どこですか theo sau.', 'トイレは どこですか。\nNhà vệ sinh ở đâu ạ?', 'Hỏi người lạ hoặc khách thì đổi どこ thành どちら cho lịch sự.', 2),
(18, 3, NULL, 'N は いくら ですか', 'Hỏi giá một món đồ\nĐáp lại bằng số tiền kèm えん: ろっぴゃくえんです。', 'この さいふは いくらですか。\nCái ví này bao nhiêu tiền ạ?', 'Hỏi giá món đang cầm hoặc đang chỉ thì thêm この／その／あの phía trước.', 3),
(19, 3, NULL, 'N1 の N2', 'Của nước nào, của hãng nào\nNước hoặc hãng đứng trước, món đồ đứng sau — にほんの くるま là xe của Nhật.', 'ドイツの くるまは たかいです。\nXe ô tô của Đức thì đắt.', 'Đây vẫn là の của bài trước, chỉ đổi thứ đứng trước từ người sang nơi.', 4),
(20, 3, NULL, 'この／その／あの N は …', 'Chỉ trỏ kèm gọi tên món đồ hay nơi chốn\nKhác với ここ／そこ／あそこ ở chỗ ba từ này phải có danh từ đi kèm ngay sau.', 'この さいふは ごせんえんですか。\nCái ví này 5000 yên phải không ạ?', 'Nói この みせ chứ không nói ここ みせ.', 5),
(21, 3, NULL, 'こちら／そちら／あちら は N です', 'Nói chỗ theo lối lịch sự\nDùng khi tiếp khách, nói với người trên, hoặc khi mình là người của cửa hàng.', 'そちらは かいぎしつです。\nPhía đó là phòng họp.', 'Cùng nghĩa với ここ／そこ／あそこ nhưng nghe trang trọng hơn hẳn.', 6),
(22, 4, NULL, 'N は ～じ ～ふん です', 'Nói giờ\nGiờ đứng trước, phút đứng sau, đọc liền một mạch: しちじ じゅっぷん.', 'いまは くじ です。\nBây giờ là 9 giờ.', 'Rưỡi thì nói はん thay cho さんじゅっぷん, nghe tự nhiên hơn.', 1),
(23, 4, NULL, 'N は なんじ ですか ／ なんようび ですか', 'Hỏi mấy giờ\nHỏi giờ của một việc: cuộc họp, buổi học, giờ nghỉ trưa.', 'ひるやすみは なんじ ですか。\nGiờ nghỉ trưa là mấy giờ?', 'Hỏi khoảng thời gian thì thêm から／まで: なんじから なんじまでですか.', 2),
(24, 4, NULL, '～ます／～ますか', 'Nói việc mình làm và hỏi lại người khác\nĐuôi ます dùng cho việc thường ngày và việc sắp làm.', 'まいにち べんきょうしますか。\nHằng ngày bạn có học bài không?', 'Hỏi thì thêm か vào cuối, giọng hơi lên ở chữ cuối.', 3),
(25, 4, NULL, '～ません／～ませんでした', 'Nói không làm\nBỏ ます thay bằng ません; chuyện đã qua thì ませんでした.', 'きのう はたらきませんでした。\nHôm qua tôi đã không làm việc.', 'Việc đã làm rồi dùng ました, đừng lẫn với ません.', 4),
(26, 4, NULL, 'N の N (giờ của việc)', 'Gắn giờ giấc với việc\nきんようびの よる là tối thứ sáu, ごごの かいぎ là cuộc họp buổi chiều.', 'あさの じゅぎょうは くじからです。\nTiết học buổi sáng bắt đầu từ 9 giờ.', 'Thứ tự là cái lớn trước cái nhỏ sau: thứ rồi mới tới buổi.', 5),
(27, 4, NULL, 'N は ～から ～まで です', 'Nói từ mấy giờ đến mấy giờ\nから là mốc mở đầu, まで là mốc kết thúc, hai cái hay đi cùng nhau.', 'しごとは くじから ごじまで です。\nCông việc từ 9 giờ đến 5 giờ.', 'Chỉ có mốc mở thì bỏ まで: みせは じゅうじからです.', 6),
(28, 5, NULL, 'N へ いきます／きます／かえります', 'Nói đi đâu, đến đâu, về đâu\nNơi đến đứng trước, へ nối vào rồi mới tới động từ.', 'としょかんへ いきます。\nTôi đi đến thư viện.', 'Chữ へ ở đây đọc là え, không đọc là へ.', 1),
(29, 5, NULL, 'どこへ いきますか ／ いつ いきますか', 'Hỏi đi đâu\nHỏi nơi đến thì đổi chỗ nơi đến thành どこ, phần còn lại giữ nguyên.', 'こんしゅう どこへ いきますか。\nTuần này bạn đi đâu?', 'Không biết đi đâu thì đáp どこも いきません — không đi đâu cả.', 2),
(30, 5, NULL, 'N で いきます', 'Nói đi bằng phương tiện gì\nPhương tiện đứng trước で: でんしゃで、バスで、じてんしゃで.', 'えきで でんしゃに のります。\nTôi lên tàu ở nhà ga.', 'Đi bộ là ngoại lệ, nói あるいて chứ không nói あしで.', 3),
(31, 5, NULL, '～ません／～ませんでした', 'Nói không đi, chưa đi\nChuyện chưa xảy ra dùng ません, chuyện đã qua mà không làm thì ませんでした.', 'せんしゅう どこも いきませんでした。\nTuần trước tôi đã không đi đâu cả.', 'Đáp lời rủ mà từ chối thì thêm ちょっと cho nhẹ.', 4),
(32, 5, NULL, 'N と いきます', 'Nói đi với ai\nNgười đi cùng đứng trước と; đi một mình thì nói ひとりで, không dùng と.', 'だれと とうきょうへ いきますか。\nBạn đi Tokyo với ai?', 'Hỏi ai đi cùng thì だれと いきますか.', 5),
(33, 5, NULL, '<nơi> から <nơi> まで', 'Nói đi từ đâu đến đâu\nGiống mốc giờ bài trước, nhưng lần này là mốc nơi chốn.', 'えきから くうこうまで バスが でます。\nCó xe buýt chạy từ ga ra sân bay.', 'Hai mốc hay đi cùng câu chỉ phương tiện: うちから えきまで あるいて いきます.', 6),
(34, 6, NULL, 'N を V ます', 'Nói mình làm gì với vật gì\nVật bị tác động đứng trước を, rồi mới tới động từ: ごはんを たべます.', 'ごはんを たべます。\nTôi ăn cơm.', 'Trợ từ を chỉ viết chữ を, nhưng đọc là お.', 1),
(35, 6, NULL, 'なにを V ますか ／ どこで V ますか', 'Hỏi ăn gì, làm ở đâu\nHỏi vật thì thay chỗ vật bằng なに, hỏi chỗ thì thêm どこで.', 'なにを たべますか。\nBạn ăn gì?', 'Chỗ diễn ra hành động đi với で, khác với へ chỉ nơi đến của bài trước.', 2),
(36, 6, NULL, 'N で N を V ます', 'Nói làm việc gì ở đâu\nChỗ đứng trước で, vật đứng trước を: しょくどうで ごはんを たべます.', 'しょくどうで ともだちに あいます。\nTôi gặp bạn ở nhà ăn.', 'Thứ tự chỗ rồi mới tới vật nghe tự nhiên hơn ngược lại.', 3),
(37, 6, NULL, '～ません／～ませんでした', 'Nói không làm việc đó\nChuyện thường ngày mà mình không làm thì ません.', 'ざんねんですが、きょうは たべません。\nTiếc quá, hôm nay tôi không ăn được.', 'Đừng lẫn ません (không làm) với ませんか (rủ rê).', 4),
(38, 6, NULL, 'いっしょに ～ませんか', 'Rủ người khác cùng làm\nNghe như câu phủ định nhưng thật ra là lời mời, giọng nhẹ và lịch sự.', 'いっしょに ラーメンを たべませんか。\nCùng ăn mì ramen nhé?', 'Nhận lời thì đáp ええ、いいですね; từ chối thì mở đầu bằng ざんねんですが.', 5),
(39, 6, NULL, 'V ましょう', 'Chốt lại: cùng làm thôi\nDùng khi cả hai đã đồng ý, chốt việc sẽ làm.', 'いっしょに ごはんを たべましょう。\nCùng ăn cơm thôi.', 'ませんか là hỏi ý, ましょう là đã thống nhất rồi.', 6),
(40, 7, NULL, 'N1 に N2 を あげます／かします／おしえます／おくります', 'Cho ai, tặng ai cái gì\nNgười nhận đứng trước に, món đồ đứng trước を: ともだちに はなを あげます.', 'ともだちに プレゼントを あげます。\nTôi tặng quà cho bạn.', 'あげます là mình đưa ra. Không dùng あげます cho việc mình đưa cho người trên (thầy cô, sếp).', 1),
(41, 7, NULL, 'N1 に N2 を もらいます／かります／ならいます', 'Nhận của ai cái gì\nCũng dùng に nhưng chiều ngược lại: người cho đứng trước に, còn mình là người nhận.', 'ともだちに プレゼントを もらいます。\nTôi nhận quà từ bạn.', 'かります (mượn) và ならいます (học của ai) đi cùng kiểu câu này.', 2),
(42, 7, NULL, 'N で V ます', 'Làm bằng cái gì, nói bằng tiếng gì\nDụng cụ hay thứ tiếng dùng để làm việc đó đứng trước で: はしで たべます, にほんごで かきます.', 'ペンで てがみを かきます。\nTôi viết thư bằng bút.', 'Cùng chữ で nhưng khác bài trước: bài trước là nơi diễn ra việc, bài này là thứ mình dùng.', 3),
(43, 7, NULL, 'だれに ～ますか ／ なにを ～ますか', 'Hỏi cho ai, hỏi nhận gì\nHỏi người thì thay chỗ người bằng だれ, hỏi vật thì thay bằng なに, phần còn lại giữ nguyên.', 'なにを つかいますか。\nBạn sử dụng cái gì?', 'Hỏi người nhận là だれに, hỏi người sở hữu là だれの — đừng lẫn hai cái.', 4),
(44, 7, NULL, '～ません／～ませんでした', 'Nói không cho, không nhận\nViệc mình không làm thì đổi đuôi ます thành ません.', 'ともだちに おかねを あげません。\nTôi không cho bạn tiền.', 'Từ chối nhận đồ thì nói cả câu cho rõ, đừng nói trống một chữ ません.', 5),
(45, 7, NULL, 'もう ～ました ／ まだです', 'Đã xong rồi hay vẫn chưa\nXong rồi thì もう + đuôi ました; chưa thì đáp gọn まだです.', 'もう カードを おくりましたか。\nĐã gửi thiệp chưa?', 'Đáp まだです là chưa nhưng sẽ làm. Nói ません là không làm — hai ý khác hẳn nhau.', 6),
(46, 8, NULL, 'N は Aい です', 'Khen chê bằng tính từ đuôi い\nTính từ đuôi い giữ nguyên rồi thêm です: ほんは やすいです.', 'がっこうは おおきいです。\nTrường học thì lớn.', 'Đừng bỏ chữ い đi. Nói やすです là sai.', 1),
(47, 8, NULL, 'N は Aな です', 'Khen chê bằng tính từ đuôi な\nLoại này rụng な khi đứng cuối câu: しずかな → へやは しずかです.', 'へやは きれいです。\nCăn phòng thì sạch đẹp.', 'きれい và ゆうめい tuy kết thúc bằng い nhưng thuộc loại な — học thuộc riêng.', 2),
(48, 8, NULL, 'Aい N ／ Aな N', 'Đặt lời khen ngay trước danh từ\nĐứng trước danh từ thì đuôi い giữ nguyên, còn loại な phải trả lại な: たかい やま · ゆうめいな やま.', 'あたらしい がっこうです。\nLà ngôi trường mới.', 'Đây là chỗ hay quên な nhất, vì khi đứng cuối câu thì lại không có な.', 3),
(49, 8, NULL, 'Aい → ～くないです ／ Aな → ～じゃ ありません', 'Nói không phải như vậy\nĐuôi い đổi thành くない; loại な dùng じゃ ありません như câu danh từ.', 'この ほんは ふるくないです。\nQuyển sách này không cũ.', 'いい là ngoại lệ, chê thì nói よくないです chứ không phải いくないです.', 4),
(50, 8, NULL, 'とても ／ ちょっと ／ あまり ～ない', 'Nói mức độ nhiều ít\nとても là rất, ちょっと／すこし là hơi, あまり là không ... lắm.', 'かんじは とても むずかしいです。\nChữ Hán rất khó.', 'あまり bắt buộc đi với đuôi phủ định ở cuối câu, không đứng một mình được.', 5),
(51, 8, NULL, 'N は どうですか ／ どんな N ですか', 'Hỏi thấy thế nào\nどうですか hỏi cảm nhận chung, どんな hỏi thuộc loại nào, kiểu gì.', 'たかい ホテルは どうですか。\nKhách sạn đắt tiền thì thế nào?', 'どうですか đứng một mình; どんな bắt buộc có danh từ theo sau.', 6),
(52, 9, NULL, 'N が すき／きらいです', 'Nói thích hay không ưa\nThứ mình thích đứng trước が, không phải を: おんがくが すきです.', 'おんがくが すきです。\nTôi thích âm nhạc.', 'Nhấn mạnh thì thêm だい: だいすき (rất thích) · だいきらい (rất ghét).', 1),
(53, 9, NULL, 'N が じょうず／へたです', 'Nói giỏi hay kém việc gì\nCũng đi với が: ギターが じょうずです.', 'スポーツが じょうずです。\nGiỏi thể thao.', 'Người Nhật ít tự khen mình じょうず — nói về mình thì dùng すき hoặc ちょっと できます cho khiêm tốn.', 2),
(54, 9, NULL, 'N が わかります／あります', 'Nói hiểu được, có sẵn\nHai động từ này cũng lấy が chứ không lấy を: かんじが わかります · じかんが あります.', 'にほんごが わかります。\nHiểu tiếng Nhật.', 'あります dùng cho đồ vật và sự việc. Người và con vật thì dùng います.', 3),
(55, 9, NULL, 'N が すきですか ／ N が わかりますか', 'Hỏi thích không, hiểu không\nGiữ nguyên が rồi thêm か ở cuối: スポーツが じょうずですか.', 'えいがが すきですか。\nBạn có thích phim ảnh không?', 'Đáp gọn thì nhắc lại chính thứ được hỏi, đừng đáp trống một chữ はい.', 4),
(56, 9, NULL, '～ですから、～ ／ ～ますから、～', 'Nói lý do rồi mới nói việc\nVế lý do đứng trước, gắn から vào cuối rồi mới tới vế việc làm.', 'じかんが ありますから、りょこうに いきます。\nVì có thời gian nên tôi đi du lịch.', 'から đứng SAU lý do, ngược với tiếng Việt nói "vì" ở đầu câu.', 5),
(57, 9, NULL, 'どうして ～か', 'Hỏi vì sao\nĐặt どうして ở đầu câu hỏi; người trả lời đáp bằng vế có から.', 'どうして べんきょうが きらいですか。\nTại sao bạn ghét việc học?', 'Hỏi どうして nhiều lần nghe gắt — trong công việc thường hỏi nhẹ hơn.', 6),
(58, 9, NULL, 'よく／だいたい／たくさん／すこし', 'Nói mức độ nhiều ít\nMấy từ này đứng trước động từ: よく ききます · すこし わかります.', 'よく かいものを します。\nTôi thường đi mua sắm.', 'ぜんぜん và あまり bắt buộc đi với đuôi phủ định ở cuối câu.', 7),
(59, 9, NULL, '～ません ／ ～じゃ ありません', 'Nói không thích, không có\nĐộng từ đổi đuôi thành ません; tính từ loại な dùng じゃ ありません.', 'じかんが ぜんぜん ありません。\nTôi hoàn toàn không có thời gian.', 'ぜんぜん ～ません là không chút nào, あまり ～ません là không mấy.', 8),
(60, 10, NULL, 'N に N が あります', 'Ở chỗ đó có đồ vật gì\nChỗ đứng trước に, vật đứng trước が: だいどころに れいぞうこが あります.', 'へやに つくえが あります。\nTrong phòng có cái bàn làm việc.', 'Câu này giới thiệu vật mới, nên vật đi với が chứ không phải は.', 1),
(61, 10, NULL, 'N に N が います', 'Ở chỗ đó có ai, có con gì\nNgười và con vật dùng います, đồ vật dùng あります. Cấu trúc giống hệt nhau.', 'ベッドの うえに ねこが います。\nTrên giường có con mèo.', 'Cây cối là vật, nên vẫn dùng あります dù nó sống.', 2),
(62, 10, NULL, 'N は N の うえ／した／なか／まえ／うしろ／となり／ちかく／あいだ に あります', 'Nói rõ thứ đó nằm chỗ nào\nĐã biết vật rồi, muốn chỉ chỗ thì vật đi với は: かばんは いすの したに あります.', 'いすは へやの なかに あります。\nCái ghế nằm ở trong căn phòng.', 'Chữ chỉ chỗ (うえ・した・なか) luôn có の đứng trước nó.', 3),
(63, 10, NULL, 'N は どこに ありますか ／ に なにが ありますか', 'Hỏi ở đâu, hỏi có gì\nHỏi chỗ thì どこに, hỏi vật thì なにが, hỏi người thì だれが.', 'テレビは どこに ありますか。\nCái ti vi để ở đâu?', 'Người ta hỏi どこ thì đáp bằng chỗ, đừng đáp bằng tên đồ vật.', 4),
(64, 10, NULL, '～ありません ／ ～いません', 'Nói không có gì, không có ai\nĐổi đuôi ます thành ません như mọi động từ khác.', 'うちに かぞくは いません。\nỞ nhà không có ai trong gia đình.', 'だれも và なにも bắt buộc đi với đuôi phủ định.', 5),
(65, 11, NULL, 'N を ～つ ください', 'Xin bao nhiêu cái\nSố đếm đứng SAU tên vật, không đứng trước: りんごを ふたつ ください.', 'りんごを ひとつ ください。\nCho tôi một quả táo.', 'Dãy ひとつ・ふたつ・みっつ dùng cho vật chung chung, đếm tới とお (mười) thì hết.', 1),
(66, 11, NULL, 'N を ～まい／～ほん／～さつ／～だい', 'Đếm theo hình dạng của vật\nVật mỏng dùng まい, vật dài dùng ほん, sách vở dùng さつ, máy móc dùng だい.', 'きってを いちまい かいます。\nTôi mua một tấm tem.', 'Số đọc chệch ở vài chỗ: いっぽん・さんぼん・さんばい — nghe quen dần chứ đừng học vẹt.', 2),
(67, 11, NULL, 'N が ～にん います', 'Đếm người\nTừ ba người trở lên là số + にん: さんにん.', 'こどもが よんにん います。\nCó bốn đứa trẻ.', 'Một người và hai người đọc riêng: ひとり · ふたり, không phải いちにん · みにん.', 3),
(68, 11, NULL, 'いっしゅうかんに ～かい', 'Nói mấy lần trong một khoảng\nKhoảng thời gian đứng trước に, rồi mới tới số lần: いっかげつに にかい.', 'いっしゅうかんに いっかい およぎます。\nTôi bơi một lần một tuần.', 'Chữ に ở đây là trong một khoảng, khác với に chỉ giờ giấc.', 4),
(69, 11, NULL, '～だけ', 'Nói chỉ có bấy nhiêu\nだけ đứng ngay sau số lượng: ひとつだけ あります.', 'ケーキが ひとつだけ あります。\nChỉ có một cái bánh ngọt.', 'だけ mang giọng ít ỏi, hơi tiếc. Muốn nói trung tính thì bỏ nó đi.', 5),
(70, 11, NULL, 'いくつ ／ なんまい ／ なんにん ／ なんぼん ／ なんかい ですか', 'Hỏi bao nhiêu\nĐổi số thành なん rồi giữ nguyên đuôi đếm: なんまい · なんにん · なんだい.', 'りんごは いくつ ですか。\nTáo có mấy quả?', 'Hỏi vật chung chung thì dùng いくつ, không cần đuôi đếm.', 6),
(71, 12, NULL, 'N1 は N2 より Aです ／ N1 の ほうが Aです', 'Nói cái này hơn cái kia\nThứ được cho là hơn đứng đầu câu, thứ đem ra so đứng trước より.', 'でんしゃの ほうが タクシーより はやいです。\nTàu điện thì nhanh hơn xe taxi.', 'より đứng SAU thứ bị so — ngược với tiếng Việt nói "hơn" ở giữa.', 1),
(72, 12, NULL, 'N の なかで N が いちばん Aです', 'Nói cái nào nhất trong nhóm\nNhóm đứng trước なかで, thứ đứng nhất đi với が: くだものの なかで りんごが いちばん おいしいです.', 'みせの なかで とうきょうの みせが いちばん しずかです。\nTrong các cửa hàng, cửa hàng ở Tokyo là yên tĩnh nhất.', 'Nhóm là nơi chốn thì bỏ なか, chỉ cần で: クラスで いちばん.', 2),
(73, 12, NULL, 'N1 と N2 と どちらが Aですか ／ どれが いちばん Aですか', 'Hỏi cái nào hơn, cái nào nhất\nHai thứ thì dùng どちら, từ ba thứ trở lên thì どれ (người thì だれ).', 'なつと ふゆと どちらが すきですか。\nMùa hè với mùa đông anh thích mùa nào hơn?', 'Hỏi hai thứ mà dùng どれ là sai — どちら mới đúng cho cặp đôi.', 3),
(74, 12, NULL, 'Aい → ～かったです ／ Aな・N → ～でした', 'Kể chuyện đã qua\nĐuôi い đổi thành かった rồi thêm です; loại な và danh từ thì でした.', 'きのう ハノイは あつかったです。\nHôm qua Hà Nội đã nóng.', 'いい là ngoại lệ: đã tốt thì nói よかったです.', 4),
(75, 12, NULL, '～くなかったです ／ ～じゃ ありませんでした', 'Nói chuyện đã qua mà không phải vậy\nGhép hai bước: trước hết chuyển sang phủ định, rồi mới chuyển sang đã qua.', 'きょねんの なつは あまり あつくなかったです。\nMùa hè năm ngoái đã không nóng lắm.', 'あまり và ぜんぜん vẫn bắt buộc đi với đuôi phủ định như thường.', 5),
(76, 13, NULL, 'N が ほしいです', 'Nói muốn có thứ gì\nThứ mình muốn đi với が: あたらしい くるまが ほしいです.', 'あたらしい くるまが ほしいです。\nTôi muốn có xe ô tô mới.', 'ほしい nói về mình. Nói người khác muốn gì thì phải thêm cách nói khác, chưa học ở bài này.', 1),
(77, 13, NULL, 'V たいです', 'Nói muốn làm việc gì\nBỏ ます rồi thêm たいです: いきます → いきたいです.', 'とうきょうへ いきたいです。\nTôi muốn đi Tokyo.', 'Chỗ を có thể đổi thành が cho tự nhiên hơn: すしが たべたいです.', 2),
(78, 13, NULL, 'N へ N／V ます に いきます', 'Nói đi đâu để làm gì\nViệc định làm đứng trước に: デパートへ かいものに いきます.', 'らいしゅう デパートへ かいものに いきます。\nTuần sau tôi đi trung tâm thương mại để mua sắm.', 'Động từ thì bỏ ます rồi mới thêm に: みます → みに いきます.', 3),
(79, 13, NULL, 'なにが ほしいですか ／ なにを ～たいですか', 'Hỏi muốn gì, muốn làm gì\nHỏi vật thì なにが, hỏi việc thì なにを, hỏi nơi thì どこへ.', 'どこへ かいものに いきたいですか。\nBạn muốn đi đâu để mua sắm?', 'Hỏi thẳng người trên rằng họ muốn gì nghe hơi sỗ — với sếp nên hỏi vòng hơn.', 4),
(80, 13, NULL, '～ほしくないです ／ ～たくないです', 'Nói không muốn\nCả hai đều là đuôi い nên chuyển thành くない như tính từ.', 'いま くるまは ほしくないです。\nBây giờ tôi không muốn có ô tô.', 'Từ chối thẳng bằng たくないです nghe hơi cụt — thêm lý do vào cho nhẹ.', 5),
(81, 14, NULL, 'V て ください', 'Nhờ người khác làm giúp\nĐộng từ chuyển sang đuôi て rồi thêm ください: まちます → まって ください.', 'ペンを かして ください。\nCho tôi mượn cái bút.', 'Đây là câu nhờ lịch sự nhưng vẫn là câu sai bảo — với người trên nên mở đầu bằng すみませんが.', 1),
(82, 14, NULL, 'V て います', 'Nói đang làm dở việc gì\nCũng dùng đuôi て, nhưng thêm います: たべて います là đang ăn.', 'だいどころで たべて います。\nTôi đang ăn trong bếp.', 'Với việc làm lâu dài (nghề nghiệp, chỗ ở) thì nó mang nghĩa hiện đang như vậy chứ không phải đang làm ngay lúc này.', 2),
(83, 14, NULL, 'V ましょうか ／ V ませんか', 'Mời và ngỏ ý giúp\nましょうか là ngỏ ý làm giúp, ませんか là rủ cùng làm.', 'かさを もって いきましょうか。\nĐể tôi mang ô đi nhé?', 'Hai câu này nghe nhẹ hơn ください nhiều — muốn lịch sự thì chọn chúng.', 3),
(84, 14, NULL, 'なにを して いますか ／ どこで ～て いますか', 'Hỏi đang làm gì, ở đâu\nGiữ nguyên đuôi て います rồi thêm か.', 'かいしゃで なにを して いますか。\nỞ công ty anh đang làm gì?', 'Hỏi nghề nghiệp cũng dùng câu này: どんな しごとを して いますか.', 4),
(85, 15, NULL, 'V ても いいです', 'Xin phép và cho phép\nĐuôi て rồi thêm も いいです: すわっても いいですか là tôi ngồi được không.', 'ここに すわっても いいです。\nCó thể ngồi ở đây.', 'Đáp cho phép thì nói はい、いいですよ hoặc どうぞ, đừng đáp trống một chữ はい.', 1),
(86, 15, NULL, 'V ては いけません', 'Nói việc đó không được làm\nCũng từ đuôi て: たばこを すっては いけません.', 'びょういんで たばこを すっては いけません。\nTrong bệnh viện không được hút thuốc.', 'Câu này nặng, thường là nội quy. Từ chối trong đời thường thì nói ちょっと... cho nhẹ.', 2),
(87, 15, NULL, 'V て います (tình trạng)', 'Kể chỗ ở, nghề, chuyện đã thành nếp\nKhác với bài trước: đây không phải đang làm dở, mà là tình trạng đang duy trì — とうきょうに すんで います.', 'とうきょうに すんで います。\nTôi sống ở Tokyo.', 'しって います (biết) là đặc biệt: phủ định phải nói しりません, không nói しって いません.', 3),
(88, 15, NULL, '～ても いいですか ／ ～て いますか', 'Hỏi xin phép, hỏi tình trạng\nXin phép thì thêm か vào sau いいです; hỏi tình trạng thì thêm か sau います.', 'しゃしんを とっても いいですか。\nTôi chụp ảnh được không ạ?', 'Hỏi chuyện riêng (lập gia đình chưa, sống với ai) chỉ nên hỏi khi đã thân.', 4),
(89, 15, NULL, 'まだ ～て いません ／ しりません', 'Nói chưa, nói không có\nChưa làm thì まだ + て いません; không mang theo thì もって いません.', 'まだ けっこんして いません。\nTôi vẫn chưa lập gia đình.', 'まだ mang nghĩa chưa nhưng rồi sẽ, khác hẳn với ません là không làm.', 5),
(90, 16, NULL, 'V てから V', 'Xong việc này rồi mới việc kia\nNhấn mạnh thứ tự trước sau: たべてから くすりを のみます.', 'おきてから、かおを あらいます。\nThức dậy xong rồi rửa mặt.', 'Cả câu chỉ có MỘT chỗ てから; muốn kể ba việc thì dùng cách nối bên dưới.', 1),
(91, 16, NULL, 'V て、V て、V ます', 'Nối nhiều việc theo thứ tự\nCác việc giữa câu để đuôi て, chỉ việc CUỐI mới chia đuôi ます.', 'よんで、やすんで、ねます。\nTôi đọc sách, nghỉ ngơi rồi đi ngủ.', 'Thì của cả câu nằm ở động từ cuối — muốn kể chuyện hôm qua thì chỉ đổi chữ cuối thành ました.', 2),
(92, 16, NULL, 'N を わたって ／ N へ まがって ／ あるいて', 'Chỉ đường bằng chuỗi việc\nChỉ đường thực chất là nối nhiều việc: みちを わたって、まっすぐ いきます.', 'みちを わたって、まっすぐ いきます。\nAnh băng qua đường rồi đi thẳng.', 'Hướng rẽ đi với へ, chỗ băng qua đi với を.', 3),
(93, 16, NULL, 'どうやって ～か ／ なにを してから ～か', 'Hỏi cách làm, hỏi thứ tự\nどうやって hỏi đi bằng cách nào, làm bằng cách nào.', 'どうやって かいぎへ いきますか。\nBạn đi đến cuộc họp bằng cách nào?', 'Đáp どうやって thì kể cả chuỗi việc, đừng đáp mỗi tên phương tiện.', 4),
(94, 17, NULL, 'V なければ なりません', 'Nói việc buộc phải làm\nChuyển động từ sang đuôi ない, bỏ い rồi thêm ければ なりません: のみます → のまなければ なりません.', 'きょう しょるいを ださなければ なりません。\nHôm nay tôi phải nộp giấy tờ.', 'Câu này dài nhưng là một khối — đừng ngắt hơi giữa なければ và なりません.', 1),
(95, 17, NULL, 'V ないで ください', 'Xin người khác đừng làm\nGiữ nguyên đuôi ない rồi thêm で ください: またないで ください.', 'ここで またないで ください。\nĐừng đợi ở đây.', 'Nhẹ hơn ては いけません nhiều — đây là lời xin, không phải nội quy.', 2),
(96, 17, NULL, 'V なくても いいです', 'Nói không làm cũng được\nĐuôi ない bỏ い rồi thêm くても いいです: こない → こなくても いいです.', 'きょう しょるいを ださなくても いいです。\nHôm nay không nộp giấy tờ cũng được.', 'Khác hẳn ないで ください: đây là được phép bỏ qua, không phải bị cấm.', 3),
(97, 17, NULL, '～なければ なりませんか ／ ～は いりますか', 'Hỏi có phải làm không\nThêm か vào cuối; hỏi đồ vật cần hay không thì dùng いりますか.', 'ねつが ありますから びょういんへ いかなければ なりませんか。\nVì bị sốt nên có phải đi bệnh viện không?', 'Đáp không cần thì nói なくても いいです, đừng đáp trống một chữ いいえ.', 4),
(98, 18, NULL, 'V る ことが できます', 'Nói làm được việc gì\nĐộng từ để ở dạng gốc (thể từ điển) rồi thêm ことが できます: およぐ ことが できます.', 'わたしは くるまを うんてんする ことが できます。\nTôi lái được ô tô.', 'Chỗ này KHÔNG dùng đuôi ます — nói およぎます ことが できます là sai.', 1),
(99, 18, NULL, 'V る ことが できません', 'Nói không làm được\nChỉ đổi cuối câu thành できません, phần trước giữ nguyên.', 'かんじを よむ ことが できません。\nTôi không đọc được chữ Hán.', 'Thêm ぜんぜん cho ý hoàn toàn không, thêm あまり cho ý không được mấy.', 2),
(100, 18, NULL, 'しゅみは V る こと です ／ V る ことが すきです', 'Nói sở thích\nBiến một việc thành danh từ bằng chữ こと rồi mới nói thích hay là sở thích.', 'しゅみは えを かく こと です。\nSở thích của tôi là vẽ tranh.', 'Người Nhật hay đáp gọn bằng danh từ (おんがくです) — cả hai cách đều dùng được.', 3),
(101, 18, NULL, 'V る まえに ／ N の まえに', 'Nói trước khi làm gì\nVế trước まえに luôn để dạng gốc, dù cả câu nói chuyện đã qua.', 'ねる まえに、 おんがくを ききます。\nTrước khi ngủ, tôi nghe nhạc.', 'Danh từ thì phải có の: しょくじの まえに, không nói しょくじ まえに.', 4),
(102, 18, NULL, '～ことが できますか ／ しゅみは なんですか', 'Hỏi làm được không, hỏi sở thích\nThêm か vào cuối như mọi câu hỏi khác.', 'あなたは なにが できますか。\nBạn có thể làm được gì?', 'Hỏi người mới quen thì hỏi sở thích dễ bắt chuyện hơn hỏi khả năng.', 5),
(103, 19, NULL, 'V た ことが あります', 'Nói từng làm việc gì rồi\nĐộng từ để ở đuôi た rồi thêm ことが あります: いった ことが あります.', 'ふじさんに のぼった ことが あります。\nTôi từng leo núi Phú Sĩ.', 'Đây là kể trải nghiệm trong đời, khác với いきました là kể một lần cụ thể.', 1),
(104, 19, NULL, 'V た ことが ありません', 'Nói chưa từng làm\nChỉ đổi cuối câu thành ありません.', 'にほんごを ならった ことが ありません。\nTôi chưa từng học tiếng Nhật.', 'Thêm いちども cho ý chưa lần nào, thêm まだ cho ý chưa nhưng sẽ có dịp.', 2),
(105, 19, NULL, 'V たり V たり します', 'Kể vài việc làm không theo thứ tự\nKể vài việc tiêu biểu, ý là còn làm cả thứ khác nữa: よんだり きいたり します.', 'にちようびは よんだり テレビを みたり します。\nChủ nhật khi thì đọc, khi thì xem ti vi.', 'Khác với đuôi て nối câu: đuôi て là làm lần lượt, たり là kể ví dụ vài việc.', 3),
(106, 19, NULL, 'A く なります ／ N に なります', 'Nói cái gì đổi khác đi\nTính từ đuôi い đổi い thành く; tính từ đuôi な và danh từ thì thêm に.', 'はるは あたたかくなります。\nMùa xuân trở nên ấm áp.', 'いい là ngoại lệ: khá lên thì nói よく なります.', 4),
(107, 19, NULL, '～た ことが ありますか ／ なにを したり しますか', 'Hỏi từng làm chưa, hỏi hay làm gì\nThêm か vào cuối như thường.', 'ふじさんに のぼった ことが ありますか。\nAnh từng leo núi Phú Sĩ chưa?', 'Đáp chưa từng thì nên nói thêm một câu (まだです、こんど いきたいです) cho đỡ cụt.', 5),
(108, 20, NULL, 'V る ／ A い ／ N だ', 'Nói thân mật ở hiện tại\nBỏ ます trả động từ về dạng gốc; tính từ đuôi い bỏ です; danh từ và tính từ đuôi な thay です bằng だ.', 'きょうは やすみだ。\nHôm nay là ngày nghỉ.', 'Đây KHÔNG phải là nói trống không cho tiện — nó là một kiểu riêng, chỉ dùng đúng chỗ.', 1),
(109, 20, NULL, 'V た ／ A かった ／ N だった', 'Nói thân mật về chuyện đã qua\nĐộng từ dùng đuôi た; tính từ đuôi い thành かった; danh từ thành だった.', 'きのうは やすみだった。\nHôm qua đã là ngày nghỉ.', 'でした thân mật hoá thành だった, không phải でした trơn bỏ đuôi.', 2),
(110, 20, NULL, 'V ない ／ N じゃ ない', 'Nói thân mật kiểu phủ định\nĐộng từ dùng đuôi ない; danh từ và tính từ đuôi な dùng じゃ ない.', 'きょうは やすみじゃ ない。\nHôm nay không phải ngày nghỉ.', 'ありません thân mật hoá thành ない, không nói あらない.', 3),
(111, 20, NULL, '～？ (lên giọng cuối câu)', 'Hỏi kiểu thân mật\nBỏ luôn chữ か, chỉ lên giọng ở cuối: いく？ · たべた？', 'きょうは どう？\nHôm nay thế nào?', 'Câu danh từ thì bỏ cả だ khi hỏi: あした ひま？ chứ không nói ひまだ？', 4),
(112, 21, NULL, '～と おもいます', 'Nói ý nghĩ của mình\nVế trước と phải để ở lối nói thân mật (bài trước), rồi mới thêm と おもいます.', 'あめが ふると おもいます。\nTôi nghĩ trời sẽ mưa.', 'Danh từ và tính từ đuôi な cần thêm だ trước と: べんりだと おもいます.', 1),
(113, 21, NULL, '～と いいました', 'Thuật lại lời người khác\nCũng để vế trước ở lối thân mật rồi thêm と いいました.', 'たなかさんは あめが ふると いいました。\nAnh Tanaka đã nói rằng trời sẽ mưa.', 'Người nói đứng đầu câu và đi với は: たなかさんは ～と いいました.', 2),
(114, 21, NULL, '～でしょう', 'Đoán chuyện chưa chắc\nDùng khi chưa chắc chắn, hay đi với たぶん hoặc きっと.', 'ごごは あめが ふるでしょう。\nBuổi chiều chắc là trời sẽ mưa.', 'Lên giọng cuối (でしょう？) thì thành câu hỏi ý người nghe, khác hẳn nghĩa đoán.', 3),
(115, 21, NULL, 'そう おもいません ／ しりません', 'Nói không nghĩ vậy, không biết\nPhản đối nhẹ thì nói そう おもいません, không nắm được thì しりません.', 'わたしは そう おもいません。\nTôi thì không nghĩ vậy.', 'Người Nhật ít phản đối thẳng — thường mở đầu bằng そうですね rồi mới nói ý khác.', 4),
(116, 21, NULL, 'どう おもいますか ／ なんと いいましたか', 'Hỏi ý nghĩ, hỏi lời người khác\nHỏi ý kiến thì どう おもいますか, hỏi người ta nói gì thì なんと いいましたか.', 'この プランを どう おもいますか。\nAnh nghĩ thế nào về kế hoạch này?', 'Chỗ này dùng を chứ không dùng は: この プランを どう おもいますか.', 5),
(117, 22, NULL, 'V る ／ V て いる + N', 'Đặt cả một việc trước danh từ để tả\nCụm tả đứng TRƯỚC danh từ, không có の ở giữa: よく いく みせ.', 'こうえんに たって いる おんなのひとは リンさん です。\nNgười phụ nữ đang đứng ở công viên là chị Linh.', 'Trong cụm tả, chủ ngữ đi với が chứ không đi với は: ははが つくった りょうり.', 1),
(118, 22, NULL, 'V た + N', 'Tả bằng việc đã xảy ra\nDùng đuôi た cho việc đã rồi: きのう かった ほん.', 'きのう かった ほんは せんせいの です。\nQuyển sách mua hôm qua là của thầy giáo.', 'Thì của cụm tả độc lập với thì của cả câu — cụm để た mà câu vẫn có thể là hiện tại.', 2),
(119, 22, NULL, 'V ない + N', 'Tả bằng việc không làm\nDùng đuôi ない: しらない ことば là từ mình không biết.', 'しらない ひとが うちへ きました。\nCó người lạ tới nhà tôi.', 'Đây là cụm tả, không phải câu — đừng thêm です vào giữa.', 3),
(120, 22, NULL, 'どんな N ですか ／ ～は だれですか', 'Hỏi về thứ được tả\nHỏi loại nào thì どんな, hỏi người thì だれ.', 'たなかさんは どんな ひと ですか。\nAnh Tanaka là người thế nào?', 'Đáp どんな nên đáp bằng cả cụm tả, đừng đáp mỗi một tính từ.', 4),
(121, 23, NULL, 'N の とき ／ A い とき ／ V る とき', 'Nói lúc nào thì làm gì\nVế trước とき để ở dạng gốc: ひまな とき · でかける とき.', 'ひまな とき、ほんを よみます。\nLúc rảnh rỗi, tôi đọc sách.', 'Danh từ phải có の: こどもの とき, không nói こども とき.', 1),
(122, 23, NULL, 'V た とき', 'Lúc việc kia đã xong\nDùng đuôi た khi việc trước đã xong rồi mới tới việc sau: えきに ついた とき でんわします.', 'えきに ついた とき、でんわします。\nLúc đã tới ga, tôi sẽ gọi điện.', 'いく とき (trên đường đi) khác ぜんぜn với いった とき (đã tới nơi) — đây là chỗ hay nhầm nhất.', 2),
(123, 23, NULL, 'V る と、～', 'Hễ làm thế này thì thế kia\nDùng cho quy luật luôn đúng: máy móc, đường đi, thời tiết theo mùa.', 'ボタンを おすと、でんきが つきます。\nHễ bấm nút thì đèn sáng.', 'Vế sau KHÔNG được là lời nhờ hay lời rủ — không nói ボタンを おすと、おして ください.', 3),
(124, 23, NULL, 'どうすると ～か ／ いつ ～か', 'Hỏi cách làm, hỏi lúc nào\nHỏi thao tác thì どうすると, hỏi thời điểm thì いつ.', 'スイッチを どうすると、でんきが つきますか。\nThao tác thế nào với công tắc thì đèn sáng?', 'Đáp どうすると nên đáp bằng cả vế と cho rõ, đừng đáp mỗi tên nút.', 4),
(125, 24, NULL, 'N に V て あげます', 'Tôi làm giúp người khác\nNgười được giúp đứng trước に: リンさんに おしえて あげました.', 'リンさんに にもつを はこんで あげました。\nTôi đã khiêng hành lý giúp Linh.', 'Nói thẳng あげます với người trên nghe như kể công — với sếp nên bỏ đi, chỉ nói việc mình làm.', 1),
(126, 24, NULL, 'N が V て くれます', 'Người khác làm cho tôi\nNgười ra tay đứng đầu và đi với が: たなかさんが てつだって くれました.', 'たなかさんが かんじを おしえて くれました。\nAnh Tanaka đã chỉ chữ Hán cho tôi.', 'くれます luôn hướng về phía mình — không dùng cho việc người này làm cho người kia.', 2),
(127, 24, NULL, 'N に V て もらいます', 'Tôi nhờ được người ta làm\nCũng là người ta làm, nhưng nhìn từ phía mình đi nhờ: せんせいに おしえて もらいました.', 'たなかさんに しゃしんを とって もらいました。\nTôi đã nhờ anh Tanaka chụp ảnh giúp.', 'くれます là người ta tự làm; もらいます là mình có nhờ. Cùng một việc, khác cách nhìn.', 3),
(128, 24, NULL, '～て もらえますか ／ だれが ～て くれましたか', 'Nhờ vả và hỏi ai đã giúp\nNhờ lịch sự thì もらえますか, hỏi ai giúp thì だれが ～て くれましたか.', 'しごとを てつだって もらえますか。\nAnh giúp tôi công việc này được không ạ?', 'もらえますか nhẹ hơn ください nhiều — nhờ người chưa thân thì nên dùng.', 4),
(129, 25, NULL, 'V たら ／ A かったら ／ N だったら', 'Nếu như thế thì sẽ thế này\nLấy dạng đuôi た rồi thêm ら: ふった → ふったら · やすかった → やすかったら.', 'あめが ふったら、うちに います。\nNếu trời mưa thì tôi ở nhà.', 'Khác với と ở bài trước: たら dùng cho chuyện cụ thể chưa chắc xảy ra, と dùng cho quy luật luôn đúng.', 1),
(130, 25, NULL, 'V ても ／ A くても ／ N でも', 'Dù thế nào vẫn làm\nTừ đuôi て thêm も: ふって → ふっても; tính từ đuôi い thành くても.', 'あめが ふっても、あそびに いきます。\nDù trời mưa, tôi vẫn đi chơi.', 'Vế sau phải là chuyện đi NGƯỢC với vế trước, không thì nghe kỳ.', 2),
(131, 25, NULL, 'N を かえます ／ ひっこします ／ かえります', 'Nói dự định đổi thay\nViệc lớn trong đời thường đi với mốc thời gian: らいねん けっこんします.', 'らいねん、しごとを かえます。\nSang năm, tôi sẽ đổi công việc.', 'Chuyện chưa chắc thì nên thêm と おもいます cho nhẹ, đừng nói chắc như đinh.', 3),
(132, 25, NULL, '～たら、どう しますか ／ いつ ～か', 'Hỏi nếu thế thì tính sao\nĐặt vế điều kiện trước rồi mới hỏi どう しますか.', 'あめが ふったら、りょこうは どう しますか。\nNếu trời mưa thì chuyến du lịch tính sao?', 'Đáp nên nhắc lại vế điều kiện cho rõ, đừng đáp trống mỗi một việc.', 4),
(133, 26, NULL, '～んですか', 'Hỏi cho ra đầu đuôi\nThấy có chuyện lạ thì hỏi bằng んですか, nghe mềm hơn là hỏi trống không: きのうは どうして やすんだんですか.', 'パスポートが いるんですか。\nCó cần hộ chiếu không ạ?', 'Động từ và tính từ đuôi い nối thẳng thể thường vào ん. Danh từ và tính từ đuôi な phải thêm な: がくせいなんですか.', 1),
(134, 26, NULL, '～んです', 'Nói rõ lý do của mình\nNgười ta hỏi rồi thì đáp bằng んです để nêu hoàn cảnh: ねつが あるんです.', 'きょうは ようじが あるんです。\nHôm nay tôi có việc bận.', 'んです là kể hoàn cảnh, không phải thông báo suông. Nói việc bình thường mà cứ gắn んです thì nghe như lúc nào cũng có uẩn khúc.', 2),
(135, 26, NULL, '～ないんです', 'Nói cái mình không có, không làm được\nGhép thể ない với んです để nói lý do phủ định: じかんが ないんです.', 'きぶんが よくないんです。\nTôi thấy trong người không ổn.', 'Đây là câu giải thích, nên thường đi kèm câu xin lỗi hoặc lời nhờ ở sau.', 3),
(136, 26, NULL, '～たいんです', 'Nói ý muốn của mình\nMuốn làm gì mà cần người khác biết lý do thì dùng たいんです: びょういんへ いきたいんです.', 'びょういんへ いきたいんです。\nTôi muốn đi đến bệnh viện.', 'Chỉ nói ý muốn của chính mình. Hỏi người trên "muốn gì" bằng たいですか là bất lịch sự.', 4),
(137, 26, NULL, '～んですが、～', 'Mở lời rồi mới nhờ\nNêu hoàn cảnh trước bằng んですが, rồi mới nói việc cần nhờ: かさが ないんですが、かして ください.', 'ちょっと てつだって ほしいんですが、いいですか。\nTôi muốn nhờ bạn giúp một tay một chút được không?', 'が ở đây không phải "nhưng", chỉ là câu dạo đầu cho đỡ đường đột. Nói mỗi vế đầu rồi bỏ lửng cũng được, người nghe tự hiểu.', 5),
(138, 26, NULL, '～たら いいですか', 'Hỏi cách làm\nKhông biết làm sao thì hỏi thẳng cách: しょるいは どこに だしたら いいですか.', 'もうしこみしょは どこに だしたら いいですか。\nĐơn đăng ký nộp ở đâu thì được ạ?', 'Hay đi cùng từ để hỏi どこ・いつ・だれに・どう. Bỏ từ để hỏi đi thì câu thành xin phép, nghĩa khác hẳn.', 6),
(139, 27, NULL, 'N が V られます', 'Nói việc mình làm được\nĐổi đuôi động từ sang thể khả năng là nói được việc mình làm nổi: かんじが よめます.', 'かんじが よめます。\nTôi đọc được chữ Hán.', 'Câu khả năng thường thay を bằng が. Nhóm I đổi đuôi い sang え rồi thêm ます, nhóm II bỏ ます thêm られます.', 1),
(140, 27, NULL, 'N が V られません', 'Nói việc mình chưa làm được\nThể khả năng ở dạng phủ định để nói cái mình chưa làm nổi: ピアノは ひけません.', 'にほんごが ききとれません。\nTôi không nghe kịp tiếng Nhật.', 'Đặt まだ ở trước thì thành "vẫn chưa", nghe còn đường tiến; ぜんぜん thì là dứt khoát không.', 2),
(141, 27, NULL, 'N が みえます', 'Cảnh tự lọt vào mắt\nKhông phải mình cố nhìn, mà cảnh tự hiện ra trước mắt: まどから やまが みえます.', 'やまが みえます。\nNhìn thấy núi.', 'Khác みられます (xem được vì có điều kiện, có vé). Cảnh trước mặt thì dùng みえます.', 3),
(142, 27, NULL, 'N が きこえます', 'Tiếng tự lọt vào tai\nTiếng tự vọng tới tai mình, không phải mình cố nghe: となりから こえが きこえます.', 'おとが きこえます。\nNghe thấy tiếng động.', 'Khác きけます (nghe được vì có máy, có đĩa). Tiếng vọng tới thì dùng きこえます.', 4),
(143, 27, NULL, 'N が できます', 'Làm nên, làm xong, có cái mới\nできます nói việc hoàn thành hoặc cái mới xuất hiện: しゅくだいが できました · あたらしい みちが できました.', 'よやくが できました。\nĐã đặt chỗ xong.', 'できます còn nghĩa "làm được" (スポーツが できます). Nhìn câu mà đoán: có mốc thời gian thì thường là nghĩa hoàn thành.', 5),
(144, 27, NULL, 'N は V られますか', 'Hỏi làm được hay không\nHỏi khả năng của người ta bằng thể khả năng: かんじは よめますか.', 'かんじは よめますか。\nChữ Hán anh đọc được không?', 'Hỏi thẳng người trên là hơi đường đột. Với người trên nên hỏi vòng: ～は いかがですか.', 6),
(145, 28, NULL, 'V ながら V', 'Hai việc cùng một lúc\nBỏ ます của động từ thứ nhất rồi thêm ながら: コーヒーを のみながら しんぶんを よみます.', 'コーヒーを のみながら しんぶんを よみます。\nVừa uống cà phê vừa đọc báo.', 'Việc CHÍNH nằm ở vế sau. Nói ngược lại là đổi ý: "vừa đọc báo vừa uống cà phê" thành ra việc chính là uống.', 1),
(146, 28, NULL, 'V て います (nếp quen)', 'Việc làm đều đặn thành nếp\nて います không chỉ là đang làm lúc này, mà còn là việc làm đều: まいばん にっきを かいて います.', 'まいあさ あさごはんを たべて います。\nMỗi sáng tôi đều ăn sáng.', 'Hay đi cùng まいにち・まいばん・ときどき. Bỏ mấy từ đó đi thì câu dễ bị hiểu là đang làm ngay lúc nói.', 2),
(147, 28, NULL, 'V て いません', 'Việc mình không làm đều\nDạng phủ định của nếp quen: うんどうは あまり して いません.', 'うんどうは あまり して いません。\nThể dục thì tôi ít tập lắm.', 'Khác まだ V て いません (chưa làm lần nào). Có あまり hay ぜんぜん ở trước thì là nói nếp, không phải nói chưa.', 3),
(148, 28, NULL, 'N で／に V て います', 'Nghề và nơi mình làm\nNói nghề nghiệp, chỗ ở, chỗ làm bằng て います: ぎんこうで はたらいて います.', 'かれは この みせで はたらいて います。\nAnh ấy đang làm việc ở quán này.', 'はたらきます đi với で (nơi diễn ra việc), つとめます đi với に (nơi mình thuộc về). Đổi trợ từ là sai.', 4),
(149, 28, NULL, '～し、～し、～', 'Kể ra nhiều điều một lúc\nNối nhiều lý do hoặc nhiều điểm tốt: この みせは やすいし、ちかいし、よく きます.', 'しゅうまつは やすみだし、じかんも あるし、そうじします。\nCuối tuần được nghỉ, lại có thời gian, nên tôi dọn dẹp.', 'Danh từ và tính từ đuôi な phải thêm だ trước し: しずかだし. Thiếu だ là câu hỏng.', 5),
(150, 28, NULL, 'N は V て いますか', 'Hỏi nếp quen của người ta\nHỏi xem người ta có làm đều việc gì không: にほんごは まいにち べんきょうして いますか.', 'おんがくは まいにち きいて いますか。\nÂm nhạc thì ngày nào bạn cũng nghe à?', 'Trả lời gọn thì nhắc lại đúng thứ được hỏi rồi mới nói có hay không.', 6),
(151, 29, NULL, 'N が V て います (tự động từ)', 'Trạng thái đang thế\nĐộng từ tự thân (あきます・しまります・つきます) ghép て います để tả trạng thái nhìn thấy: まどが あいて います.', 'ドアが あいて います。\nCửa ra vào đang mở.', 'Câu này chỉ tả cảnh trước mắt, không nói ai làm. Muốn nói ai làm thì phải dùng động từ có người tác động.', 1),
(152, 29, NULL, 'N を V ました (động từ có người làm)', 'Việc chính tay mình làm\nCặp còn lại của mỗi động từ, có người ra tay: まどを あけました.', 'まどを あけました。\nTôi đã mở cửa sổ.', 'Nhớ theo cặp: あきます／あけます · しまります／しめます · つきます／つけます · きえます／けします. Vế có を là vế có người làm.', 2),
(153, 29, NULL, 'V て しまいました (lỡ tay)', 'Lỡ tay, lỡ quên mất rồi\nViệc xảy ra ngoài ý muốn, nói ra kèm tiếc nuối: さいふを なくして しまいました.', 'さいふを なくして しまいました。\nTôi lỡ làm mất ví rồi.', 'Cùng một hình thức với nghĩa "làm xong hẳn". Có うっかり hay ざんねん ở gần thì là nghĩa lỡ tay.', 3),
(154, 29, NULL, 'V て しまいました (xong hẳn)', 'Làm xong sạch, không còn dư\nNhấn rằng việc đã làm trọn, không còn sót: しゅくだいは もう やって しまいました.', 'レポートは もう よんで しまいました。\nBản báo cáo thì tôi đã đọc xong rồi.', 'Hay đi cùng もう hoặc ぜんぶ. Không có hai từ đó thì người nghe dễ hiểu sang nghĩa lỡ tay.', 4),
(155, 29, NULL, 'まだ V て いません', 'Việc vẫn chưa làm\nNói việc đến giờ vẫn chưa xong: レポートは まだ かいて いません.', 'レポートは まだ かいて いません。\nBản báo cáo tôi vẫn chưa viết.', 'Đáp cho câu hỏi もう ～ましたか. Trả lời いいえ、まだです cũng được, đủ lịch sự.', 5),
(156, 29, NULL, 'N は V て いますか', 'Hỏi xem đang thế nào\nHỏi trạng thái của đồ vật hoặc nơi chốn: まどは あいて いますか.', 'まどは あいて いますか。\nCửa sổ có đang mở không?', 'Trả lời thì nhắc lại đúng thứ được hỏi, rồi mới nói đang mở hay đang đóng.', 6),
(157, 30, NULL, 'N が V て あります', 'Ai đó đã bày sẵn từ trước\nCó người làm rồi để đấy, giờ mình thấy kết quả: つくえに メモが おいて あります.', 'つくえに おちゃが おいて あります。\nCó trà đã được đặt sẵn trên bàn làm việc.', 'Khác với て います tả trạng thái tự nhiên. て あります luôn ngụ ý có người cố ý làm, dù không nói ra là ai.', 1),
(158, 30, NULL, 'V て おきます', 'Làm trước cho xong việc sau\nLàm sẵn từ giờ để sau đỡ vất: かいぎの まえに しりょうを よんで おきます.', 'パーティーの まえに のみものを かって おきます。\nTrước buổi tiệc tôi mua sẵn đồ uống.', 'Hay đi cùng まえに hoặc ～までに. Đây là việc mình chủ động làm, khác hẳn て あります (tả cái đã có sẵn).', 2),
(159, 30, NULL, 'V て おきます (để nguyên)', 'Cứ để nguyên như thế\nKhông đụng vào, giữ nguyên trạng vì lát nữa còn dùng: まどは あけて おきます.', 'あとで つかいますから、そのままに して おきます。\nLát nữa còn dùng đến nên tôi cứ để nguyên như thế.', 'Cùng hình thức với "làm trước". Có そのまま hoặc lý do "còn dùng" ở gần thì là nghĩa giữ nguyên.', 3),
(160, 30, NULL, 'まだ V て いません', 'Việc vẫn chưa làm\nĐáp thẳng khi được hỏi đã chuẩn bị chưa: よやくは まだ して いません.', 'かいぎの じゅんびは まだです。\nViệc chuẩn bị cuộc họp vẫn chưa xong.', 'Đừng đáp いいえ trơn, người Nhật nghe cụt. Nói まだです rồi thêm bao giờ làm là vừa đủ.', 4),
(161, 30, NULL, 'N は V て ありますか', 'Hỏi đã bày sẵn chưa\nHỏi xem thứ cần đã được chuẩn bị chưa: しりょうは じゅんびして ありますか.', 'しりょうは じゅんびして ありますか。\nTài liệu đã chuẩn bị sẵn chưa?', 'Hỏi về kết quả nhìn thấy được. Muốn hỏi ai làm thì đổi sang だれが ～ましたか.', 5),
(162, 30, NULL, 'N を V ました', 'Nói rõ ai làm việc đó\nKhi cần chỉ đích danh người làm thì bỏ て あります đi: いすは ぶちょうが ならべました.', 'かいぎの しりょうを じゅんびしました。\nĐã chuẩn bị tài liệu cuộc họp.', 'Câu có を là câu có người làm. Trộn を với て あります là sai.', 6),
(163, 31, NULL, 'V よう と おもいます', 'Định sẽ làm (vừa nghĩ ra)\nNói ý định của mình, thường là mới nghĩ tới: らいげつから およぎを ならおうと おもいます.', 'そつぎょうしたら、にほんで はたらこうと おもいます。\nTốt nghiệp xong tôi định làm ở Nhật.', 'Nhóm I đổi đuôi う sang お rồi thêm う; nhóm II bỏ ます thêm よう. Chỉ nói ý của chính mình, không nói hộ người khác.', 1),
(164, 31, NULL, 'V る つもりです', 'Có ý định, đã nghĩ kỹ\nÝ đã cân nhắc từ trước, chắc hơn ようと おもいます: ふゆやすみは くにへ かえる つもりです.', 'ふゆやすみは くにへ かえる つもりです。\nNghỉ đông tôi định về nước.', 'Dùng thể từ điển trước つもり. Nói về người trên (sếp, thầy) bằng つもり là hơi suồng sã.', 2),
(165, 31, NULL, 'V ない つもりです', 'Định không làm\nPhủ định nằm ở động từ, không phải ở つもり: たかいので、かわない つもりです.', 'たかいので、かわない つもりです。\nĐắt quá nên tôi định không mua.', 'Khác つもりは ありません (dứt khoát không có ý đó). ない つもり là đã cân nhắc rồi quyết không làm.', 3),
(166, 31, NULL, 'N の よていです', 'Theo lịch đã định\nViệc đã có lịch, không phải ý riêng: しゅっぱつは あさ ８じの よていです.', 'ひっこしは らいげつの よていです。\nViệc chuyển nhà theo kế hoạch là tháng sau.', 'よてい là lịch bên ngoài đặt ra; つもり là ý trong bụng mình. Lịch công ty thì dùng よてい.', 4),
(167, 31, NULL, 'V よう (nói thân mật)', 'Rủ nhau, tự nhủ\nThể ý chí đứng một mình là lời rủ thân mật hoặc lời tự nhủ: おそいから、そろそろ かえろう.', 'つぎの えきまで あるいて いこう。\nĐi bộ tới ga sau thôi.', 'Chỉ dùng với bạn bè, người nhà. Với người trên phải nói ～ましょう.', 5),
(168, 31, NULL, 'N は V る つもりですか', 'Hỏi dự định của người ta\nHỏi xem người ta tính thế nào: なつやすみは なにを する つもりですか.', 'なつやすみは りょこうする つもりですか。\nKỳ nghỉ hè bạn có định đi du lịch không?', 'Hỏi người trên thì nên đổi sang ～の よていですか cho nhẹ, つもり nghe như đang truy.', 6),
(169, 32, NULL, 'V た ほうが いいです', 'Khuyên nên làm\nKhuyên người ta làm một việc cho tốt hơn: きょうは やすんだ ほうが いいです.', 'ねつが ある ときは やすんだ ほうが いいです。\nKhi bị sốt thì nên nghỉ ngơi.', 'Dùng thể た, không dùng thể từ điển. Nói với người trên thì thêm よろしいかと おもいます cho nhẹ.', 1),
(170, 32, NULL, 'V ない ほうが いいです', 'Khuyên không nên làm\nCan người ta đừng làm: たいふうの ひは でない ほうが いいです.', 'つかれた ときは むりを しない ほうが いいです。\nKhi mệt thì không nên gắng sức.', 'Vế phủ định giữ nguyên thể ない (không đổi sang なかった). Đây là lời khuyên, nhẹ hơn ～ては いけません (cấm).', 2),
(171, 32, NULL, '～でしょう', 'Đoán chừng có căn cứ\nĐoán dựa vào dự báo hay lẽ thường: あしたは ゆきが ふるでしょう.', 'ゆうがたは あめが ふるでしょう。\nChiều tối chắc là mưa sẽ rơi.', 'Danh từ và tính từ đuôi な bỏ です rồi mới thêm でしょう. Lên giọng cuối câu thì thành câu hỏi dò ý.', 3),
(172, 32, NULL, '～かもしれません', 'Có lẽ, biết đâu\nKhả năng thấp hơn でしょう, chỉ là một đường có thể xảy ra: でんしゃは おくれるかもしれません.', 'たいふうで でんしゃが おくれるかもしれません。\nVì bão nên có lẽ tàu điện sẽ trễ.', 'Nối vào thể thường. Danh từ và tính từ đuôi な nối thẳng, không thêm だ.', 4),
(173, 32, NULL, 'N は V た ほうが いいですか', 'Hỏi xem có nên làm không\nHỏi ý người khác trước khi quyết: くすりは のんだ ほうが いいですか.', 'てんきの よほうは みた ほうが いいですか。\nDự báo thời tiết thì có nên xem không?', 'Người ta đáp lại bằng chính mẫu này, nên nghe câu đáp là biết nên hay không nên.', 5),
(174, 32, NULL, '～と おもいます', 'Nói ý nghĩ của mình\nĐưa ý kiến riêng cho nhẹ giọng: いかない ほうが いいと おもいます.', 'たぶん だいじょうぶだと おもいます。\nTôi nghĩ chắc là không sao đâu.', 'Thêm と おもいます làm lời khuyên bớt áp đặt, hợp khi nói với người mới quen.', 6),
(175, 33, NULL, 'V ろ／V え (thể mệnh lệnh)', 'Lời ra lệnh cộc lốc\nBảo người ta làm ngay, cộc và gắt: あぶないから、そこで とまれ.', 'あぶないから そこで とまれ。\nVì nguy hiểm nên hãy dừng lại ở đó.', 'Chỉ gặp ở biển báo, lời hô của huấn luyện viên, người trên nói với người dưới rất thân. Người học KHÔNG dùng khi nói chuyện thường.', 1),
(176, 33, NULL, 'V な (thể cấm)', 'Lời cấm cộc lốc\nCấm làm gì, gắt hơn ～ては いけません: きかいには さわるな.', 'きんえんだから ここで たばこを すうな。\nVì cấm hút thuốc nên đừng hút ở đây.', 'Thêm な vào thể từ điển. Nghe rất nặng, ngoài biển báo thì gần như không dùng.', 2),
(177, 33, NULL, '～と かいて あります', 'Trên biển ghi là…\nThuật lại chữ ghi trên biển, giấy dán: もんに たちいりきんしと かいて あります.', 'はりがみに きんえんと かいて あります。\nTrên tờ giấy dán ghi là cấm hút thuốc.', 'Phần chữ ghi để nguyên trước と, không đổi sang lối lịch sự. Đây là thuật lại, không phải mình ra lệnh.', 3),
(178, 33, NULL, '～と いう いみです', 'Câu đó nghĩa là…\nGiải nghĩa chữ khó cho người chưa hiểu: たちいりきんしは はいるなと いう いみです.', 'この マークは きんえんと いう いみです。\nKý hiệu này có nghĩa là cấm hút thuốc.', 'Hỏi lại bằng ～は どういう いみですか. Đây là cách hỏi nghĩa lịch sự nhất khi thấy biển lạ.', 4),
(179, 33, NULL, 'N が ～と いいました', 'Thuật lại lời người khác\nKể lại lời ai đó dặn, kể cả lời gắt: ぶちょうが おくれるなと いいました.', 'せんせいが はやく しろと いいました。\nThầy giáo đã nói là làm nhanh lên.', 'Giữ nguyên lời gốc trước と. Người nghe hiểu là lời của người kia, không phải mình ra lệnh.', 5),
(180, 33, NULL, 'N は なんと かいて ありますか ／ どういう いみですか', 'Hỏi trên biển ghi gì\nGặp biển lạ thì hỏi thẳng: この かんばんは なんと かいて ありますか.', 'この かんばんは なんと かいて ありますか。\nTấm biển này ghi cái gì vậy?', 'Hỏi nghĩa thì dùng どういう いみですか; hỏi cách đọc thì dùng なんと よみますか. Hai câu khác nhau.', 6),
(181, 34, NULL, 'V る／N の とおりに', 'Làm đúng y như mẫu\nLàm theo đúng cái đã thấy, đã học, đã được chỉ: レシピの とおりに つくりました.', 'せつめいの とおりに します。\nTôi làm đúng như lời hướng dẫn.', 'Sau danh từ phải có の. Việc đã xảy ra thì dùng thể た (みた とおりに), việc đang diễn ra thì thể từ điển.', 1),
(182, 34, NULL, 'N の／V た あとで', 'Sau khi làm xong việc kia\nNói rõ việc nào trước việc nào sau: しょくじの あとで、くすりを のみます.', 'しょくじの あとで、くすりを のみます。\nSau bữa ăn thì uống thuốc.', 'Sau danh từ có の, sau động từ dùng thể た. Khác て から ở chỗ あとで chỉ nói thứ tự, không nhấn quan hệ nhân quả.', 2),
(183, 34, NULL, 'V ないで、～', 'Không làm cái kia mà vẫn làm\nViệc chính vẫn diễn ra dù thiếu cái kia: じしょを つかわないで よみました.', 'さとうを いれないで、つくります。\nKhông cho đường mà vẫn làm.', 'Khác なくて (nêu nguyên nhân). ないで đi với hành động, なくて đi với lý do.', 3),
(184, 34, NULL, 'V ないで、V ます', 'Không làm A mà làm B\nBỏ cách này chọn cách kia: バスに のらないで、あるいて いきました.', 'バスに のらないで、あるいて いきます。\nKhông đi xe buýt mà đi bộ đi.', 'Hai vế đối nhau nên thường có dấu phẩy ở giữa. Người nghe chờ vế sau, đừng bỏ lửng.', 4),
(185, 34, NULL, 'V ないで ください', 'Nhắc người ta đừng làm\nLời nhắc nhẹ nhàng, khác hẳn thể cấm cộc lốc: きかいには さわらないで ください.', 'きかいには さわらないで ください。\nXin đừng chạm vào máy.', 'Đây là lối lịch sự của bài trước (さわるな). Với khách hoặc người trên thì luôn dùng dạng này.', 5),
(186, 34, NULL, 'N は いつ／どう しますか', 'Hỏi thứ tự và cách làm\nHỏi việc nào làm lúc nào, làm ra sao: くすりは いつ のみますか.', 'じゅぎょうの よしゅうは いつ しますか。\nViệc chuẩn bị bài thì khi nào làm ạ?', 'Người ta đáp bằng あとで hoặc とおりに, nghe câu đáp là biết thứ tự.', 6),
(187, 35, NULL, 'V ば、～', 'Hễ làm thế thì sẽ thế\nNêu điều kiện chung, hễ có A là có B: はやく いけば、せきが あります.', 'はやく いけば きっぷが あります。\nHễ đi sớm thì sẽ còn vé.', 'Nhóm I đổi đuôi う sang え rồi thêm ば; nhóm II bỏ る thêm れば. Vế sau không dùng lời rủ hay lời nhờ.', 1),
(188, 35, NULL, 'V なければ、～', 'Nếu không làm thì\nĐiều kiện ngược, cảnh báo hậu quả: いそがなければ、まにあいません.', 'いそがなければ まにあいません。\nNếu không nhanh lên thì không kịp.', 'Bỏ い của thể ない rồi thêm ければ. Vế sau thường là chuyện không hay, nên nghe như lời nhắc.', 2),
(189, 35, NULL, 'N なら、～', 'Nếu nói tới cái đó thì\nBắt lấy chủ đề người ta vừa nhắc rồi mới góp ý: きょうとなら、はるが いちばん きれいです.', 'きょうとなら はるが いいです。\nNếu là Kyoto thì mùa xuân là hợp nhất.', 'Chỉ dùng khi đối phương vừa nêu chủ đề đó. Nói なら khi chưa ai nhắc tới thì nghe hụt hẫng.', 3),
(190, 35, NULL, 'V ば V るほど', 'Càng thế thì càng thế\nHai vế cùng tăng: れんしゅうすれば するほど はやく なります.', 'れんしゅうすれば するほど じょうずになります。\nCàng rèn luyện thì càng giỏi lên.', 'Lặp lại chính động từ đó: vế đầu thể ば, vế sau thể từ điển. Tính từ đuôi い thì はやければ はやいほど.', 4),
(191, 35, NULL, 'できれば／よければ、～', 'Nếu được thì (nói cho khéo)\nMở lời nhẹ nhàng khi đề nghị hoặc góp ý: よければ、いっしょに いきませんか.', 'できれば いっしょに いきませんか。\nNếu được thì cùng đi với mình nhé?', 'Hai cụm này làm câu đề nghị bớt áp đặt, rất hay dùng nơi làm việc.', 5),
(192, 35, NULL, 'どうすれば／どこなら ～か', 'Hỏi cách và hỏi trường hợp\nHỏi làm sao cho được, hoặc trường hợp nào thì hợp: こうつうひは どうすれば やすく なりますか.', 'とうきょうで ひっこしは どうすれば いいですか。\nChuyển nhà ở Tokyo thì làm thế nào thì tốt?', 'Người ta đáp lại bằng ば hoặc なら, nghe câu đáp là nắm được điều kiện.', 6),
(193, 36, NULL, 'V る／V ない ように、～', 'Làm gì đó để hướng tới điều kia\nVế đầu là điều mong, vế sau là việc mình làm cho được điều đó: おくれない ように、はやめに でます.', 'はやく はしれる ように、 まいにち うんどうして います。\nĐể có thể chạy nhanh, hằng ngày tôi đang vận động.', 'Vế trước ように phải là việc KHÔNG do mình cố ý điều khiển (đọc được, không bị cảm). Việc mình chủ động thì dùng ために (bài sau).', 1),
(194, 36, NULL, 'V るように なりました', 'Trước không được, nay được rồi\nNói sự đổi khác theo thời gian: にほんごが はなせるように なりました.', 'にほんごが はなせるように なりました。\nTiếng Nhật giờ tôi nói được rồi.', 'Hay đi cùng だんだん, すこしずつ, やっと. Dạng phủ định là ～なく なりました.', 2),
(195, 36, NULL, 'V るように して います', 'Việc mình cố giữ đều\nKhông phải đã thành thói quen sẵn, mà là mình đang cố duy trì: やさいを たべるように して います.', 'まいにち がんばって ふくしゅうするように して います。\nNgày nào tôi cũng chịu khó ôn lại bài.', 'Khác て います (nếp đã có sẵn). ように して います nhấn cái sự CỐ, nên hợp khi kể chuyện giữ gìn sức khoẻ.', 3),
(196, 36, NULL, 'V ないように して います', 'Việc mình cố tránh\nMặt trái của việc giữ nếp: よるは コーヒーを のまないように して います.', 'よるは コーヒーを のまないように して います。\nBuổi tối tôi cố không uống cà phê.', 'Giữ nguyên thể ない rồi mới thêm ように. Đây là mình tự đặt ra cho mình, không phải luật cấm.', 4),
(197, 36, NULL, 'まだ V られません', 'Việc vẫn chưa làm được\nĐáp thật khi chưa tới đích: はやおきには まだ なれません.', 'かんじは まだ よめません。\nChữ Hán thì tôi vẫn chưa thể đọc được.', 'Thêm まだ để câu nghe còn đường tiến, khác hẳn できません trơn (nghe như bỏ cuộc).', 5),
(198, 36, NULL, 'N は ～ように なりましたか', 'Hỏi đã làm được chưa\nHỏi xem người ta tiến tới đâu: にほんごは はなせるように なりましたか.', 'うんどうは できるように なりましたか。\nVề việc vận động, bạn đã có thể thực hiện được chưa?', 'Người ta đáp bằng ように なりました hoặc まだ, nghe là biết đã tới đâu.', 6),
(199, 37, NULL, 'N に V られます', 'Chuyện người khác làm tới mình\nNgười làm đứng trước に, mình là người chịu: ぶちょうに よばれました.', 'ぶちょうに よばれました。\nTôi bị trưởng phòng gọi.', 'Nhóm I đổi đuôi う sang あ rồi thêm れます; nhóm II bỏ ます thêm られます. Đừng lẫn với thể khả năng cùng hình thức られます của nhóm II.', 1),
(200, 37, NULL, 'N に N を V られます', 'Chịu phiền vì việc người khác làm\nCái bị đụng tới đứng trước を, mình vẫn là chủ ngữ: でんしゃで あしを ふまれました.', 'こどもに あしを ふまれました。\nTôi bị trẻ con giẫm vào chân.', 'Câu này luôn mang ý khó chịu. Nói あめに ふられました là than trời mưa, không phải kể thời tiết.', 2),
(201, 37, NULL, 'N に ほめられます／えらばれます', 'Được nhận điều hay\nCũng là thể bị động nhưng việc nhận là điều tốt: だいひょうに えらばれました.', 'せんせいに ほめられました。\nTôi được thầy khen.', 'Đây là chỗ hiếm hoi câu bị động nghe vui. Muốn nhấn lòng biết ơn thì dùng ～て いただきました (bài sau).', 3),
(202, 37, NULL, 'N は N に よって V られました', 'Đồ vật do ai làm ra\nNói người làm ra một tác phẩm, công trình: この ほんは わかい さっかに よって かかれました.', 'この はしは むかしの ひとに よって つくられました。\nCây cầu này do người xưa xây nên.', 'Với tác phẩm thì dùng に よって, không dùng に. Không cần nói ai thì bỏ hẳn vế đó.', 4),
(203, 37, NULL, 'N が V られます (chuyện chung)', 'Chuyện chung, không nói ai làm\nDùng cho tin tức, lịch chung, chuyện ai cũng biết: しけんは らいげつ おこなわれます.', 'ふるい たてものが はっけんされました。\nMột toà nhà cổ đã được phát hiện.', 'Đây là lối văn thông báo, hay gặp trên báo và bảng tin. Nói với bạn bè thì nghe hơi trịnh trọng.', 5),
(204, 37, NULL, 'N は いつ／どこで／だれに V られましたか', 'Hỏi chuyện đã xảy tới\nHỏi việc đã xảy ra với người ta hoặc với đồ vật: はしは いつ つくられましたか.', 'レポートは だれに よって かかれましたか。\nBản báo cáo do ai viết ạ?', 'Nghe câu đáp có に thì biết ai làm, không có に thì người ta cố ý không nói.', 6),
(205, 38, NULL, 'V る のが すきです', 'Thích làm việc gì\nThêm の sau động từ để biến việc thành danh từ rồi nói cảm nhận: うたうのが すきです.', 'うたうのが すきです。\nTôi thích hát.', 'Sau の phải là が, không phải を. Ghét thì đổi thành きらいです, không thích thì すきじゃ ありません.', 1),
(206, 38, NULL, 'V る のが とくい／にがてです', 'Việc mình khá hay ngại\nNói sở trường sở đoản: ひとに おしえるのが とくいです.', 'りょうりするのが とくいです。\nTôi khá khoản nấu ăn.', 'とくい／にがて nói về mình cho khiêm tốn; じょうず／へた thường nói về người khác. Khen mình じょうず nghe kiêu.', 2),
(207, 38, NULL, 'V る のは ～です', 'Nhận xét về một việc\nĐưa việc lên làm chủ đề rồi nhận xét: かんじを おぼえるのは むずかしいです.', 'みんなで およぐのは たのしいです。\nCả nhóm cùng đi bơi thì vui.', 'Dùng は (chủ đề), khác với が ở mẫu "thích". Đổi trợ từ là đổi cả trọng tâm câu.', 3),
(208, 38, NULL, 'V る ことです', 'Việc đó là… (nói trịnh trọng)\nこと thay cho の khi nói sở thích, ước mơ, nội dung công việc: ゆめは にほんで はたらく ことです.', 'たいせつな ことは やくそくを まもる ことです。\nĐiều quan trọng là giữ lời hứa.', 'こと nghe trang trọng hơn の. Câu "A は B ことです" hay dùng khi giới thiệu bản thân.', 4),
(209, 38, NULL, 'V る のを わすれました', 'Quên mất phải làm gì\nViệc bị quên đứng trước のを: かぎを かけるのを わすれました.', 'はやく おきるのを わすれました。\nTôi đã quên mất việc phải dậy sớm.', 'Chỗ này bắt buộc là の, không thay bằng こと được. Nhắc người khác thì nói のを わすれないで ください.', 5),
(210, 38, NULL, 'V る のは ～ですか', 'Hỏi cảm nhận về một việc\nHỏi người ta thấy việc đó thế nào: かんじを おぼえるのは たいへんですか.', 'ひとりで およぐのは たのしいですか。\nĐi bơi một mình có vui không?', 'Trả lời thì nhắc lại việc đó rồi mới nói cảm nhận, nghe mới trọn câu.', 6),
(211, 39, NULL, 'V て、～', 'Việc trước là nguyên do việc sau\nVế trước xảy ra rồi kéo theo vế sau: でんしゃが おくれて、ちこくしました.', 'でんしゃが おくれて、ちこくしました。\nTàu điện trễ nên tôi tới muộn.', 'Vế sau KHÔNG được là lời rủ, lời nhờ hay ý định. Muốn nhờ vả thì phải dùng から.', 1),
(212, 39, NULL, 'A くて、～ (cảm xúc)', 'Vì thế nên thấy ngại, thấy buồn\nTính từ đuôi い đổi thành くて rồi nối cảm xúc: ひとが おおくて、つかれました.', 'しごとが おおくて、こまりました。\nCông việc nhiều nên tôi đã gặp khó khăn.', 'Vế sau luôn là chuyện xảy tới với chính mình. Không dùng để sai bảo người khác.', 2),
(213, 39, NULL, 'V て、うれしかったです', 'Vì thế nên thấy vui\nKể việc rồi nói lòng mình: プレゼントを もらって、うれしかったです.', 'パソコンが なおって、うれしかったです。\nVì máy tính đã được sửa xong nên tôi rất vui.', 'Cảm xúc thường để thì quá khứ vì nói về lúc việc đó xảy ra.', 3),
(214, 39, NULL, 'N で、～', 'Vì thiên tai, sự cố mà ra thế\nDanh từ chỉ nguyên do đi với で: たいふうで がっこうが やすみに なりました.', 'じしんで こわれて、こまりました。\nVì động đất nên bị hỏng, tôi gặp rắc rối.', 'で ở đây là nguyên do, khác với で chỉ nơi chốn hay phương tiện. Nhìn danh từ mà đoán nghĩa.', 4),
(215, 39, NULL, 'N は ～ました', 'Kể lại kết cục\nTrả lời gọn khi người ta hỏi việc đó ra sao: パソコンは きのう なおりました.', 'パソコンは ぶじに なおりました。\nMáy tính đã được sửa xong xuôi an toàn.', 'Nhắc lại đúng thứ được hỏi rồi mới nói kết cục, nghe mới trọn.', 5),
(216, 39, NULL, 'N は どう なりましたか', 'Hỏi việc đó ra sao\nHỏi kết cục hoặc nguyên do: しあいは どう なりましたか.', 'しあいは どう なりましたか。\nTrận đấu ra sao rồi ạ?', 'Hỏi nguyên do thì thêm どうして. Người ta đáp bằng て hoặc で, nghe là biết nguyên do.', 6),
(217, 40, NULL, '～か どうか、～', 'Có hay không thì chưa rõ\nNói điều còn hai đường, chưa ngã ngũ: まにあうか どうか、わかりません.', 'せきが あいて いるか どうか、わかりません。\nChỗ còn trống hay không thì tôi không rõ.', 'Nối bằng thể thường. Danh từ và tính từ đuôi な bỏ だ: ひつようか どうか, không nói ひつようだか どうか.', 1),
(218, 40, NULL, '～か、しりません', 'Không biết ai, ở đâu, bao giờ\nĐã có từ để hỏi trong câu thì chỉ cần か, không thêm どうか: だれが くるか、わかりません.', 'いくらか、しりません。\nGiá bao nhiêu tiền thì tôi không biết.', 'Có どこ・だれ・いつ・いくら rồi thì bỏ どうか đi. Thêm vào là câu thừa.', 2),
(219, 40, NULL, 'V て みます', 'Làm thử xem sao\nLàm để biết kết quả ra sao, chưa chắc thành: あたらしい みせに いって みます.', 'せんせいに きいて みます。\nTôi sẽ hỏi thử thầy giáo xem sao.', 'Chỉ dùng cho việc mình chủ động làm. Nói với người trên nên thêm ～て みても いいですか cho lịch sự.', 3),
(220, 40, NULL, 'N で かくにんします／しらべます', 'Đi kiểm cho rõ\nNói mình sẽ tra ở đâu cho ra: ホームページで しらべます.', 'じむしょで かくにんします。\nTôi sẽ kiểm tra lại ở văn phòng.', 'かくにん là xác nhận lại điều đã biết một nửa; しらべる là tra từ đầu. Hai việc khác nhau.', 4),
(221, 40, NULL, 'N は しって います／わかりました', 'Điều này thì đã rõ\nĐáp phần mình nắm được, tách khỏi phần chưa rõ: ばしょは きまりました.', 'ばしょは しって います。\nVề địa điểm thì tôi biết rồi.', 'Trả lời nên tách hai phần: cái biết nói trước, cái chưa biết nói sau, người nghe đỡ hiểu nhầm.', 5),
(222, 40, NULL, 'N は ～か', 'Hỏi cho ra điều chưa rõ\nHỏi thẳng thứ mình cần biết: ばしょは きまりましたか.', 'かいぎは なんじからですか。\nCuộc họp từ mấy giờ ạ?', 'Người ta đáp bằng か どうか thì nghĩa là chính họ cũng chưa chắc, đừng nghe nhầm thành "không".', 6),
(223, 41, NULL, 'N に N を いただきます', 'Xin nhận của người trên\nMình là người nhận, người cho ở bậc trên: ぶちょうに ネクタイを いただきました.', 'ぶちょうに おかしを いただきました。\nTôi đã nhận bánh kẹo từ trưởng phòng.', 'いただきます là lối nói hạ mình của もらいます. Người cho đi với に hoặc から, không đi với が.', 1),
(224, 41, NULL, 'N が N を くださいます', 'Người trên cho mình\nNgười cho làm chủ ngữ, người nhận là mình nên không cần nói ra: せんせいが ざっしを くださいました.', 'せんせいが ざっしを くださいました。\nCô giáo cho tôi quyển tạp chí.', 'くださいます là lối nói kính trọng của くれます. Chỉ dùng khi vật về phía mình, không dùng cho người thứ ba.', 2),
(225, 41, NULL, 'N に N を やります', 'Cho người dưới, cho cây và con vật\nCho em nhỏ, cho vật nuôi, tưới cây thì dùng やります: いぬに えさを やりました.', 'いぬに えさを やりました。\nTôi cho chó ăn rồi.', 'Nói với người lớn tuổi hơn mà dùng やります là bất lịch sự. Nay nhiều người nói あげます cho nhẹ.', 3),
(226, 41, NULL, 'V て いただきます', 'Được người trên làm giúp\nKhông phải nhận vật mà nhận một việc: せんぱいに レポートを てつだって いただきました.', 'せんぱいに レポートを てつだって いただきました。\nTôi đã được tiền bối giúp đỡ làm bản báo cáo.', 'Nhờ lịch sự thì nói ～て いただけませんか, nghe nhã hơn ～て ください nhiều.', 4),
(227, 41, NULL, 'V て くださいます', 'Người trên chịu khó làm cho mình\nNgười làm giúp đứng làm chủ ngữ: せんせいが しゃしんを おくって くださいました.', 'しゃちょうが ていねいに せつめいして くださいました。\nGiám đốc đã giải thích cẩn thận cho tôi.', 'Cùng một việc, nói theo phía mình thì dùng いただきます, nói theo phía người ta thì dùng くださいます.', 5),
(228, 41, NULL, 'N は だれに いただきましたか ／ だれが くださいましたか', 'Hỏi ai cho, ai làm giúp\nHỏi nguồn của món quà hay của việc giúp: この ネクタイは だれに いただきましたか.', 'この ネクタイは だれに いただきましたか。\nCái cà vạt này anh được ai cho vậy?', 'Trả lời phải nhắc lại đúng thứ được hỏi rồi mới nói người cho, nghe mới trọn câu.', 6),
(229, 42, NULL, 'V る ために、～', 'Làm việc này để đạt việc kia\nVế trước là đích nhắm tới, vế sau là việc đang làm: くるまを かう ために、おかねを ためて います.', 'くるまを かう ために、 おかねを ためて います。\nTôi đang dành dụm tiền để mua xe hơi.', 'Hai vế phải cùng một người làm và người ấy chủ động. Việc ngoài ý muốn thì dùng ように, không dùng ために.', 1),
(230, 42, NULL, 'N の ために、～', 'Vì ai đó, vì việc gì đó\nDanh từ đứng trước の ために: かぞくの ために、はたらいて います.', 'かぞくの ために、 はたらいて います。\nTôi đang làm việc vì gia đình.', 'Cùng chữ ために nhưng trước danh từ phải có の. Quên の là câu sai ngay.', 2),
(231, 42, NULL, 'N は V る のに つかいます', 'Cái này dùng vào việc gì\nNói công dụng của đồ vật: はさみは かみを きるのに つかいます.', 'はさみは かみを きるのに つかいます。\nKéo dùng để cắt giấy.', 'Chỗ này là のに, không phải ために. Nói công dụng thì quen dùng のに hơn.', 3),
(232, 42, NULL, 'V る のに べんりです', 'Tiện cho việc gì\nKhen chê một thứ theo việc mình cần: アプリは よやくするのに べんりです.', 'この アプリは さがすのに べんりです。\nỨng dụng này tiện lợi cho việc tìm kiếm.', 'Đổi べんり thành ふべん, いい, たいへん đều được. Trước のに luôn là thể từ điển.', 4),
(233, 42, NULL, 'V る のに N が いります', 'Việc đó cần thứ gì\nNói cái phải có để làm được việc: ひっこしを するのに おかねが いります.', 'くるまを かうのに おかねが いります。\nCần tiền để mua xe hơi.', 'Thứ cần có đi với が, không đi với を. Nói thời gian thì đổi いります thành かかります.', 5),
(234, 42, NULL, 'N は なにに つかいますか ／ なんの ために ～か', 'Hỏi công dụng, hỏi mục đích\nHỏi thứ này dùng làm gì, việc kia làm để làm gì: この きかいは なにに つかいますか.', 'この きかいは なにに つかいますか。\nCái máy này dùng vào việc gì vậy?', 'Hỏi mục đích thì nói なんの ために. Trả lời phải nhắc lại đúng thứ được hỏi.', 6),
(235, 43, NULL, 'A そうです', 'Nhìn mà đoán tính chất\nChưa nếm chưa thử, chỉ nhìn mà đoán: この ケーキは おいしそうです.', 'この ケーキは おいしそうです。\nCái bánh ngọt này trông có vẻ ngon.', 'Tính từ đuôi い bỏ い rồi thêm そう; いい thành よさそう. Đã nếm rồi thì nói thẳng おいしいです, không そう nữa.', 1),
(236, 43, NULL, 'V そうです', 'Trông sắp xảy ra tới nơi\nNhìn dấu hiệu mà biết việc sắp xảy: あめが ふりそうです.', 'あめが ふりそうです。\nTrời trông sắp mưa rồi.', 'Bỏ ます rồi thêm そう. Mẫu này nói việc ngay trước mắt, không nói chuyện tuần sau.', 2),
(237, 43, NULL, 'A なさそうです ／ V そうに ありません', 'Trông có vẻ không phải thế\nĐoán theo hướng phủ định: この みせは たかくなさそうです.', 'この ケーキは たかくなさそうです。\nBánh ngọt này trông có vẻ không đắt.', 'ない thành なさそう, thêm さ chứ không nói なそう. Với động từ thì nói ～そうに ありません.', 3),
(238, 43, NULL, 'V て きます／いきます', 'Đổi dần tới nay, đổi dần về sau\nきます là dần dần tới lúc này, いきます là từ nay về sau: にほんごが わかって きました.', 'にほんごが わかって きました。\nTôi đã dần hiểu ra tiếng Nhật rồi.', 'Hai đuôi này nói hướng thời gian, không nói hướng đi lại. Nhìn mốc hiện tại mà chọn.', 4),
(239, 43, NULL, 'N を もって いきます／きます', 'Mang đi và mang tới\nMang rời khỏi đây thì いきます, mang tới đây thì きます: おべんとうを もって いきます.', 'おべんとうを もって いきます。\nTôi mang cơm hộp đi.', 'Người thì dùng つれて いきます. Nhầm sang もって いきます là bất lịch sự với người.', 5),
(240, 43, NULL, 'N は ～そうですか ／ ～ましたか', 'Hỏi trông thế nào\nHỏi người ta nhìn thấy sao: ボタンは とれそうですか.', 'ケーキは おいしそうですか。\nBánh trông ngon không?', 'Trả lời nhắc lại đúng thứ được hỏi rồi mới nói mình đoán gì.', 6),
(241, 44, NULL, 'V／A すぎます', 'Quá mức, quá tay\nNói việc vượt quá mức vừa phải, thường kèm ý chê: きのう おさけを のみすぎました.', 'きのう おさけを のみすぎました。\nHôm qua tôi uống quá tay.', 'Động từ bỏ ます, tính từ đuôi い bỏ い rồi thêm すぎます. Mẫu này gần như luôn mang ý không tốt.', 1),
(242, 44, NULL, 'V やすいです', 'Dễ làm, dễ dùng\nKhen một thứ vì làm việc gì đó thấy nhẹ tay: この ペンは つかいやすいです.', 'この ペンは つかいやすいです。\nCây bút này dễ sử dụng.', 'Bỏ ます rồi thêm やすい. Cả cụm biến đổi như một tính từ đuôi い: やすかったです, やすくないです.', 2),
(243, 44, NULL, 'V にくいです', 'Khó làm, khó dùng\nChê một thứ vì làm việc gì đó thấy vướng: この かんじは よみにくいです.', 'この アプリは つかいにくいです。\nỨng dụng này khó sử dụng.', 'にくい nói cái khó do bản thân vật, khác với むずかしい nói cái khó của việc.', 3),
(244, 44, NULL, 'V かた', 'Cách làm một việc\nBỏ ます rồi thêm かた thì việc thành danh từ chỉ cách: つかいかたを おしえて ください.', 'この アプリの つかいかたを おしえて ください。\nXin hãy chỉ cho tôi cách dùng ứng dụng này.', 'Sau khi thành danh từ thì tân ngữ đổi を thành の: かんじの かきかた.', 4),
(245, 44, NULL, '～すぎないで ください ／ ～た ほうが いいです', 'Khuyên đừng quá tay\nNhắc nhau giữ chừng mực: おさけを のみすぎないで ください.', 'おさけを のみすぎないで ください。\nAnh đừng uống quá tay nhé.', 'Nói nhẹ hơn thì dùng ～ほうが いいです. Với người trên nên tránh nói thẳng câu cấm.', 5),
(246, 44, NULL, 'N は ～やすいですか ／ ～にくいですか', 'Hỏi dễ hay khó\nHỏi người ta dùng thấy sao: この くつは あるきやすいですか.', 'この ペンは つかいやすいですか。\nCây bút này dùng có dễ không?', 'Trả lời nhắc lại đúng thứ được hỏi rồi mới nói dễ hay khó, nghe mới trọn câu.', 6),
(247, 45, NULL, 'N の ばあいは、～', 'Trường hợp này thì làm thế\nNêu một tình huống rồi nói cách xử: じしんの ばあいは、そとへ でないで ください.', 'じしんの ばあいは、すぐ れんらくして ください。\nTrường hợp có động đất, hãy liên lạc ngay.', 'ばあい nói tình huống giả định chung, dùng nhiều trong bảng hướng dẫn và thông báo.', 1),
(248, 45, NULL, 'V た ばあいは、～', 'Nếu việc ấy xảy ra thì\nViệc đã xảy tới rồi thì xử thế nào: でんしゃが とまった ばあいは、バスを つかいます.', 'でんしゃが とまった ばあいは、すぐ れんらくして ください。\nNếu tàu dừng chạy, hãy liên lạc ngay.', 'Thể た nói việc đã xong, thể từ điển nói việc chưa xảy. Đổi thể là đổi mốc thời gian.', 2),
(249, 45, NULL, 'V ない ばあいは、～', 'Nếu không có, không làm thì\nNêu trường hợp thiếu hoặc không xảy ra: パスポートが ない ばあいは、たいしかんへ いって ください.', 'おかねが たりない ばあいは、カードを つかいますか。\nNếu không đủ tiền, bạn có dùng thẻ không?', 'Với danh từ thì nói N じゃ ない ばあいは. Câu này hay gặp trong hướng dẫn thủ tục.', 3),
(250, 45, NULL, '～のに、～', 'Đã thế rồi mà lại\nVế sau đi ngược điều đáng lẽ phải xảy: きっぷを かったのに、いけませんでした.', 'きっぷを かったのに、でんしゃが とまりました。\nĐã mua vé rồi mà tàu lại dừng chạy.', 'のに luôn kèm chút bực hoặc tiếc. Không dùng để rủ rê hay nhờ vả ở vế sau.', 4),
(251, 45, NULL, '～のに、ざんねんです', 'Tiếc quá, trách nhẹ một câu\nNói ra lòng mình sau chuyện trái ý: やくそくを したのに、こなかったので、がっかりしました.', 'やくそくしたのに、こなかったので、ざんねんです。\nĐã hẹn rồi mà không đến nên tiếc quá.', 'Nói với người trên thì bỏ vế trách, chỉ giữ ざんねんです cho nhã.', 5),
(252, 45, NULL, 'N の ばあいは どう しますか ／ ～は どう なりましたか', 'Hỏi trường hợp ấy xử sao\nHỏi cách xử khi gặp tình huống: じしんの ばあいは どう しますか.', 'じしんの ばあいは どう しますか。\nTrường hợp động đất thì làm thế nào?', 'Trả lời nhắc lại đúng trường hợp được hỏi rồi mới nói cách xử.', 6),
(253, 46, NULL, 'V る ところです', 'Sắp làm tới nơi\nNgay trước lúc bắt tay vào việc: かいぎは これから はじまる ところです.', 'これから かいぎが はじまる ところです。\nCuộc họp sắp sửa bắt đầu từ bây giờ.', 'Thể từ điển đứng trước ところ. Mẫu này chỉ nói mốc sát ngay, không nói chuyện ngày mai.', 1),
(254, 46, NULL, 'V て いる ところです', 'Đang giữa chừng\nViệc đang chạy dở tại thời điểm nói: いま しりょうを つくって いる ところです.', 'いま しりょうを つくって いる ところです。\nTôi đang làm tài liệu dở.', 'Khác với ～て います thường: ところ nhấn vào đúng khoảnh khắc này, nghe gấp hơn.', 2),
(255, 46, NULL, 'V た ところです', 'Vừa xong ngay lúc nãy\nViệc vừa kết thúc trong tích tắc: しごとは いま おわった ところです.', 'いま ごはんを たべた ところです。\nBây giờ tôi vừa mới ăn cơm xong.', 'Mốc này rất sát, thường đi với いま hoặc ちょうど.', 3),
(256, 46, NULL, 'V た ばかりです', 'Mới đây thôi\nNgười nói thấy việc mới xảy, dù có thể đã mấy hôm: にほんへ きた ばかりです.', 'ぶちょうは さっき かえった ばかりです。\nTrưởng phòng mới về lúc nãy thôi.', 'ばかり đo bằng CẢM GIÁC người nói, ところ đo bằng đồng hồ. Đó là chỗ khác nhau.', 4),
(257, 46, NULL, '～はずです', 'Theo lẽ thì chắc là thế\nCó căn cứ nên tin việc đó đúng: にもつは あした とどく はずです.', 'にもつは もう とどく はずです。\nKiện hàng chắc là sắp tới rồi.', 'Khác với かもしれません (chỉ là có thể). はず có căn cứ rõ nên nghe chắc hơn nhiều.', 5),
(258, 46, NULL, 'N は ～ましたか', 'Hỏi việc xong chưa\nHỏi để biết việc đang ở mốc nào: しごとは おわりましたか.', 'しごとは おわりましたか。\nViệc xong chưa anh?', 'Trả lời nhắc lại đúng việc được hỏi rồi mới nói mốc, nghe mới trọn câu.', 6),
(259, 47, NULL, '～そうです (nghe nói)', 'Nghe nói là thế\nNói lại tin mình nghe được, không thêm ý mình: らいしゅう しけんが ある そうです.', 'らいしゅう しけんが ある そうです。\nNghe nói tuần sau có kỳ thi.', 'Trước そうです là thể thường (ふる, ふった). Khác hẳn そうです ở bài trước — bài đó bỏ ます (ふりそう) và là mắt nhìn, bài này là tai nghe.', 1),
(260, 47, NULL, 'N に よると、～そうです', 'Theo nguồn này thì\nNói rõ tin ở đâu ra cho người nghe tin: てんきよほうに よると、あした あめが ふる そうです.', 'てんきよほうに よると、あした あめが ふる そうです。\nTheo dự báo, mai trời mưa.', 'Nêu nguồn thì câu nghe chắc hơn hẳn. Nguồn hay gặp: bản tin, người quen, thông báo.', 2),
(261, 47, NULL, '～ようです', 'Nhìn tình hình thì hình như\nTự mình quan sát rồi đoán: ぶちょうは かぜを ひいた ようです.', 'ぶちょうは つかれて いる ようです。\nHình như trưởng phòng đang mệt.', 'ようです dựa trên cái mình thấy nên nghe có trách nhiệm hơn らしいです.', 3),
(262, 47, NULL, '～らしいです', 'Nghe đồn là thế\nTin nghe loáng thoáng, chưa chắc: あの みせは しまった らしいです.', 'あの みせは しまった らしいです。\nNghe đồn quán đó đóng cửa rồi.', 'らしい để khoảng cách với tin, ý là mình không chịu trách nhiệm. Nói chuyện hệ trọng thì tránh.', 4),
(263, 47, NULL, '～みたいです', 'Trông như là (nói thân mật)\nCùng nghĩa ようです nhưng nói thân mật: そとは さむいみたいです.', 'そとは さむいみたいです。\nNgoài trời trông lạnh.', 'みたい là lối nói thường ngày. Với khách hay cấp trên thì dùng ようです.', 5),
(264, 47, NULL, 'N は どうですか ／ N は ～ですか', 'Hỏi tình hình ra sao\nHỏi để người ta kể lại tin hoặc nói đoán: てんきは どうですか.', 'あしたの てんきは どうですか。\nThời tiết ngày mai thế nào?', 'Trả lời nhắc lại đúng thứ được hỏi rồi mới nói tin, nghe mới trọn câu.', 6),
(265, 48, NULL, 'N に N を V させます', 'Sai người ta làm việc gì\nNgười trên sai người dưới: こどもに へやを かたづけさせます.', 'こどもに せんたくを させます。\nTôi bắt đứa trẻ phải làm việc giặt giũ.', 'Người bị sai đi với に khi câu đã có tân ngữ を. Chỉ dùng với người dưới mình, không dùng với cấp trên.', 1),
(266, 48, NULL, 'N を V させます', 'Cho ai đi, cho ai về\nĐộng từ không có tân ngữ thì người bị sai đi với を: ぶかを しゅっちょうに いかせます.', 'ぶかを しゅっちょうに いかせます。\nCông ty cử cấp dưới đi công tác.', 'Cùng một câu không dùng を hai lần. Đó là lý do có lúc に, có lúc を.', 2),
(267, 48, NULL, 'N に V させて あげます', 'Cho phép ai làm điều họ muốn\nSai khiến theo hướng chiều ý người ta: こどもに すきな ことを させて あげます.', 'こどもに すきな ことを させて あげます。\nTôi cho bọn trẻ làm điều chúng thích.', 'Cùng dạng させます nhưng thêm あげます thì thành cho phép, không còn là ép.', 3),
(268, 48, NULL, 'V させて ください', 'Xin cho tôi được làm\nXin phép làm việc mình muốn: はっぴょうを させて ください.', 'おてつだいを させて ください。\nXin cho tôi được phụ giúp một tay.', 'Câu này nghe chủ động, khác với ～ても いいですか chỉ là hỏi có được không.', 4),
(269, 48, NULL, 'V させて いただけませんか', 'Xin phép cho thật nhã\nLối xin phép lịch sự nhất với cấp trên: きょうは そうたいさせて いただけませんか.', 'そうたいさせて いただけませんか。\nTôi xin phép được về sớm có được không ạ?', 'Càng dài càng nhã. Với cấp trên nên dùng câu này thay cho させて ください.', 5),
(270, 48, NULL, 'N は なにを させますか ／ ～ても いいですか', 'Hỏi sai làm gì, hỏi có cho không\nHỏi người ta giao việc gì cho ai: こどもは なにを させますか.', 'こどもには なにを させますか。\nVới con thì chị sai làm gì ạ?', 'Trả lời nhắc lại đúng người hoặc việc được hỏi rồi mới nói tiếp.', 6),
(271, 49, NULL, 'V (ら)れます', 'Đuôi kính trọng nhẹ nhàng\nDạng giống thể bị động nhưng dùng để kính người trên: しゃちょうは 5じに かえられます.', 'しゃちょうは ごじに かえられます。\nGiám đốc về lúc năm giờ ạ.', 'Mặt chữ trùng thể bị động, phải nhìn ngữ cảnh mà phân. Đây là lối kính nhẹ, dùng hằng ngày ở công ty.', 1),
(272, 49, NULL, 'お V に なります', 'Lối kính trang trọng hơn\nBỏ ます rồi kẹp giữa お và に なります: ぶちょうは しんぶんを およみに なりました.', 'ぶちょうは しんぶんを およみに なります。\nTrưởng phòng đọc báo ạ.', 'Kính hơn dạng れます. Động từ một âm tiết như みます thì không dùng khuôn này.', 2),
(273, 49, NULL, 'いらっしゃいます／めしあがります／ごらんに なります／おっしゃいます', 'Động từ kính có dạng riêng\nMột số động từ có hẳn dạng kính riêng: おきゃくさまが いらっしゃいました.', 'おきゃくさまが いらっしゃいました。\nKhách đã tới rồi ạ.', 'いらっしゃいます thay cho います・いきます・きます. Ba nghĩa một chữ, nhìn câu mà hiểu.', 3),
(274, 49, NULL, 'お V ください', 'Mời làm, nhờ làm cho nhã\nMời khách làm việc gì: こちらに おかけ ください.', 'どうぞ こちらに おかけ ください。\nXin mời ngài ngồi vào phía này ạ.', 'Nhã hơn ～て ください nhiều. Dùng nhiều ở cửa hàng, quầy tiếp nhận, nhà ga.', 4),
(275, 49, NULL, 'N さま／～の かた', 'Cách gọi người cho lịch sự\nGọi khách và người trên bằng さま hoặc かた: あちらの かたは どなたですか.', 'あちらの かたは どなたですか。\nVị bên kia là ai vậy ạ?', 'かた lịch sự hơn ひと, さま lịch sự hơn さん. Gọi sai bậc là mất lịch sự ngay.', 5),
(276, 49, NULL, 'N は ～ますか (kính)', 'Hỏi người trên cho nhã\nHỏi giờ giấc, ý muốn của người trên: しゃちょうは いつ かえられますか.', 'しゃちょうは いつ かえられますか。\nGiám đốc khi nào về ạ?', 'Trả lời nhắc lại đúng người hoặc thứ được hỏi rồi mới nói tiếp.', 6),
(277, 50, NULL, 'お V します', 'Hạ mình khi làm việc cho người trên\nBỏ ます rồi kẹp giữa お và します: にもつを おもちします.', 'わたくしが にもつを おもちします。\nTôi xin phép mang hành lý giúp ạ.', 'Chỉ dùng khi việc mình làm có dính tới người trên. Việc riêng của mình thì nói thường.', 1),
(278, 50, NULL, 'まいります／いたします／いただきます／はいけんします／うかがいます', 'Động từ khiêm có dạng riêng\nMột số động từ có hẳn dạng khiêm: あした くうこうへ まいります.', 'あした くうこうへ まいります。\nMai tôi ra sân bay ạ.', 'まいります thay いきます・きます, いたします thay します. Đây là lối nói về CHÍNH MÌNH.', 2),
(279, 50, NULL, 'わたくしは N と もうします', 'Tự giới thiệu cho trang trọng\nXưng tên trong buổi làm việc: わたくしは グエンと もうします.', 'わたくしは たなかと もうします。\nTôi tên là Tanaka ạ.', 'わたくし trang trọng hơn わたし. Câu này dùng ở buổi gặp đầu, ở điện thoại công việc.', 3),
(280, 50, NULL, 'V て おります', 'Đang… (nói khiêm)\nDạng khiêm của ～て います: たなかは ただいま せきを はずして おります.', 'けっかは ぞんじて おります。\nVề kết quả thì tôi có biết ạ.', 'Nói về mình và về người bên mình (đồng nghiệp) trước mặt khách thì đều dùng おります.', 4),
(281, 50, NULL, 'V させて いただきます', 'Xin phép được làm\nVừa xin phép vừa hạ mình: せつめいさせて いただきます.', 'けっかを せつめいさせて いただきます。\nTôi xin phép được giải thích về kết quả ạ.', 'Nghe nhã nhất trong các cách nói làm việc gì. Dùng nhiều khi mở đầu bài trình bày.', 5),
(282, 50, NULL, 'N は ～ますか', 'Hỏi lại cho nhã\nHỏi việc mình sẽ làm giúp hoặc việc bên mình: にもつは おもちしましょうか.', 'にもつは おもちしましょうか。\nHành lý để tôi mang nhé ạ?', 'Trả lời nhắc lại đúng thứ được hỏi rồi mới nói tiếp, nghe mới trọn câu.', 6),
(283, 61, 64, 'V-た + ばかり', 'Vừa mới làm gì xong — Diễn tả hành động vừa xảy ra cách đây không lâu, theo cảm nhận chủ quan của người nói.', '日本に来たばかりで、まだ慣れていません。', 'Khác với ～たところ: ～たところ là vừa xong về mặt thời gian thật, còn ～たばかり có thể là vài ngày, vài tháng trước nhưng người nói vẫn thấy là mới.', 1),
(284, 61, 64, 'V-て + おく', 'Làm sẵn, để đó — Làm trước một việc để chuẩn bị, hoặc để nguyên trạng thái như vậy.', '会議の前に資料を読んでおきます。', 'Văn nói rút gọn thành ～とく: 買っておく → 買っとく.', 2),
(285, 61, 64, 'V từ điển / N の + 予定だ', 'Theo lịch, dự kiến — Kế hoạch đã được sắp xếp cụ thể, mang tính khách quan.', '会議は十時から始まる予定です。', 'Chắc chắn hơn つもり vì đã có lịch. Hay đi với mốc thời gian rõ ràng.', 3),
(286, 61, 64, 'Câu hỏi + かどうか', 'Có hay không — Nêu một mệnh đề chưa xác định được đúng sai.', '彼が来るかどうか分かりません。', 'Nếu câu hỏi đã có từ để hỏi (誰, いつ) thì chỉ dùng か, không dùng かどうか.', 4),
(287, 61, 64, 'お / ご + V thể ます (bỏ ます) + ください', 'Xin ngài hãy — Tôn kính ngữ dùng để mời hoặc đề nghị lịch sự.', 'こちらにお座りください。', 'Động từ する: ご + danh từ + ください (ご確認ください). Lịch sự hơn てください nhiều.', 5),
(288, 61, 64, 'N / V ことに + 慣れている', 'Đã quen với — Đã thành thạo hoặc thích nghi với việc gì.', '日本の生活に慣れてきました。', '慣れる là động từ nên cần に. Dạng 慣れてきた = đã dần quen.', 6),
(289, 62, 65, 'Thể thường + はずだ', 'Chắc hẳn là, lẽ ra phải — Người nói suy đoán có căn cứ rằng điều gì đó đúng hoặc sẽ xảy ra.', '彼は昨日出発したから、今日着くはずです。', 'はずがない là phủ định mạnh: không thể nào. Khác với かもしれない (chỉ là khả năng) vì はず có cơ sở rõ ràng.', 1),
(290, 62, 65, 'V-て + しまう', 'Lỡ mất, xong mất — Hoàn tất hành động, hoặc diễn tả sự tiếc nuối vì việc đã lỡ xảy ra.', '電車に傘を忘れてしまいました。', 'Văn nói rút gọn: ～ちゃう (食べちゃった), ～じゃう với động từ đuôi ぬ/む/ぶ (飲んじゃった).', 2),
(291, 62, 65, 'V-ている / N の + 間に', 'Trong lúc, nhân lúc — Làm việc gì trong khoảng thời gian một việc khác đang diễn ra.', '母が寝ている間に、部屋を掃除した。', '間に = việc xảy ra tại một điểm trong khoảng đó. 間 (không に) = việc kéo dài suốt khoảng đó.', 3),
(292, 62, 65, 'V từ điển / N の + 場合は', 'Trong trường hợp — Nêu tình huống giả định và cách xử lý tương ứng.', '地震の場合は、エレベーターを使わないでください。', 'Trang trọng hơn たら, hay gặp trong hướng dẫn và quy định.', 4),
(293, 62, 65, 'N + でございます', 'Là (kính ngữ) — Dạng khiêm nhường trang trọng của です.', '受付は二階でございます。', 'Dùng trong dịch vụ và lễ nghi. ございます = あります dạng lịch sự.', 5),
(294, 62, 65, 'V thể ます (bỏ ます) + そうもない', 'Xem chừng không — Nhìn tình hình thì khả năng xảy ra là rất thấp.', 'この雨はやみそうもない。', 'Dạng khác そうにない. Là phủ định của そうだ suy đoán.', 6),
(295, 63, 66, 'Thể thường + わけだ', 'Thảo nào, hoá ra là — Kết luận rút ra một cách tự nhiên sau khi biết được lý do.', '十年も住んでいたのか。日本語が上手なわけだ。', 'わけがない = không có lý nào, không thể. わけではない = không hẳn là. Ba mẫu này nghĩa khác hẳn nhau, đừng nhầm.', 1),
(296, 63, 66, 'V thể sai khiến (～せる / ～させる)', 'Bắt, để cho làm — Người trên khiến người dưới làm gì, hoặc cho phép ai đó làm gì.', '先生は学生に作文を書かせた。', 'Nhóm 1: う→あ + せる (書かせる). Nhóm 2: る→させる (食べさせる). Bất quy tắc: する→させる, 来る→来させる. Dạng ～させてください = xin cho phép tôi.', 2),
(297, 63, 66, 'V-て + から', 'Sau khi — Nhấn mạnh thứ tự: xong việc trước rồi mới làm việc sau.', '手を洗ってから食べてください。', 'Khác với 〜たあとで ở chỗ てから nhấn mạnh mối liên hệ trực tiếp giữa hai việc.', 3),
(298, 63, 66, 'V từ điển / N の + 代わりに', 'Thay vì, thay cho — Dùng cái này thay cho cái kia, hoặc đổi lại bằng việc khác.', 'バターの代わりにオリーブオイルを使います。', 'Còn nghĩa bù đắp: 給料は安いが、その代わり休みが多い.', 4),
(299, 63, 66, 'Lượng từ + ずつ', 'Mỗi, từng — Chia đều theo từng phần bằng nhau.', '一人ずつ名前を呼びます。', '少しずつ = từng chút một. 一人ずつ = từng người một.', 5),
(300, 63, 66, 'V-て / A-くて + しょうがない', 'Quá đỗi, chịu không nổi — Cảm giác mạnh đến mức không kiểm soát được, giọng văn nói.', 'おなかがすいてしょうがない。', 'Dạng nói của しかたがない. Chỉ dùng cho cảm giác của bản thân.', 6),
(301, 64, 67, 'V từ điển / V-ない + ようにする', 'Cố gắng để, chú ý để — Chủ động nỗ lực duy trì một thói quen hoặc tránh một việc gì.', '毎日野菜を食べるようにしています。', 'ようにする là do mình cố gắng; ようになる là kết quả tự thay đổi. Dạng ようにしている nhấn mạnh đang duy trì thói quen.', 1),
(302, 64, 67, 'Thể thường + かもしれない', 'Có thể là — Nêu một khả năng, mức độ chắc chắn thấp hơn はずだ và でしょう nhiều.', '午後から雨が降るかもしれません。', 'Văn nói rút gọn thành かも. Khác với に違いない (gần như chắc chắn) và はずだ (có căn cứ rõ).', 2),
(303, 64, 67, 'V thể bị động (〜れる / 〜られる)', 'Bị, được — Chủ ngữ chịu tác động từ người hoặc vật khác.', '先生に名前を呼ばれました。', 'Nhóm 1: う→あ + れる (書かれる). Nhóm 2: る→られる (食べられる). Bị động gián tiếp diễn tả sự phiền toái: 雨に降られた (bị mưa).', 3),
(304, 64, 67, 'V-ている / N の + 最中に', 'Đang giữa lúc — Đúng lúc việc gì đang diễn ra sôi nổi nhất thì việc khác xen vào.', '会議の最中に携帯が鳴ってしまった。', 'Mạnh hơn 間に, hàm ý bị ngắt quãng. Không dùng cho trạng thái kéo dài bình thường.', 4),
(305, 64, 67, 'Lượng từ + おきに', 'Cách một — Lặp lại sau mỗi khoảng cách nhất định, bỏ qua khoảng ở giữa.', 'この薬は四時間おきに飲んでください。', '一日おきに = cách một ngày (hai ngày một lần). Khác ごとに (mỗi, không bỏ qua).', 5),
(306, 64, 67, 'V từ điển / A / N の + ように見える', 'Trông có vẻ — Đánh giá qua vẻ bề ngoài nhìn thấy được.', '彼は元気そうに見える。', 'Khác với そうに見える ở chỗ ように見える mang tính so sánh hoặc suy luận rõ hơn.', 6),
(307, 65, 68, 'V từ điển / V-ない + ようになる', 'Trở nên, đã có thể — Diễn tả sự thay đổi trạng thái hoặc năng lực theo thời gian.', '練習して、泳げるようになりました。', 'Hay đi với thể khả năng: 話せるようになる (đã nói được). Phủ định thường dùng なくなる hơn: 食べなくなった.', 1),
(308, 65, 68, 'Thể thường + に違いない', 'Chắc chắn là — Người nói tin gần như chắc chắn dựa trên căn cứ mình có.', '電気がついている。中に誰かいるに違いない。', 'Mạnh hơn はずだ. Là suy đoán chủ quan nên không dùng cho sự thật đã xác nhận.', 2),
(309, 65, 68, 'V thể sai khiến bị động (〜させられる)', 'Bị bắt phải — Bị người khác bắt làm việc mình không muốn.', '子供のころ、毎日ピアノを練習させられた。', 'Nhóm 1 rút gọn thành 〜される (書かされる), trừ động từ kết thúc bằng す. Luôn mang sắc thái miễn cưỡng.', 3),
(310, 65, 68, 'V-ている / V-た + ところに / ところへ', 'Đúng lúc đang thì — Đúng thời điểm đó thì có việc khác xảy ra.', '出かけようとしたところに、客が来た。', 'Vế sau thường là sự xuất hiện của người hoặc việc bất ngờ.', 4),
(311, 65, 68, 'N / V từ điển + ごとに', 'Mỗi, cứ mỗi — Lặp lại đều đặn theo từng đơn vị, không bỏ qua.', '五分ごとにバスが来ます。', '三日ごとに = ba ngày một lần. So với おきに thì ごとに tính cả mốc đó.', 5),
(312, 66, 69, 'V từ điển / N の + ために', 'Để, vì (mục đích hoặc nguyên nhân) — Nêu mục đích khi đi với động từ ý chí, nêu nguyên nhân khi đi với sự việc đã xảy ra.', '留学するために、お金をためています。', 'Phân biệt với ように: ために dùng khi chủ ngữ tự làm được (động từ ý chí), ように dùng với động từ không ý chí hoặc thể khả năng.', 1),
(313, 66, 69, 'Thể thường + ようだ / みたいだ', 'Có vẻ như, dường như — Suy đoán dựa trên điều bản thân trực tiếp cảm nhận được.', '外は寒いようです。みんなコートを着ています。', 'みたいだ là dạng thân mật của ようだ, nối trực tiếp sau danh từ (子供みたい) còn ようだ cần の (子供のようだ).', 2),
(314, 66, 69, 'お + V thể ます (bỏ ます) + する', 'Khiêm nhường ngữ — Hạ thấp hành động của mình để tỏ kính trọng với đối phương.', 'お荷物をお持ちします。', 'Tôn kính ngữ là お〜になる (dùng cho hành động của người trên). Đừng dùng lẫn: nói お書きになります về mình là sai.', 3),
(315, 66, 69, 'Khoảng thời gian + ぶりに', 'Sau bấy lâu — Sau một khoảng thời gian dài mới lại xảy ra.', '十年ぶりに故郷に帰った。', 'Chỉ dùng với khoảng thời gian tương đối dài. 久しぶり là cách nói quen thuộc nhất.', 4),
(316, 66, 69, 'N + しか + phủ định', 'Chỉ có mỗi — Nhấn mạnh sự ít ỏi, kèm cảm giác không đủ.', '財布に千円しかない。', 'Vế sau bắt buộc phủ định. Khác だけ (trung tính) ở chỗ しか mang ý tiếc.', 5),
(317, 67, 70, 'V thể khả năng / V-ない + ように', 'Để mà, sao cho — Nêu mục đích với những việc không hoàn toàn do mình quyết định.', '後ろの人にも聞こえるように、大きい声で話した。', 'Đi với động từ không ý chí (わかる, 見える) hoặc thể khả năng. Câu sau thường là hành động mình làm để đạt được điều đó.', 1),
(318, 67, 70, 'V thể ます (bỏ ます) / A bỏ い + そうだ', 'Trông có vẻ, sắp — Phán đoán từ vẻ bề ngoài nhìn thấy được, hoặc dấu hiệu sắp xảy ra.', 'このケーキ、おいしそうですね。', 'いい → よさそう, ない → なさそう là hai ngoại lệ. Đừng nhầm với そうだ truyền đạt (nối sau thể thường).', 2),
(319, 67, 70, 'V-て + くる / いく', 'Dần dần, từ đó trở đi — Diễn tả sự thay đổi theo thời gian, hoặc hướng di chuyển so với người nói.', 'だんだん寒くなってきました。', 'てくる = thay đổi từ quá khứ đến hiện tại; ていく = từ hiện tại về tương lai. Còn nghĩa di chuyển: 買ってくる (mua rồi mang về).', 3),
(320, 67, 70, 'N + 向け / 向き', 'Dành cho, hợp với — 向け là làm ra nhắm tới đối tượng đó; 向き là tình cờ phù hợp.', 'これは初心者向けの教科書です。', '子供向けの番組 (chương trình làm cho trẻ em) khác 子供向きの番組 (chương trình hợp với trẻ em).', 4),
(321, 67, 70, 'Mốc thời gian + までに', 'Trước khi, chậm nhất là — Hạn chót để hoàn thành một việc.', '金曜までに提出してください。', 'Khác với まで (kéo dài cho đến). 五時まで働く (làm đến năm giờ) khác 五時までに終わる (xong trước năm giờ).', 5),
(322, 68, 71, 'Thể thường + そうだ', 'Nghe nói rằng — Truyền đạt lại thông tin nghe được từ nguồn khác, không thêm nhận định của mình.', '天気予報によると、明日は雨だそうです。', 'Khác hẳn そうだ dạng suy đoán (V thể ます (bỏ ます) + そうだ = trông có vẻ). Dạng truyền đạt nối sau thể thường, không chia phủ định そうじゃない.', 1),
(323, 68, 71, 'V từ điển / V-ない + ことにする', 'Quyết định làm — Chính người nói tự quyết định một việc.', '来年から日本で働くことにしました。', 'ことにしている = duy trì thói quen do mình đặt ra. Khác với ことになる (do hoàn cảnh hoặc người khác quyết).', 2),
(324, 68, 71, 'V-て + ある', 'Đã được làm sẵn — Trạng thái còn lại sau khi ai đó cố ý làm việc gì, nhấn mạnh kết quả.', '壁に地図が貼ってあります。', 'Chỉ dùng với tha động từ. So sánh: ドアが開いている (cửa đang mở, tả trạng thái) và ドアが開けてある (cửa được mở sẵn, có người mở).', 3),
(325, 68, 71, 'V thể ます (bỏ ます) + っぱなし', 'Cứ để nguyên đó — Để nguyên trạng thái đáng lẽ phải kết thúc, mang ý chê trách.', '水を出しっぱなしにしないで。', 'Gần với まま nhưng chê rõ hơn và chỉ dùng với động từ. 立ちっぱなし = đứng suốt.', 4),
(326, 68, 71, 'N の + ように / ような', 'Giống như — So sánh hoặc nêu ví dụ minh hoạ.', '彼は父親のように優しい。', 'ように bổ nghĩa cho động từ, ような bổ nghĩa cho danh từ. Văn nói dùng みたい.', 5),
(327, 69, 72, 'Thể thường + らしい', 'Hình như, có vẻ (nghe ngóng được) — Suy đoán dựa trên thông tin nghe hoặc thấy từ bên ngoài, người nói không chắc chắn hoàn toàn.', 'あの店は閉まったらしい。', 'Còn một nghĩa khác: N + らしい = đúng chất, ra dáng (男らしい = ra dáng đàn ông). Phân biệt theo ngữ cảnh.', 1),
(328, 69, 72, 'V từ điển / V-ない + ことになる', 'Được quyết định là — Kết quả do hoàn cảnh hoặc tổ chức quyết định, không phải ý mình.', '来月、大阪へ転勤することになりました。', 'Người Nhật hay dùng ことになりました cả khi tự quyết, để tránh nghe như khoe: 結婚することになりました.', 2),
(329, 69, 72, 'V-て + みる', 'Thử làm — Làm thử để xem kết quả ra sao.', 'この服を着てみてもいいですか。', 'Không dùng khi việc đó chắc chắn phải làm. てみたい = muốn thử.', 3),
(330, 69, 72, 'お + V thể ます (bỏ ます) + になる', 'Tôn kính ngữ — Nâng hành động của người trên lên để tỏ kính trọng.', '社長はもうお帰りになりました。', 'Dùng cho hành động của ĐỐI PHƯƠNG. Nói về mình phải dùng khiêm nhường ngữ お〜する. Nhiều động từ có dạng riêng: 行く → いらっしゃる.', 4),
(331, 69, 72, 'N とか N + とか', 'Nào là nào là — Liệt kê vài ví dụ không đầy đủ, giọng văn nói.', '果物はりんごとかバナナとかが好きです。', 'Suồng sã hơn や. Có thể dùng với động từ: 行くとか行かないとか.', 5),
(332, 70, 73, 'V từ điển / V-ている / V-た + ところだ', 'Vừa định, đang, vừa mới xong — Chỉ rõ giai đoạn của hành động theo thời gian.', '今から出かけるところです。', 'V từ điển + ところ = sắp làm; V-ている + ところ = đang làm; V-た + ところ = vừa làm xong ngay lúc này.', 1),
(333, 70, 73, 'V-た + ことがある', 'Đã từng — Nêu kinh nghiệm đã trải qua trong quá khứ.', '富士山に登ったことがありますか。', 'Khác với V từ điển + ことがある = thỉnh thoảng có khi (たまに遅れることがある). Không dùng cho việc vừa mới xảy ra.', 2),
(334, 70, 73, 'V-て + あげる / くれる / もらう', 'Cho, giúp, được giúp — Diễn tả việc cho nhận ân huệ giữa các bên.', '友達が空港まで送ってくれました。', 'あげる = mình làm cho người khác (cẩn thận, dễ nghe như ban ơn). くれる = người khác làm cho mình. もらう = mình nhờ và nhận được.', 3),
(335, 70, 73, 'Thể thường + のだ / んです', 'Là bởi vì, thì ra là — Giải thích lý do, hoặc nhấn mạnh hoàn cảnh.', 'どうして遅れたんですか。', 'んです là dạng nói. Dùng quá nhiều nghe như đang phân bua. Danh từ và tính từ đuôi な nối bằng な: 学生なんです.', 4),
(336, 70, 73, 'N + なんか / など', 'Những thứ như, cỡ như — Nêu ví dụ, hoặc hạ thấp giá trị.', '映画なんかどうですか。', 'なんか là dạng nói của など. Khi nói về mình thì mang ý khiêm tốn: 私なんか.', 5),
(337, 71, 74, 'V thể ます (bỏ ます) + ながら', 'Vừa làm vừa làm — Hai hành động diễn ra đồng thời, hành động chính nằm ở vế sau.', '音楽を聞きながら勉強します。', 'Hai hành động phải cùng một chủ ngữ. Còn nghĩa thứ hai là tuy nhưng (残念ながら = tiếc là).', 1),
(338, 71, 74, 'V-た / V-ない + ほうがいい', 'Nên, không nên — Khuyên ai đó nên hoặc không nên làm gì.', '熱があるなら、休んだほうがいいですよ。', 'Khẳng định dùng thể た (休んだほうがいい), phủ định dùng thể ない (行かないほうがいい). Nói với người trên thì nên thêm と思います cho nhẹ.', 2),
(339, 71, 74, 'V-て + いただけませんか', 'Xin phiền ngài làm giúp — Nhờ vả một cách rất lịch sự.', 'もう一度説明していただけませんか。', 'Mức độ lịch sự tăng dần: てください < てくれませんか < ていただけませんか < ていただけないでしょうか.', 3),
(340, 71, 74, 'Thể thường + だろう / でしょう', 'Chắc là — Suy đoán của người nói, mức độ vừa phải.', '明日は晴れるでしょう。', 'でしょう lịch sự hơn だろう. Lên giọng cuối câu thì thành xác nhận: 明日でしょう？', 4),
(341, 71, 74, 'N + でも', 'Chẳng hạn như — Nêu một gợi ý nhẹ nhàng, không áp đặt.', 'お茶でも飲みませんか。', 'Khác với でも nghĩa nhượng bộ. Ở đây là お茶でも飲みませんか (uống trà chẳng hạn nhé).', 5),
(342, 72, 75, 'V-ている / V-ない / A / N の + うちに', 'Trong lúc còn, trước khi — Làm việc gì trong khoảng thời gian điều kiện còn thuận lợi, trước khi nó thay đổi.', '熱いうちに召し上がってください。', 'ないうちに = trước khi điều gì xảy ra. Khác với 間に: うちに nhấn mạnh kẻo lỡ mất cơ hội.', 1),
(343, 72, 75, 'V-ない bỏ い + ければならない', 'Phải, bắt buộc — Nghĩa vụ hoặc quy định bắt buộc, không làm không được.', '明日までにレポートを出さなければなりません。', 'Văn nói rút gọn: なきゃ, なくちゃ. Dạng なくてもいい là phủ định của nó: không cần phải.', 2),
(344, 72, 75, 'V thể ます (bỏ ます) + 始める / 出す', 'Bắt đầu, bỗng nhiên — Nêu thời điểm bắt đầu của một hành động.', '去年から日本語を習い始めました。', '始める là bắt đầu có chủ ý; 出す là bỗng dưng xảy ra ngoài dự tính: 泣き出す (bỗng khóc oà).', 3),
(345, 72, 75, 'V-た / N の + 上で', 'Sau khi rồi mới — Làm xong bước trước rồi mới tiến hành bước sau, dùng cho việc quan trọng.', 'よく相談した上で決めます。', 'Trang trọng, hay gặp trong hợp đồng và thủ tục. Khác với てから ở chỗ 上で nhấn mạnh sự cân nhắc.', 4),
(346, 72, 75, 'N + こそ', 'Chính là, mới là — Nhấn mạnh rằng đúng cái đó chứ không phải cái khác.', '今度こそ成功させたい。', 'こちらこそ = tôi mới phải cảm ơn. 今度こそ = lần này nhất định.', 5),
(347, 73, 76, 'V từ điển / N の + たびに', 'Mỗi lần — Cứ mỗi lần việc này xảy ra thì việc kia cũng xảy ra theo.', 'この歌を聞くたびに、故郷を思い出す。', 'Trang trọng hơn ～ときはいつも. Không dùng cho việc chỉ xảy ra một lần.', 1),
(348, 73, 76, 'V-ない bỏ い + くてもいい', 'Không cần phải — Cho biết việc đó không bắt buộc.', '急がなくてもいいですよ。', 'Danh từ và tính từ cũng dùng được: 新しくなくてもいい, 全部でなくてもいい.', 2),
(349, 73, 76, 'V thể ます (bỏ ます) + 続ける / 終わる', 'Tiếp tục, làm xong — Nêu việc kéo dài hoặc kết thúc của hành động.', '三時間も歩き続けた。', '続ける là chủ động tiếp tục; 続く là tự nó kéo dài. Đừng dùng lẫn.', 3),
(350, 73, 76, 'V-た + きり', 'Kể từ đó rồi thôi — Sau việc đó thì không có diễn biến tiếp theo như lẽ thường.', '彼は出て行ったきり、帰ってこない。', 'Hầu như luôn đi với phủ định ở vế sau, mang ý nuối tiếc hoặc lo lắng.', 4),
(351, 73, 76, 'Thể thường + からこそ', 'Chính vì mà — Nhấn mạnh lý do, khẳng định đó mới là nguyên nhân thật.', 'あなただからこそ話すのです。', 'Mạnh hơn から. Vế sau thường có のだ để nhấn thêm.', 5),
(352, 74, 77, 'V từ điển / V-た / N の + とおりに', 'Đúng như, theo như — Làm giống hệt như điều đã nói, đã thấy hoặc đã hướng dẫn.', '先生が言ったとおりにやってみます。', 'Nối sau danh từ thì đọc là どおり: 予定どおり (đúng như kế hoạch), 説明どおり.', 1),
(353, 74, 77, 'V-て + もいい / V-て + はいけない', 'Được phép, không được phép — Cho phép hoặc cấm đoán.', 'ここに座ってもいいですか。', 'Hỏi xin phép: 〜てもいいですか. Cấm đoán てはいけない khá mạnh, với người trên nên dùng ご遠慮ください.', 2),
(354, 74, 77, 'V thể ます (bỏ ます) + やすい / にくい', 'Dễ, khó — Việc gì đó dễ hoặc khó thực hiện, dễ hoặc khó xảy ra.', 'このペンは書きやすいです。', 'Sau khi thêm thì chia như tính từ đuôi い: 使いやすかった. Khác với がち ở chỗ やすい trung tính.', 3),
(355, 74, 77, 'たとえ + V-て + も', 'Cho dù đi nữa — Nhấn mạnh rằng dù giả định thế nào kết quả cũng không đổi.', 'たとえ雨が降っても、試合は行います。', 'たとえ là phó từ báo hiệu, bắt buộc vế sau có ても. Mạnh hơn ても đứng một mình.', 4),
(356, 74, 77, 'V từ điển / A + ものだ', 'Vốn dĩ, hồi đó hay — Nêu lẽ thường tình, hoặc hồi tưởng chuyện xưa.', '時間がたつのは早いものだ。', 'Hồi tưởng dùng thể た: よく遊んだものだ. Lời khuyên: 早く寝るものだ.', 5),
(357, 75, 78, 'N + によって', 'Tuỳ theo, bởi, nhờ vào — Nêu sự khác nhau tuỳ trường hợp, nêu phương tiện, hoặc nêu chủ thể trong câu bị động.', '国によって習慣が違います。', 'Ba nghĩa phân biệt theo ngữ cảnh: 人によって違う (tuỳ người), 話し合いによって解決する (bằng cách), 彼によって作られた (bởi anh ấy).', 1),
(358, 75, 78, 'V từ điển / V-ない + と', 'Hễ là, cứ là — Điều kiện tất yếu: cứ xảy ra A thì B luôn xảy ra.', '春になると、桜が咲きます。', 'Vế sau KHÔNG được là ý chí, mệnh lệnh hay rủ rê. Dùng cho quy luật tự nhiên, cách vận hành máy móc, chỉ đường.', 2),
(359, 75, 78, 'V thể ます (bỏ ます) / A bỏ い + すぎる', 'Quá mức — Vượt quá mức hợp lý, hầu như luôn mang nghĩa không tốt.', '昨日は飲みすぎました。', 'いい → よすぎる, ない → なさすぎる. Chia như động từ nhóm 2: 食べすぎました.', 3),
(360, 75, 78, 'V từ điển + ようにしている', 'Đang duy trì thói quen — Nhấn mạnh việc cố gắng duy trì đều đặn, không chỉ một lần.', '毎日日記をつけるようにしています。', 'Khác với ようにする (quyết tâm từ giờ) ở chỗ ようにしている là đã và đang làm.', 4),
(361, 75, 78, 'V-ない bỏ ない + ずにすむ', 'Không phải, thoát khỏi việc — May mắn không phải làm việc đáng lẽ phải làm.', '友達が車を出してくれたので、歩かずにすんだ。', 'する → せずにすむ. Dạng khác ないですむ. Mang cảm giác nhẹ nhõm.', 5),
(362, 76, 79, 'N + について', 'Về, liên quan đến — Nêu chủ đề của việc nói, nghe, viết, suy nghĩ hay điều tra.', '日本の文化について発表します。', 'Khác với に対して (hướng thái độ về phía ai đó). について chỉ nêu đề tài.', 1),
(363, 76, 79, 'V-た + ら', 'Nếu, sau khi — Điều kiện hoặc trình tự thời gian, dùng rộng nhất trong bốn mẫu điều kiện.', '駅に着いたら、電話してください。', 'Vế sau được phép là ý chí hay mệnh lệnh, khác với と. Nếu vế sau là việc đã xảy ra thì mang nghĩa bất ngờ: 窓を開けたら、雪が降っていた.', 2),
(364, 76, 79, 'V thể ます (bỏ ます) + 方', 'Cách làm — Chỉ phương pháp hoặc cách thức làm việc gì.', 'この漢字の書き方を教えてください。', 'Trở thành danh từ nên nối bằng の: 漢字の書き方. Trợ từ を đổi thành の: 料理を作る → 料理の作り方.', 3),
(365, 76, 79, 'N + にする', 'Chọn, quyết định lấy — Chọn một phương án trong nhiều lựa chọn.', '私はコーヒーにします。', 'Hay dùng khi gọi món. Khác với になる (tự nhiên trở thành).', 4),
(366, 76, 79, 'Thể thường + のではないか', 'Chẳng phải là sao — Nêu phán đoán một cách dè dặt, hoặc gợi ý nhẹ.', '何か誤解があるのではないでしょうか。', 'Văn nói rút gọn んじゃないか. Cách nói vòng để không áp đặt.', 5),
(367, 77, 80, 'N + に対して', 'Đối với, ngược lại với — Nêu đối tượng mà thái độ hay hành động hướng tới; hoặc nêu sự tương phản giữa hai bên.', 'お客様に対して丁寧な言葉を使います。', 'Đừng nhầm với について. に対して luôn có đối tượng nhận tác động, hoặc đặt hai vế đối lập nhau.', 1),
(368, 77, 80, 'N / Thể thường + なら', 'Nếu là, nếu vậy thì — Tiếp nhận thông tin đối phương vừa nói rồi đưa ra ý kiến hoặc lời khuyên.', '日本語を勉強するなら、この本がいいですよ。', 'Khác hẳn たら ở chỗ なら dựa trên điều người kia vừa nói. Không dùng cho việc chắc chắn xảy ra theo tự nhiên.', 2),
(369, 77, 80, 'V thể ます (bỏ ます) + たがる', 'Người khác muốn — Diễn tả mong muốn của người thứ ba, quan sát từ bên ngoài.', '子供が外へ行きたがっている。', 'たい chỉ dùng cho bản thân; nói về người khác phải dùng たがる hoặc たいようだ. Chia như động từ nhóm 1.', 3),
(370, 77, 80, 'N + としては', 'Về phần, xét theo tiêu chuẩn — Nêu lập trường của mình, hoặc nêu tiêu chuẩn để đánh giá.', '私としては反対です。', 'Khác với として (tư cách) ở chỗ としては có thêm sắc thái đánh giá hoặc bày tỏ quan điểm.', 4),
(371, 77, 80, 'V-た + らどうですか', 'Sao không thử — Gợi ý hoặc khuyên nhẹ nhàng.', '少し休んだらどうですか。', 'Với người trên thì hơi sỗ, nên dùng てはいかがでしょうか.', 5),
(372, 78, 81, 'N + として', 'Với tư cách là — Nêu tư cách, vai trò hay danh nghĩa của người hoặc vật.', '彼は研究者として有名です。', 'としては dùng khi nêu lập trường: 私としては賛成です (về phần tôi thì tôi đồng ý).', 1),
(373, 78, 81, 'V-た / N の / A + まま', 'Cứ để nguyên, trong trạng thái — Một trạng thái được giữ nguyên không đổi, thường là điều lẽ ra phải thay đổi.', 'エアコンをつけたまま出かけてしまった。', 'Hay mang sắc thái bỏ mặc: つけたまま (để bật nguyên), 靴のまま (cứ nguyên giày). Khác với ておく là cố ý để lại cho có ích.', 2),
(374, 78, 81, 'V từ điển + ことができる', 'Có thể — Nêu khả năng hoặc sự cho phép, trang trọng hơn thể khả năng.', 'ここでは写真を撮ることができません。', 'Văn viết hay dùng mẫu này, văn nói thường dùng thể khả năng: 泳げる.', 3),
(375, 78, 81, 'N + さえ + V thể ば', 'Chỉ cần là được — Chỉ cần đủ một điều kiện duy nhất thì mọi việc ổn.', 'この薬さえ飲めば、すぐよくなります。', 'Nhấn mạnh rằng không cần gì thêm. Động từ: V thể ます + さえすれば.', 4),
(376, 78, 81, 'V-て + ばかりいる', 'Suốt ngày chỉ — Chỉ làm mỗi việc đó, mang ý chê trách.', '彼は遊んでばかりいる。', 'Khác N+ばかり ở chỗ đây đi với động từ và nhấn mạnh sự lặp lại đáng trách.', 5),
(377, 79, 82, 'Thể thường / N の + わりに', 'So với thì, tuy nhưng — Kết quả không tương xứng với điều lẽ ra phải như vậy, thường mang ý bất ngờ.', 'この店は安いわりにおいしい。', 'Thường mang sắc thái khen hoặc ngạc nhiên nhẹ. Không dùng để chê nặng.', 1),
(378, 79, 82, 'V từ điển / V-た / N の + ついでに', 'Tiện thể — Nhân lúc làm việc chính thì làm luôn việc phụ.', '買い物に行くついでに、郵便局にも寄ります。', 'Việc chính phải là việc quan trọng hơn. Không dùng khi hai việc ngang nhau.', 2),
(379, 79, 82, 'V thể ば', 'Nếu — Điều kiện mang tính giả định hoặc quy luật chung.', '時間があれば、行きます。', 'Vế sau không nên là mệnh lệnh nếu vế trước là động từ hành động. Tính từ đuôi い: 安ければ. Danh từ: 学生であれば.', 3),
(380, 79, 82, 'V-て + ほしい', 'Muốn ai đó làm gì — Mong muốn người khác thực hiện hành động nào đó.', 'もう少し静かにしてほしい。', 'Khác với たい (mình muốn làm). Phủ định: ないでほしい. Với người trên nên dùng ていただきたい.', 4),
(381, 79, 82, 'N / V từ điển + ほど', 'Đến mức — Nêu mức độ bằng một hình ảnh cụ thể.', '死ぬほど疲れた。', 'Khác ほど〜ない (không bằng). Ở đây là 死ぬほど疲れた (mệt đến chết đi được).', 5),
(382, 80, 83, 'Thể thường / N の + くせに', 'Vậy mà, thế mà (chê trách) — Chỉ sự mâu thuẫn, kèm thái độ trách móc hoặc coi thường của người nói.', '知っているくせに教えてくれない。', 'Mang cảm xúc tiêu cực rõ, không dùng với người trên. Nếu chỉ muốn nêu sự trái ngược trung tính thì dùng のに.', 1),
(383, 80, 83, 'Thể thường / N の + おかげで', 'Nhờ có — Nêu nguyên nhân dẫn đến kết quả tốt, kèm lòng biết ơn.', '先生のおかげで合格できました。', 'Ngược lại là せいで (tại, vì — kết quả xấu). Dùng nhầm hai mẫu này là lỗi rất nặng về sắc thái.', 2),
(384, 80, 83, 'V-ない bỏ ない + ずに', 'Mà không — Làm việc gì mà không làm việc kia, dùng trong văn viết.', '朝ご飯を食べずに出かけた。', 'する → せずに (ngoại lệ). Dạng văn nói tương đương là ないで.', 3),
(385, 80, 83, 'N を + ほしがる', 'Người khác muốn có — Diễn tả mong muốn sở hữu của người thứ ba.', '子供が新しいゲームをほしがっている。', 'ほしい chỉ dùng cho mình; nói về người khác phải dùng ほしがる hoặc ほしいようだ.', 4),
(386, 80, 83, 'N / V từ điển + くらい', 'Đến mức, cỡ — Nêu mức độ hoặc lượng ước chừng.', '歩けないくらい足が痛い。', 'Nghĩa mức độ gần ほど. Nghĩa coi nhẹ: それくらいできるでしょう (chừng ấy thì làm được chứ).', 5),
(387, 81, 84, 'V-ば + V từ điển + ほど', 'Càng thì càng — Mức độ của vế sau tăng theo mức độ của vế trước.', '考えれば考えるほど分からなくなる。', 'Tính từ đuôi い: 安ければ安いほど. Tính từ đuôi な: 便利なら便利なほど.', 1),
(388, 81, 84, 'N + によると', 'Theo như — Nêu nguồn của thông tin được truyền đạt lại.', 'ニュースによると、地震があったそうです。', 'Vế sau hầu như luôn kết thúc bằng そうだ, らしい hoặc ということだ.', 2),
(389, 81, 84, 'Thể thường + し', 'Vừa vừa, vả lại — Liệt kê nhiều lý do hoặc nhiều đặc điểm cùng chiều.', 'この店は安いし、近いし、よく行きます。', 'Hàm ý còn lý do khác nữa chưa kể hết. Khác với から (chỉ một lý do dứt khoát).', 3),
(390, 81, 84, 'V thể ý chí + とする', 'Định làm, cố làm — Ngay trước lúc bắt đầu hành động, hoặc cố gắng làm gì.', '出かけようとしたとき、電話が鳴った。', 'としたとき = đúng lúc định. ようとしない = không chịu làm.', 4),
(391, 81, 84, 'V-て + からずっと', 'Từ khi đến giờ vẫn — Trạng thái kéo dài liên tục kể từ một mốc.', '引っ越してからずっとここに住んでいる。', 'Nhấn mạnh tính liên tục, khác với てから đơn thuần chỉ trình tự.', 5),
(392, 82, 85, 'N + さえ', 'Đến cả, ngay cả — Nêu một ví dụ cực đoan để hàm ý những trường hợp khác đương nhiên cũng vậy.', '忙しくて、食事をする時間さえない。', 'さえ～ば = chỉ cần thì: これさえあればいい (chỉ cần có cái này là được).', 1),
(393, 82, 85, 'Thể thường + のに', 'Vậy mà, mặc dù — Kết quả trái với mong đợi, kèm cảm giác bất mãn hoặc tiếc nuối.', '薬を飲んだのに、まだ熱が下がらない。', 'Trung tính hơn くせに (chê trách) và mạnh hơn が. Danh từ và tính từ đuôi な nối bằng な: 便利なのに.', 2),
(394, 82, 85, 'V-たり、V-たり + する', 'Nào là nào là — Liệt kê vài hành động tiêu biểu trong nhiều hành động.', '休みの日は本を読んだり、散歩したりします。', 'Không phải liệt kê theo thứ tự thời gian. Hai việc trái nghĩa thì diễn tả sự lặp lại: 降ったりやんだり.', 3),
(395, 82, 85, 'Thể thường + はずがない', 'Không thể nào — Phủ định mạnh dựa trên căn cứ, khẳng định điều đó không thể đúng.', '彼がそんなことを言うはずがない。', 'Khác với わけがない ở chỗ はずがない dựa trên lý lẽ, わけがない mang cảm xúc mạnh hơn.', 4),
(396, 82, 85, 'V-た + ばかりなのに', 'Vừa mới thế mà — Nhấn mạnh sự trái khoáy: vừa xong đã xảy ra chuyện.', '買ったばかりなのに、もう壊れた。', 'Kết hợp たばかり và のに. Mang cảm giác bực hoặc ngạc nhiên.', 5),
(397, 83, 86, 'N + だらけ', 'Đầy, toàn là — Bám đầy hoặc đầy rẫy thứ gì đó, hầu như luôn mang nghĩa xấu.', 'この作文は間違いだらけだ。', 'Khác với だらけ là いっぱい (trung tính) và まみれ (bám dính chất lỏng, bụi). 間違いだらけ = sai be bét.', 1),
(398, 83, 86, 'V-て / A-くて / N で + も', 'Dù cho, cho dù — Dù điều kiện thế nào thì kết quả vẫn không đổi.', 'いくら呼んでも返事がない。', 'Hay đi với いくら, どんなに để nhấn mạnh: いくら説明しても分からない.', 2),
(399, 83, 86, 'N より N の + ほうが', 'So với thì hơn — So sánh hai đối tượng và chọn ra bên nào hơn.', '電車よりバスのほうが安いです。', 'Trật tự có thể đảo: AのほうがBより〜. Câu hỏi lựa chọn dùng どちらのほうが.', 3),
(400, 83, 86, 'Thể thường + わけがない', 'Làm gì có chuyện — Phủ định dứt khoát, giọng chủ quan và mạnh.', 'こんな簡単な問題、間違えるわけがない。', 'Đừng nhầm với わけではない (không hẳn là) và わけだ (thảo nào).', 4),
(401, 83, 86, 'V từ điển / V-ない + ように言う', 'Bảo ai làm gì — Truyền đạt lại lời nhờ vả, mệnh lệnh hoặc lời khuyên.', '医者に酒をやめるように言われた。', 'Hay đi với 言う, 頼む, 注意する. Là cách trích dẫn gián tiếp.', 5),
(402, 84, 87, 'V thể ます (bỏ ます) / N + がち', 'Hay bị, có xu hướng — Chỉ khuynh hướng dễ xảy ra, phần lớn mang nghĩa không mong muốn.', '冬は運動不足になりがちです。', 'Khác với ～やすい (dễ, trung tính). がち nhấn mạnh tần suất và thường tiêu cực: 遅れがち, 病気がち.', 1),
(403, 84, 87, 'Thể thường / N + だけでなく〜も', 'Không chỉ mà còn — Bổ sung thêm một điều nữa ngoài điều đã nêu.', '彼は英語だけでなく、中国語も話せる。', 'Trang trọng hơn thì dùng のみならず. Vế sau thường có も hoặc まで.', 2),
(404, 84, 87, 'N ほど + phủ định', 'Không đến mức bằng — Phủ định ở mức so sánh: cái này không bằng cái kia.', '今年の冬は去年ほど寒くない。', 'Vế sau bắt buộc phải là phủ định. Khác với より ở chỗ ほど〜ない nhẹ nhàng hơn.', 3),
(405, 84, 87, 'V-たら / V-ば + いい', 'Nên làm gì thì tốt — Đưa ra lời khuyên hoặc nêu mong muốn.', 'どうしたらいいか分かりません。', 'Câu hỏi どうしたらいいですか = tôi nên làm thế nào. Dạng たらよかった = giá mà đã.', 4),
(406, 84, 87, 'N + によって違う', 'Khác nhau tuỳ theo — Nhấn mạnh sự khác biệt giữa các trường hợp.', '考え方は人によって違う。', 'Là một cách dùng cụ thể của によって. Vế sau thường là 違う, 異なる, さまざまだ.', 5),
(407, 85, 88, 'N / V thể ます (bỏ ます) / A bỏ い + っぽい', 'Có vẻ, hay bị, ngả sang — Mang tính chất hoặc khuynh hướng của điều gì đó, dùng trong văn nói.', '彼は怒りっぽい性格だ。', 'Thường hàm ý chê nhẹ: 子供っぽい (trẻ con), 忘れっぽい (hay quên). Sau khi thêm っぽい thì chia như tính từ đuôi い.', 1),
(408, 85, 88, 'N + はもちろん', 'Đương nhiên là, khỏi phải nói — Điều trước là hiển nhiên, nhấn mạnh điều sau mới đáng nói.', 'この店はラーメンはもちろん、餃子もおいしい。', 'Sắc thái nhẹ nhàng hơn だけでなく, thường dùng khi khen.', 2),
(409, 85, 88, 'N + ばかり', 'Toàn là, chỉ mỗi — Chỉ có mỗi thứ đó, thường kèm ý chê.', '彼は文句ばかり言っている。', 'Khác với た+ばかり (vừa mới). V-てばかりいる = cứ làm mãi một việc: 遊んでばかりいる.', 3),
(410, 85, 88, 'V-て + もらえませんか', 'Anh làm giúp được không — Nhờ vả lịch sự vừa phải.', 'ちょっと手伝ってもらえませんか。', 'Thang lịch sự: てくれない < てくれませんか < てもらえませんか < ていただけませんか.', 4),
(411, 85, 88, 'N + がする', 'Có cảm giác, nghe thấy — Cảm nhận qua giác quan: mùi, tiếng, vị, cảm giác.', '台所からいいにおいがする。', 'Chỉ dùng với 音, におい, 味, 感じ, 気. Không dùng với thị giác.', 5),
(412, 86, 89, 'V thể ます (bỏ ます) + きる', 'Làm trọn, làm hết — Hoàn thành trọn vẹn đến cùng, hoặc đạt tới mức tận cùng.', '長い小説を三日で読みきった。', 'Phủ định きれない = không thể làm hết: 食べきれない (ăn không hết). Đây là mẫu rất hay gặp.', 1),
(413, 86, 89, 'N + に比べて', 'So với — Đối chiếu hai đối tượng để nêu sự khác biệt.', '去年に比べて、今年は暖かい。', 'Có thể nói に比べると. Không dùng khi so sánh hai lựa chọn để chọn một — lúc đó dùng より〜ほうが.', 2),
(414, 86, 89, 'N + という + N', 'Được gọi là, có tên là — Giới thiệu tên gọi mà người nghe có thể chưa biết.', '田中という人から電話がありました。', 'ということだ = nghe nói rằng (truyền đạt). というのは = nghĩa là (giải thích).', 3),
(415, 86, 89, 'V thể sai khiến + てください', 'Xin cho phép tôi — Xin phép được tự mình làm việc gì.', 'その仕事は私にやらせてください。', 'Lịch sự hơn: させていただけませんか. Dùng khi mình chủ động xin làm.', 4),
(416, 86, 89, 'V từ điển + ところだった', 'Suýt nữa thì — May mà tránh được, chút nữa là xảy ra chuyện.', 'もう少しで転ぶところだった。', 'Hay đi với もう少しで, 危うく. Việc đó thực tế đã không xảy ra.', 5),
(417, 87, 90, 'V thể ます (bỏ ます) + かける', 'Đang dở, suýt — Hành động mới bắt đầu và còn dang dở, chưa hoàn tất.', '言いかけてやめた。', 'かけの dùng làm định ngữ: 読みかけの本 (cuốn sách đang đọc dở).', 1),
(418, 87, 90, 'V từ điển / V-ない + つもりだ', 'Dự định, có ý định — Ý định chủ quan của người nói, chưa chắc thành hiện thực.', '夏休みに国へ帰るつもりです。', 'Khác với 予定 (lịch đã sắp, khách quan). つもりはない = hoàn toàn không có ý định.', 2),
(419, 87, 90, 'Thể thường + ということだ', 'Nghe nói rằng, tức là — Truyền đạt lại nguyên văn thông tin, hoặc rút ra kết luận.', '部長は今日休むということです。', 'Nghĩa truyền đạt tương đương そうだ nhưng trang trọng hơn, hay dùng trong thông báo.', 3),
(420, 87, 90, 'V thể sai khiến + ていただく', 'Xin phép được — Khiêm nhường ngữ: xin phép làm gì với sự cho phép của đối phương.', '本日、司会を務めさせていただきます。', 'Rất hay dùng trong công việc: 説明させていただきます. Đừng lạm dụng, nghe nặng nề.', 4),
(421, 87, 90, 'V-て + すみません', 'Xin lỗi vì đã — Xin lỗi về hành động mình đã làm.', '遅れてすみません。', 'Trang trọng hơn: て申し訳ありません. Cảm ơn thì dùng てくれてありがとう.', 5),
(422, 88, 91, 'N + において / における', 'Tại, trong lĩnh vực — Nêu nơi chốn, thời điểm hoặc phạm vi, dùng trong văn viết trang trọng.', '会議は大ホールにおいて行われます。', 'Dạng định ngữ là における: 会議における発言. Văn nói thì dùng で.', 1),
(423, 88, 91, 'V từ điển / N の + おそれがある', 'Có nguy cơ — Cảnh báo khả năng xảy ra điều xấu.', '大雨のおそれがあります。', 'Chỉ dùng cho việc tiêu cực, hay gặp trong bản tin và cảnh báo.', 2),
(424, 88, 91, 'N + にほかならない', 'Chính là chứ không gì khác — Khẳng định mạnh rằng đó đúng là điều đó.', '成功は努力の結果にほかならない。', 'Trang trọng, hay dùng khi kết luận nguyên nhân: 努力の結果にほかならない.', 3),
(425, 88, 91, 'Thể thường + わけではない', 'Không hẳn là — Phủ định một phần, không phủ định hoàn toàn.', '嫌いなわけではないが、あまり食べない。', 'Khác わけがない (phủ định tuyệt đối) và わけだ (thảo nào). Ba mẫu rất dễ lẫn.', 4),
(426, 88, 91, 'N なり N + なり', 'Hoặc là hoặc là — Đưa ra vài lựa chọn để người nghe tự chọn.', '電話なりメールなりで連絡してください。', 'Vế sau thường là đề nghị hoặc mệnh lệnh. Khác たり (liệt kê hành động).', 5),
(427, 89, 92, 'N + に関して / に関する', 'Liên quan đến — Nêu đề tài, trang trọng hơn について.', 'この件に関しては後日ご連絡します。', 'Dạng định ngữ là に関する: 環境に関する研究. Nghĩa gần について nhưng cứng hơn, hay dùng trong văn bản.', 1),
(428, 89, 92, 'V thể ます (bỏ ます) + かねない', 'Có thể dẫn đến (điều xấu) — Khả năng xảy ra hậu quả không mong muốn.', 'そんな運転では事故を起こしかねない。', 'Chỉ dùng cho việc xấu. Đừng nhầm với かねる (không thể làm được).', 2),
(429, 89, 92, 'Thể thường + に相違ない', 'Chắc chắn là — Khẳng định chắc chắn, dạng văn viết của に違いない.', '犯人はこの部屋にいたに相違ない。', 'Cứng hơn に違いない, hay gặp trong văn bản pháp lý và báo cáo.', 3),
(430, 89, 92, 'Thể thường + とは限らない', 'Chưa chắc đã — Không phải lúc nào cũng đúng như vậy.', '高いものが必ずしもいいとは限らない。', 'Hay đi với 必ずしも để nhấn mạnh: 必ずしも〜とは限らない.', 4),
(431, 89, 92, 'N + といえば', 'Nhắc đến thì — Lấy từ khoá vừa nghe để chuyển sang chủ đề liên quan.', '京都といえば、お寺が有名ですね。', 'Dạng khác といったら. Cách chuyển đề tài rất tự nhiên trong hội thoại.', 5),
(432, 90, 93, 'V từ điển / N + に際して', 'Nhân dịp, khi — Vào đúng dịp làm một việc quan trọng.', '卒業に際して、一言申し上げます。', 'Chỉ dùng cho dịp đặc biệt, không dùng cho việc thường ngày. Trang trọng, hay gặp trong diễn văn.', 1),
(433, 90, 93, 'V thể ます (bỏ ます) + かねる', 'Khó lòng, không thể — Không thể làm vì lý do lập trường hoặc cảm xúc, nói giảm rất lịch sự.', 'その件についてはお答えしかねます。', 'Hay dùng trong dịch vụ khách hàng để từ chối khéo: 分かりかねます.', 2),
(434, 90, 93, 'Thể thường + というものだ', 'Thế mới gọi là — Đưa ra nhận định mang tính chân lý chung.', '助け合うのが友達というものだ。', 'Phủ định というものではない = không hẳn là như vậy.', 3),
(435, 90, 93, 'V-ない + ことはない', 'Cũng không phải là không — Khẳng định dè dặt, thừa nhận một khả năng nhỏ.', '食べられないことはないが、好きではない。', 'Cách nói vòng, nhẹ nhàng. Đừng nhầm với ことはない (không cần phải).', 4),
(436, 90, 93, 'N + というと', 'Nói đến là nghĩ ngay — Nghe từ đó là liên tưởng ngay tới điều gì.', '日本の食べ物というと、寿司を思い出す。', 'Gần といえば. Còn dùng để xác nhận lại: というと、明日ですか.', 5),
(437, 91, 94, 'V từ điển / N + に当たって', 'Trước khi bước vào — Vào thời điểm bắt đầu một việc lớn, thường mang tính tích cực.', '新年を迎えるに当たって、目標を立てた。', 'Gần với に際して. Không dùng cho việc đã xảy ra hay việc vặt.', 1),
(438, 91, 94, 'V thể ます (bỏ ます) + 得る / 得ない', 'Có thể, không thể — Nêu khả năng về mặt lý thuyết.', '誰にでも起こり得ることです。', '得る đọc là うる hoặc える, phủ định luôn là えない. あり得ない = không thể nào.', 2),
(439, 91, 94, 'Thể thường + に決まっている', 'Chắc chắn là rồi — Khẳng định chủ quan mạnh, giọng văn nói.', 'そんな話、嘘に決まっている。', 'Thân mật hơn に違いない nhiều. Không dùng trong văn bản trang trọng.', 3),
(440, 91, 94, 'V từ điển / V-ない + ことになっている', 'Theo quy định là — Nêu quy tắc, lịch trình hoặc thông lệ đã được định sẵn.', '会議は毎週月曜に開かれることになっている。', 'Khác với ことになった (vừa được quyết định) ở chỗ ている là trạng thái duy trì.', 4),
(441, 91, 94, 'Thể thường / N + にしては', 'So với thì lại — Kết quả không tương xứng với tiêu chuẩn đã nêu.', '初めてにしては上手だ。', 'Khác わりに ở chỗ にしては cần một chuẩn cụ thể rõ ràng.', 5),
(442, 92, 95, 'V từ điển / N + に先立って', 'Trước khi — Làm việc chuẩn bị trước một sự kiện chính thức.', '開会に先立って、写真撮影を行います。', 'Nhấn mạnh trình tự trước sau, trang trọng hơn 前に nhiều.', 1),
(443, 92, 95, 'V thể ます (bỏ ます) + がたい', 'Khó mà — Về mặt tâm lý hoặc đạo lý thì khó làm được.', '彼の話は信じがたい。', 'Khác với にくい (khó về mặt kỹ thuật). 信じがたい, 忘れがたい là những cụm hay gặp.', 2),
(444, 92, 95, 'V thể ます (bỏ ます) + っこない', 'Làm gì có chuyện — Phủ định mạnh khả năng, giọng văn nói suồng sã.', 'そんな難しい問題、分かりっこないよ。', 'Chỉ dùng trong hội thoại thân mật. Tương đương はずがない.', 3),
(445, 92, 95, 'Thể thường + ものがある', 'Có cái gì đó thật — Cảm nhận được một điều gì đó đáng kể, mang tính đánh giá.', '彼の演奏には心を打つものがある。', 'Chủ ngữ thường không phải người cụ thể. Hay dùng khi khen hoặc nhận xét.', 4),
(446, 92, 95, 'Thể thường + としたら / とすれば', 'Nếu giả sử — Giả định một điều kiện rồi suy ra kết quả.', '宝くじが当たったとしたら、何を買いますか。', 'Thuần giả định, không dùng cho việc chắc chắn xảy ra.', 5),
(447, 93, 96, 'N + をめぐって', 'Xoay quanh — Nhiều ý kiến hoặc tranh luận xoay quanh một vấn đề.', '新しい法律をめぐって議論が続いている。', 'Vế sau thường là 議論, 対立, 争う. Dạng định ngữ là をめぐる.', 1),
(448, 93, 96, 'V thể ます (bỏ ます) + 抜く', 'Làm đến cùng — Vượt qua khó khăn để hoàn thành trọn vẹn.', '最後まで走り抜いた。', 'Khác với きる (hết sạch) ở chỗ 抜く nhấn mạnh sự bền bỉ vượt khó.', 2),
(449, 93, 96, 'V thể ます (bỏ ます) / N + 気味', 'Hơi hơi, có vẻ — Cảm thấy hơi nghiêng về trạng thái đó, thường không tốt.', '風邪気味なので早退します。', 'Nhẹ hơn がち. Hay gặp: 風邪気味, 疲れ気味, 遅れ気味.', 3),
(450, 93, 96, 'V-る / V-ている + ようでは', 'Nếu cứ như thế thì — Nếu duy trì tình trạng không tốt đó thì kết quả sẽ xấu.', 'そんなに休むようでは、合格できないよ。', 'Vế sau luôn tiêu cực, mang giọng cảnh báo hoặc trách móc.', 4),
(451, 93, 96, 'V từ điển + つもりはない', 'Hoàn toàn không định — Phủ định dứt khoát ý định làm gì.', '会社を辞めるつもりはありません。', 'Mạnh hơn つもりではない. Thể hiện lập trường rõ ràng.', 5),
(452, 94, 97, 'N + を中心に', 'Lấy làm trung tâm — Đặt cái gì làm trọng tâm rồi triển khai xung quanh.', '若者を中心に人気が広がっている。', 'Dạng định ngữ là を中心とする. Hay dùng khi mô tả phạm vi lan toả.', 1),
(453, 94, 97, 'V thể ます (bỏ ます) + つつある', 'Đang dần — Quá trình đang tiến triển theo một hướng.', '景気は回復しつつある。', 'Trang trọng hơn ている, nhấn mạnh sự biến đổi liên tục.', 2),
(454, 94, 97, 'A bỏ い / V thể ます (bỏ ます) + げ', 'Ra vẻ, trông — Biểu hiện ra bên ngoài một cảm xúc.', '彼女は寂しげな表情をしていた。', 'Chia như tính từ đuôi な: 楽しげな声. Hay gặp: 寂しげ, 得意げ, 言いたげ.', 3),
(455, 94, 97, 'V từ điển + くらいなら', 'Thà còn hơn là — Thà chọn phương án kia còn hơn phải chịu điều này.', 'あんな人に頼むくらいなら、自分でやる。', 'Vế sau thường có ほうがましだ hoặc ほうがいい.', 4),
(456, 94, 97, 'V-て + はいられない', 'Không thể cứ mãi — Hoàn cảnh không cho phép tiếp tục ở trạng thái đó.', 'こうしてはいられない、急ごう。', 'Thể hiện sự sốt ruột hoặc cấp bách.', 5),
(457, 95, 98, 'N + をもとに', 'Dựa trên — Lấy cái gì làm nguyên liệu hoặc căn cứ để tạo ra cái mới.', '実話をもとに映画が作られた。', 'Khác với に基づいて ở chỗ をもとに là lấy làm chất liệu, に基づいて là tuân theo quy tắc.', 1),
(458, 95, 98, 'V thể ます (bỏ ます) + つつ', 'Vừa vừa, tuy nhưng — Hai hành động đồng thời, hoặc nghĩa nhượng bộ.', '結果を気にしつつ、待っている。', 'Nghĩa đồng thời giống ながら nhưng văn viết. Nghĩa nhượng bộ hay đi với も: 悪いと知りつつも.', 2),
(459, 95, 98, 'N + 抜きで / は抜きにして', 'Bỏ qua, không tính — Loại bỏ phần nào đó ra khỏi việc đang làm.', '冗談は抜きにして、本題に入ろう。', 'Hay gặp: 冗談は抜きにして (nói nghiêm túc nhé), 朝食抜きで.', 3),
(460, 95, 98, 'N + にして', 'Mãi đến mới, vừa lại vừa — Đến tận giai đoạn đó mới xảy ra, hoặc mang cả hai tính chất.', '五十歳にして初めて絵を習い始めた。', 'Hai nghĩa: 五十歳にして (mãi đến năm mươi tuổi mới) và 医者にして作家 (vừa là bác sĩ vừa là nhà văn).', 4),
(461, 95, 98, 'V-て + しようがない', 'Hết cách, quá đỗi — Dạng trang trọng hơn của しょうがない.', '退屈でしようがない。', 'Nghĩa gần てたまらない. Chỉ dùng cho cảm giác của bản thân.', 5),
(462, 96, 99, 'N + に基づいて', 'Căn cứ theo — Làm theo đúng quy định, dữ liệu hoặc nguyên tắc đã có.', '法律に基づいて処理します。', 'Dạng định ngữ に基づく. Trang trọng, hay gặp trong văn bản pháp lý.', 1),
(463, 96, 99, 'V từ điển + 一方だ', 'Ngày càng — Xu hướng chỉ tiến về một phía, thường là xấu đi.', '物価は上がる一方だ。', 'Khác với 一方で (mặt khác). Vế trước phải là động từ chỉ sự biến đổi.', 2),
(464, 96, 99, 'N + を込めて', 'Với trọn, dồn cả — Dồn tình cảm hoặc tâm huyết vào việc gì.', '心を込めて手紙を書いた。', 'Chỉ dùng với danh từ trừu tượng chỉ tình cảm: 心, 愛, 感謝, 祈り.', 3),
(465, 96, 99, 'V từ điển + ほどのことではない', 'Không đến mức phải — Việc đó nhỏ, không đáng để phản ứng mạnh như vậy.', 'わざわざ来ていただくほどのことではありません。', 'Hay dùng để trấn an. Gần với ことはない nhưng nhấn mạnh mức độ.', 4),
(466, 96, 99, 'Thể thường + だけのことはある', 'Xứng đáng là — Kết quả tương xứng với công sức hoặc danh tiếng, là lời khen.', 'さすが十年練習しただけのことはある。', 'Gần だけあって nhưng đứng cuối câu.', 5),
(467, 97, 100, 'N + に沿って', 'Dọc theo, theo đúng — Đi dọc theo vật gì, hoặc làm theo đúng phương châm.', '川に沿って道が続いている。', 'Nghĩa cụ thể: 川に沿って歩く. Nghĩa trừu tượng: 方針に沿って進める.', 1),
(468, 97, 100, 'Thể thường + 一方（で）', 'Mặt khác — Nêu hai mặt song song hoặc đối lập của cùng một sự việc.', '彼は厳しい一方で、優しいところもある。', 'Khác hẳn 一方だ. Hai vế phải cùng chủ đề.', 2),
(469, 97, 100, 'N + を問わず', 'Bất kể — Không phân biệt, không đặt điều kiện về mặt nào đó.', '年齢を問わず応募できます。', 'Hay gặp trong tin tuyển dụng: 経験を問わず, 年齢性別を問わず.', 3),
(470, 97, 100, 'V-て + はじめて', 'Sau khi mới — Chỉ sau khi trải qua việc đó mới nhận ra hoặc làm được điều kia.', '親になってはじめて、親の気持ちが分かった。', 'Vế sau thường là 分かる, 気づく. Nhấn mạnh trải nghiệm là điều kiện cần.', 4),
(471, 97, 100, 'N + に加えて', 'Thêm vào đó — Bổ sung thêm yếu tố nữa vào điều đã có.', '雨に加えて風も強くなった。', 'Trang trọng hơn そのうえ. Hai yếu tố cùng chiều.', 5),
(472, 98, 101, 'Khoảng thời gian hoặc phạm vi + にわたって', 'Suốt, trải khắp — Phạm vi hoặc thời gian rộng lớn trải dài.', '工事は三年にわたって続いた。', 'Dạng định ngữ にわたる. Nhấn mạnh quy mô lớn, không dùng cho khoảng ngắn.', 1),
(473, 98, 101, 'Thể thường + 反面', 'Trái lại, mặt trái là — Nêu hai mặt trái ngược của cùng một đối tượng.', '便利な反面、危険も多い。', 'Gần với 一方で nhưng nhấn mạnh sự tương phản rõ hơn.', 2),
(474, 98, 101, 'V-て + からでないと', 'Nếu chưa thì không — Phải xong việc trước mới làm được việc sau.', '上司に確認してからでないと、返事できません。', 'Vế sau bắt buộc phủ định. Dạng khác てからでなければ.', 3),
(475, 98, 101, 'V từ điển + には', 'Để mà thì cần — Nêu mục đích rồi đưa ra điều kiện cần thiết.', '日本で働くには、ビザが必要です。', 'Vế sau thường là 必要だ, いい, 大切だ. Khác ために ở chỗ には hướng tới đánh giá điều kiện.', 4),
(476, 98, 101, 'N + を除いて', 'Ngoại trừ — Loại một đối tượng ra khỏi phạm vi đang nói.', '日曜を除いて毎日営業しています。', 'Dạng khác を除き. Trang trọng hơn 以外.', 5),
(477, 99, 102, 'N + を通じて / を通して', 'Thông qua, suốt — Nêu phương tiện trung gian, hoặc khoảng thời gian liên tục.', 'インターネットを通じて世界とつながる。', 'Nghĩa phương tiện: 友人を通じて知り合った. Nghĩa thời gian: 一年を通して暖かい.', 1),
(478, 99, 102, 'N + に反して', 'Trái với — Kết quả đi ngược lại điều mong đợi hoặc dự đoán.', '予想に反して、彼が勝った。', 'Dạng định ngữ に反する. Hay đi với 予想, 期待, 予測.', 2),
(479, 99, 102, 'V-て + 以来', 'Kể từ khi — Từ mốc đó đến nay trạng thái vẫn tiếp diễn.', '日本に来て以来、彼に会っていない。', 'Không dùng cho khoảng thời gian ngắn. Vế sau thường là tình trạng kéo dài.', 3),
(480, 99, 102, 'Thể thường + ことになる', 'Tức là, hoá ra là — Kết luận logic rút ra từ điều đã biết.', 'これで三回目ということになる。', 'Khác với ことになる nghĩa được quyết định. Ở đây là suy luận: 三年いたことになる.', 4),
(481, 99, 102, 'N + 以外に', 'Ngoài ra còn — Nêu thêm điều khác ngoài cái đã biết.', '彼以外に知っている人はいない。', '以外は = ngoài ra thì không. 以外に = ngoài ra còn có.', 5),
(482, 100, 103, 'V thể ます (bỏ ます) + 次第', 'Ngay khi xong là — Việc gì vừa xong thì lập tức làm việc tiếp theo.', '到着次第、ご連絡します。', 'Vế sau không được là quá khứ. Khác với たらすぐ ở chỗ 次第 trang trọng và chỉ dùng cho tương lai.', 1),
(483, 100, 103, 'Thể thường / N + にもかかわらず', 'Mặc dù vậy mà — Kết quả xảy ra bất chấp điều kiện đã nêu.', '雨にもかかわらず、大勢の人が集まった。', 'Trang trọng hơn のに và không mang cảm xúc trách móc.', 2),
(484, 100, 103, 'V từ điển + につけ', 'Mỗi khi là lại — Cứ gặp việc đó là cảm xúc nào đó lại trào lên.', 'この写真を見るにつけ、母を思い出す。', 'Vế sau là cảm xúc hoặc suy nghĩ tự nhiên, không phải hành động. Dạng lặp: 何かにつけ.', 3),
(485, 100, 103, 'V-た + 上で', 'Sau khi rồi mới — Hoàn tất bước quan trọng trước rồi mới tiến hành bước sau.', '契約内容を確認した上で、署名してください。', 'Trang trọng, hay gặp trong thủ tục. Khác てから ở chỗ 上で nhấn mạnh sự cân nhắc.', 4),
(486, 100, 103, 'N + にかけても', 'Dù có phải đánh đổi — Thề nguyện, lấy điều quý giá ra bảo đảm.', '命にかけても守ります。', 'Cụm cố định: 命にかけても, 名誉にかけても.', 5),
(487, 101, 104, 'N + 次第だ / 次第で', 'Tuỳ thuộc vào — Kết quả thay đổi tuỳ theo yếu tố nào đó.', '成功するかどうかは努力次第だ。', 'Đừng nhầm với V-ます + 次第 (ngay khi). Ở đây nối sau danh từ.', 1),
(488, 101, 104, 'Thể thường / N + にしても', 'Dù có là, kể cả — Nhượng bộ: dù trong trường hợp đó thì kết luận vẫn vậy.', '冗談にしても、言い過ぎだ。', 'Dạng lặp にしても〜にしても = dù A hay B. Gần với としても.', 2),
(489, 101, 104, 'V từ điển / N + に伴って', 'Cùng với, kéo theo — Việc này thay đổi thì việc kia thay đổi theo.', '人口の増加に伴って、住宅が不足している。', 'Trang trọng. Dạng định ngữ に伴う.', 3),
(490, 101, 104, 'N の + 上での', 'Trong quá trình, khi — Nêu bối cảnh mà điều gì đó phát sinh.', 'これは仕事の上での付き合いです。', 'Hay gặp: 生活する上での問題, 仕事の上での付き合い.', 4),
(491, 101, 104, 'Thể thường + ものですから', 'Là bởi vì ạ — Dạng lịch sự của ものだから, dùng để biện minh.', '道が混んでいたものですから、遅れました。', 'Giọng nhẹ nhàng, hay dùng khi xin lỗi.', 5),
(492, 102, 105, 'N + 上', 'Về mặt — Xét trên phương diện nào đó.', '健康上の理由で退職しました。', 'Đọc là じょう: 法律上, 健康上, 仕事上. Không nhầm với 上で (sau khi).', 1),
(493, 102, 105, 'Thể thường / N + にしろ / にせよ', 'Dù là — Giống にしても nhưng văn viết và cứng hơn.', '理由が何にせよ、遅刻は遅刻だ。', 'Hay dùng cặp: いずれにせよ (dù thế nào đi nữa).', 2),
(494, 102, 105, 'V từ điển / N + とともに', 'Cùng với, đồng thời — Hai việc xảy ra song song, hoặc cùng ai đó làm gì.', '年をとるとともに、体力が落ちる。', 'Ba nghĩa: cùng lúc, cùng với ai, và thay đổi song song.', 3),
(495, 102, 105, 'N + のはずみで', 'Do lỡ đà, trong lúc vô ý — Việc xảy ra ngoài ý muốn do một động tác bất chợt.', '転んだはずみで手をついた。', 'Hay gặp: 勢いのはずみで, 何かのはずみで.', 4),
(496, 102, 105, 'N の + ことだから', 'Vì là nên chắc — Dựa vào tính cách quen thuộc của ai đó mà suy đoán.', '彼のことだから、また遅れるだろう。', 'Chỉ dùng với người mà cả hai bên đều biết rõ.', 5),
(497, 103, 106, 'Thể thường + 以上（は）', 'Đã thì phải — Đã ở trong tình huống đó thì đương nhiên phải làm theo.', '約束した以上、守らなければならない。', 'Vế sau thường là ý chí, nghĩa vụ hoặc khuyên nhủ. Gần với からには.', 1),
(498, 103, 106, 'V-た + ところ', 'Khi làm thử thì — Làm một việc rồi phát hiện ra kết quả, thường bất ngờ.', '問い合わせたところ、在庫があるとのことだった。', 'Khác với たら ở chỗ たところ là văn viết và chỉ dùng cho việc đã xảy ra.', 2),
(499, 103, 106, 'V từ điển / N + にしたがって', 'Theo, càng thì càng — Biến đổi song song, hoặc tuân theo chỉ dẫn.', '山を登るにしたがって、気温が下がった。', 'Hai nghĩa: 指示にしたがう (tuân theo) và 上がるにしたがって (càng lên càng).', 3),
(500, 103, 106, 'ついに + V', 'Cuối cùng thì — Sau thời gian dài chờ đợi thì cũng xảy ra.', 'ついに完成した。', 'Kết quả có thể tốt hoặc xấu. Khác とうとう ở chỗ ついに trang trọng hơn.', 4);
INSERT INTO grammar_point (id, lesson_id, tag_id, pattern, meaning, example, note, order_index) VALUES
(501, 103, 106, 'Thể thường + というのは', 'Sở dĩ là vì, cái gọi là — Giải thích lý do hoặc định nghĩa một khái niệm.', '行けません。というのは急用ができたからです。', 'というのは〜からだ là cấu trúc giải thích lý do rất hay gặp.', 5),
(502, 104, 107, 'Thể thường + からには', 'Đã thì — Nhấn mạnh quyết tâm hoặc trách nhiệm đi kèm.', '引き受けたからには、最後までやる。', 'Gần 以上は nhưng cảm xúc mạnh hơn, thường kèm quyết tâm của người nói.', 1),
(503, 104, 107, 'V-た + とたん', 'Vừa mới thì lập tức — Ngay khoảnh khắc việc trước xảy ra thì việc sau xảy ra ngay, thường ngoài dự tính.', 'ドアを開けたとたん、猫が飛び出した。', 'Vế sau không được là ý chí hay mệnh lệnh. Luôn là việc đã xảy ra.', 2),
(504, 104, 107, 'V từ điển / N + につれて', 'Càng thì càng — Hai bên biến đổi tỉ lệ với nhau một cách tự nhiên.', '時間がたつにつれて、痛みは和らいだ。', 'Chỉ dùng cho biến đổi dần dần, không dùng cho việc xảy ra tức thì.', 3),
(505, 104, 107, 'N + によっては', 'Tuỳ trường hợp có khi — Trong một số trường hợp thì khác đi.', '人によっては辛く感じるかもしれない。', 'Khác によって (tuỳ theo, nêu quy luật chung) ở chỗ によっては chỉ nói về một phần.', 4),
(506, 104, 107, 'V-て + こそ', 'Có thì mới — Chỉ khi làm việc đó thì mới đạt được kết quả thật sự.', '苦労してこそ、喜びも大きい。', 'Nhấn mạnh điều kiện thiết yếu. Vế sau thường tích cực.', 5),
(507, 105, 108, 'Thể thường + だけに', 'Chính vì nên càng — Vì lý do đó nên mức độ càng cao hơn bình thường.', '期待していただけに、残念だ。', 'Có thể mang nghĩa tích cực lẫn tiêu cực. Khác với だけあって (chỉ dùng khen).', 1),
(508, 105, 108, 'V từ điển + か + V-ない + かのうちに', 'Vừa mới chưa kịp thì — Việc trước còn chưa dứt hẳn thì việc sau đã xảy ra.', 'ベルが鳴るか鳴らないかのうちに、彼は教室を出た。', 'Nhấn mạnh hai việc gần như cùng lúc. Văn viết.', 2),
(509, 105, 108, 'Thể thường + からといって', 'Không phải cứ là — Không thể chỉ vì lý do đó mà kết luận như vậy.', '高いからといって、いいとは限らない。', 'Vế sau bắt buộc phủ định. Hay đi với わけではない.', 3),
(510, 105, 108, 'Thể thường + ほどだ', 'Đến mức là — Nêu ví dụ cụ thể để minh hoạ mức độ.', '足が痛くて歩けないほどだ。', 'Dạng giữa câu là ほどの. Khác ほど〜ない (không bằng).', 4),
(511, 106, 109, 'Thể thường + だけあって', 'Quả không hổ danh — Xứng đáng với danh tiếng hoặc điều kiện đã có, luôn là lời khen.', 'さすが専門家だけあって、説明が分かりやすい。', 'Không dùng cho việc xấu. Chủ ngữ thường là người hoặc vật được đánh giá cao.', 1),
(512, 106, 109, 'V từ điển + やいなや', 'Vừa là ngay lập tức — Hai việc nối nhau tức thì, văn viết trang trọng.', '彼は家に着くやいなや、寝てしまった。', 'Cứng hơn とたん. Không dùng trong hội thoại thường ngày.', 2),
(513, 106, 109, 'N + からして', 'Ngay cả cũng, xét từ — Lấy một ví dụ tiêu biểu để suy ra toàn thể.', '名前からして怪しい店だ。', 'Hai nghĩa: 名前からして変だ (ngay cái tên đã lạ) và 様子からして (xét từ dáng vẻ).', 3),
(514, 106, 109, 'Thể thường + ばかりでなく', 'Không chỉ mà còn — Bổ sung thêm phạm vi ngoài điều đã nêu.', '彼は日本語ばかりでなく韓国語も話す。', 'Gần だけでなく. Vế sau thường có も.', 4),
(515, 107, 110, 'Thể thường + ものだから', 'Là tại vì — Biện minh cho việc mình làm, mang tính bào chữa.', '道が込んでいたものだから、遅れました。', 'Chỉ dùng để giải thích lý do cho bản thân, không dùng ra lệnh hay rủ rê ở vế sau.', 1),
(516, 107, 110, 'V thể khả năng + ものなら', 'Nếu mà có thể thì — Giả định điều khó xảy ra, kèm mong muốn của người nói.', '戻れるものなら、学生時代に戻りたい。', 'Vế sau thường là たい hoặc のに. Khác với ものだから (biện minh).', 2),
(517, 107, 110, 'N + からすると / からすれば', 'Xét từ góc độ — Đứng từ lập trường hoặc căn cứ nào đó mà phán đoán.', 'あの成績からすると、合格は難しい。', 'Gần にとっては nhưng からすると nhấn mạnh căn cứ suy luận.', 3),
(518, 107, 110, 'N + にかけては', 'Về khoản thì — Về lĩnh vực đó thì không ai bằng, luôn là lời khen.', '料理にかけては彼女の右に出る者はいない。', 'Chỉ dùng khen. Vế sau thường là 自信がある, 誰にも負けない.', 4),
(519, 108, 111, 'Thể thường + ものの', 'Tuy là nhưng — Thừa nhận vế trước nhưng kết quả không như mong đợi.', '買ったものの、一度も使っていない。', 'Văn viết. Gần với が, けれど nhưng trang trọng hơn.', 1),
(520, 108, 111, 'V-た / N の + あげく', 'Sau bao nhiêu rốt cuộc — Sau một quá trình dài loay hoay thì dẫn tới kết quả, thường không tốt.', 'さんざん迷ったあげく、何も買わなかった。', 'Khác với 末に (trung tính hoặc tốt) ở chỗ あげく hầu như luôn tiêu cực.', 2),
(521, 108, 111, 'N + にとって', 'Đối với — Nêu lập trường của người hoặc tổ chức để đánh giá.', '私にとって家族が一番大切だ。', 'Vế sau thường là tính từ đánh giá. Khác với に対して (hướng hành động tới).', 3),
(522, 108, 111, 'N + に応じて', 'Tuỳ theo mà linh hoạt — Thay đổi cho phù hợp với tình hình hoặc yêu cầu.', '収入に応じて税金が決まる。', 'Dạng định ngữ に応じた. Hay gặp: 収入に応じて, 状況に応じて.', 4),
(523, 109, 112, 'V từ điển / V-ない + ことだ', 'Nên, cần phải — Khuyên bảo hoặc nêu điều nên làm, giọng của người có kinh nghiệm.', '上手になりたければ、毎日練習することだ。', 'Không dùng với người trên. Khác với ものだ (lẽ thường tình).', 1),
(524, 109, 112, 'V-た / N の + 末に', 'Sau cùng thì — Sau khi trải qua quá trình dài rồi đi đến kết luận.', 'よく考えた末に、留学を決めた。', 'Kết quả có thể tốt, khác với あげく. Hay đi với 考えた末に, 努力の末に.', 2),
(525, 109, 112, 'N の / V từ điển + あまり', 'Vì quá mà — Cảm xúc hoặc mức độ quá lớn dẫn đến kết quả bất thường.', '驚きのあまり、声も出なかった。', 'Hay đi với cảm xúc mạnh: 心配, 驚き, うれしさ. Vế sau thường tiêu cực.', 3),
(526, 109, 112, 'N + にこたえて', 'Đáp lại — Thực hiện theo mong đợi hoặc yêu cầu của ai.', '皆様のご期待にこたえて、新商品を発売します。', 'Hay đi với 期待, 要望, 声援. Dạng định ngữ にこたえる.', 4),
(527, 110, 113, 'V từ điển + ことはない', 'Không cần phải — Trấn an rằng việc đó là không cần thiết.', 'そんなに心配することはないよ。', 'Khác với ことがない (chưa từng). Hay dùng để an ủi.', 1),
(528, 110, 113, 'V từ điển / Thể thường + かぎり（は）', 'Chừng nào còn — Trong phạm vi điều kiện đó còn duy trì.', '体が丈夫なかぎり、働き続けたい。', 'ないかぎり = nếu không thì. できるかぎり = hết mức có thể.', 2),
(529, 110, 113, 'V từ điển + まい', 'Quyết không, chắc không — Ý chí phủ định mạnh, hoặc suy đoán phủ định.', '二度と嘘はつくまいと決めた。', 'Nhóm 2 và bất quy tắc có thể dùng cả hai dạng: 食べまい / 食べるまい. Văn viết.', 3),
(530, 110, 113, 'N + をきっかけに', 'Nhân cơ hội, từ đó mà — Một sự kiện trở thành khởi điểm cho thay đổi.', '留学をきっかけに、考え方が変わった。', 'Dạng khác をきっかけとして. Vế sau là thay đổi bắt đầu từ đó.', 4),
(531, 111, 114, 'Thể thường + ことから', 'Từ việc đó mà — Nêu căn cứ dẫn đến một kết luận hoặc tên gọi.', '窓が割れていることから、泥棒が入ったと分かった。', 'Hay dùng để giải thích nguồn gốc tên gọi hoặc lý do phán đoán.', 1),
(532, 111, 114, 'V từ điển / V-た + かぎりでは', 'Theo như mà tôi — Giới hạn phán đoán trong phạm vi thông tin mình có.', '私が知るかぎりでは、彼は正直な人だ。', 'Hay đi với 見る, 聞く, 知る, 調べる. Hàm ý có thể chưa đầy đủ.', 2),
(533, 111, 114, 'V thể ます (bỏ ます) + ようがない', 'Không còn cách nào — Muốn làm cũng không có cách nào thực hiện.', '連絡先が分からないので、知らせようがない。', 'Khác với できない ở chỗ ようがない nhấn mạnh không có phương tiện, không có cách.', 3),
(534, 111, 114, 'N + を契機に', 'Lấy làm bước ngoặt — Giống をきっかけに nhưng trang trọng hơn hẳn.', 'この事故を契機に、安全基準が見直された。', 'Văn viết. Hay gặp trong báo cáo và tin tức.', 4),
(535, 112, 115, 'A / V-た + ことに', 'Thật là — Nêu cảm xúc của người nói trước khi kể sự việc.', '驚いたことに、彼は全部知っていた。', 'Chỉ dùng với từ chỉ cảm xúc: 驚いたことに, 残念なことに, うれしいことに.', 1),
(536, 112, 115, 'N + に限って', 'Chỉ riêng lại, riêng thì — Chỉ đúng vào lúc đó lại xảy ra chuyện xui, hoặc khẳng định riêng người đó thì không.', '急いでいる時に限って、電車が遅れる。', 'Hai nghĩa: 急ぐ日に限って渋滞する (xui) và うちの子に限ってそんなことはしない (tin tưởng).', 2),
(537, 112, 115, 'V-ない bỏ ない + ずにはいられない', 'Không thể không — Không kìm được, buộc phải làm theo cảm xúc.', 'この話を聞くと、笑わずにはいられない。', 'する → せずにはいられない. Dạng khác ないではいられない (văn nói hơn).', 3),
(538, 112, 115, 'N + 上は', 'Về mặt thì — Xét trên phương diện chính thức hoặc hình thức.', '表面上は問題ないように見える。', 'Hay gặp: 法律上は, 表面上は, 建前上は. Hàm ý thực tế có thể khác.', 4),
(539, 113, 116, 'Thể thường / N + どころか', 'Đừng nói là, trái lại còn — Phủ định mạnh điều vừa nêu và đưa ra thực tế trái ngược.', '漢字どころか、ひらがなも読めない。', 'Vế sau thường ngược hẳn với vế trước, gây bất ngờ.', 1),
(540, 113, 116, 'N + に限らず', 'Không chỉ riêng — Không giới hạn ở phạm vi đó mà còn rộng hơn.', '日本に限らず、世界中で問題になっている。', 'Vế sau thường có も. Gần だけでなく nhưng nhấn mạnh phạm vi.', 2),
(541, 113, 116, 'V-て / A-くて + たまらない', 'Đến không chịu nổi — Cảm giác hoặc mong muốn mạnh đến mức không chịu được.', '暑くてたまらない。', 'Chỉ dùng cho cảm giác của bản thân. Về người khác phải thêm ようだ, らしい.', 3),
(542, 113, 116, 'V từ điển + はずだった', 'Lẽ ra đã phải — Dự định hoặc kỳ vọng nhưng thực tế không xảy ra.', '今日着くはずだったのに、まだ届かない。', 'Mang cảm giác tiếc nuối hoặc bất ngờ. Vế sau thường nêu thực tế trái ngược.', 4),
(543, 114, 117, 'V từ điển / N + どころではない', 'Không phải lúc để — Hoàn cảnh không cho phép làm việc đó.', '忙しくて、旅行どころではない。', 'Khác với どころか ở chỗ どころではない nhấn mạnh hoàn cảnh cấp bách.', 1),
(544, 114, 117, 'Thể thường / N + のみならず', 'Không những mà còn — Dạng văn viết trang trọng của だけでなく.', '彼は学者のみならず、実業家でもある。', 'Vế sau thường có も hoặc まで. Rất hay gặp trong văn bản và báo chí.', 2),
(545, 114, 117, 'V-て / A-くて + ならない', 'Cứ mãi, không sao dứt được — Cảm xúc hoặc suy nghĩ tự nhiên trào lên không kiểm soát được.', '残念でならない。', 'Trang trọng hơn たまらない. Hay đi với 気がしてならない, 残念でならない.', 3),
(546, 114, 117, 'V từ điển + つもりだった', 'Đã định nhưng — Ý định trong quá khứ nhưng không thực hiện được.', '早く帰るつもりだったが、残業になった。', 'Dạng khác つもりはなかった = tôi không hề có ý định.', 4),
(547, 115, 118, 'Thể thường + ばかりか', 'Không những mà còn — Bổ sung thêm điều vượt xa mức vừa nêu.', '彼は英語ばかりか、フランス語も話せる。', 'Mạnh hơn だけでなく. Vế sau thường có も, まで.', 1),
(548, 115, 118, 'N + はもとより', 'Đã đành là, khỏi nói — Điều trước là hiển nhiên, điều sau mới đáng nói.', '子供はもとより大人も楽しめる。', 'Trang trọng hơn はもちろん. Vế sau thường có も.', 2),
(549, 115, 118, 'V-て / A-くて + しかたがない', 'Hết cách, quá đỗi — Mức độ cảm giác quá lớn, không làm gì được.', '眠くてしかたがない。', 'Văn nói rút gọn しょうがない. Nghĩa gần たまらない.', 3),
(550, 115, 118, 'V-た / N の + つもりで', 'Cứ coi như là — Hành động với tâm thế như thể điều đó là thật.', '死んだつもりで頑張ります。', 'Hay gặp: 死んだつもりで, 新人のつもりで.', 4),
(551, 116, 119, 'Thể thường + ばかりに', 'Chỉ vì mà — Chỉ vì một lý do nhỏ mà dẫn đến hậu quả xấu.', '一言言わなかったばかりに、誤解された。', 'Luôn mang ý tiếc nuối. Khác hẳn với ばかりか.', 1),
(552, 116, 119, 'N + はともかく', 'Khoan hãy nói tới — Tạm gác điều đó sang một bên để bàn điều quan trọng hơn.', '味はともかく、量は多い。', 'Dạng khác はさておき. Điều được gác lại thường ít quan trọng hơn.', 2),
(553, 116, 119, 'V từ điển + よりほかない / ほかない', 'Chỉ còn cách — Không còn lựa chọn nào khác ngoài việc đó.', '電車が止まったので、歩くよりほかない。', 'Trang trọng hơn しかない. Dạng khác よりほかしかたがない.', 3),
(554, 116, 119, 'Thể thường + にもならない', 'Chẳng ra gì, không thành — Không đạt được cả mức tối thiểu.', 'そんな計画では話にもならない。', 'Cụm hay gặp: 話にもならない, 一円にもならない.', 4),
(555, 117, 120, 'V từ điển + わけにはいかない', 'Không thể (vì lý do xã hội) — Về lý thuyết thì làm được nhưng vì hoàn cảnh hoặc đạo lý nên không thể.', '大事な会議だから、休むわけにはいかない。', 'Khác với できない (không có khả năng). Phủ định ないわけにはいかない = buộc phải làm.', 1),
(556, 117, 120, 'Thể thường / N + にすぎない', 'Chẳng qua chỉ là — Hạ thấp mức độ, nhấn mạnh chỉ có vậy thôi.', 'これは言い訳にすぎない。', 'Hay đi với ただ, ほんの để nhấn mạnh thêm.', 2),
(557, 117, 120, 'V-ない bỏ ない + ざるを得ない', 'Buộc phải — Không muốn nhưng hoàn cảnh buộc phải làm.', '上司の命令なので、従わざるを得ない。', 'する → せざるを得ない. Mang cảm giác miễn cưỡng rõ, khác với しかない (trung tính hơn).', 3),
(558, 117, 120, 'N やら N + やら', 'Nào là nào là, lẫn lộn — Liệt kê nhiều thứ trong tình trạng bối rối hoặc lộn xộn.', 'うれしいやら悲しいやら、複雑な気持ちだ。', 'Mang cảm giác rối rắm, khác với とか (liệt kê trung tính).', 4),
(559, 118, 121, 'N + をおいて', 'Ngoài ra không còn ai khác — Chỉ có duy nhất đối tượng đó là xứng đáng, không có lựa chọn thứ hai.', 'この仕事を任せられるのは、彼をおいてほかにいない。', 'Vế sau bắt buộc phủ định: をおいて〜ない. Luôn mang nghĩa đánh giá cao.', 1),
(560, 118, 121, 'N + を踏まえて', 'Dựa trên, căn cứ vào — Lấy kết quả hoặc bài học trước làm nền để tiến hành bước tiếp.', '前回の反省を踏まえて計画を練り直した。', 'Trang trọng, hay dùng trong họp hành: 結果を踏まえて, 反省を踏まえて.', 2),
(561, 118, 121, '柄にもなく / らしくもない', 'Chẳng có chút nào — Phủ định tuyệt đối sự tồn tại của tính chất nào đó.', '柄にもなく緊張してしまった。', 'Cụm hay gặp: 柄にもない (không hợp với mình), 柄にもなく.', 3),
(562, 119, 122, 'N + をよそに', 'Mặc kệ, phớt lờ — Bỏ ngoài tai sự lo lắng hay phản đối của người khác.', '親の心配をよそに、彼は一人で旅に出た。', 'Hay đi với 心配, 反対, 不安. Mang sắc thái phê phán nhẹ.', 1),
(563, 119, 122, 'N + に即して', 'Sát với, theo đúng — Bám sát thực tế hoặc quy định mà xử lý.', '実情に即した対策が必要だ。', 'Hay đi với 実情, 事実, 法律. Khác に沿って ở chỗ に即して bám vào nội dung cụ thể.', 2),
(564, 119, 122, 'N + とて', 'Dù là cũng — Ngay cả trường hợp đó cũng không ngoại lệ, văn cổ.', '私とて同じ気持ちだ。', 'Rất trang trọng và cổ. Gần といえども nhưng ngắn hơn.', 3),
(565, 120, 123, 'N + をものともせず', 'Bất chấp, không nao núng trước — Vượt qua khó khăn lớn một cách dũng cảm, luôn là lời khen.', 'けがをものともせず、最後まで走り切った。', 'Khác với をよそに ở chỗ をものともせず là khen ngợi, còn をよそに là phê phán.', 1),
(566, 120, 123, 'N + に照らして', 'Đối chiếu với — So với chuẩn mực hoặc tiền lệ để phán xét.', '規定に照らして判断する。', 'Hay đi với 法律, 基準, 経験. Trang trọng, dùng trong văn bản.', 2),
(567, 120, 123, 'N + なしでは', 'Nếu thiếu thì không — Không có cái đó thì không thể tiến hành.', '眼鏡なしでは何も見えない。', 'Thân mật hơn なくして. Vế sau bắt buộc phủ định.', 3),
(568, 121, 124, 'N + を余儀なくされる', 'Buộc phải, đành phải — Do hoàn cảnh ngoài ý muốn mà buộc phải chấp nhận.', '台風で試合は中止を余儀なくされた。', 'Chủ ngữ là người chịu đựng. Dạng chủ động を余儀なくさせる = buộc ai đó phải.', 1),
(569, 121, 124, 'N + を限りに', 'Kể từ là chấm dứt — Lấy mốc đó làm điểm kết thúc.', '今日を限りにたばこをやめる。', 'Hay gặp: 今日を限りに, 本日を限りに. Vế sau là việc chấm dứt.', 2),
(570, 121, 124, 'V thể ば + それまでだ', 'Thì cũng coi như xong — Nếu điều đó xảy ra thì mọi công sức đổ sông đổ biển.', 'いくら貯金しても、病気になればそれまでだ。', 'Giọng bi quan hoặc cảnh báo. Hay gặp: 失敗すればそれまでだ.', 3),
(571, 122, 125, 'N + を禁じ得ない', 'Không kìm được — Không thể nén được cảm xúc trào lên.', 'その話を聞いて涙を禁じ得なかった。', 'Chỉ dùng với danh từ chỉ cảm xúc: 涙, 怒り, 同情. Văn viết trang trọng.', 1),
(572, 122, 125, 'N + をはじめ', 'Trước hết là, đứng đầu là — Nêu đại diện tiêu biểu rồi hàm ý còn nhiều nữa.', '社長をはじめ、全社員が参加した。', 'Dạng khác をはじめとする. Cái nêu ra phải là tiêu biểu nhất.', 2),
(573, 122, 125, 'V từ điển + にとどまらず', 'Không dừng lại ở — Ảnh hưởng lan rộng vượt khỏi phạm vi ban đầu.', '被害は国内にとどまらず、海外にも及んだ。', 'Trang trọng. Vế sau thường có まで hoặc も.', 3),
(574, 123, 126, 'N + にあって', 'Trong hoàn cảnh — Đặt trong bối cảnh đặc biệt nào đó.', 'この不況にあって、売上を伸ばすのは難しい。', 'Trang trọng, hay dùng với hoàn cảnh khó khăn: 困難な状況にあって.', 1),
(575, 123, 126, 'N + なりに / なりの', 'Theo cách riêng của — Tuy hạn chế nhưng đã cố hết sức theo khả năng của mình.', '子供は子供なりに考えている。', 'Mang sắc thái thông cảm, thừa nhận nỗ lực. 私なりに = theo cách của riêng tôi.', 2),
(576, 123, 126, 'N + を経て', 'Trải qua rồi mới — Đi qua một quá trình hoặc giai đoạn rồi mới đến kết quả.', '三年の準備期間を経て開店した。', 'Trang trọng, hay gặp trong tiểu sử và thủ tục.', 3),
(577, 124, 127, 'N / V từ điển + に至る', 'Đi đến mức, dẫn tới — Cuối cùng đạt tới một trạng thái hoặc kết quả nghiêm trọng.', '交渉は決裂するに至った。', 'に至るまで = cho đến tận. に至っては = đến như thì. に至って = mãi đến khi mới.', 1),
(578, 124, 127, 'V thể ます (bỏ ます) + つ + V thể ます (bỏ ます) + つ', 'Lúc thì lúc thì — Hai động tác trái nghiều lặp đi lặp lại.', '駅の前を行きつ戻りつしていた。', 'Cụm cố định: 行きつ戻りつ, 抜きつ抜かれつ, 持ちつ持たれつ. Không tự ghép tuỳ tiện.', 2),
(579, 124, 127, 'N / V từ điển + につけても', 'Mỗi khi nghĩ đến lại — Cứ nhớ đến việc đó là cảm xúc lại dâng lên.', 'それにつけても彼のことが思い出される。', 'Hay gặp: それにつけても. Vế sau là cảm xúc tự nhiên.', 3),
(580, 125, 128, 'N / V từ điển + に難くない', 'Không khó để — Dễ dàng tưởng tượng hoặc hiểu được.', '彼の苦労は想像に難くない。', 'Hầu như chỉ đi với 想像 và 察する: 想像に難くない.', 1),
(581, 125, 128, 'Thể thường + ものと思われる', 'Được cho là — Phán đoán khách quan, tránh nói thẳng ý kiến cá nhân.', '原因は配線の不具合によるものと思われる。', 'Văn viết báo chí và báo cáo. Dạng khác ものとみられる.', 2),
(582, 125, 128, 'Thể thường + ものとする', 'Được quy định là — Quy định trong văn bản pháp lý hoặc hợp đồng.', '費用は甲が負担するものとする。', 'Chỉ dùng trong văn bản chính thức, không dùng trong hội thoại.', 3),
(583, 126, 129, 'N / V từ điển + に堪えない', 'Không chịu nổi, vô cùng — Không thể chịu đựng được, hoặc cảm xúc dâng trào đến mức tột cùng.', 'その光景は見るに堪えなかった。', 'Hai nghĩa: 見るに堪えない (không nỡ nhìn) và 感謝に堪えない (vô cùng biết ơn). Phân biệt theo từ đi kèm.', 1),
(584, 126, 129, 'Thể thường + と思いきや', 'Tưởng là ai ngờ — Kết quả trái hẳn với điều vừa nghĩ, kèm bất ngờ.', '簡単だと思いきや、意外に難しかった。', 'Văn nói pha chút cổ. Luôn mang yếu tố bất ngờ.', 2),
(585, 126, 129, 'N / V từ điển + に値する', 'Xứng đáng với — Có đủ giá trị để nhận được điều đó.', '彼の努力は賞賛に値する。', 'Phủ định に値しない. Hay gặp: 賞賛に値する, 信頼に値する.', 3),
(586, 127, 130, 'N / V từ điển + に足る', 'Đủ để, xứng đáng — Có đủ giá trị hoặc phẩm chất để làm gì.', '彼は信頼するに足る人物だ。', 'Phủ định に足りない = không đáng. Hay dùng: 信頼に足る人物.', 1),
(587, 127, 130, 'Thể thường + と言っても過言ではない', 'Nói là cũng không ngoa — Khẳng định mạnh rằng cách nói đó không hề phóng đại.', '彼は天才だと言っても過言ではない。', 'Cụm cố định trang trọng, hay dùng khi đánh giá cao.', 2),
(588, 127, 130, 'N / Thể thường + にかかわらず', 'Bất kể — Không phân biệt, không phụ thuộc vào yếu tố đó.', '年齢にかかわらず応募できます。', 'Đừng nhầm với にもかかわらず (mặc dù vậy mà). Khác nhau một chữ も.', 3),
(589, 128, 131, 'N / Thể thường + にひきかえ', 'Trái ngược hẳn với — So sánh hai bên hoàn toàn trái ngược, kèm đánh giá của người nói.', '兄にひきかえ、弟はよく勉強する。', 'Chủ quan hơn に対して. Thường một bên tốt một bên kém.', 1),
(590, 128, 131, 'N + なくして', 'Nếu không có thì — Thiếu điều kiện đó thì việc kia không thành.', '努力なくして成功はない。', 'Vế sau bắt buộc phủ định. Trang trọng hơn なしには.', 2),
(591, 128, 131, 'N + ながらの', 'Nguyên vẹn như xưa — Giữ nguyên trạng thái từ trước đến nay.', '昔ながらの製法を守っている。', 'Hay gặp: 昔ながらの, 生まれながらの.', 3),
(592, 129, 132, 'N + にもまして', 'Hơn cả, càng hơn trước — Mức độ vượt hơn cả đối tượng vốn đã cao.', '今年は去年にもまして暑い。', '何にもまして = hơn hết thảy. 以前にもまして = hơn cả trước kia.', 1),
(593, 129, 132, 'N + と相まって', 'Kết hợp với — Hai yếu tố cộng hưởng tạo nên kết quả lớn hơn.', '好天と相まって、来場者は過去最多となった。', 'Văn viết. Cả hai yếu tố đều góp phần, không phải nguyên nhân đơn lẻ.', 2),
(594, 129, 132, 'V thể ます (bỏ ます) + こそすれ', 'Chỉ có chứ không — Khẳng định một chiều và phủ định chiều ngược lại.', '感謝こそすれ、恨むことはない。', 'Vế sau bắt buộc phủ định. Văn viết trang trọng.', 3),
(595, 130, 133, 'N + ならでは', 'Chỉ có ở mới có được — Đặc trưng riêng có, không nơi nào khác sánh được.', 'これは職人ならではの技だ。', 'Luôn là lời khen. Dạng định ngữ ならではの: 京都ならではの風景.', 1),
(596, 130, 133, 'N + ひとつ', 'Chỉ cần một cái thôi — Một yếu tố nhỏ cũng đủ thay đổi cục diện.', '考え方ひとつで人生は変わる。', 'Cụm hay gặp: 考えひとつで, やり方ひとつで. Nhấn mạnh tính quyết định.', 2),
(597, 130, 133, 'Câu hỏi + であろうと', 'Dù là gì đi nữa — Bất kể trường hợp nào, kết luận vẫn không đổi.', '誰であろうと規則は守るべきだ。', 'Hay đi với 誰, 何, どこ. Trang trọng hơn でも.', 3),
(598, 131, 134, 'N / V thể ます (bỏ ます) + ながらに', 'Nguyên trạng, trong khi — Giữ nguyên trạng thái đó mà làm việc gì.', '彼女は涙ながらに事情を語った。', 'Cụm cố định hay gặp: 涙ながらに (vừa khóc vừa), 生まれながらに (bẩm sinh), 居ながらに.', 1),
(599, 131, 134, 'N + とは', 'Thế mà lại, cái gọi là — Bày tỏ kinh ngạc, hoặc nêu định nghĩa.', '彼が辞めるとは思わなかった。', 'Nghĩa kinh ngạc thường bỏ lửng cuối câu. Nghĩa định nghĩa hay gặp trong từ điển.', 2),
(600, 132, 135, 'N + なしには', 'Nếu không có thì không — Thiếu điều kiện đó thì không thể thực hiện được.', '努力なしには成功はあり得ない。', 'Vế sau bắt buộc phủ định. Dạng khác: なくしては, なしでは.', 1),
(601, 132, 135, 'N / V thể ば + こそ', 'Chính vì có mà — Nhấn mạnh rằng đúng điều đó mới là nguyên nhân thật sự.', '努力があればこそ、今の成功がある。', 'Trang trọng hơn からこそ. Vế sau thường kết bằng のだ.', 2),
(602, 133, 136, 'V-ない bỏ ない + んばかり', 'Như thể sắp — Trông như sắp làm việc gì đến nơi, dù thực tế chưa làm.', '彼は泣かんばかりの顔をしていた。', 'する → せんばかり (ngoại lệ). Văn viết, mang tính miêu tả mạnh.', 1),
(603, 133, 136, 'V từ điển + までだ / までのことだ', 'Thì chỉ còn cách — Nếu không được thì đơn giản là làm cách khác, giọng dứt khoát.', '断られたら、他を当たるまでだ。', 'Thể hiện sự bình thản hoặc quyết đoán, không than vãn.', 2),
(604, 134, 137, 'Câu trích + とばかりに', 'Ra vẻ như muốn nói — Không nói ra lời nhưng thái độ thể hiện rõ điều đó.', 'もう帰れとばかりに、彼は時計を見た。', 'Vế trước là lời chưa nói ra. Hay gặp: ここぞとばかりに (nhân cơ hội này).', 1),
(605, 134, 137, 'V từ điển + までもない', 'Không cần phải đến mức — Việc đó hiển nhiên nên không cần thiết làm.', '言うまでもなく、健康が第一だ。', 'Cụm hay gặp: 言うまでもない (khỏi phải nói). Trang trọng.', 2),
(606, 135, 138, 'V từ điển + が早いか', 'Vừa mới là đã — Việc sau xảy ra gần như đồng thời, nhanh đến bất ngờ.', '彼はベルが鳴るが早いか、教室を飛び出した。', 'Vế sau là việc đã xảy ra, không dùng ý chí. Cứng hơn とたん và や否や.', 1),
(607, 135, 138, 'Thể thường + に越したことはない', 'Thì tốt hơn cả — Được như vậy là tốt nhất, dù không bắt buộc.', '用心するに越したことはない。', 'Cụm cố định. Thường dùng khi đưa lời khuyên nhẹ nhàng.', 2),
(608, 136, 139, 'V từ điển / V-た + そばから', 'Vừa xong lại ngay — Việc lặp đi lặp lại: vừa làm xong lại hỏng ngay.', '片付けるそばから子供が散らかす。', 'Nhấn mạnh sự lặp lại vô ích, thường kèm bực bội.', 1),
(609, 136, 139, 'N + なりとも', 'Dù chỉ một chút — Dù ít ỏi cũng được, mang tính khiêm nhường.', '多少なりともお役に立てれば幸いです。', 'Cụm hay gặp: 多少なりとも, 少しなりとも.', 2),
(610, 137, 140, 'V từ điển + なり', 'Vừa là lập tức — Ngay sau hành động đó thì làm ngay việc bất ngờ tiếp theo.', '彼は部屋に入るなり、電気を消した。', 'Chủ ngữ hai vế phải giống nhau. Vế sau là việc đã xảy ra và thường khác thường.', 1),
(611, 137, 140, 'V-た + が最後', 'Một khi đã là xong — Một khi làm việc đó thì hậu quả xấu không tránh khỏi.', '彼に貸したが最後、返ってこない。', 'Dạng khác たら最後. Vế sau luôn tiêu cực và dứt khoát.', 2),
(612, 138, 141, 'N + かたがた', 'Nhân tiện, kết hợp — Làm việc chính đồng thời kết hợp mục đích phụ, dùng trong giao tiếp lễ nghi.', 'お礼かたがたご挨拶に伺いました。', 'Chỉ dùng với danh từ mang tính nghi thức: お礼, ご挨拶, お見舞い.', 1),
(613, 138, 141, 'A / N + といったらない', 'Thì không gì bằng — Mức độ cao đến mức không diễn tả nổi.', 'あの日の暑さといったらなかった。', 'Dạng khác ったらない. Dùng được cả nghĩa tốt lẫn xấu.', 2),
(614, 139, 142, 'N の / V từ điển + かたわら', 'Bên cạnh việc chính — Ngoài công việc chính còn làm thêm việc khác lâu dài.', '彼は仕事のかたわら小説を書いている。', 'Khác với ながら ở chỗ かたわら nói về hoạt động kéo dài, không phải hai việc cùng lúc.', 1),
(615, 139, 142, 'V từ điển + ともなく', 'Vô thức, chẳng chủ ý — Làm việc gì mà không có ý định rõ ràng.', '見るともなくテレビを見ていた。', 'Dạng khác ともなしに. Hay gặp: 見るともなく, 聞くともなく.', 2),
(616, 140, 143, 'N / V thể ます (bỏ ます) + がてら', 'Tiện thể — Nhân lúc làm việc này thì làm luôn việc kia.', '散歩がてら郵便局に寄った。', 'Gần ついでに nhưng chỉ dùng với hành động di chuyển: 散歩がてら, 買い物がてら.', 1),
(617, 140, 143, 'N + にして初めて', 'Phải đến mới — Phải đạt tới mức đó rồi mới có được điều kia.', 'この年齢にして初めて分かることがある。', 'Nhấn mạnh điều kiện khắt khe. Hay gặp: 大人になって初めて.', 2),
(618, 141, 144, 'N + ずくめ', 'Toàn một màu, toàn những — Toàn bộ đều là thứ đó, không có gì khác.', '黒ずくめの男が立っていた。', 'Hay gặp: 黒ずくめ (toàn đồ đen), いいことずくめ (toàn chuyện tốt). Khác だらけ ở chỗ ずくめ trung tính hoặc tích cực.', 1),
(619, 141, 144, 'N + にあらず', 'Không phải là — Phủ định theo lối văn cổ, dùng trong châm ngôn và khẩu hiệu.', 'もはや他人事にあらず。', 'Cứng và cổ. Hay gặp trong tục ngữ: 人にあらず.', 2),
(620, 142, 145, 'N + まみれ', 'Bê bết, dính đầy — Bề mặt bám đầy chất lỏng hoặc bụi bẩn.', '汗まみれになって働いた。', 'Chỉ dùng với chất cụ thể: 泥, 汗, 血, ほこり. Khác だらけ (có thể trừu tượng như 間違いだらけ).', 1),
(621, 142, 145, 'V từ điển + べくもない', 'Không thể nào mà — Hoàn toàn không có khả năng, văn viết trang trọng.', '真相は知るべくもない。', 'Cụm hay gặp: 知るべくもない, 望むべくもない.', 2),
(622, 143, 146, 'N + めく', 'Ngả sang, nhuốm vẻ — Bắt đầu mang dáng vẻ hoặc không khí của thứ gì đó.', 'ようやく春めいてきた。', 'Chia như động từ nhóm 1. Hay gặp: 春めく, 謎めいた, 皮肉めいた.', 1),
(623, 143, 146, 'Thể thường + とはいえ', 'Tuy nói là nhưng — Thừa nhận vế trước nhưng thực tế khác đi.', '春とはいえ、まだ寒い。', 'Trang trọng hơn とはいうものの. Đứng đầu câu cũng được.', 2),
(624, 144, 147, 'A / N + 極まる / 極まりない', 'Vô cùng, hết mức — Mức độ đạt tới cực điểm, hầu như luôn tiêu cực.', '彼の態度は失礼極まりない。', '極まる và 極まりない nghĩa giống nhau dù một cái có ない. Đây là điểm dễ nhầm.', 1),
(625, 144, 147, 'V thể ます (bỏ ます) / A / N + ながらも', 'Tuy mà vẫn — Nhượng bộ: dù ở trạng thái đó nhưng vẫn làm được điều khác.', '狭いながらも楽しい我が家。', 'Khác ながら chỉ sự đồng thời. ながらも luôn mang nghĩa nhượng bộ.', 2),
(626, 145, 148, 'N + の極み', 'Tột đỉnh của — Đạt tới đỉnh điểm của một trạng thái, dùng trong văn viết.', 'これは贅沢の極みだ。', 'Hay gặp: 感激の極み, 贅沢の極み, 疲労の極み.', 1),
(627, 145, 148, 'Thể thường / N + といえども', 'Dù cho là — Ngay cả trường hợp đặc biệt đó cũng không ngoại lệ.', '専門家といえども間違うことはある。', 'Rất trang trọng, văn viết. Vế sau thường phủ định hoặc trái mong đợi.', 2),
(628, 146, 149, 'N + の至り', 'Thật là, vô cùng — Cảm xúc dâng đến mức cao nhất, dùng trong lời chào trang trọng.', 'お招きいただき光栄の至りです。', 'Hay gặp: 光栄の至り, 恐縮の至り, 若気の至り (bồng bột tuổi trẻ).', 1),
(629, 146, 149, 'V thể ます (bỏ ます) + もしない', 'Đến cả cũng không thèm — Phủ định mạnh kèm chê trách: không thèm làm dù chỉ chút ít.', '彼は謝りもしなかった。', 'Nhấn mạnh sự thờ ơ. Dạng liên quan: 見向きもしない.', 2),
(630, 147, 150, 'N + たるもの', 'Đã là thì phải — Người ở vị trí đó thì đương nhiên phải có trách nhiệm tương xứng.', '教師たるもの、学生の模範であるべきだ。', 'Chỉ dùng với chức danh hoặc vai trò: 教師たるもの, リーダーたるもの.', 1),
(631, 147, 150, 'N + に関わる', 'Liên quan sống còn đến — Ảnh hưởng nghiêm trọng đến điều quan trọng.', 'これは命に関わる問題だ。', 'Chỉ dùng với việc hệ trọng: 命, 名誉, 信用. Khác に関して (chỉ nêu đề tài).', 2),
(632, 148, 151, 'N + ともあろう', 'Đường đường là mà lại — Người ở vị trí cao mà lại làm điều không xứng đáng, kèm thất vọng.', '医者ともあろう人がそんなミスをするとは。', 'Luôn mang ý phê phán. Vế sau là hành vi đáng trách.', 1),
(633, 148, 151, 'V-た / Thể thường + ことと存じます', 'Kính mong rằng, chắc là — Phỏng đoán lịch sự về tình hình của đối phương, dùng trong thư từ.', '皆様お元気のことと存じます。', 'Cụm lễ nghi trong thư thương mại: お元気のことと存じます.', 2),
(634, 149, 152, 'N + であれ / であろうと', 'Dù là ai đi nữa — Bất kể trường hợp nào thì kết luận vẫn không đổi.', '理由が何であれ、遅刻は許されない。', 'Dạng lặp であれ〜であれ. Hay đi với từ để hỏi: 誰であれ, どこであれ.', 1),
(635, 149, 152, 'N + のもとで / のもとに', 'Dưới sự — Dưới sự chỉ đạo, điều kiện hoặc ảnh hưởng của cái gì.', '先生のもとで研究を続けている。', 'のもとで nhấn mạnh nơi chốn hoặc sự giám sát; のもとに nhấn mạnh điều kiện.', 2),
(636, 150, 153, 'N + いかんによらず / いかんで', 'Bất kể, tuỳ thuộc — いかんで = tuỳ vào; いかんによらず = bất kể thế nào.', '理由のいかんによらず、返品はできません。', 'Hai dạng nghĩa ngược nhau, phải nhìn kỹ đuôi. 理由のいかんによらず = bất kể lý do gì.', 1),
(637, 150, 153, 'N + にしてみれば', 'Đứng ở vị trí mà xét — Nhìn từ lập trường của người đó thì cảm nhận sẽ khác.', '彼にしてみれば、当然の反応だろう。', 'Hay dùng để bênh vực hoặc thông cảm. Gần にとっては nhưng chủ quan hơn.', 2),
(638, 151, 154, 'N + をもって', 'Bằng, kể từ — Nêu phương tiện, hoặc mốc thời gian kết thúc, trong văn thông báo.', '本日をもって閉店いたします。', '本日をもって = kể từ hôm nay. 身をもって = bằng chính bản thân.', 1),
(639, 151, 154, 'V từ điển + に足りない', 'Không đáng để — Giá trị quá nhỏ, không xứng để bận tâm.', '取るに足りない問題だ。', 'Cụm hay gặp: 取るに足りない. Là phủ định của に足る.', 2),
(640, 152, 155, 'V từ điển + ことなしに', 'Mà không cần — Không làm việc trước thì không đạt được việc sau.', '努力することなしに成功はない。', 'Vế sau thường phủ định. Văn viết, gần với ないで nhưng trang trọng hơn nhiều.', 1),
(641, 152, 155, 'Thể thường + ものか', 'Làm gì có chuyện — Phủ định mạnh kèm cảm xúc, giọng văn nói dứt khoát.', 'あんな店、二度と行くものか。', 'Dạng lịch sự ものですか. Thể hiện quyết tâm hoặc bác bỏ.', 2),
(642, 153, 156, 'V từ điển + べからず / べからざる', 'Không được phép — Cấm đoán mạnh, dùng trong bảng cấm hoặc văn cổ.', 'ここにゴミを捨てるべからず。', 'する → すべからず. Dạng định ngữ べからざる: 許すべからざる行為.', 1),
(643, 153, 156, 'N / V từ điển + どころの話ではない', 'Còn lâu mới là chuyện — Mức độ vượt xa điều vừa nêu, hoàn cảnh nghiêm trọng hơn nhiều.', '忙しいどころの話ではない。', 'Mạnh hơn どころではない. Nhấn mạnh sự chênh lệch lớn.', 2),
(644, 154, 157, 'V từ điển + べく', 'Để mà — Nêu mục đích, văn viết trang trọng.', '真相を確かめるべく調査を始めた。', 'する → すべく. Vế sau là hành động chủ ý của cùng chủ ngữ.', 1),
(645, 154, 157, 'N / Thể thường + ゆえの', 'Do mà có — Dạng định ngữ của ゆえに, nêu nguyên nhân của một đặc điểm.', '経験不足ゆえのミスだった。', 'Văn viết cổ điển. 若さゆえの過ち = sai lầm do tuổi trẻ.', 2),
(646, 155, 158, 'Thể thường / N + ゆえに', 'Bởi vì, do đó — Nêu nguyên nhân, văn viết cổ điển và trang trọng.', '経験不足ゆえに失敗した。', 'Danh từ nối trực tiếp hoặc có の. Dạng định ngữ ゆえの.', 1),
(647, 155, 158, 'N / V từ điển + に限る', 'Thì nhất — Theo ý người nói, cái đó là tốt nhất.', '夏はビールに限る。', 'Mang tính chủ quan, giọng thân mật. Khác với に限って (chỉ riêng).', 2),
(648, 156, 159, 'Thể thường / N + とあって', 'Vì là nên — Do hoàn cảnh đặc biệt nên xảy ra kết quả tương ứng.', '連休とあって、道路は混んでいる。', 'Vế sau là sự thật khách quan, không dùng cho ý chí của người nói.', 1),
(649, 156, 159, 'V từ điển + ことなく', 'Mà không hề — Không làm việc kia mà vẫn tiến hành việc này, văn viết.', '彼は休むことなく働き続けた。', 'Trang trọng hơn ないで. Hay gặp: 休むことなく, 変わることなく.', 2),
(650, 157, 160, 'Thể thường / N + とあれば', 'Nếu vì thì — Nếu vì mục đích đó thì sẵn sàng làm bất cứ gì.', '子供のためとあれば、何でもする。', 'Thể hiện quyết tâm mạnh. Vế sau thường là việc bình thường không làm.', 1),
(651, 157, 160, 'N + をかえりみず', 'Bất chấp, không màng — Không đoái hoài đến điều đáng lẽ phải cân nhắc.', '彼は危険をかえりみず川に飛び込んだ。', 'Hay gặp: 危険をかえりみず, 家庭をかえりみず. Có thể khen hoặc chê tuỳ ngữ cảnh.', 2),
(652, 158, 161, 'N / V từ điển + ともなると', 'Đã đến mức thì — Khi đạt tới giai đoạn hoặc vị trí đó thì mọi việc khác hẳn.', '社会人ともなると、責任が重くなる。', 'Dạng khác ともなれば. Hay dùng với tuổi tác, chức vụ, mùa.', 1),
(653, 158, 161, 'N + と引き換えに', 'Đổi lấy — Đánh đổi cái này để lấy cái kia.', '自由と引き換えに安定を得た。', 'Khác にひきかえ (trái ngược hẳn). Hai mẫu gần giống chữ nhưng khác nghĩa hoàn toàn.', 2),
(654, 159, 162, 'Lượng từ + たりとも', 'Dù chỉ một cũng không — Phủ định tuyệt đối, dù mức nhỏ nhất cũng không.', '一日たりとも忘れたことはない。', 'Vế sau bắt buộc phủ định. Hay gặp: 一日たりとも, 一円たりとも.', 1),
(655, 159, 162, 'N + いかんによっては', 'Tuỳ vào mà có thể — Kết quả thay đổi tuỳ theo yếu tố đó.', '結果いかんによっては計画を見直す。', 'Cùng họ với いかんで. Trang trọng, hay gặp trong thông báo.', 2),
(656, 160, 163, 'N + だに', 'Chỉ cần đã — Chỉ mới làm việc nhỏ nhất đó thôi đã thấy thế nào rồi.', '想像するだに恐ろしい。', 'Cụm cố định: 想像するだに, 考えるだに, 微動だにしない.', 1),
(657, 160, 163, 'N / V từ điển + には及ばない', 'Không cần phải, không bằng — Không cần thiết làm việc đó, hoặc không sánh bằng.', 'ご心配には及びません。', 'Hai nghĩa: 心配には及ばない (khỏi lo) và 彼には及ばない (không bằng anh ấy).', 2),
(658, 161, 164, 'N + すら', 'Đến cả cũng — Nêu ví dụ cực đoan, cứng hơn さえ.', '自分の名前すら書けない。', 'Văn viết. Vế sau thường phủ định.', 1),
(659, 161, 164, 'V-て / N + までして', 'Đến mức phải — Làm đến cả việc cực đoan đó để đạt mục đích.', '借金までして車を買った。', 'Thường kèm đánh giá tiêu cực về sự thái quá.', 2),
(660, 162, 165, 'Lượng từ + からある / からする', 'Tới tận — Nhấn mạnh số lượng, kích thước hoặc giá trị lớn.', '百キロからある荷物を運んだ。', 'からある dùng cho độ dài, trọng lượng; からする dùng cho giá tiền.', 1),
(661, 162, 165, 'V từ điển + はずの', 'Lẽ ra phải, vốn dĩ — Dạng định ngữ của はずだ, đứng trước danh từ.', '来るはずの人がまだ来ない。', 'Thường kèm ý trái với thực tế: 来るはずの人が来ない.', 2),
(662, 163, 166, 'Thể thường + ものを', 'Vậy mà lại, đáng lẽ đã — Tiếc nuối vì lẽ ra đã tốt nếu làm khác đi.', '言ってくれれば手伝ったものを。', 'Mang cảm xúc trách móc hoặc nuối tiếc rõ. Thường bỏ lửng cuối câu.', 1),
(663, 163, 166, 'N + でなくてなんだろう', 'Nếu không phải là thì là gì — Khẳng định mạnh bằng câu hỏi tu từ, giọng văn chương.', 'これが奇跡でなくてなんだろう。', 'Hay gặp: これが愛でなくてなんだろう. Dùng trong văn viết cảm thán.', 2),
(664, 164, 167, 'N の / Thể thường + ところを', 'Trong lúc đang mà — Lời xin lỗi vì làm phiền người khác đúng lúc họ bận.', 'お忙しいところをありがとうございます。', 'Cụm lễ nghi hay gặp: お忙しいところを, お休みのところを.', 1),
(665, 164, 167, 'V từ điển + に堪える', 'Đáng để, chịu được — Có đủ giá trị để làm việc đó.', 'この作品は鑑賞に堪える。', 'Hay gặp: 鑑賞に堪える, 読むに堪える. Phủ định là に堪えない.', 2),
(666, 165, 168, 'V từ điển + 始末だ', 'Rốt cuộc đến nông nỗi — Sự việc xấu đi dần rồi dẫn tới kết cục tệ hại.', '何度も注意したのに、とうとう喧嘩する始末だ。', 'Luôn tiêu cực. Vế trước thường kể quá trình xấu dần.', 1),
(667, 165, 168, 'N + いかんにかかわらず', 'Bất kể như thế nào — Không phụ thuộc vào yếu tố đó.', '理由のいかんにかかわらず返金はできません。', 'Đồng nghĩa いかんによらず. Trang trọng, hay gặp trong điều khoản.', 2),
(668, 166, 169, 'V-て + やまない', 'Không ngừng, tha thiết — Tình cảm mạnh mẽ kéo dài không dứt.', 'ご成功を願ってやみません。', 'Chỉ dùng với động từ chỉ cảm xúc: 願う, 愛する, 期待する.', 1),
(669, 166, 169, 'N + をもってすれば', 'Nếu dùng thì — Với năng lực hoặc phương tiện đó thì việc gì cũng được.', '彼の実力をもってすれば、優勝も可能だ。', 'Luôn mang ý tin tưởng vào năng lực. Vế sau thường tích cực.', 2),
(670, 167, 170, 'A / N + 限りだ', 'Thật là vô cùng — Bày tỏ cảm xúc mạnh của chính người nói.', 'お会いできてうれしい限りです。', 'Chỉ dùng cho cảm xúc của bản thân: うれしい限りだ, 心細い限りだ.', 1),
(671, 167, 170, 'Thể thường + ではあるまいし', 'Đâu phải là mà — Nhắc nhở rằng đối phương không phải như vậy nên đừng hành xử thế.', '子供ではあるまいし、自分でやりなさい。', 'Giọng trách nhẹ, văn nói. Hay gặp: 子供ではあるまいし.', 2),
(672, 168, 171, 'V từ điển / N の + きらいがある', 'Có khuynh hướng xấu — Có xu hướng thiên về điều không tốt.', '彼は物事を悲観的に考えるきらいがある。', 'Luôn tiêu cực, nhẹ nhàng hơn lời chê trực tiếp. Không dùng cho việc tốt.', 1),
(673, 168, 171, 'Thể thường + といったところだ', 'Cùng lắm cũng chỉ — Mức độ chỉ vào khoảng đó, không hơn.', '参加者はせいぜい十人といったところだ。', 'Hay dùng để hạ mức kỳ vọng. Dạng khác というところだ.', 2),
(674, 169, 172, 'N + を皮切りに', 'Mở đầu bằng rồi lan ra — Bắt đầu từ một điểm rồi phát triển rộng liên tiếp.', '東京公演を皮切りに、全国ツアーが始まった。', 'Vế sau phải là chuỗi việc nối tiếp nhau. Dạng khác を皮切りとして.', 1),
(675, 169, 172, 'V từ điển + に忍びない', 'Không nỡ — Không đành lòng làm việc đó vì thương cảm.', '思い出の品なので捨てるに忍びない。', 'Hay gặp: 捨てるに忍びない, 見るに忍びない.', 2),
(676, 177, 180, '〜と申します', 'Tôi tên là ~ (khiêm nhường)', '〜ともうします', 'Dùng khi tự giới thiệu với khách hàng, lịch sự hơn 〜です.', 1),
(677, 177, 180, '〜を担当いたします', 'Tôi phụ trách ~', '〜をたんとういたします', 'Nói rõ vai trò của mình trong dự án.', 2),
(678, 177, 180, '窓口となって', 'Làm đầu mối liên lạc', 'まどぐちとなって', 'Câu quan trọng nhất để khách hiểu vai trò của BrSE.', 3),
(679, 178, 181, 'ファムはただいま会議中でございます', 'Anh Phạm hiện đang họp', 'ファムはただいまかいぎちゅうでございます', 'Khi nói với khách, gọi đồng nghiệp bên mình không kèm さん.', 1),
(680, 178, 181, '申し伝えます', 'Tôi sẽ chuyển lời', 'もうしつたえます', 'Khiêm nhường ngữ, dùng khi chuyển lời của khách cho người bên mình.', 2),
(681, 178, 181, '私、〇〇が承りました', 'Tôi là ~ đã nhận lời nhắn', 'わたくし、〇〇がうけたまわりました', 'Câu kết chuẩn khi nhận lời nhắn qua điện thoại.', 3),
(682, 179, 182, '一点確認させていただきたいのですが', 'Tôi muốn xác nhận một điểm', 'いってんかくにんさせていただきたいのですが', 'Mở đầu lịch sự khi hỏi lại khách.', 1),
(683, 179, 182, 'どちらをご想定でしょうか', 'Anh đang hình dung phương án nào?', 'どちらをごそうていでしょうか', 'Đưa sẵn phương án cho khách chọn, thay vì hỏi câu mở.', 2),
(684, 179, 182, '〜ということでよろしいでしょうか', 'Hiểu là ~ có đúng không ạ?', '〜ということでよろしいでしょうか', 'Nhắc lại để chốt, kỹ năng cốt lõi của BrSE.', 3),
