(718, 197, 200, '〜をお願いします', 'Cho tôi xin ~', '〜をおねがいします', 'Câu đề nghị cơ bản, dùng khắp nơi trong dịch vụ.', 1),
(719, 197, 200, 'よろしいですか', 'Anh thấy được không ạ', 'よろしいですか', 'Dạng lịch sự của いいですか, nhân viên hay dùng để xác nhận.', 2),
(720, 198, 201, '〜になります', 'Sẽ thành ~, phải ~', '〜になります', 'Cách nói gián tiếp, mềm hơn nói thẳng です.', 1),
(721, 198, 201, '〜のほうが〜', 'Bên ~ thì hơn', '〜のほうが〜', 'Mẫu so sánh cơ bản, rất hay dùng khi tư vấn.', 2),
(722, 199, 202, 'お待ちしておりました', 'Chúng tôi đã chờ ngài', 'おまちしておりました', 'Khiêm nhường ngữ, chuẩn mực trong ngành dịch vụ.', 1),
(723, 199, 202, '承ります', 'Chúng tôi xin tiếp nhận', 'うけたまわります', 'Dạng khiêm nhường của 受ける, dùng khi nhận yêu cầu.', 2),
(724, 200, 203, '〜が付きます', 'Có kèm ~', '〜がつきます', 'Dùng khi mô tả suất ăn hoặc dịch vụ đi kèm.', 1),
