(1114, 84, 'LISTENING', NULL, 'Linh', 'いいえ、じゅうしょは かかなくても いいです。', 'Không, địa chỉ thì không cần viết.', 4),
(1115, 84, 'LISTENING', NULL, 'Nguyễn', 'はんこは いりますか。', 'Có cần con dấu tên không ạ?', 5),
(1116, 84, 'LISTENING', NULL, 'Linh', 'はい、いります。パスポートも もって きて ください。', 'Có ạ. Anh mang cả hộ chiếu tới nữa.', 6),
(1117, 84, 'LISTENING', NULL, 'Nguyễn', 'しめきりは いつですか。', 'Hạn chót là khi nào ạ?', 7),
(1118, 84, 'LISTENING', NULL, 'Linh', 'あしたです。きょうじゅうに だしても いいですよ。', 'Là ngày mai ạ. Nộp trong hôm nay cũng được.', 8),
(1119, 85, 'LISTENING', NULL, 'Tanaka', 'きょうは やすみますか。', 'Hôm nay anh nghỉ à?', 1),
(1120, 85, 'LISTENING', NULL, 'Nguyễn', 'ええ、かぜですから やすまなければ なりません。', 'Ừ, bị cảm nên tôi phải nghỉ.', 2),
(1121, 85, 'LISTENING', NULL, 'Tanaka', 'ねつは ありますか。', 'Anh có sốt không?', 3),
(1122, 85, 'LISTENING', NULL, 'Nguyễn', 'すこし あります。あたまも いたいです。', 'Có sốt nhẹ. Đầu cũng đau nữa.', 4),
