(1587, 119, 'LISTENING', NULL, 'Nguyễn', 'はい、けさ おくって くれました。', 'Rồi ạ, sáng nay đã gửi rồi.', 5),
(1588, 119, 'LISTENING', NULL, 'Tanaka', 'じゃ、あとは わたしが みて あげます。', 'Vậy phần còn lại để tôi xem cho.', 6),
(1589, 119, 'LISTENING', NULL, 'Nguyễn', 'おねがいします。', 'Nhờ anh ạ.', 7),
