(1591, 120, 'LISTENING', NULL, 'Linh', 'すみません、しゃしんを とって もらえますか。', 'Xin lỗi, anh chụp giúp tấm ảnh được không ạ?', 1),
(1592, 120, 'LISTENING', NULL, 'Nguyễn', 'はい、いいですよ。', 'Vâng, được thôi.', 2),
(1593, 120, 'LISTENING', NULL, 'Linh', 'ありがとう ございます。', 'Cảm ơn anh ạ.', 3),
(1594, 120, 'LISTENING', NULL, 'Nguyễn', 'ホテルは だれに よやくして もらいましたか。', 'Khách sạn em nhờ ai đặt thế?', 4),
(1595, 120, 'LISTENING', NULL, 'Linh', 'ともだちに よやくして もらいました。', 'Em nhờ bạn đặt giúp ạ.', 5),
