(1599, 121, 'READING', NULL, 'Danh sách từ vựng bài 25', 'Bài 25 có 50 từ vựng.', NULL, 1),
(1600, 123, 'GRAMMAR', 129, 'Ví dụ 1', 'あめが ふったら、うちに います。', 'Nếu trời mưa thì tôi ở nhà.', 1),
(1601, 123, 'GRAMMAR', 129, 'Ví dụ 2', 'ひまだったら、あそびに いきます。', 'Nếu rảnh thì tôi đi chơi.', 2),
(1602, 123, 'GRAMMAR', 129, 'Ví dụ 3', 'やすかったら、りょこうに いきます。', 'Nếu rẻ, tôi sẽ đi du lịch.', 3),
(1603, 123, 'GRAMMAR', 129, 'Ví dụ 4', 'じかんが あったら、あそびに いきます。', 'Nếu có thời gian, tôi sẽ đi chơi.', 4),
(1604, 123, 'GRAMMAR', 129, 'Ví dụ 5', 'つかれたら、うちに います。', 'Nếu mệt, tôi sẽ ở nhà.', 5),
(1605, 123, 'GRAMMAR', 129, 'Ví dụ 6', 'わからなかったら、きいて ください。', 'Nếu không hiểu thì anh hỏi nhé.', 6),
(1606, 123, 'GRAMMAR', 129, 'Ví dụ 7', 'てんきが わるかったら、うちに います。', 'Nếu thời tiết xấu, tôi sẽ ở nhà.', 7),
(1607, 123, 'GRAMMAR', 129, 'Ví dụ 8', 'おかねが あったら、あそびに いきます。', 'Nếu có tiền, tôi sẽ đi chơi.', 8),
(1608, 123, 'GRAMMAR', 129, 'Ví dụ 9', 'ついたら、でんわします。', 'Nếu tới nơi, tôi sẽ gọi điện.', 9),
(1609, 123, 'GRAMMAR', 129, 'Ví dụ 10', 'ひまだったら、てつだいます。', 'Nếu rảnh, tôi sẽ giúp.', 10),
(1610, 123, 'GRAMMAR', 130, 'Ví dụ 11', 'あめが ふっても、あそびに いきます。', 'Dù trời mưa, tôi vẫn đi chơi.', 11),
(1611, 123, 'GRAMMAR', 130, 'Ví dụ 12', 'たかくても、りょこうに いきます。', 'Dù đắt, tôi vẫn đi du lịch.', 12),
(1612, 123, 'GRAMMAR', 130, 'Ví dụ 13', 'いそがしくても、べんきょうを つづけます。', 'Dù bận, tôi vẫn tiếp tục học.', 13),
(1613, 123, 'GRAMMAR', 130, 'Ví dụ 14', 'ざんねんでも、しごとを やめます。', 'Dù tiếc, tôi vẫn nghỉ việc.', 14),
(1614, 123, 'GRAMMAR', 130, 'Ví dụ 15', 'むずかしくても、べんきょうを つづけます。', 'Dù khó, tôi vẫn tiếp tục học.', 15),
(1615, 123, 'GRAMMAR', 130, 'Ví dụ 16', 'さむくても、あそびに いきます。', 'Dù lạnh, tôi vẫn đi chơi.', 16),
(1616, 123, 'GRAMMAR', 131, 'Ví dụ 17', 'らいねん、しごとを かえます。', 'Sang năm, tôi sẽ đổi công việc.', 17),
(1617, 123, 'GRAMMAR', 131, 'Ví dụ 18', 'らいげつ、ひっこします。', 'Tháng sau, tôi sẽ chuyển nhà.', 18),
(1618, 123, 'GRAMMAR', 131, 'Ví dụ 19', 'らいねん、くにへ かえります。', 'Sang năm, tôi sẽ về nước.', 19),
(1619, 123, 'GRAMMAR', 131, 'Ví dụ 20', 'らいげつ けっこんしますから、ひっこします。', 'Vì tháng sau lập gia đình nên tôi sẽ chuyển nhà.', 20),
(1620, 123, 'GRAMMAR', 130, 'Ví dụ 21', 'たいへんでも、べんきょうを つづけます。', 'Dù vất vả, tôi vẫn tiếp tục học.', 21),
(1621, 123, 'GRAMMAR', 131, 'Ví dụ 22', 'らいねん、ひっこします。', 'Sang năm, tôi sẽ chuyển nhà.', 22),
(1622, 123, 'GRAMMAR', 131, 'Ví dụ 23', 'らいげつ、しごとを かえます。', 'Tháng sau, tôi sẽ đổi công việc.', 23),
