(1631, 123, 'GRAMMAR', 132, 'Ví dụ 32', 'あめが ふったら、りょこうは どう しますか。', 'Nếu trời mưa thì chuyến du lịch tính sao?', 32),
(1632, 123, 'GRAMMAR', 132, 'Ví dụ 33', 'てんきが わるかったら、どう しますか。', 'Nếu thời tiết xấu thì anh làm sao?', 33),
(1633, 123, 'GRAMMAR', 129, 'Ví dụ 34', 'てんきが わるかったら、りょこうを やめます。', 'Nếu thời tiết xấu, tôi sẽ hủy chuyến du lịch.', 34),
(1634, 123, 'GRAMMAR', 132, 'Ví dụ 35', 'あめが ふったら、どう しますか。', 'Nếu mưa thì anh tính sao ạ?', 35),
(1635, 123, 'GRAMMAR', 132, 'Ví dụ 36', 'いつ くにへ かえりますか。', 'Khi nào anh về nước?', 36),
(1636, 123, 'GRAMMAR', 131, 'Ví dụ 37', 'らいげつ、くにへ かえります。', 'Tháng sau, tôi sẽ về nước.', 37),
(1637, 123, 'GRAMMAR', 132, 'Ví dụ 38', 'しごとが おわったら、どう しますか。', 'Nếu xong việc thì anh tính sao?', 38),
(1638, 123, 'GRAMMAR', 130, 'Ví dụ 39', 'たいへんでも、しごとを つづけます。', 'Dù vất vả tôi vẫn làm tiếp.', 39),
(1639, 123, 'GRAMMAR', 130, 'Ví dụ 40', 'たいへんでも、がんばります。', 'Dù vất vả tôi vẫn cố.', 40),
(1640, 123, 'GRAMMAR', 130, 'Ví dụ 41', 'むずかしくても、がんばります。', 'Dù khó tôi vẫn cố.', 41),
(1641, 123, 'GRAMMAR', 129, 'Ví dụ 42', 'ひまだったら、のみに いきます。', 'Nếu rảnh, tôi sẽ đi uống.', 42),
(1642, 123, 'GRAMMAR', 129, 'Ví dụ 43', 'たとえば あめが ふったら、うちに います。', 'Ví dụ như nếu trời mưa, tôi sẽ ở nhà.', 43),
(1643, 123, 'GRAMMAR', 129, 'Ví dụ 44', 'きたら、ぜひ あんないします。', 'Nếu anh tới, tôi nhất định sẽ dẫn đi tham quan.', 44),
(1644, 123, 'GRAMMAR', 129, 'Ví dụ 45', 'うちへ かえったら、また でんわします。', 'Về tới nhà tôi sẽ gọi lại.', 45),
(1645, 123, 'GRAMMAR', 129, 'Ví dụ 46', 'にほんへ きたら、でんわして ください。', 'Sang Nhật thì anh gọi cho tôi nhé.', 46),
(1646, 123, 'GRAMMAR', 129, 'Ví dụ 47', 'きたら、あんないします。', 'Nếu anh tới, tôi sẽ dẫn đi tham quan.', 47),
(1647, 123, 'GRAMMAR', 131, 'Ví dụ 48', 'くにへ かえりますから、さびしいです。', 'Vì sắp về nước nên tôi cảm thấy buồn.', 48),
(1648, 123, 'GRAMMAR', 131, 'Ví dụ 49', 'くにへ かえりますから、おげんきで。', 'Vì tôi sắp về nước, chúc anh giữ gìn sức khỏe nhé.', 49),
(1649, 123, 'GRAMMAR', 131, 'Ví dụ 50', 'くにへ かえりますから、おせわに なりました。', 'Tôi sắp về nước, cảm ơn anh đã giúp đỡ.', 50),
(1650, 124, 'LISTENING', NULL, 'Linh', 'あめが ふったら、どう しますか。', 'Nếu trời mưa thì anh tính sao ạ?', 1),
(1651, 124, 'LISTENING', NULL, 'Nguyễn', 'あめが ふったら、うちで えいがを みます。', 'Nếu mưa thì mình xem phim ở nhà.', 2),
(1652, 124, 'LISTENING', NULL, 'Linh', 'てんきが よかったら。', 'Còn nếu thời tiết đẹp ạ?', 3),
(1653, 124, 'LISTENING', NULL, 'Nguyễn', 'うみへ あそびに いきます。', 'Thì mình ra biển chơi.', 4),
(1654, 124, 'LISTENING', NULL, 'Linh', 'とおくても いきますか。', 'Xa thì anh vẫn đi ạ?', 5),
(1655, 124, 'LISTENING', NULL, 'Nguyễn', 'ええ、とおくても いきますよ。', 'Ừ, xa mấy anh vẫn đi.', 6),
(1656, 124, 'LISTENING', NULL, 'Linh', 'じゃ、えきに ついたら でんわします。', 'Vậy tới ga em gọi điện nhé.', 7),
(1657, 124, 'LISTENING', NULL, 'Nguyễn', 'はい、まって います。', 'Ừ, anh đợi.', 8),
(1658, 125, 'LISTENING', NULL, 'Tanaka', 'くには いつ かえりますか。', 'Khi nào anh về nước?', 1),
(1659, 125, 'LISTENING', NULL, 'Nguyễn', 'しごとが おわったら、らいねん かえります。', 'Xong việc thì sang năm tôi về.', 2),
(1660, 125, 'LISTENING', NULL, 'Tanaka', 'さびしく なりますね。', 'Sẽ hụt hẫng lắm đấy.', 3),
(1661, 125, 'LISTENING', NULL, 'Nguyễn', 'ながい あいだ おせわに なりました。', 'Suốt thời gian qua anh đã giúp tôi nhiều.', 4),
(1662, 125, 'LISTENING', NULL, 'Tanaka', 'べんきょうは つづけますか。', 'Anh vẫn học tiếp chứ?', 5),
(1663, 125, 'LISTENING', NULL, 'Nguyễn', 'いそがしくても、つづけます。', 'Dù bận tôi vẫn học tiếp.', 6),
(1664, 125, 'LISTENING', NULL, 'Tanaka', 'ベトナムへ いったら、あんないして くれますか。', 'Nếu tôi sang Việt Nam, anh dẫn tôi đi nhé?', 7),
(1665, 125, 'LISTENING', NULL, 'Nguyễn', 'もちろんです。おげんきで。', 'Tất nhiên rồi. Anh giữ sức khoẻ nhé.', 8),
