(1706, 128, 'GRAMMAR', 138, 'Ví dụ 40', 'この きかいは どう つかったら いいですか。', 'Máy này dùng thế nào thì được ạ?', 40),
(1707, 128, 'GRAMMAR', 138, 'Ví dụ 41', 'てつづきは いつ したら いいですか。', 'Thủ tục thì làm lúc nào thì được ạ?', 41),
(1708, 128, 'GRAMMAR', 134, 'Ví dụ 42', 'じつは ねつが あるんです。', 'Thật ra là tôi bị sốt.', 42),
(1709, 128, 'GRAMMAR', 134, 'Ví dụ 43', 'それで びょういんへ いくんです。', 'Vì thế nên tôi mới đi bệnh viện.', 43),
(1710, 128, 'GRAMMAR', 134, 'Ví dụ 44', 'たぶん でんしゃが おくれて いるんです。', 'Chắc là tàu đang trễ ạ.', 44),
(1711, 128, 'GRAMMAR', 134, 'Ví dụ 45', 'すぐ れんらくするんです。', 'Tôi sẽ liên lạc ngay.', 45),
(1712, 128, 'GRAMMAR', 134, 'Ví dụ 46', 'あとで ぎんこうへ いくんです。', 'Lát nữa tôi đi ngân hàng.', 46),
(1713, 128, 'GRAMMAR', 135, 'Ví dụ 47', 'じかんが ないんです。', 'Tôi không có thời gian.', 47),
(1714, 128, 'GRAMMAR', 135, 'Ví dụ 48', 'おかねが ないんです。', 'Tôi không có tiền.', 48),
(1715, 128, 'GRAMMAR', 135, 'Ví dụ 49', 'でんわが つながらないんです。', 'Điện thoại không gọi được.', 49),
(1716, 128, 'GRAMMAR', 135, 'Ví dụ 50', 'ビザは いらないんです。', 'Visa thì không cần.', 50),
(1717, 128, 'GRAMMAR', 134, 'Ví dụ 51', 'きょう もうしこむんです。', 'Hôm nay tôi nộp đơn đăng ký.', 51),
(1718, 128, 'GRAMMAR', 134, 'Ví dụ 52', 'ろくじまで ざんぎょうするんです。', 'Tôi tăng ca tới sáu giờ.', 52),
(1719, 129, 'LISTENING', NULL, 'Tanaka', 'はい、たなかです。', 'Alô, Tanaka nghe đây.', 1),
(1720, 129, 'LISTENING', NULL, 'Nguyễn', 'グエンです。あさから ねつが あるんです。', 'Nguyễn đây ạ. Từ sáng em bị sốt.', 2),
(1721, 129, 'LISTENING', NULL, 'Tanaka', 'それは たいへんですね。びょういんへ いきましたか。', 'Thế thì mệt rồi. Cậu đi bệnh viện chưa?', 3),
(1722, 129, 'LISTENING', NULL, 'Nguyễn', 'まだです。これから いきたいんです。', 'Vẫn chưa ạ. Lát nữa em muốn đi.', 4),
(1723, 129, 'LISTENING', NULL, 'Tanaka', 'きょうは やすんで ください。しごとは だいじょうぶです。', 'Hôm nay cậu nghỉ đi. Việc thì không sao.', 5),
(1724, 129, 'LISTENING', NULL, 'Nguyễn', 'すみません。ごごの かいぎが あるんですが。', 'Em xin lỗi. Chiều nay có cuộc họp mà ạ.', 6),
(1725, 129, 'LISTENING', NULL, 'Tanaka', 'かいぎは わたしが でます。ゆっくり やすんで ください。', 'Cuộc họp để tôi dự. Cậu cứ nghỉ cho khoẻ.', 7),
(1726, 129, 'LISTENING', NULL, 'Nguyễn', 'ありがとう ございます。あとで また れんらくします。', 'Em cảm ơn anh. Lát nữa em liên lạc lại.', 8),
(1727, 130, 'LISTENING', NULL, 'Linh', 'たなかさん、ちょっと そうだんが あるんですが。', 'Anh Tanaka ơi, em có chuyện muốn hỏi ý anh một chút.', 1),
(1728, 130, 'LISTENING', NULL, 'Tanaka', 'はい、なにか あったんですか。', 'Ừ, có chuyện gì thế?', 2),
(1729, 130, 'LISTENING', NULL, 'Linh', 'じゅうしょが かわったんです。もうしこみしょは どこに だしたら いいですか。', 'Em vừa đổi địa chỉ. Đơn đăng ký nộp ở đâu thì được ạ?', 3),
(1730, 130, 'LISTENING', NULL, 'Tanaka', '３ばんの まどぐちです。パスポートは やくしょで つくるんです。', 'Ở quầy số 3. Hộ chiếu thì làm ở cơ quan hành chính đấy.', 4),
(1731, 130, 'LISTENING', NULL, 'Linh', 'いんかんは いるんですか。', 'Có cần con dấu tên không ạ?', 5),
(1732, 130, 'LISTENING', NULL, 'Tanaka', 'いんかんは いらないんです。サインで いいですよ。', 'Con dấu tên thì không cần. Ký tên là được.', 6),
(1733, 130, 'LISTENING', NULL, 'Linh', 'てつづきは どのぐらい かかるんですか。', 'Thủ tục mất chừng bao lâu ạ?', 7),
(1734, 130, 'LISTENING', NULL, 'Tanaka', '３０ぷんぐらいです。じかんが ないんですか。', 'Chừng ba mươi phút. Em không có thời gian à?', 8),
