(2125, 159, 'LISTENING', NULL, 'Nguyễn', 'かいぎは でた ほうが いいですか。', 'Cuộc họp có nên dự không ạ?', 4),
(2126, 159, 'LISTENING', NULL, 'Tanaka', 'むりを しない ほうが いいです。わたしが でます。', 'Không nên gắng sức. Để tôi dự cho.', 5),
(2127, 159, 'LISTENING', NULL, 'Nguyễn', 'ありがとう ございます。くすりは のんだ ほうが いいですか。', 'Cảm ơn anh. Thuốc có nên uống không ạ?', 6),
(2128, 159, 'LISTENING', NULL, 'Tanaka', 'くすりは ごはんの あとで のんだ ほうが いいです。', 'Thuốc thì nên uống sau bữa ăn.', 7),
(2129, 159, 'LISTENING', NULL, 'Nguyễn', 'わかりました。あしたも やすむかもしれません。', 'Tôi hiểu rồi. Có lẽ mai tôi cũng nghỉ.', 8),
(2130, 160, 'LISTENING', NULL, 'Linh', 'たなかさん、てんきは どうでしょうか。', 'Anh Tanaka, thời tiết sẽ thế nào ạ?', 1),
