(2132, 160, 'LISTENING', NULL, 'Linh', 'きょうの じゅぎょうは いった ほうが いいですか。', 'Buổi học hôm nay có nên đi không ạ?', 3),
(2133, 160, 'LISTENING', NULL, 'Tanaka', 'たいふうの ひは でない ほうが いいです。', 'Ngày bão thì không nên ra ngoài.', 4),
(2134, 160, 'LISTENING', NULL, 'Linh', 'でんしゃも とまるかもしれませんね。', 'Tàu điện có lẽ cũng dừng nhỉ.', 5),
(2135, 160, 'LISTENING', NULL, 'Tanaka', 'はい。もしかしたら じゅぎょうも ちゅうしに なるかもしれません。', 'Ừ. Biết đâu buổi học cũng bị huỷ cũng nên.', 6),
(2136, 160, 'LISTENING', NULL, 'Linh', 'せんせいに れんらくした ほうが いいですね。', 'Em nên báo cho thầy thì hơn nhỉ.', 7),
(2137, 160, 'LISTENING', NULL, 'Tanaka', 'そう しましょう。あしたは はれるでしょう。', 'Làm thế đi. Mai chắc sẽ nắng thôi.', 8),
