(2194, 164, 'LISTENING', NULL, 'Tanaka', 'さわるなと かいて あります。きかいが あぶないんです。', 'Ghi là đừng chạm vào. Vì máy nguy hiểm.', 6),
(2195, 164, 'LISTENING', NULL, 'Nguyễn', 'わかりました。ヘルメットは いりますか。', 'Tôi hiểu rồi. Có cần mũ bảo hộ không ạ?', 7),
(2196, 164, 'LISTENING', NULL, 'Tanaka', 'はい。こうじげんばに ヘルメットちゃくようと かいて あります。', 'Có. Ở công trường ghi là phải đội mũ bảo hộ.', 8),
(2197, 165, 'LISTENING', NULL, 'Linh', 'あの ひょうしきは とまれと かいて ありますね。', 'Biển kia ghi là dừng lại nhỉ.', 1),
(2198, 165, 'LISTENING', NULL, 'Tanaka', 'そうです。とまれは つよい ことばです。', 'Đúng rồi. "Dừng lại" là lời nói gắt.', 2),
(2199, 165, 'LISTENING', NULL, 'Linh', 'ともだちにも つかえますか。', 'Với bạn bè có dùng được không ạ?', 3),
