(2450, 183, 'GRAMMAR', 201, 'Ví dụ 44', 'せんせいに ほめられて うれしかったです。', 'Tôi đã rất vui vì được thầy cô khen.', 44),
(2451, 183, 'GRAMMAR', 202, 'Ví dụ 45', 'この レポートは どうりょうに よって かかれました。', 'Bản báo cáo này được viết ra bởi đồng nghiệp.', 45),
(2452, 183, 'GRAMMAR', 204, 'Ví dụ 46', 'さいふは だれに とられましたか。', 'Cái ví đã bị lấy mất bởi ai?', 46),
(2453, 183, 'GRAMMAR', 204, 'Ví dụ 47', 'はしは いつ つくられましたか。', 'Cây cầu đã được làm ra khi nào?', 47),
(2454, 183, 'GRAMMAR', 204, 'Ví dụ 48', 'さいふは どこで ぬすまれましたか。', 'Cái ví đã bị trộm ở đâu?', 48),
(2455, 183, 'GRAMMAR', 202, 'Ví dụ 49', 'この たてものは ゆうめいな ひとに よって つくられました。', 'Toà nhà này do một người nổi tiếng dựng nên.', 49),
(2456, 183, 'GRAMMAR', 200, 'Ví dụ 50', 'ともだちに にっきを よまれました。', 'Tôi bị bạn đọc mất nhật ký.', 50),
(2457, 184, 'LISTENING', NULL, 'Tanaka', 'どう したんですか。', 'Có chuyện gì thế?', 1),
(2458, 184, 'LISTENING', NULL, 'Linh', 'かえりに あめに ふられました。', 'Lúc về em bị mưa dội ạ.', 2),
(2459, 184, 'LISTENING', NULL, 'Tanaka', 'かさは なかったんですか。', 'Em không có ô à?', 3),
(2460, 184, 'LISTENING', NULL, 'Linh', 'でんしゃで さいふを とられました。かさも かえませんでした。', 'Em bị lấy mất ví trên tàu. Nên ô cũng không mua được.', 4),
(2461, 184, 'LISTENING', NULL, 'Tanaka', 'それは たいへんですね。けいさつには いきましたか。', 'Thế thì căng rồi. Em ra cảnh sát chưa?', 5),
(2462, 184, 'LISTENING', NULL, 'Linh', 'いきました。けいさつに いろいろ きかれました。', 'Em ra rồi. Em bị cảnh sát hỏi đủ thứ.', 6),
(2463, 184, 'LISTENING', NULL, 'Tanaka', 'じてんしゃは みつかりましたか。', 'Xe đạp tìm thấy chưa?', 7),
(2464, 184, 'LISTENING', NULL, 'Linh', 'じてんしゃは こうえんで みつかりました。', 'Xe đạp tìm thấy ở công viên rồi ạ.', 8),
(2465, 185, 'LISTENING', NULL, 'Nguyễn', 'はしは いつ つくられましたか。', 'Cây cầu được xây khi nào ạ?', 1),
(2466, 185, 'LISTENING', NULL, 'Tanaka', 'この はしは １００ねん まえに つくられました。', 'Cây cầu này được xây một trăm năm trước.', 2),
(2467, 185, 'LISTENING', NULL, 'Nguyễn', 'むこうの たてものも ふるいですね。', 'Toà nhà đằng kia cũng cổ nhỉ.', 3),
(2468, 185, 'LISTENING', NULL, 'Tanaka', 'たてものは えどじだいに たてられました。', 'Toà nhà được dựng thời Edo.', 4),
(2469, 185, 'LISTENING', NULL, 'Nguyễn', 'この まちは ゆうめいですか。', 'Thị trấn này có nổi tiếng không ạ?', 5),
(2470, 185, 'LISTENING', NULL, 'Tanaka', 'この まちは おんせんで しられて います。', 'Thị trấn này nổi tiếng nhờ suối nước nóng.', 6),
(2471, 185, 'LISTENING', NULL, 'Nguyễn', 'まつりは いつ ひらかれますか。', 'Lễ hội được tổ chức khi nào ạ?', 7),
(2472, 185, 'LISTENING', NULL, 'Tanaka', 'まつりは まいとし なつに ひらかれます。', 'Lễ hội được tổ chức vào mùa hè hằng năm.', 8),
(2473, 186, 'READING', NULL, 'Danh sách từ vựng bài 38', 'Bài 38 có 50 từ vựng.', NULL, 1),
(2474, 188, 'GRAMMAR', 210, 'Ví dụ 1', 'ひとりで およぐのは たのしいですか。', 'Đi bơi một mình có vui không?', 1),
(2475, 188, 'GRAMMAR', 205, 'Ví dụ 2', 'うたうのが すきです。', 'Tôi thích hát.', 2),
