(2477, 188, 'GRAMMAR', 206, 'Ví dụ 4', 'りょうりするのが とくいです。', 'Tôi khá khoản nấu ăn.', 4),
(2478, 188, 'GRAMMAR', 205, 'Ví dụ 5', 'しゃしんを とるのが すきです。', 'Tôi thích chụp ảnh.', 5),
(2479, 188, 'GRAMMAR', 205, 'Ví dụ 6', 'ほんを よむのが すきです。', 'Tôi thích đọc sách.', 6),
(2480, 188, 'GRAMMAR', 206, 'Ví dụ 7', 'えを かくのが とくいです。', 'Tôi khá việc vẽ tranh.', 7),
(2481, 188, 'GRAMMAR', 206, 'Ví dụ 8', 'かんじを おぼえるのが にがてです。', 'Tôi ngại việc ghi nhớ chữ Hán.', 8),
(2482, 188, 'GRAMMAR', 206, 'Ví dụ 9', 'みんなは うたうのが じょうずです。', 'Mọi người hát rất giỏi.', 9),
(2483, 188, 'GRAMMAR', 206, 'Ví dụ 10', 'えを かくのが へたです。', 'Tôi vẽ tranh rất vụng.', 10),
(2484, 188, 'GRAMMAR', 205, 'Ví dụ 11', 'まつのが きらいです。', 'Tôi ghét phải chờ.', 11),
(2485, 188, 'GRAMMAR', 207, 'Ví dụ 12', 'みんなで およぐのは たのしいです。', 'Cả nhóm cùng đi bơi thì vui.', 12),
(2486, 188, 'GRAMMAR', 207, 'Ví dụ 13', 'かんじを おぼえるのは むずかしいです。', 'Nhớ chữ Hán thì khó.', 13),
(2487, 188, 'GRAMMAR', 207, 'Ví dụ 14', 'でんきを けすのは かんたんです。', 'Tắt đèn thì dễ.', 14),
(2488, 188, 'GRAMMAR', 207, 'Ví dụ 15', 'はやく おきるのは たいへんです。', 'Dậy sớm thì vất vả.', 15),
(2489, 188, 'GRAMMAR', 207, 'Ví dụ 16', 'ほんを よむのは おもしろいです。', 'Đọc sách thì thú vị.', 16),
(2490, 188, 'GRAMMAR', 207, 'Ví dụ 17', 'レポートを かくのは じかんが かかります。', 'Viết báo cáo thì mất thời gian.', 17),
(2491, 188, 'GRAMMAR', 209, 'Ví dụ 18', 'はやく おきるのを わすれました。', 'Tôi đã quên mất việc phải dậy sớm.', 18),
(2492, 188, 'GRAMMAR', 209, 'Ví dụ 19', 'でんきを けすのを わすれないで ください。', 'Anh đừng quên tắt đèn nhé.', 19),
(2493, 188, 'GRAMMAR', 208, 'Ví dụ 20', 'たいせつな ことは やくそくを まもる ことです。', 'Điều quan trọng là giữ lời hứa.', 20),
(2494, 188, 'GRAMMAR', 208, 'Ví dụ 21', 'もんだいは やくそくを しらなかった ことです。', 'Vấn đề là tôi đã không biết có cuộc hẹn ấy.', 21),
(2495, 188, 'GRAMMAR', 208, 'Ví dụ 22', 'たいせつな ことは やくそくを おぼえている ことです。', 'Điều quan trọng là ghi nhớ lời hứa.', 22),
(2496, 188, 'GRAMMAR', 208, 'Ví dụ 23', 'しゅみは ほんを よむ ことです。', 'Sở thích là đọc sách.', 23),
(2497, 188, 'GRAMMAR', 208, 'Ví dụ 24', 'ゆめは ひとりで およぐ ことです。', 'Ước mơ là tự mình bơi lội.', 24),
(2498, 188, 'GRAMMAR', 208, 'Ví dụ 25', 'しごとの ないようは レポートを かく ことです。', 'Nội dung công việc là viết báo cáo.', 25),
(2499, 188, 'GRAMMAR', 208, 'Ví dụ 26', 'やくそくは はやく おきる ことです。', 'Lời hứa là sẽ dậy sớm.', 26),
(2500, 188, 'GRAMMAR', 208, 'Ví dụ 27', 'たいせつな ことは かぎを かける ことです。', 'Điều quan trọng là khoá cửa.', 27);
