(2597, 194, 'LISTENING', NULL, 'Tanaka', 'よかったです。あんしんしました。', 'May quá. Tôi yên tâm rồi.', 7),
(2598, 194, 'LISTENING', NULL, 'Nguyễn', 'ごめんなさい。あしたは はやめに でます。', 'Tôi xin lỗi. Mai tôi sẽ đi sớm hơn.', 8),
(2599, 195, 'LISTENING', NULL, 'Tanaka', 'しあいは どう なりましたか。', 'Trận đấu ra sao rồi?', 1),
(2600, 195, 'LISTENING', NULL, 'Linh', 'あめで しあいが ちゅうしに なりました。', 'Vì mưa mà trận đấu bị huỷ ạ.', 2),
(2601, 195, 'LISTENING', NULL, 'Tanaka', 'ざんねんでしたね。', 'Tiếc nhỉ.', 3),
(2602, 195, 'LISTENING', NULL, 'Linh', 'はい、ちゅうしに なって、ざんねんでした。', 'Vâng, bị huỷ nên em tiếc lắm.', 4),
(2603, 195, 'LISTENING', NULL, 'Tanaka', 'しらせは きましたか。', 'Tin báo tới chưa?', 5),
(2604, 195, 'LISTENING', NULL, 'Linh', 'しらせは けさ きました。ごうかくの しらせを きいて、うれしかったです。', 'Tin báo sáng nay tới rồi. Nghe tin đỗ em vui lắm.', 6),
(2605, 195, 'LISTENING', NULL, 'Tanaka', 'おめでとう ございます。がっこうは やすみですか。', 'Chúc mừng em. Trường có nghỉ không?', 7),
(2606, 195, 'LISTENING', NULL, 'Linh', 'たいふうで がっこうが やすみに なりました。', 'Vì bão mà trường thành nghỉ ạ.', 8),
