(3306, 248, 'GRAMMAR', 281, 'Ví dụ 25', 'さきに はっぴょうさせて いただきます。', 'Tôi xin phép được trình bày trước ạ.', 25),
(3307, 248, 'GRAMMAR', 281, 'Ví dụ 26', 'あした やすませて いただきます。', 'Ngày mai tôi xin phép được nghỉ ạ.', 26),
(3308, 248, 'GRAMMAR', 281, 'Ví dụ 27', 'さきに かえらせて いただきます。', 'Tôi xin phép được về trước ạ.', 27),
(3309, 248, 'GRAMMAR', 281, 'Ví dụ 28', 'この かさを つかわせて いただきます。', 'Tôi xin phép được dùng cái ô này ạ.', 28),
(3310, 248, 'GRAMMAR', 282, 'Ví dụ 29', 'にもつは おもちしましょうか。', 'Hành lý để tôi mang nhé ạ?', 29),
(3311, 248, 'GRAMMAR', 282, 'Ví dụ 30', 'メールは とどきましたか。', 'Thư điện tử đã tới chưa ạ?', 30),
(3312, 248, 'GRAMMAR', 282, 'Ví dụ 31', 'かいぎしつは どちらですか。', 'Phòng họp ở đâu ạ?', 31),
(3313, 248, 'GRAMMAR', 282, 'Ví dụ 32', 'たなかさんは いらっしゃいますか。', 'Anh Tanaka có ở đó không ạ?', 32),
(3314, 248, 'GRAMMAR', 282, 'Ví dụ 33', 'くうこうへは なんじに まいれば よろしいですか。', 'Mấy giờ tôi ra sân bay thì được ạ?', 33),
(3315, 248, 'GRAMMAR', 282, 'Ví dụ 34', 'コピーは おねがいできますか。', 'Nhờ anh phô tô được không ạ?', 34),
(3316, 248, 'GRAMMAR', 277, 'Ví dụ 35', 'かいぎしつまで しりょうを おもちします。', 'Tôi xin phép mang tài liệu đến phòng họp ạ.', 35),
(3317, 248, 'GRAMMAR', 280, 'Ví dụ 36', 'たなかは まって おります。', 'Anh Tanaka đang chờ ạ.', 36),
(3318, 248, 'GRAMMAR', 278, 'Ví dụ 37', 'ただいま くうこうへ まいります。', 'Ngay lúc này tôi sẽ tới sân bay ạ.', 37),
(3319, 248, 'GRAMMAR', 277, 'Ví dụ 38', 'わたくしが コピーを おもちします。', 'Tôi xin phép mang bản phô tô đến ạ.', 38),
(3320, 248, 'GRAMMAR', 280, 'Ví dụ 39', 'ただいま かいぎしつで まって おります。', 'Tôi hiện đang chờ ở phòng họp ạ.', 39),
(3321, 248, 'GRAMMAR', 278, 'Ví dụ 40', 'のちほど おたくへ まいります。', 'Lát nữa tôi sẽ tới quý phủ ạ.', 40),
(3322, 248, 'GRAMMAR', 281, 'Ví dụ 41', 'さきに つかわせて いただきます。', 'Tôi xin phép được dùng trước ạ.', 41),
(3323, 248, 'GRAMMAR', 281, 'Ví dụ 42', 'けっかを はっぴょうさせて いただきます。', 'Tôi xin phép công bố kết quả ạ.', 42),
(3324, 248, 'GRAMMAR', 277, 'Ví dụ 43', 'のちほど おでんわを おかけします。', 'Tôi xin phép gọi điện thoại sau ạ.', 43),
(3325, 248, 'GRAMMAR', 277, 'Ví dụ 44', 'メールを おおくりします。', 'Tôi xin gửi thư điện tử ạ.', 44),
(3326, 248, 'GRAMMAR', 277, 'Ví dụ 45', 'さきに メールを おおくりします。', 'Tôi xin phép gửi thư điện tử trước ạ.', 45),
(3327, 248, 'GRAMMAR', 278, 'Ví dụ 46', 'しりょうを おねがい いたします。', 'Tôi xin nhờ ngài việc tài liệu ạ.', 46),
(3328, 248, 'GRAMMAR', 278, 'Ví dụ 47', 'これで しつれい いたします。', 'Tôi xin phép cáo lui ạ.', 47),
(3329, 248, 'GRAMMAR', 280, 'Ví dụ 48', 'わたくしは おせわに なって おります。', 'Tôi vẫn luôn được ngài giúp đỡ ạ.', 48),
(3330, 248, 'GRAMMAR', 281, 'Ví dụ 49', 'ごせつめいさせて いただきます。', 'Tôi xin phép được giải thích ạ.', 49),
(3331, 248, 'GRAMMAR', 278, 'Ví dụ 50', 'あした おたくへ うかがいます。', 'Mai tôi xin tới nhà ngài ạ.', 50),
(3332, 248, 'GRAMMAR', 278, 'Ví dụ 51', 'あした おたくへ まいります。', 'Ngày mai tôi sẽ tới quý phủ ạ.', 51),
(3333, 249, 'LISTENING', NULL, 'Nguyễn', 'はじめまして。わたくしは グエンと もうします。', 'Hân hạnh gặp ngài. Tôi tên là Nguyễn ạ.', 1),
(3334, 249, 'LISTENING', NULL, 'Tanaka', 'よろしく おねがい いたします。', 'Rất mong được giúp đỡ ạ.', 2),
(3335, 249, 'LISTENING', NULL, 'Nguyễn', 'にもつは おもちしましょうか。', 'Hành lý để tôi mang nhé ạ?', 3),
(3336, 249, 'LISTENING', NULL, 'Tanaka', 'にもつを おもちします。どうぞ こちらへ。', 'Để tôi mang hành lý. Mời ngài đi lối này.', 4),
(3337, 249, 'LISTENING', NULL, 'Nguyễn', 'かいぎしつは どちらですか。', 'Phòng họp ở đâu ạ?', 5),
(3338, 249, 'LISTENING', NULL, 'Tanaka', 'かいぎしつへ ごあんないします。', 'Tôi xin dẫn ngài tới phòng họp ạ.', 6),
(3339, 249, 'LISTENING', NULL, 'Nguyễn', 'コピーは おねがいできますか。', 'Nhờ anh phô tô được không ạ?', 7),
(3340, 249, 'LISTENING', NULL, 'Tanaka', 'コピーを おとりします。', 'Để tôi phô tô cho ạ.', 8),
(3341, 250, 'LISTENING', NULL, 'Nguyễn', 'たなかは おりますか。', 'Anh Tanaka có ở đó không ạ?', 1),
(3342, 250, 'LISTENING', NULL, 'Linh', 'たなかは ただいま せきを はずして おります。', 'Anh Tanaka hiện không có mặt ạ.', 2),
(3343, 250, 'LISTENING', NULL, 'Nguyễn', 'しりょうは とどきましたか。', 'Tài liệu tới chưa ạ?', 3),
(3344, 250, 'LISTENING', NULL, 'Linh', 'しりょうを おおくりしました。', 'Tài liệu tôi đã gửi rồi ạ.', 4),
(3345, 250, 'LISTENING', NULL, 'Nguyễn', 'くうこうへは なんじに まいりますか。', 'Mấy giờ thì ra sân bay ạ?', 5),
(3346, 250, 'LISTENING', NULL, 'Linh', 'あした くうこうへ まいります。', 'Mai tôi ra sân bay ạ.', 6),
