(3551, 260, 'READING', NULL, 'bya', 'ビャ', 'bya', 28),
(3552, 260, 'READING', NULL, 'byu', 'ビュ', 'byu', 29),
(3553, 260, 'READING', NULL, 'byo', 'ビョ', 'byo', 30),
(3554, 260, 'READING', NULL, 'pya', 'ピャ', 'pya', 31),
(3555, 260, 'READING', NULL, 'pyu', 'ピュ', 'pyu', 32),
(3556, 260, 'READING', NULL, 'pyo', 'ピョ', 'pyo', 33),
(3557, 261, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(3558, 263, 'GRAMMAR', 283, 'Ví dụ 1', '日本に来たばかりで、まだ慣れていません。', 'Tôi mới sang Nhật nên vẫn chưa quen.', 1),
(3559, 263, 'GRAMMAR', 283, 'Ví dụ 2', 'さっきご飯を食べたばかりなのに、もうお腹がすいた。', 'Vừa mới ăn xong mà đã đói rồi.', 2),
(3560, 263, 'GRAMMAR', 284, 'Ví dụ 3', '会議の前に資料を読んでおきます。', 'Tôi sẽ đọc tài liệu trước cuộc họp.', 3),
(3561, 263, 'GRAMMAR', 284, 'Ví dụ 4', '窓は開けておいてください。', 'Xin cứ để cửa sổ mở.', 4),
(3562, 263, 'GRAMMAR', 285, 'Ví dụ 5', '会議は十時から始まる予定です。', 'Cuộc họp dự kiến bắt đầu từ mười giờ.', 5),
(3563, 263, 'GRAMMAR', 285, 'Ví dụ 6', '来週、出張の予定があります。', 'Tuần sau tôi có lịch đi công tác.', 6),
(3564, 263, 'GRAMMAR', 286, 'Ví dụ 7', '彼が来るかどうか分かりません。', 'Tôi không biết anh ấy có đến hay không.', 7),
(3565, 263, 'GRAMMAR', 286, 'Ví dụ 8', '正しいかどうか確認してください。', 'Xin kiểm tra xem có đúng không.', 8),
(3566, 263, 'GRAMMAR', 287, 'Ví dụ 9', 'こちらにお座りください。', 'Xin ngài ngồi bên này ạ.', 9),
(3567, 263, 'GRAMMAR', 287, 'Ví dụ 10', '内容をご確認ください。', 'Xin ngài xác nhận nội dung ạ.', 10),
(3568, 263, 'GRAMMAR', 288, 'Ví dụ 11', '日本の生活に慣れてきました。', 'Tôi đã dần quen với cuộc sống ở Nhật.', 11),
(3569, 263, 'GRAMMAR', 288, 'Ví dụ 12', '早起きすることに慣れていない。', 'Tôi chưa quen dậy sớm.', 12),
(3570, 264, 'LISTENING', NULL, 'Linh', '課長、今お時間よろしいでしょうか。', 'Trưởng phòng, bây giờ anh có rảnh chút không ạ?', 1),
(3571, 264, 'LISTENING', NULL, 'Trưởng phòng Sato', 'はい、どうしました。', 'Ừ, có chuyện gì thế?', 2),
(3572, 264, 'LISTENING', NULL, 'Linh', '実は、明日病院に行くために、一日休ませていただきたいのですが。', 'Thực ra là ngày mai em muốn xin nghỉ một ngày để đi bệnh viện ạ.', 3),
(3573, 264, 'LISTENING', NULL, 'Trưởng phòng Sato', 'そうですか。体調が悪いんですか。', 'Vậy à. Em thấy trong người không khoẻ à?', 4),
(3574, 264, 'LISTENING', NULL, 'Linh', '先週から咳が続いていて、一度診てもらったほうがいいと思いまして。', 'Em bị ho liên tục từ tuần trước, em nghĩ nên đi khám một lần cho chắc ạ.', 5),
(3575, 264, 'LISTENING', NULL, 'Trưởng phòng Sato', '分かりました。無理しないで、ゆっくり休んでください。', 'Tôi hiểu rồi. Đừng gắng sức, cứ nghỉ ngơi cho khoẻ nhé.', 6),
(3576, 264, 'LISTENING', NULL, 'Linh', 'ありがとうございます。仕事は田中さんに引き継いでおきます。', 'Em cảm ơn ạ. Công việc em sẽ bàn giao trước cho anh Tanaka.', 7),
(3577, 265, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(3578, 267, 'GRAMMAR', 289, 'Ví dụ 1', '彼は昨日出発したから、今日着くはずです。', 'Anh ấy khởi hành hôm qua nên hôm nay chắc hẳn đã tới.', 1),
(3579, 267, 'GRAMMAR', 289, 'Ví dụ 2', 'そんなことがあるはずがない。', 'Không thể nào có chuyện đó.', 2),
(3580, 267, 'GRAMMAR', 290, 'Ví dụ 3', '電車に傘を忘れてしまいました。', 'Tôi lỡ để quên ô trên tàu.', 3),
(3581, 267, 'GRAMMAR', 290, 'Ví dụ 4', '宿題はもうやってしまいました。', 'Bài tập tôi làm xong hết rồi.', 4),
(3582, 267, 'GRAMMAR', 291, 'Ví dụ 5', '母が寝ている間に、部屋を掃除した。', 'Nhân lúc mẹ đang ngủ tôi dọn phòng.', 5),
(3583, 267, 'GRAMMAR', 291, 'Ví dụ 6', '夏休みの間、ずっとアルバイトをしていた。', 'Suốt kỳ nghỉ hè tôi làm thêm.', 6),
(3584, 267, 'GRAMMAR', 292, 'Ví dụ 7', '地震の場合は、エレベーターを使わないでください。', 'Trong trường hợp động đất, xin đừng dùng thang máy.', 7),
(3585, 267, 'GRAMMAR', 292, 'Ví dụ 8', '遅れる場合は連絡してください。', 'Trường hợp đến muộn thì hãy liên lạc.', 8),
(3586, 267, 'GRAMMAR', 293, 'Ví dụ 9', '受付は二階でございます。', 'Quầy tiếp tân ở tầng hai ạ.', 9),
(3587, 267, 'GRAMMAR', 293, 'Ví dụ 10', 'こちらが資料でございます。', 'Đây là tài liệu ạ.', 10),
(3588, 267, 'GRAMMAR', 294, 'Ví dụ 11', 'この雨はやみそうもない。', 'Cơn mưa này xem chừng không tạnh.', 11),
(3589, 267, 'GRAMMAR', 294, 'Ví dụ 12', '今日中には終わりそうにない。', 'Xem chừng trong hôm nay không xong.', 12),
(3590, 268, 'LISTENING', NULL, 'Linh', 'すみません、予約はしていないんですが、診ていただけますか。', 'Xin lỗi, tôi chưa đặt hẹn, nhưng có khám được không ạ?', 1),
(3591, 268, 'LISTENING', NULL, 'Lễ tân', 'はい、大丈夫です。こちらの問診票にご記入ください。', 'Vâng, được ạ. Xin anh điền vào phiếu khai bệnh này.', 2),
(3592, 268, 'LISTENING', NULL, 'Linh', '書き方が分からないところがあるんですが。', 'Có chỗ tôi không biết cách viết ạ.', 3),
(3593, 268, 'LISTENING', NULL, 'Lễ tân', '症状と、いつから続いているかを書いていただければ大丈夫ですよ。', 'Anh chỉ cần ghi triệu chứng và bị từ bao giờ là được ạ.', 4),
(3594, 268, 'LISTENING', NULL, 'Bác sĩ', 'リンさん、どうされましたか。', 'Anh Linh, anh thấy sao?', 5),
(3595, 268, 'LISTENING', NULL, 'Linh', '先週から咳が止まらなくて、夜も眠れないんです。', 'Từ tuần trước tôi ho không dứt, ban đêm cũng không ngủ được.', 6),
(3596, 268, 'LISTENING', NULL, 'Bác sĩ', '熱はありますか。', 'Anh có sốt không?', 7),
(3597, 268, 'LISTENING', NULL, 'Linh', '熱はないんですが、のどがとても痛いです。', 'Sốt thì không, nhưng họng rất đau ạ.', 8),
(3598, 268, 'LISTENING', NULL, 'Bác sĩ', '風邪でしょう。薬を出しますから、三日分飲んでみてください。', 'Chắc là cảm thôi. Tôi kê thuốc, anh thử uống ba ngày xem.', 9),
(3599, 268, 'LISTENING', NULL, 'Bác sĩ', 'それでもよくならないようなら、また来てください。', 'Nếu vẫn không đỡ thì anh lại đến nhé.', 10),
(3600, 269, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(3601, 271, 'GRAMMAR', 295, 'Ví dụ 1', '十年も住んでいたのか。日本語が上手なわけだ。', 'Sống tới mười năm cơ à. Thảo nào tiếng Nhật giỏi thế.', 1),
(3602, 271, 'GRAMMAR', 295, 'Ví dụ 2', 'エアコンが壊れている。暑いわけだ。', 'Điều hoà hỏng. Thảo nào nóng.', 2),
(3603, 271, 'GRAMMAR', 296, 'Ví dụ 3', '先生は学生に作文を書かせた。', 'Thầy giáo bắt học sinh viết bài văn.', 3),
(3604, 271, 'GRAMMAR', 296, 'Ví dụ 4', 'その仕事は私にやらせてください。', 'Xin hãy để tôi làm công việc đó.', 4),
(3605, 271, 'GRAMMAR', 297, 'Ví dụ 5', '手を洗ってから食べてください。', 'Hãy rửa tay rồi mới ăn.', 5),
(3606, 271, 'GRAMMAR', 297, 'Ví dụ 6', '日本に来てから、三年になります。', 'Từ khi sang Nhật đến nay đã ba năm.', 6),
(3607, 271, 'GRAMMAR', 298, 'Ví dụ 7', 'バターの代わりにオリーブオイルを使います。', 'Tôi dùng dầu ô liu thay cho bơ.', 7),
(3608, 271, 'GRAMMAR', 298, 'Ví dụ 8', '部長の代わりに私が出席します。', 'Tôi sẽ dự thay trưởng phòng.', 8),
(3609, 271, 'GRAMMAR', 299, 'Ví dụ 9', '一人ずつ名前を呼びます。', 'Tôi sẽ gọi tên từng người một.', 9),
(3610, 271, 'GRAMMAR', 299, 'Ví dụ 10', '少しずつ上手になっています。', 'Tôi đang giỏi lên từng chút.', 10),
(3611, 271, 'GRAMMAR', 300, 'Ví dụ 11', 'おなかがすいてしょうがない。', 'Tôi đói không chịu nổi.', 11),
(3612, 271, 'GRAMMAR', 300, 'Ví dụ 12', '結果が気になってしょうがない。', 'Tôi sốt ruột về kết quả quá.', 12),
(3613, 272, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(3614, 274, 'GRAMMAR', 301, 'Ví dụ 1', '毎日野菜を食べるようにしています。', 'Tôi cố gắng ăn rau mỗi ngày.', 1),
(3615, 274, 'GRAMMAR', 301, 'Ví dụ 2', '夜遅く食べないようにしてください。', 'Xin hãy chú ý đừng ăn khuya.', 2),
(3616, 274, 'GRAMMAR', 302, 'Ví dụ 3', '午後から雨が降るかもしれません。', 'Chiều nay có thể trời mưa.', 3),
(3617, 274, 'GRAMMAR', 302, 'Ví dụ 4', '彼はもう帰ったかもしれない。', 'Có thể anh ấy về rồi.', 4),
(3618, 274, 'GRAMMAR', 303, 'Ví dụ 5', '先生に名前を呼ばれました。', 'Tôi được thầy gọi tên.', 5),
(3619, 274, 'GRAMMAR', 303, 'Ví dụ 6', '帰る途中で雨に降られた。', 'Trên đường về tôi bị mưa.', 6),
(3620, 274, 'GRAMMAR', 304, 'Ví dụ 7', '会議の最中に携帯が鳴ってしまった。', 'Đang giữa cuộc họp thì điện thoại tôi reo.', 7),
(3621, 274, 'GRAMMAR', 304, 'Ví dụ 8', '食事の最中に電話がかかってきた。', 'Đang ăn thì có điện thoại gọi đến.', 8),
(3622, 274, 'GRAMMAR', 305, 'Ví dụ 9', 'この薬は四時間おきに飲んでください。', 'Thuốc này uống cách bốn tiếng một lần.', 9),
(3623, 274, 'GRAMMAR', 305, 'Ví dụ 10', '一日おきにジムに通っている。', 'Tôi đến phòng gym cách ngày.', 10),
(3624, 274, 'GRAMMAR', 306, 'Ví dụ 11', '彼は元気そうに見える。', 'Anh ấy trông có vẻ khoẻ.', 11),
(3625, 274, 'GRAMMAR', 306, 'Ví dụ 12', 'その建物は城のように見える。', 'Toà nhà đó trông như một lâu đài.', 12),
(3626, 275, 'LISTENING', NULL, 'Linh', '駅の近くで、家賃六万円くらいの部屋を探しているんですが。', 'Tôi đang tìm phòng gần ga, tiền thuê khoảng sáu vạn yên ạ.', 1),
(3627, 275, 'LISTENING', NULL, 'Nhân viên môi giới', '広さはどのくらいをお考えですか。', 'Anh đang tính diện tích khoảng bao nhiêu ạ?', 2),
(3628, 275, 'LISTENING', NULL, 'Linh', '一人暮らしなので、ワンルームで十分です。', 'Tôi sống một mình nên một phòng là đủ.', 3),
(3629, 275, 'LISTENING', NULL, 'Nhân viên môi giới', 'こちらはいかがでしょうか。駅から歩いて七分です。', 'Chỗ này thì sao ạ? Đi bộ từ ga bảy phút.', 4),
(3630, 275, 'LISTENING', NULL, 'Linh', '日当たりはどうですか。', 'Ánh sáng thế nào ạ?', 5),
(3631, 275, 'LISTENING', NULL, 'Nhân viên môi giới', '南向きなので、昼間は電気をつけなくても明るいですよ。', 'Hướng nam nên ban ngày không bật đèn cũng sáng đấy ạ.', 6),
(3632, 275, 'LISTENING', NULL, 'Linh', '実際に見せていただくことはできますか。', 'Tôi có thể xem thực tế được không ạ?', 7),
(3633, 275, 'LISTENING', NULL, 'Nhân viên môi giới', 'もちろんです。今日の午後でしたらご案内できます。', 'Tất nhiên rồi ạ. Chiều nay thì tôi dẫn anh đi xem được.', 8),
(3634, 276, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(3635, 278, 'GRAMMAR', 307, 'Ví dụ 1', '練習して、泳げるようになりました。', 'Nhờ luyện tập, tôi đã bơi được.', 1),
(3636, 278, 'GRAMMAR', 307, 'Ví dụ 2', '最近、朝早く起きるようになった。', 'Gần đây tôi đã dậy sớm được.', 2),
(3637, 278, 'GRAMMAR', 308, 'Ví dụ 3', '電気がついている。中に誰かいるに違いない。', 'Đèn đang bật. Chắc chắn bên trong có người.', 3),
(3638, 278, 'GRAMMAR', 308, 'Ví dụ 4', 'この字を見れば、彼が書いたに違いない。', 'Nhìn nét chữ này là biết chắc chắn anh ấy viết.', 4),
(3639, 278, 'GRAMMAR', 309, 'Ví dụ 5', '子供のころ、毎日ピアノを練習させられた。', 'Hồi nhỏ tôi bị bắt tập piano mỗi ngày.', 5),
(3640, 278, 'GRAMMAR', 309, 'Ví dụ 6', '飲み会で歌を歌わされました。', 'Ở tiệc rượu tôi bị bắt hát.', 6),
(3641, 278, 'GRAMMAR', 310, 'Ví dụ 7', '出かけようとしたところに、客が来た。', 'Đúng lúc định ra ngoài thì có khách đến.', 7),
(3642, 278, 'GRAMMAR', 310, 'Ví dụ 8', '困っているところへ、彼が助けに来てくれた。', 'Đang lúc bí thì anh ấy đến giúp.', 8),
(3643, 278, 'GRAMMAR', 311, 'Ví dụ 9', '五分ごとにバスが来ます。', 'Cứ năm phút lại có một chuyến xe buýt.', 9),
(3644, 278, 'GRAMMAR', 311, 'Ví dụ 10', '会うごとに彼は元気になっていた。', 'Mỗi lần gặp anh ấy lại khoẻ hơn.', 10),
(3645, 279, 'LISTENING', NULL, 'Linh', 'これをベトナムに送りたいんですが。', 'Tôi muốn gửi cái này sang Việt Nam ạ.', 1),
(3646, 279, 'LISTENING', NULL, 'Nhân viên bưu điện', '中身は何でしょうか。', 'Bên trong là gì ạ?', 2),
(3647, 279, 'LISTENING', NULL, 'Linh', '服とお菓子です。壊れ物は入っていません。', 'Quần áo và bánh kẹo ạ. Không có đồ dễ vỡ.', 3),
(3648, 279, 'LISTENING', NULL, 'Nhân viên bưu điện', '船便と航空便がありますが、どちらになさいますか。', 'Có đường biển và đường hàng không, anh chọn loại nào ạ?', 4),
(3649, 279, 'LISTENING', NULL, 'Linh', '急がないので、安いほうでお願いします。', 'Tôi không vội nên cho tôi loại rẻ hơn ạ.', 5),
(3650, 279, 'LISTENING', NULL, 'Nhân viên bưu điện', '船便ですと一か月ほどかかりますが、よろしいですか。', 'Đường biển thì mất khoảng một tháng, anh thấy được không ạ?', 6),
(3651, 279, 'LISTENING', NULL, 'Linh', 'はい、大丈夫です。追跡はできますか。', 'Vâng, không sao ạ. Có theo dõi được không ạ?', 7),
(3652, 279, 'LISTENING', NULL, 'Nhân viên bưu điện', 'はい、こちらの番号でご確認いただけます。', 'Vâng, anh có thể kiểm tra bằng mã số này ạ.', 8),
(3653, 280, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(3654, 282, 'GRAMMAR', 312, 'Ví dụ 1', '留学するために、お金をためています。', 'Tôi đang để dành tiền để đi du học.', 1),
(3655, 282, 'GRAMMAR', 312, 'Ví dụ 2', '台風のために、電車が止まりました。', 'Vì bão nên tàu điện đã dừng.', 2),
(3656, 282, 'GRAMMAR', 313, 'Ví dụ 3', '外は寒いようです。みんなコートを着ています。', 'Bên ngoài có vẻ lạnh. Ai cũng mặc áo khoác.', 3),
(3657, 282, 'GRAMMAR', 313, 'Ví dụ 4', '彼は疲れているみたいだ。', 'Anh ấy trông có vẻ mệt.', 4),
(3658, 282, 'GRAMMAR', 314, 'Ví dụ 5', 'お荷物をお持ちします。', 'Để tôi xách hành lý giúp ạ.', 5),
(3659, 282, 'GRAMMAR', 314, 'Ví dụ 6', 'こちらでお待ちしております。', 'Tôi xin đợi ở đây ạ.', 6),
(3660, 282, 'GRAMMAR', 315, 'Ví dụ 7', '十年ぶりに故郷に帰った。', 'Sau mười năm tôi mới về quê.', 7),
(3661, 282, 'GRAMMAR', 315, 'Ví dụ 8', '三日ぶりに雨がやんだ。', 'Sau ba ngày mưa mới tạnh.', 8),
(3662, 282, 'GRAMMAR', 316, 'Ví dụ 9', '財布に千円しかない。', 'Trong ví chỉ còn mỗi nghìn yên.', 9),
(3663, 282, 'GRAMMAR', 316, 'Ví dụ 10', '彼しか知らない。', 'Chỉ mỗi anh ấy biết.', 10),
(3664, 283, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(3665, 285, 'GRAMMAR', 317, 'Ví dụ 1', '後ろの人にも聞こえるように、大きい声で話した。', 'Tôi nói to để người ngồi sau cũng nghe được.', 1),
(3666, 285, 'GRAMMAR', 317, 'Ví dụ 2', '忘れないように、メモしておきます。', 'Tôi ghi chú lại để khỏi quên.', 2),
(3667, 285, 'GRAMMAR', 318, 'Ví dụ 3', 'このケーキ、おいしそうですね。', 'Cái bánh này trông ngon nhỉ.', 3),
(3668, 285, 'GRAMMAR', 318, 'Ví dụ 4', '雨が降りそうだから、傘を持っていこう。', 'Trời có vẻ sắp mưa, mang ô đi thôi.', 4),
(3669, 285, 'GRAMMAR', 319, 'Ví dụ 5', 'だんだん寒くなってきました。', 'Trời đã dần lạnh đi.', 5),
(3670, 285, 'GRAMMAR', 319, 'Ví dụ 6', 'これから人口は減っていくだろう。', 'Từ nay dân số chắc sẽ giảm dần.', 6),
(3671, 285, 'GRAMMAR', 320, 'Ví dụ 7', 'これは初心者向けの教科書です。', 'Đây là giáo trình dành cho người mới bắt đầu.', 7),
(3672, 285, 'GRAMMAR', 320, 'Ví dụ 8', 'この部屋は南向きで明るい。', 'Phòng này hướng nam nên sáng.', 8),
(3673, 285, 'GRAMMAR', 321, 'Ví dụ 9', '金曜までに提出してください。', 'Xin nộp chậm nhất là thứ sáu.', 9),
(3674, 285, 'GRAMMAR', 321, 'Ví dụ 10', '五時まで待ちます。', 'Tôi sẽ đợi đến năm giờ.', 10),
(3675, 286, 'LISTENING', NULL, 'Linh', 'ゆきちゃん、ちょっと謝りたいことがあるんだ。', 'Yuki ơi, tớ có chuyện muốn xin lỗi.', 1),
(3676, 286, 'LISTENING', NULL, 'Yuki', '何。どうしたの。', 'Gì thế? Sao vậy?', 2),
(3677, 286, 'LISTENING', NULL, 'Linh', '借りたコップを落として、割ってしまったの。', 'Cái cốc tớ mượn, tớ đánh rơi vỡ mất rồi.', 3),
(3678, 286, 'LISTENING', NULL, 'Yuki', 'えっ、けがはしなかった。', 'Ơ, cậu có bị thương không?', 4),
(3679, 286, 'LISTENING', NULL, 'Linh', 'うん、大丈夫。本当にごめん。同じものを買って返すね。', 'Ừ, không sao. Tớ xin lỗi thật đấy. Tớ sẽ mua cái y hệt đền cho cậu.', 5),
(3680, 286, 'LISTENING', NULL, 'Yuki', 'そんなに気にしないで。安いものだし、けががなくてよかった。', 'Đừng bận tâm thế. Cốc rẻ thôi mà, không bị thương là may rồi.', 6),
(3681, 286, 'LISTENING', NULL, 'Linh', 'でも、気持ちだけでも受け取ってほしいな。', 'Nhưng ít ra tớ muốn cậu nhận cho tớ chút tấm lòng.', 7),
(3682, 286, 'LISTENING', NULL, 'Yuki', '分かった。じゃあ、今度お茶でもおごって。', 'Được rồi. Vậy lần tới cậu mời tớ trà nhé.', 8),
(3683, 287, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(3684, 289, 'GRAMMAR', 322, 'Ví dụ 1', '天気予報によると、明日は雨だそうです。', 'Theo dự báo thời tiết, nghe nói mai trời mưa.', 1),
(3685, 289, 'GRAMMAR', 322, 'Ví dụ 2', '山田さんは来月結婚するそうだ。', 'Nghe nói tháng sau anh Yamada kết hôn.', 2),
(3686, 289, 'GRAMMAR', 323, 'Ví dụ 3', '来年から日本で働くことにしました。', 'Tôi đã quyết định từ sang năm sẽ làm việc ở Nhật.', 3),
(3687, 289, 'GRAMMAR', 323, 'Ví dụ 4', '毎朝六時に起きることにしている。', 'Tôi tự đặt ra thói quen dậy lúc sáu giờ mỗi sáng.', 4),
(3688, 289, 'GRAMMAR', 324, 'Ví dụ 5', '壁に地図が貼ってあります。', 'Trên tường có dán sẵn tấm bản đồ.', 5),
(3689, 289, 'GRAMMAR', 324, 'Ví dụ 6', '飲み物は冷やしてあります。', 'Đồ uống đã được làm lạnh sẵn.', 6),
(3690, 289, 'GRAMMAR', 325, 'Ví dụ 7', '水を出しっぱなしにしないで。', 'Đừng để nước chảy suốt như thế.', 7),
(3691, 289, 'GRAMMAR', 325, 'Ví dụ 8', '電車で二時間立ちっぱなしだった。', 'Tôi phải đứng suốt hai tiếng trên tàu.', 8),
(3692, 289, 'GRAMMAR', 326, 'Ví dụ 9', '彼は父親のように優しい。', 'Anh ấy hiền như cha của mình.', 9),
(3693, 289, 'GRAMMAR', 326, 'Ví dụ 10', '氷のような冷たい手だ。', 'Đôi tay lạnh như băng.', 10),
(3694, 290, 'LISTENING', NULL, 'Linh', 'すみません、新宿へ行きたいんですが、この電車で合っていますか。', 'Xin lỗi, tôi muốn đi Shinjuku, đi tàu này có đúng không ạ?', 1),
(3695, 290, 'LISTENING', NULL, 'Nhân viên nhà ga', 'いいえ、この電車は反対方向です。', 'Không, tàu này đi ngược hướng ạ.', 2),
(3696, 290, 'LISTENING', NULL, 'Linh', 'えっ、どうすればいいですか。', 'Ơ, vậy tôi phải làm sao ạ?', 3),
(3697, 290, 'LISTENING', NULL, 'Nhân viên nhà ga', '次の駅で降りて、向かい側のホームに移ってください。', 'Anh xuống ga kế tiếp rồi chuyển sang sân ga đối diện ạ.', 4),
(3698, 290, 'LISTENING', NULL, 'Linh', '切符はそのまま使えますか。', 'Vé cũ vẫn dùng được chứ ạ?', 5),
(3699, 290, 'LISTENING', NULL, 'Nhân viên nhà ga', 'はい、同じ切符で大丈夫です。改札を出なければ追加料金はかかりません。', 'Vâng, cùng vé đó là được. Không ra khỏi cửa soát vé thì không mất thêm phí ạ.', 6),
(3700, 290, 'LISTENING', NULL, 'Linh', '分かりました。何分ぐらいかかりますか。', 'Tôi hiểu rồi. Mất khoảng bao nhiêu phút ạ?', 7),
(3701, 290, 'LISTENING', NULL, 'Nhân viên nhà ga', '乗り換えを入れて二十分ほどです。お気をつけて。', 'Tính cả đổi tàu thì khoảng hai mươi phút. Anh đi cẩn thận ạ.', 8),
(3702, 291, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(3703, 293, 'GRAMMAR', 327, 'Ví dụ 1', 'あの店は閉まったらしい。', 'Hình như cửa hàng đó đóng cửa rồi.', 1),
(3704, 293, 'GRAMMAR', 327, 'Ví dụ 2', '今日は春らしい天気ですね。', 'Hôm nay thời tiết đúng chất mùa xuân nhỉ.', 2),
(3705, 293, 'GRAMMAR', 328, 'Ví dụ 3', '来月、大阪へ転勤することになりました。', 'Tháng sau tôi được chuyển công tác đến Osaka.', 3),
(3706, 293, 'GRAMMAR', 328, 'Ví dụ 4', '会議は三時からということになった。', 'Cuộc họp được chốt là bắt đầu từ ba giờ.', 4),
(3707, 293, 'GRAMMAR', 329, 'Ví dụ 5', 'この服を着てみてもいいですか。', 'Tôi mặc thử bộ này được không ạ?', 5),
(3708, 293, 'GRAMMAR', 329, 'Ví dụ 6', '一度日本料理を作ってみたい。', 'Tôi muốn thử nấu món Nhật một lần.', 6),
(3709, 293, 'GRAMMAR', 330, 'Ví dụ 7', '社長はもうお帰りになりました。', 'Giám đốc đã ra về rồi ạ.', 7),
(3710, 293, 'GRAMMAR', 330, 'Ví dụ 8', 'この本をお読みになりましたか。', 'Ngài đã đọc cuốn sách này chưa ạ?', 8),
(3711, 293, 'GRAMMAR', 331, 'Ví dụ 9', '果物はりんごとかバナナとかが好きです。', 'Hoa quả thì tôi thích nào là táo nào là chuối.', 9),
(3712, 293, 'GRAMMAR', 331, 'Ví dụ 10', '行くとか行かないとか、はっきりして。', 'Đi hay không thì nói rõ đi.', 10),
(3713, 294, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(3714, 296, 'GRAMMAR', 332, 'Ví dụ 1', '今から出かけるところです。', 'Tôi đang định ra ngoài bây giờ.', 1),
(3715, 296, 'GRAMMAR', 332, 'Ví dụ 2', 'ちょうど食べ終わったところです。', 'Tôi vừa ăn xong đúng lúc này.', 2),
(3716, 296, 'GRAMMAR', 333, 'Ví dụ 3', '富士山に登ったことがありますか。', 'Bạn đã từng leo núi Phú Sĩ chưa?', 3),
(3717, 296, 'GRAMMAR', 333, 'Ví dụ 4', '日本の映画は一度も見たことがない。', 'Tôi chưa từng xem phim Nhật lần nào.', 4),
(3718, 296, 'GRAMMAR', 334, 'Ví dụ 5', '友達が空港まで送ってくれました。', 'Bạn tôi đã tiễn tôi ra tận sân bay.', 5),
(3719, 296, 'GRAMMAR', 334, 'Ví dụ 6', '先生に作文を直してもらいました。', 'Tôi được thầy sửa bài văn cho.', 6),
(3720, 296, 'GRAMMAR', 335, 'Ví dụ 7', 'どうして遅れたんですか。', 'Sao bạn lại đến muộn thế?', 7),
(3721, 296, 'GRAMMAR', 335, 'Ví dụ 8', '頭が痛いんです。', 'Là vì tôi đang đau đầu.', 8),
(3722, 296, 'GRAMMAR', 336, 'Ví dụ 9', '映画なんかどうですか。', 'Xem phim chẳng hạn, thấy sao?', 9),
(3723, 296, 'GRAMMAR', 336, 'Ví dụ 10', '私なんかにはできません。', 'Cỡ như tôi thì không làm nổi.', 10),
(3724, 297, 'LISTENING', NULL, 'Nhân viên phục vụ', 'ご注文はお決まりですか。', 'Quý khách đã chọn được món chưa ạ?', 1),
(3725, 297, 'LISTENING', NULL, 'Linh', 'この定食にしたいんですが、えびは入っていますか。', 'Tôi muốn lấy suất cơm này, nhưng có tôm trong đó không ạ?', 2),
(3726, 297, 'LISTENING', NULL, 'Nhân viên phục vụ', 'はい、天ぷらにえびが使われております。', 'Vâng, trong món tempura có dùng tôm ạ.', 3),
(3727, 297, 'LISTENING', NULL, 'Linh', '実はえびのアレルギーがあるので、別のものにします。', 'Thực ra tôi bị dị ứng tôm nên tôi đổi món khác.', 4),
(3728, 297, 'LISTENING', NULL, 'Nhân viên phục vụ', 'でしたら、こちらの焼き魚定食はいかがでしょうか。', 'Vậy thì suất cá nướng bên này thì sao ạ?', 5),
(3729, 297, 'LISTENING', NULL, 'Linh', 'それにします。あと、ご飯を少なめにしてもらえますか。', 'Tôi lấy món đó. À, cho tôi bớt cơm được không ạ?', 6),
(3730, 297, 'LISTENING', NULL, 'Nhân viên phục vụ', 'かしこまりました。お飲み物はいかがなさいますか。', 'Vâng ạ. Đồ uống quý khách dùng gì ạ?', 7),
(3731, 297, 'LISTENING', NULL, 'Linh', 'お水だけで結構です。', 'Cho tôi nước lọc thôi là được ạ.', 8),
(3732, 298, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(3733, 300, 'GRAMMAR', 337, 'Ví dụ 1', '音楽を聞きながら勉強します。', 'Tôi vừa nghe nhạc vừa học.', 1),
(3734, 300, 'GRAMMAR', 337, 'Ví dụ 2', '働きながら大学に通っています。', 'Tôi vừa đi làm vừa học đại học.', 2),
(3735, 300, 'GRAMMAR', 338, 'Ví dụ 3', '熱があるなら、休んだほうがいいですよ。', 'Nếu sốt thì bạn nên nghỉ đấy.', 3),
(3736, 300, 'GRAMMAR', 338, 'Ví dụ 4', '夜遅く一人で出かけないほうがいい。', 'Không nên ra ngoài một mình lúc đêm khuya.', 4),
(3737, 300, 'GRAMMAR', 339, 'Ví dụ 5', 'もう一度説明していただけませんか。', 'Xin phiền anh giải thích lại một lần nữa được không ạ?', 5),
(3738, 300, 'GRAMMAR', 339, 'Ví dụ 6', 'この書類を確認していただけませんか。', 'Phiền anh kiểm tra giúp tôi tài liệu này ạ.', 6),
(3739, 300, 'GRAMMAR', 340, 'Ví dụ 7', '明日は晴れるでしょう。', 'Ngày mai chắc trời nắng.', 7),
(3740, 300, 'GRAMMAR', 340, 'Ví dụ 8', '彼はもう知っているだろう。', 'Chắc anh ấy biết rồi.', 8),
(3741, 300, 'GRAMMAR', 341, 'Ví dụ 9', 'お茶でも飲みませんか。', 'Mình uống trà gì đó nhé?', 9),
(3742, 300, 'GRAMMAR', 341, 'Ví dụ 10', '映画でも見に行こう。', 'Đi xem phim gì đó đi.', 10),
(3743, 301, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(3744, 303, 'GRAMMAR', 342, 'Ví dụ 1', '熱いうちに召し上がってください。', 'Xin hãy dùng khi còn nóng.', 1),
(3745, 303, 'GRAMMAR', 342, 'Ví dụ 2', '暗くならないうちに帰りましょう。', 'Về thôi, trước khi trời tối.', 2),
(3746, 303, 'GRAMMAR', 343, 'Ví dụ 3', '明日までにレポートを出さなければなりません。', 'Tôi phải nộp báo cáo trước ngày mai.', 3),
(3747, 303, 'GRAMMAR', 343, 'Ví dụ 4', 'ここでは靴を脱がなくてはいけません。', 'Ở đây bắt buộc phải cởi giày.', 4),
(3748, 303, 'GRAMMAR', 344, 'Ví dụ 5', '去年から日本語を習い始めました。', 'Từ năm ngoái tôi bắt đầu học tiếng Nhật.', 5),
(3749, 303, 'GRAMMAR', 344, 'Ví dụ 6', '急に雨が降り出した。', 'Trời bỗng đổ mưa.', 6),
(3750, 303, 'GRAMMAR', 345, 'Ví dụ 7', 'よく相談した上で決めます。', 'Tôi sẽ bàn bạc kỹ rồi mới quyết định.', 7),
(3751, 303, 'GRAMMAR', 345, 'Ví dụ 8', '書類を確認の上、ご連絡ください。', 'Xin kiểm tra tài liệu rồi liên hệ lại.', 8),
(3752, 303, 'GRAMMAR', 346, 'Ví dụ 9', '今度こそ成功させたい。', 'Lần này nhất định tôi muốn thành công.', 9),
(3753, 303, 'GRAMMAR', 346, 'Ví dụ 10', 'こちらこそよろしくお願いします。', 'Tôi mới là người mong được giúp đỡ.', 10),
(3754, 304, 'LISTENING', NULL, 'Linh', '口座を作りたいんですが、何が必要ですか。', 'Tôi muốn mở tài khoản, cần những gì ạ?', 1),
(3755, 304, 'LISTENING', NULL, 'Nhân viên ngân hàng', '在留カードと印鑑をお持ちでしょうか。', 'Quý khách có mang thẻ cư trú và con dấu không ạ?', 2),
(3756, 304, 'LISTENING', NULL, 'Linh', '在留カードはありますが、印鑑は持っていません。', 'Thẻ cư trú thì có, nhưng con dấu tôi không có ạ.', 3),
(3757, 304, 'LISTENING', NULL, 'Nhân viên ngân hàng', 'でしたら、サインでのお手続きも可能でございます。', 'Vậy thì làm thủ tục bằng chữ ký cũng được ạ.', 4),
(3758, 304, 'LISTENING', NULL, 'Linh', 'よかった。給料の振込に使いたいんですが、大丈夫ですか。', 'May quá. Tôi muốn dùng để nhận lương chuyển khoản, có được không ạ?', 5),
(3759, 304, 'LISTENING', NULL, 'Nhân viên ngân hàng', 'はい、問題ございません。こちらの用紙にご記入をお願いいたします。', 'Vâng, không vấn đề gì ạ. Xin quý khách điền vào tờ khai này.', 6),
(3760, 304, 'LISTENING', NULL, 'Linh', 'キャッシュカードはいつ届きますか。', 'Thẻ rút tiền bao giờ thì tới ạ?', 7),
(3761, 304, 'LISTENING', NULL, 'Nhân viên ngân hàng', '一週間ほどでご自宅に郵送されます。', 'Khoảng một tuần sẽ được gửi về tận nhà ạ.', 8),
(3762, 305, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(3763, 307, 'GRAMMAR', 347, 'Ví dụ 1', 'この歌を聞くたびに、故郷を思い出す。', 'Mỗi lần nghe bài hát này tôi lại nhớ quê.', 1),
(3764, 307, 'GRAMMAR', 347, 'Ví dụ 2', '試験のたびに緊張します。', 'Mỗi lần thi là tôi lại căng thẳng.', 2),
(3765, 307, 'GRAMMAR', 348, 'Ví dụ 3', '急がなくてもいいですよ。', 'Bạn không cần vội đâu.', 3),
(3766, 307, 'GRAMMAR', 348, 'Ví dụ 4', '明日は来なくてもいいです。', 'Ngày mai bạn không cần đến cũng được.', 4),
(3767, 307, 'GRAMMAR', 349, 'Ví dụ 5', '三時間も歩き続けた。', 'Tôi đi bộ liên tục tới ba tiếng.', 5),
(3768, 307, 'GRAMMAR', 349, 'Ví dụ 6', 'この本を読み終わったら貸します。', 'Đọc xong cuốn này tôi cho mượn.', 6),
(3769, 307, 'GRAMMAR', 350, 'Ví dụ 7', '彼は出て行ったきり、帰ってこない。', 'Anh ta đi rồi kể từ đó không về.', 7),
(3770, 307, 'GRAMMAR', 350, 'Ví dụ 8', '一度会ったきりです。', 'Tôi chỉ gặp đúng một lần rồi thôi.', 8),
(3771, 307, 'GRAMMAR', 351, 'Ví dụ 9', 'あなただからこそ話すのです。', 'Chính vì là bạn nên tôi mới kể.', 9),
(3772, 307, 'GRAMMAR', 351, 'Ví dụ 10', '苦労したからこそ今がある。', 'Chính vì đã vất vả nên mới có ngày nay.', 10),
(3773, 308, 'LISTENING', NULL, 'Yuki', '今週の土曜、みんなでカラオケ行くんだけど、リンも来ない。', 'Thứ bảy này cả nhóm đi karaoke, Linh đi không?', 1),
(3774, 308, 'LISTENING', NULL, 'Linh', '行きたいんだけど、土曜はバイトが入ってるんだ。', 'Tớ muốn đi lắm, nhưng thứ bảy tớ có ca làm thêm rồi.', 2),
(3775, 308, 'LISTENING', NULL, 'Yuki', '何時まで。終わってからでも大丈夫だよ。', 'Đến mấy giờ? Xong rồi tới cũng được mà.', 3),
(3776, 308, 'LISTENING', NULL, 'Linh', '九時までなんだ。さすがにそのあとはきついかな。', 'Đến chín giờ cơ. Sau đó thì chắc hơi đuối.', 4),
(3777, 308, 'LISTENING', NULL, 'Yuki', 'そっか。残念だなあ。', 'Vậy à. Tiếc thật.', 5),
(3778, 308, 'LISTENING', NULL, 'Linh', 'ごめんね。今度はこっちから誘うから、日にち決めよう。', 'Xin lỗi nhé. Lần tới tớ rủ, mình chốt ngày đi.', 6),
(3779, 308, 'LISTENING', NULL, 'Yuki', 'うん、約束ね。じゃあ来月あたりどう。', 'Ừ, hứa đấy nhé. Vậy khoảng tháng sau thì sao?', 7),
(3780, 308, 'LISTENING', NULL, 'Linh', 'いいね。バイトのシフト出たら連絡する。', 'Được đấy. Có lịch làm là tớ báo.', 8),
(3781, 309, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(3782, 311, 'GRAMMAR', 352, 'Ví dụ 1', '先生が言ったとおりにやってみます。', 'Tôi sẽ thử làm đúng như thầy đã nói.', 1),
(3783, 311, 'GRAMMAR', 352, 'Ví dụ 2', '計画どおりに進んでいます。', 'Mọi việc đang tiến triển đúng kế hoạch.', 2),
(3784, 311, 'GRAMMAR', 353, 'Ví dụ 3', 'ここに座ってもいいですか。', 'Tôi ngồi đây được không ạ?', 3),
(3785, 311, 'GRAMMAR', 353, 'Ví dụ 4', '授業中に携帯を使ってはいけません。', 'Không được dùng điện thoại trong giờ học.', 4),
(3786, 311, 'GRAMMAR', 354, 'Ví dụ 5', 'このペンは書きやすいです。', 'Cây bút này viết dễ.', 5),
(3787, 311, 'GRAMMAR', 354, 'Ví dụ 6', 'この字は読みにくい。', 'Chữ này khó đọc.', 6),
(3788, 311, 'GRAMMAR', 355, 'Ví dụ 7', 'たとえ雨が降っても、試合は行います。', 'Cho dù trời mưa, trận đấu vẫn diễn ra.', 7),
(3789, 311, 'GRAMMAR', 355, 'Ví dụ 8', 'たとえ高くても買いたい。', 'Dù đắt tôi vẫn muốn mua.', 8),
(3790, 311, 'GRAMMAR', 356, 'Ví dụ 9', '時間がたつのは早いものだ。', 'Thời gian trôi nhanh thật.', 9),
(3791, 311, 'GRAMMAR', 356, 'Ví dụ 10', '子供のころはよく川で泳いだものだ。', 'Hồi bé tôi hay bơi ở sông lắm.', 10),
(3792, 312, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(3793, 314, 'GRAMMAR', 357, 'Ví dụ 1', '国によって習慣が違います。', 'Tập quán khác nhau tuỳ theo từng nước.', 1),
(3794, 314, 'GRAMMAR', 357, 'Ví dụ 2', 'この寺は十七世紀に建てられました。', 'Ngôi chùa này được xây vào thế kỷ mười bảy.', 2),
(3795, 314, 'GRAMMAR', 358, 'Ví dụ 3', '春になると、桜が咲きます。', 'Cứ đến mùa xuân là hoa anh đào nở.', 3),
(3796, 314, 'GRAMMAR', 358, 'Ví dụ 4', 'このボタンを押すと、ドアが開きます。', 'Bấm nút này thì cửa mở.', 4),
(3797, 314, 'GRAMMAR', 359, 'Ví dụ 5', '昨日は飲みすぎました。', 'Hôm qua tôi uống quá chén.', 5),
(3798, 314, 'GRAMMAR', 359, 'Ví dụ 6', 'この部屋は狭すぎる。', 'Căn phòng này chật quá.', 6),
(3799, 314, 'GRAMMAR', 360, 'Ví dụ 7', '毎日日記をつけるようにしています。', 'Tôi đang duy trì thói quen viết nhật ký mỗi ngày.', 7),
(3800, 314, 'GRAMMAR', 360, 'Ví dụ 8', '甘い物は食べないようにしている。', 'Tôi đang cố không ăn đồ ngọt.', 8),
(3801, 314, 'GRAMMAR', 361, 'Ví dụ 9', '友達が車を出してくれたので、歩かずにすんだ。', 'Bạn cho đi nhờ xe nên tôi khỏi phải đi bộ.', 9),
(3802, 314, 'GRAMMAR', 361, 'Ví dụ 10', '大事にならずにすんだ。', 'May mà không thành chuyện lớn.', 10),
(3803, 315, 'LISTENING', NULL, 'Linh', 'すみません、ごみの出し方を教えていただけますか。', 'Xin lỗi, cô chỉ giúp cháu cách đổ rác được không ạ?', 1),
(3804, 315, 'LISTENING', NULL, 'Bà Sato', 'ああ、新しく越してきた方ね。曜日で分かれているのよ。', 'À, cháu là người mới chuyển đến à. Phân theo thứ trong tuần đấy.', 2),
(3805, 315, 'LISTENING', NULL, 'Linh', '燃えるごみは何曜日ですか。', 'Rác cháy được là thứ mấy ạ?', 3),
(3806, 315, 'LISTENING', NULL, 'Bà Sato', '月曜と木曜。朝八時までに出してね。', 'Thứ hai và thứ năm. Đem ra trước tám giờ sáng nhé.', 4),
(3807, 315, 'LISTENING', NULL, 'Linh', 'ペットボトルはどうすればいいですか。', 'Chai nhựa thì làm thế nào ạ?', 5),
(3808, 315, 'LISTENING', NULL, 'Bà Sato', 'ラベルとふたを外して、水曜に出すの。', 'Bóc nhãn và nắp ra, rồi đem đổ vào thứ tư.', 6),
(3809, 315, 'LISTENING', NULL, 'Linh', '細かいんですね。間違えたらどうなりますか。', 'Tỉ mỉ thật nhỉ. Nếu làm sai thì sao ạ?', 7),
(3810, 315, 'LISTENING', NULL, 'Bà Sato', '持っていってもらえないの。分からなかったら聞いてね。', 'Người ta sẽ không thu đâu. Không biết thì cứ hỏi cô nhé.', 8),
(3811, 316, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(3812, 318, 'GRAMMAR', 362, 'Ví dụ 1', '日本の文化について発表します。', 'Tôi sẽ thuyết trình về văn hoá Nhật Bản.', 1),
(3813, 318, 'GRAMMAR', 362, 'Ví dụ 2', 'その件については後で話しましょう。', 'Về việc đó thì lát nữa nói nhé.', 2),
(3814, 318, 'GRAMMAR', 363, 'Ví dụ 3', '駅に着いたら、電話してください。', 'Đến ga thì gọi điện cho tôi nhé.', 3),
(3815, 318, 'GRAMMAR', 363, 'Ví dụ 4', 'もし雨が降ったら、中止します。', 'Nếu trời mưa thì huỷ.', 4),
(3816, 318, 'GRAMMAR', 364, 'Ví dụ 5', 'この漢字の書き方を教えてください。', 'Xin chỉ cho tôi cách viết chữ Hán này.', 5),
(3817, 318, 'GRAMMAR', 364, 'Ví dụ 6', '使い方が分かりません。', 'Tôi không biết cách dùng.', 6),
(3818, 318, 'GRAMMAR', 365, 'Ví dụ 7', '私はコーヒーにします。', 'Tôi chọn cà phê.', 7),
(3819, 318, 'GRAMMAR', 365, 'Ví dụ 8', '会議は来週にしましょう。', 'Cuộc họp để sang tuần đi.', 8),
(3820, 318, 'GRAMMAR', 366, 'Ví dụ 9', '何か誤解があるのではないでしょうか。', 'Chẳng phải là đang có hiểu lầm gì đó sao ạ?', 9),
(3821, 318, 'GRAMMAR', 366, 'Ví dụ 10', 'もう帰ったんじゃない。', 'Chẳng phải anh ta về rồi sao?', 10),
(3822, 319, 'LISTENING', NULL, 'Linh', '昨日ここで買ったシャツなんですが、サイズを交換できますか。', 'Cái áo tôi mua ở đây hôm qua, đổi cỡ được không ạ?', 1),
(3823, 319, 'LISTENING', NULL, 'Nhân viên bán hàng', 'レシートはお持ちでしょうか。', 'Quý khách có mang hoá đơn không ạ?', 2),
(3824, 319, 'LISTENING', NULL, 'Linh', 'はい、これです。一度着てみたんですが、少し小さくて。', 'Vâng, đây ạ. Tôi có mặc thử một lần, nhưng hơi chật.', 3),
(3825, 319, 'LISTENING', NULL, 'Nhân viên bán hàng', 'タグが付いたままでしたら、交換を承ります。', 'Nếu nhãn vẫn còn gắn thì chúng tôi nhận đổi ạ.', 4),
(3826, 319, 'LISTENING', NULL, 'Linh', 'よかった。一つ大きいサイズはありますか。', 'May quá. Có cỡ lớn hơn một số không ạ?', 5),
(3827, 319, 'LISTENING', NULL, 'Nhân viên bán hàng', '申し訳ございません。同じ色は在庫を切らしております。', 'Thành thật xin lỗi. Cùng màu đó thì chúng tôi đã hết hàng ạ.', 6),
(3828, 319, 'LISTENING', NULL, 'Linh', 'では、別の色でもかまいません。', 'Vậy màu khác cũng không sao ạ.', 7),
(3829, 319, 'LISTENING', NULL, 'Nhân viên bán hàng', 'かしこまりました。ただ今お持ちいたします。', 'Vâng ạ. Tôi lấy ra ngay đây ạ.', 8),
(3830, 320, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(3831, 322, 'GRAMMAR', 367, 'Ví dụ 1', 'お客様に対して丁寧な言葉を使います。', 'Phải dùng lời lẽ lịch sự đối với khách hàng.', 1),
(3832, 322, 'GRAMMAR', 367, 'Ví dụ 2', '兄が静かなのに対して、弟はよく話す。', 'Anh thì trầm tính, ngược lại em thì hay nói.', 2),
(3833, 322, 'GRAMMAR', 368, 'Ví dụ 3', '日本語を勉強するなら、この本がいいですよ。', 'Nếu học tiếng Nhật thì cuốn sách này hay đấy.', 3),
(3834, 322, 'GRAMMAR', 368, 'Ví dụ 4', '安いなら買います。', 'Nếu rẻ thì tôi mua.', 4),
(3835, 322, 'GRAMMAR', 369, 'Ví dụ 5', '子供が外へ行きたがっている。', 'Bọn trẻ đang muốn ra ngoài.', 5),
(3836, 322, 'GRAMMAR', 369, 'Ví dụ 6', '彼は何も話したがらない。', 'Anh ta chẳng muốn nói gì cả.', 6),
(3837, 322, 'GRAMMAR', 370, 'Ví dụ 7', '私としては反対です。', 'Về phần tôi thì tôi phản đối.', 7),
(3838, 322, 'GRAMMAR', 370, 'Ví dụ 8', 'この値段は学生としては高い。', 'Mức giá này với sinh viên là đắt.', 8),
(3839, 322, 'GRAMMAR', 371, 'Ví dụ 9', '少し休んだらどうですか。', 'Sao anh không nghỉ một chút?', 9),
(3840, 322, 'GRAMMAR', 371, 'Ví dụ 10', '医者に相談したらどう。', 'Hay hỏi bác sĩ xem?', 10),
(3841, 323, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(3842, 325, 'GRAMMAR', 372, 'Ví dụ 1', '彼は研究者として有名です。', 'Ông ấy nổi tiếng với tư cách nhà nghiên cứu.', 1),
(3843, 325, 'GRAMMAR', 372, 'Ví dụ 2', '留学生として日本へ来ました。', 'Tôi sang Nhật với tư cách du học sinh.', 2),
(3844, 325, 'GRAMMAR', 373, 'Ví dụ 3', 'エアコンをつけたまま出かけてしまった。', 'Tôi lỡ để nguyên điều hoà bật rồi đi ra ngoài.', 3),
(3845, 325, 'GRAMMAR', 373, 'Ví dụ 4', '靴のまま入らないでください。', 'Xin đừng đi nguyên giày vào.', 4),
(3846, 325, 'GRAMMAR', 374, 'Ví dụ 5', 'ここでは写真を撮ることができません。', 'Ở đây không được chụp ảnh.', 5),
(3847, 325, 'GRAMMAR', 374, 'Ví dụ 6', '彼はピアノを弾くことができる。', 'Anh ấy có thể chơi piano.', 6),
(3848, 325, 'GRAMMAR', 375, 'Ví dụ 7', 'この薬さえ飲めば、すぐよくなります。', 'Chỉ cần uống thuốc này là khỏi ngay.', 7),
(3849, 325, 'GRAMMAR', 375, 'Ví dụ 8', '君さえいてくれればいい。', 'Chỉ cần có em ở đây là đủ.', 8),
(3850, 325, 'GRAMMAR', 376, 'Ví dụ 9', '彼は遊んでばかりいる。', 'Cậu ta suốt ngày chỉ chơi.', 9),
(3851, 325, 'GRAMMAR', 376, 'Ví dụ 10', '泣いてばかりいないで、話して。', 'Đừng khóc mãi, nói đi.', 10),
(3852, 326, 'LISTENING', NULL, 'Lễ tân phòng khám', 'はい、さくら歯科でございます。', 'Vâng, phòng khám răng Sakura xin nghe ạ.', 1),
(3853, 326, 'LISTENING', NULL, 'Linh', '予約をお願いしたいんですが、今週空いていますか。', 'Tôi muốn đặt lịch, tuần này còn chỗ trống không ạ?', 2),
(3854, 326, 'LISTENING', NULL, 'Lễ tân phòng khám', '木曜の午後でしたら、三時か五時が空いております。', 'Nếu là chiều thứ năm thì ba giờ hoặc năm giờ còn trống ạ.', 3),
(3855, 326, 'LISTENING', NULL, 'Linh', '五時でお願いします。初めてなんですが、何か必要なものはありますか。', 'Cho tôi năm giờ ạ. Tôi đi lần đầu, có cần mang gì không ạ?', 4),
(3856, 326, 'LISTENING', NULL, 'Lễ tân phòng khám', '保険証をお持ちください。十分ほど早めにお越しいただけますか。', 'Xin mang theo thẻ bảo hiểm. Quý khách đến sớm khoảng mười phút được không ạ?', 5),
(3857, 326, 'LISTENING', NULL, 'Linh', '分かりました。もし遅れそうなときはどうすればいいですか。', 'Tôi hiểu rồi. Nếu có vẻ đến muộn thì tôi nên làm gì ạ?', 6),
(3858, 326, 'LISTENING', NULL, 'Lễ tân phòng khám', 'お電話をいただければ、調整いたします。', 'Nếu quý khách gọi điện thì chúng tôi sẽ điều chỉnh ạ.', 7),
(3859, 326, 'LISTENING', NULL, 'Linh', 'ありがとうございます。では木曜の五時に伺います。', 'Cảm ơn chị ạ. Vậy năm giờ thứ năm tôi đến ạ.', 8),
(3860, 327, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(3861, 329, 'GRAMMAR', 377, 'Ví dụ 1', 'この店は安いわりにおいしい。', 'Quán này rẻ mà lại ngon.', 1),
(3862, 329, 'GRAMMAR', 377, 'Ví dụ 2', '年のわりに若く見えますね。', 'So với tuổi thì trông anh trẻ nhỉ.', 2),
(3863, 329, 'GRAMMAR', 378, 'Ví dụ 3', '買い物に行くついでに、郵便局にも寄ります。', 'Tiện đi mua sắm tôi ghé luôn bưu điện.', 3),
(3864, 329, 'GRAMMAR', 378, 'Ví dụ 4', '散歩のついでにパンを買ってきた。', 'Tiện đi dạo tôi mua luôn bánh mì về.', 4),
(3865, 329, 'GRAMMAR', 379, 'Ví dụ 5', '時間があれば、行きます。', 'Nếu có thời gian tôi sẽ đi.', 5),
(3866, 329, 'GRAMMAR', 379, 'Ví dụ 6', '急がなければ間に合わない。', 'Không nhanh lên thì không kịp.', 6),
(3867, 329, 'GRAMMAR', 380, 'Ví dụ 7', 'もう少し静かにしてほしい。', 'Tôi muốn mọi người yên lặng hơn chút.', 7),
(3868, 329, 'GRAMMAR', 380, 'Ví dụ 8', '約束を忘れないでほしい。', 'Tôi mong bạn đừng quên lời hứa.', 8),
(3869, 329, 'GRAMMAR', 381, 'Ví dụ 9', '死ぬほど疲れた。', 'Tôi mệt đến chết đi được.', 9),
(3870, 329, 'GRAMMAR', 381, 'Ví dụ 10', '涙が出るほどうれしかった。', 'Tôi vui đến phát khóc.', 10),
(3871, 330, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(3872, 332, 'GRAMMAR', 382, 'Ví dụ 1', '知っているくせに教えてくれない。', 'Biết rõ mà không chịu chỉ cho.', 1),
(3873, 332, 'GRAMMAR', 382, 'Ví dụ 2', '子供のくせに生意気だ。', 'Trẻ con thế mà láo.', 2),
(3874, 332, 'GRAMMAR', 383, 'Ví dụ 3', '先生のおかげで合格できました。', 'Nhờ có thầy mà em đã đỗ.', 3),
(3875, 332, 'GRAMMAR', 383, 'Ví dụ 4', '雨のせいで試合が中止になった。', 'Tại mưa mà trận đấu bị huỷ.', 4),
(3876, 332, 'GRAMMAR', 384, 'Ví dụ 5', '朝ご飯を食べずに出かけた。', 'Tôi đi ra ngoài mà không ăn sáng.', 5),
(3877, 332, 'GRAMMAR', 384, 'Ví dụ 6', '何も言わずに帰ってしまった。', 'Anh ta bỏ về mà chẳng nói gì.', 6),
(3878, 332, 'GRAMMAR', 385, 'Ví dụ 7', '子供が新しいゲームをほしがっている。', 'Bọn trẻ đang muốn có trò chơi mới.', 7),
(3879, 332, 'GRAMMAR', 385, 'Ví dụ 8', '彼は何もほしがらない。', 'Anh ấy chẳng muốn gì cả.', 8),
(3880, 332, 'GRAMMAR', 386, 'Ví dụ 9', '歩けないくらい足が痛い。', 'Chân tôi đau đến mức không đi nổi.', 9),
(3881, 332, 'GRAMMAR', 386, 'Ví dụ 10', 'それくらい自分でやりなさい。', 'Chừng ấy thì tự làm đi.', 10),
(3882, 333, 'LISTENING', NULL, 'Linh', 'まいちゃん、ちょっとお願いがあるんだけど、今いい。', 'Mai ơi, tớ có việc muốn nhờ, giờ tiện không?', 1),
(3883, 333, 'LISTENING', NULL, 'Mai', 'うん、いいよ。どうしたの。', 'Ừ, được. Sao thế?', 2),
(3884, 333, 'LISTENING', NULL, 'Linh', '来週の金曜、大学の発表と重なっちゃって。シフト代わってもらえないかな。', 'Thứ sáu tuần sau trùng với buổi thuyết trình ở trường. Cậu đổi ca hộ tớ được không?', 3),
(3885, 333, 'LISTENING', NULL, 'Mai', '金曜か。夕方からなら大丈夫だと思う。何時から。', 'Thứ sáu à. Từ chiều thì tớ nghĩ là được. Từ mấy giờ?', 4),
(3886, 333, 'LISTENING', NULL, 'Linh', '五時から九時まで。もちろん、別の日に代わりに入るよ。', 'Từ năm giờ đến chín giờ. Tất nhiên hôm khác tớ làm bù cho cậu.', 5),
(3887, 333, 'LISTENING', NULL, 'Mai', 'じゃあ、再来週の日曜と交換でどう。', 'Vậy đổi với chủ nhật tuần sau nữa thì sao?', 6),
(3888, 333, 'LISTENING', NULL, 'Linh', 'それで大丈夫。助かるよ、本当にありがとう。', 'Thế được đấy. Đỡ cho tớ quá, cảm ơn cậu nhiều.', 7),
(3889, 333, 'LISTENING', NULL, 'Mai', 'いいよ。店長には自分で言っておいてね。', 'Không sao. Nhớ tự nói với quản lý nhé.', 8),
(3890, 334, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(3891, 336, 'GRAMMAR', 387, 'Ví dụ 1', '考えれば考えるほど分からなくなる。', 'Càng nghĩ càng không hiểu.', 1),
(3892, 336, 'GRAMMAR', 387, 'Ví dụ 2', '練習すればするほど上手になります。', 'Càng luyện tập càng giỏi lên.', 2),
(3893, 336, 'GRAMMAR', 388, 'Ví dụ 3', 'ニュースによると、地震があったそうです。', 'Theo tin tức thì nghe nói đã có động đất.', 3),
(3894, 336, 'GRAMMAR', 388, 'Ví dụ 4', '田中さんの話によると、店は閉まったらしい。', 'Theo lời anh Tanaka thì hình như cửa hàng đóng rồi.', 4),
(3895, 336, 'GRAMMAR', 389, 'Ví dụ 5', 'この店は安いし、近いし、よく行きます。', 'Quán này vừa rẻ vừa gần nên tôi hay đến.', 5),
(3896, 336, 'GRAMMAR', 389, 'Ví dụ 6', 'もう遅いし、帰りましょう。', 'Muộn rồi, với lại thôi về đi.', 6),
(3897, 336, 'GRAMMAR', 390, 'Ví dụ 7', '出かけようとしたとき、電話が鳴った。', 'Đúng lúc định ra ngoài thì chuông điện thoại reo.', 7),
(3898, 336, 'GRAMMAR', 390, 'Ví dụ 8', '彼は話を聞こうとしない。', 'Anh ta chẳng chịu nghe.', 8),
(3899, 336, 'GRAMMAR', 391, 'Ví dụ 9', '引っ越してからずっとここに住んでいる。', 'Từ khi chuyển nhà tôi vẫn sống ở đây.', 9),
(3900, 336, 'GRAMMAR', 391, 'Ví dụ 10', '卒業してからずっと働いている。', 'Từ khi tốt nghiệp tôi vẫn đi làm.', 10),
(3901, 337, 'LISTENING', NULL, 'Linh', 'すみません、この近くに病院はありますか。', 'Xin lỗi, gần đây có bệnh viện không ạ?', 1),
(3902, 337, 'LISTENING', NULL, 'Người qua đường', 'ええ、あの信号を右に曲がったところにありますよ。', 'Có chứ, rẽ phải ở cái đèn tín hiệu kia là tới đấy.', 2),
(3903, 337, 'LISTENING', NULL, 'Linh', '歩いてどのくらいかかりますか。', 'Đi bộ mất khoảng bao lâu ạ?', 3),
(3904, 337, 'LISTENING', NULL, 'Người qua đường', '五分もかからないと思いますよ。', 'Tôi nghĩ chưa đến năm phút đâu.', 4),
(3905, 337, 'LISTENING', NULL, 'Linh', '助かりました。今日はやっていますか。', 'Đỡ cho tôi quá. Hôm nay có mở cửa không ạ?', 5),
(3906, 337, 'LISTENING', NULL, 'Người qua đường', '土曜は午前中だけだったと思います。急いだほうがいいですよ。', 'Thứ bảy thì tôi nhớ là chỉ buổi sáng. Anh nên nhanh lên đấy.', 6),
(3907, 337, 'LISTENING', NULL, 'Linh', '分かりました。本当にありがとうございます。', 'Tôi hiểu rồi. Thật cảm ơn bác ạ.', 7),
(3908, 337, 'LISTENING', NULL, 'Người qua đường', 'いえいえ、お大事に。', 'Không có gì, giữ gìn sức khoẻ nhé.', 8),
(3909, 338, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(3910, 340, 'GRAMMAR', 392, 'Ví dụ 1', '忙しくて、食事をする時間さえない。', 'Bận đến mức không có cả thời gian ăn.', 1),
(3911, 340, 'GRAMMAR', 392, 'Ví dụ 2', 'お金さえあれば買えるのに。', 'Chỉ cần có tiền thì đã mua được rồi.', 2),
(3912, 340, 'GRAMMAR', 393, 'Ví dụ 3', '薬を飲んだのに、まだ熱が下がらない。', 'Uống thuốc rồi mà vẫn chưa hạ sốt.', 3),
(3913, 340, 'GRAMMAR', 393, 'Ví dụ 4', '約束したのに、彼は来なかった。', 'Đã hẹn rồi vậy mà anh ta không đến.', 4),
(3914, 340, 'GRAMMAR', 394, 'Ví dụ 5', '休みの日は本を読んだり、散歩したりします。', 'Ngày nghỉ tôi nào là đọc sách, nào là đi dạo.', 5),
(3915, 340, 'GRAMMAR', 394, 'Ví dụ 6', '雨が降ったりやんだりしている。', 'Mưa cứ lúc rơi lúc tạnh.', 6),
(3916, 340, 'GRAMMAR', 395, 'Ví dụ 7', '彼がそんなことを言うはずがない。', 'Không đời nào anh ấy nói vậy.', 7),
(3917, 340, 'GRAMMAR', 395, 'Ví dụ 8', '今から行って間に合うはずがない。', 'Giờ mới đi thì không thể nào kịp.', 8),
(3918, 340, 'GRAMMAR', 396, 'Ví dụ 9', '買ったばかりなのに、もう壊れた。', 'Vừa mới mua thế mà đã hỏng.', 9),
(3919, 340, 'GRAMMAR', 396, 'Ví dụ 10', '掃除したばかりなのに汚れている。', 'Vừa dọn xong mà đã bẩn rồi.', 10),
(3920, 341, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(3921, 343, 'GRAMMAR', 397, 'Ví dụ 1', 'この作文は間違いだらけだ。', 'Bài văn này sai be bét.', 1),
(3922, 343, 'GRAMMAR', 397, 'Ví dụ 2', '子供は泥だらけになって帰ってきた。', 'Bọn trẻ về nhà người đầy bùn.', 2),
(3923, 343, 'GRAMMAR', 398, 'Ví dụ 3', 'いくら呼んでも返事がない。', 'Gọi bao nhiêu lần cũng không có tiếng trả lời.', 3),
(3924, 343, 'GRAMMAR', 398, 'Ví dụ 4', '高くても買います。', 'Dù đắt tôi vẫn mua.', 4),
(3925, 343, 'GRAMMAR', 399, 'Ví dụ 5', '電車よりバスのほうが安いです。', 'Xe buýt rẻ hơn tàu điện.', 5),
(3926, 343, 'GRAMMAR', 399, 'Ví dụ 6', '一人で行くより、みんなで行くほうが楽しい。', 'Đi cùng mọi người vui hơn đi một mình.', 6),
(3927, 343, 'GRAMMAR', 400, 'Ví dụ 7', 'こんな簡単な問題、間違えるわけがない。', 'Bài dễ thế này thì làm gì có chuyện sai.', 7),
(3928, 343, 'GRAMMAR', 400, 'Ví dụ 8', '彼が知っているわけがない。', 'Làm gì có chuyện anh ta biết.', 8),
(3929, 343, 'GRAMMAR', 401, 'Ví dụ 9', '医者に酒をやめるように言われた。', 'Tôi bị bác sĩ bảo phải bỏ rượu.', 9),
(3930, 343, 'GRAMMAR', 401, 'Ví dụ 10', '遅れないように伝えてください。', 'Xin nhắn lại là đừng đến muộn.', 10),
(3931, 344, 'LISTENING', NULL, 'Linh', '先生、レポートのことでご相談があります。', 'Thưa thầy, em có việc muốn xin ý kiến về bài báo cáo ạ.', 1),
(3932, 344, 'LISTENING', NULL, 'Thầy Yamada', 'どうぞ。締め切りは明日ですね。', 'Em nói đi. Hạn nộp là ngày mai nhỉ.', 2),
(3933, 344, 'LISTENING', NULL, 'Linh', 'はい。実は先週から体調を崩していて、まだ終わっていません。', 'Vâng ạ. Thực ra từ tuần trước em bị ốm nên vẫn chưa xong ạ.', 3),
(3934, 344, 'LISTENING', NULL, 'Thầy Yamada', 'それは大変でしたね。今はもう大丈夫ですか。', 'Vất vả cho em nhỉ. Giờ đã ổn chưa?', 4),
(3935, 344, 'LISTENING', NULL, 'Linh', 'はい、よくなりました。三日ほど延ばしていただけないでしょうか。', 'Vâng, em đỡ rồi ạ. Thầy cho em lùi khoảng ba ngày được không ạ?', 5),
(3936, 344, 'LISTENING', NULL, 'Thầy Yamada', '分かりました。では月曜の授業までに出してください。', 'Được. Vậy em nộp trước buổi học thứ hai nhé.', 6),
(3937, 344, 'LISTENING', NULL, 'Linh', 'ありがとうございます。必ず間に合わせます。', 'Em cảm ơn thầy ạ. Em nhất định sẽ kịp.', 7),
(3938, 344, 'LISTENING', NULL, 'Thầy Yamada', '無理はしないで。体を大事にしてくださいね。', 'Đừng gắng quá. Em giữ gìn sức khoẻ nhé.', 8),
(3939, 345, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(3940, 347, 'GRAMMAR', 402, 'Ví dụ 1', '冬は運動不足になりがちです。', 'Mùa đông hay bị thiếu vận động.', 1),
(3941, 347, 'GRAMMAR', 402, 'Ví dụ 2', '彼は最近欠席しがちだ。', 'Dạo này cậu ấy hay vắng mặt.', 2),
(3942, 347, 'GRAMMAR', 403, 'Ví dụ 3', '彼は英語だけでなく、中国語も話せる。', 'Anh ấy không chỉ nói được tiếng Anh mà cả tiếng Trung.', 3),
(3943, 347, 'GRAMMAR', 403, 'Ví dụ 4', 'この店は安いだけでなく、味もいい。', 'Quán này không chỉ rẻ mà còn ngon.', 4),
(3944, 347, 'GRAMMAR', 404, 'Ví dụ 5', '今年の冬は去年ほど寒くない。', 'Mùa đông năm nay không lạnh bằng năm ngoái.', 5),
(3945, 347, 'GRAMMAR', 404, 'Ví dụ 6', '彼ほど親切な人はいない。', 'Không ai tốt bụng bằng anh ấy.', 6),
(3946, 347, 'GRAMMAR', 405, 'Ví dụ 7', 'どうしたらいいか分かりません。', 'Tôi không biết nên làm thế nào.', 7),
(3947, 347, 'GRAMMAR', 405, 'Ví dụ 8', 'もっと早く言えばよかった。', 'Giá mà tôi nói sớm hơn.', 8),
(3948, 347, 'GRAMMAR', 406, 'Ví dụ 9', '考え方は人によって違う。', 'Cách nghĩ khác nhau tuỳ từng người.', 9),
(3949, 347, 'GRAMMAR', 406, 'Ví dụ 10', '値段は店によって違います。', 'Giá khác nhau tuỳ cửa hàng.', 10),
(3950, 348, 'LISTENING', NULL, 'Linh', '明日の朝、大阪まで行きたいんですが。', 'Sáng mai tôi muốn đi Osaka ạ.', 1),
(3951, 348, 'LISTENING', NULL, 'Nhân viên quầy vé', '何時ごろのご希望でしょうか。', 'Quý khách muốn khoảng mấy giờ ạ?', 2),
(3952, 348, 'LISTENING', NULL, 'Linh', '九時までに着きたいので、早い便がいいです。', 'Tôi muốn tới trước chín giờ nên chuyến sớm thì tốt ạ.', 3),
(3953, 348, 'LISTENING', NULL, 'Nhân viên quầy vé', '六時半発でしたら、八時四十分に到着いたします。', 'Nếu chuyến sáu giờ rưỡi thì tám giờ bốn mươi sẽ tới ạ.', 4),
(3954, 348, 'LISTENING', NULL, 'Linh', 'それにします。窓側の席は空いていますか。', 'Tôi lấy chuyến đó. Ghế cạnh cửa sổ còn trống không ạ?', 5),
(3955, 348, 'LISTENING', NULL, 'Nhân viên quầy vé', 'あと二席ございます。禁煙でよろしいですか。', 'Còn hai ghế ạ. Toa không hút thuốc được không ạ?', 6),
(3956, 348, 'LISTENING', NULL, 'Linh', 'はい。往復で買ったほうが安いですか。', 'Vâng. Mua khứ hồi thì rẻ hơn ạ?', 7),
(3957, 348, 'LISTENING', NULL, 'Nhân viên quầy vé', '復路の日が決まっていれば、割引が適用されます。', 'Nếu đã định ngày về thì được áp dụng giảm giá ạ.', 8),
(3958, 349, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(3959, 351, 'GRAMMAR', 407, 'Ví dụ 1', '彼は怒りっぽい性格だ。', 'Anh ta tính hay cáu.', 1),
(3960, 351, 'GRAMMAR', 407, 'Ví dụ 2', 'この服は安っぽく見える。', 'Bộ đồ này trông rẻ tiền.', 2),
(3961, 351, 'GRAMMAR', 408, 'Ví dụ 3', 'この店はラーメンはもちろん、餃子もおいしい。', 'Quán này mì ramen khỏi phải nói, gyoza cũng ngon.', 3),
(3962, 351, 'GRAMMAR', 408, 'Ví dụ 4', '週末はもちろん、平日も混んでいる。', 'Cuối tuần đã đành, ngày thường cũng đông.', 4),
(3963, 351, 'GRAMMAR', 409, 'Ví dụ 5', '彼は文句ばかり言っている。', 'Anh ta suốt ngày chỉ toàn kêu ca.', 5),
(3964, 351, 'GRAMMAR', 409, 'Ví dụ 6', '甘いものばかり食べてはいけない。', 'Không được chỉ ăn mỗi đồ ngọt.', 6),
(3965, 351, 'GRAMMAR', 410, 'Ví dụ 7', 'ちょっと手伝ってもらえませんか。', 'Anh giúp tôi một chút được không?', 7),
(3966, 351, 'GRAMMAR', 410, 'Ví dụ 8', '写真を撮ってもらえませんか。', 'Anh chụp giúp tôi tấm ảnh được không?', 8),
(3967, 351, 'GRAMMAR', 411, 'Ví dụ 9', '台所からいいにおいがする。', 'Từ bếp có mùi thơm.', 9),
(3968, 351, 'GRAMMAR', 411, 'Ví dụ 10', '誰かいるような気がする。', 'Tôi có cảm giác như có ai đó.', 10),
(3969, 352, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(3970, 354, 'GRAMMAR', 412, 'Ví dụ 1', '長い小説を三日で読みきった。', 'Tôi đọc hết cuốn tiểu thuyết dài trong ba ngày.', 1),
(3971, 354, 'GRAMMAR', 412, 'Ví dụ 2', '量が多くて食べきれません。', 'Nhiều quá, tôi ăn không hết.', 2),
(3972, 354, 'GRAMMAR', 413, 'Ví dụ 3', '去年に比べて、今年は暖かい。', 'So với năm ngoái thì năm nay ấm hơn.', 3),
(3973, 354, 'GRAMMAR', 413, 'Ví dụ 4', '都会に比べて、田舎は静かだ。', 'So với thành phố thì nông thôn yên tĩnh.', 4),
(3974, 354, 'GRAMMAR', 414, 'Ví dụ 5', '田中という人から電話がありました。', 'Có điện thoại từ một người tên là Tanaka.', 5),
(3975, 354, 'GRAMMAR', 414, 'Ví dụ 6', 'これは何という花ですか。', 'Đây là hoa gì vậy?', 6),
(3976, 354, 'GRAMMAR', 415, 'Ví dụ 7', 'その仕事は私にやらせてください。', 'Xin hãy để tôi làm công việc đó.', 7),
(3977, 354, 'GRAMMAR', 415, 'Ví dụ 8', '少し考えさせてください。', 'Xin cho tôi suy nghĩ chút.', 8),
(3978, 354, 'GRAMMAR', 416, 'Ví dụ 9', 'もう少しで転ぶところだった。', 'Suýt nữa thì tôi ngã.', 9),
(3979, 354, 'GRAMMAR', 416, 'Ví dụ 10', '危うく忘れるところだった。', 'Suýt nữa thì quên mất.', 10),
(3980, 355, 'LISTENING', NULL, 'Nhân viên giao hàng', 'お隣の田中様宛てなのですが、ご不在でして。', 'Hàng gửi cho nhà Tanaka bên cạnh, nhưng họ không có nhà ạ.', 1),
(3981, 355, 'LISTENING', NULL, 'Linh', '私が受け取ってもいいんですか。', 'Tôi nhận hộ có được không ạ?', 2),
(3982, 355, 'LISTENING', NULL, 'Nhân viên giao hàng', 'はい、ご近所の方でしたら代理でお受け取りいただけます。', 'Vâng, nếu là hàng xóm thì có thể nhận thay ạ.', 3),
(3983, 355, 'LISTENING', NULL, 'Linh', '分かりました。何か書くものはありますか。', 'Tôi hiểu rồi. Có cần ký gì không ạ?', 4),
(3984, 355, 'LISTENING', NULL, 'Nhân viên giao hàng', 'こちらにお名前をお願いいたします。', 'Xin chị ký tên vào đây ạ.', 5),
(3985, 355, 'LISTENING', NULL, 'Linh', 'はい。田中さんにはどう伝えればいいですか。', 'Vâng. Tôi nên báo với anh Tanaka thế nào ạ?', 6),
(3986, 355, 'LISTENING', NULL, 'Nhân viên giao hàng', 'ポストに不在票を入れておきますので、ご安心ください。', 'Tôi sẽ bỏ phiếu báo vắng vào hòm thư nên chị yên tâm ạ.', 7),
(3987, 355, 'LISTENING', NULL, 'Linh', '分かりました。お疲れさまです。', 'Tôi rõ rồi. Anh vất vả rồi ạ.', 8),
(3988, 356, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(3989, 358, 'GRAMMAR', 417, 'Ví dụ 1', '言いかけてやめた。', 'Tôi định nói rồi lại thôi.', 1),
(3990, 358, 'GRAMMAR', 417, 'Ví dụ 2', '飲みかけのコーヒーが置いてある。', 'Có cốc cà phê uống dở để đó.', 2),
(3991, 358, 'GRAMMAR', 418, 'Ví dụ 3', '夏休みに国へ帰るつもりです。', 'Nghỉ hè tôi dự định về nước.', 3),
(3992, 358, 'GRAMMAR', 418, 'Ví dụ 4', 'そんなことを言うつもりはなかった。', 'Tôi không hề có ý nói như vậy.', 4),
(3993, 358, 'GRAMMAR', 419, 'Ví dụ 5', '部長は今日休むということです。', 'Nghe nói hôm nay trưởng phòng nghỉ.', 5),
(3994, 358, 'GRAMMAR', 419, 'Ví dụ 6', 'つまり、やめるということですね。', 'Tức là anh nghỉ việc, đúng không?', 6),
(3995, 358, 'GRAMMAR', 420, 'Ví dụ 7', '本日、司会を務めさせていただきます。', 'Hôm nay xin phép cho tôi làm người dẫn chương trình.', 7),
(3996, 358, 'GRAMMAR', 420, 'Ví dụ 8', '明日休ませていただきます。', 'Ngày mai tôi xin phép nghỉ.', 8),
(3997, 358, 'GRAMMAR', 421, 'Ví dụ 9', '遅れてすみません。', 'Xin lỗi vì tôi đến muộn.', 9),
(3998, 358, 'GRAMMAR', 421, 'Ví dụ 10', 'ご迷惑をおかけして申し訳ありません。', 'Thành thật xin lỗi vì đã làm phiền.', 10),
(3999, 359, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4000, 361, 'GRAMMAR', 422, 'Ví dụ 1', '会議は大ホールにおいて行われます。', 'Cuộc họp được tổ chức tại đại sảnh.', 1);
INSERT INTO content_item (id, section_id, content_type, grammar_point_id, title, content, translated_text, order_index) VALUES
(4001, 361, 'GRAMMAR', 422, 'Ví dụ 2', '現代社会における教育の役割は大きい。', 'Vai trò của giáo dục trong xã hội hiện đại là rất lớn.', 2),
(4002, 361, 'GRAMMAR', 423, 'Ví dụ 3', '大雨のおそれがあります。', 'Có nguy cơ mưa lớn.', 3),
(4003, 361, 'GRAMMAR', 423, 'Ví dụ 4', 'このままでは倒産するおそれがある。', 'Cứ thế này thì có nguy cơ phá sản.', 4),
(4004, 361, 'GRAMMAR', 424, 'Ví dụ 5', '成功は努力の結果にほかならない。', 'Thành công chính là kết quả của nỗ lực chứ không gì khác.', 5),
(4005, 361, 'GRAMMAR', 424, 'Ví dụ 6', 'これは責任逃れにほかならない。', 'Đây đúng là hành vi trốn tránh trách nhiệm.', 6),
(4006, 361, 'GRAMMAR', 425, 'Ví dụ 7', '嫌いなわけではないが、あまり食べない。', 'Không hẳn là ghét nhưng tôi ít ăn.', 7),
(4007, 361, 'GRAMMAR', 425, 'Ví dụ 8', '全部分かったわけではない。', 'Không phải là tôi đã hiểu hết.', 8),
(4008, 361, 'GRAMMAR', 426, 'Ví dụ 9', '電話なりメールなりで連絡してください。', 'Xin liên lạc bằng điện thoại hay email gì cũng được.', 9),
(4009, 361, 'GRAMMAR', 426, 'Ví dụ 10', '休むなり医者に行くなりしなさい。', 'Hoặc nghỉ hoặc đi bác sĩ đi.', 10),
(4010, 362, 'LISTENING', NULL, 'Người phỏng vấn', 'では、志望動機をお聞かせいただけますか。', 'Vậy, anh có thể cho biết lý do ứng tuyển không?', 1),
(4011, 362, 'LISTENING', NULL, 'Linh', '御社が海外展開に力を入れている点に魅力を感じました。', 'Tôi thấy hấp dẫn ở điểm quý công ty đang đẩy mạnh mở rộng ra nước ngoài.', 2),
(4012, 362, 'LISTENING', NULL, 'Linh', '前職での経験を生かせるのではないかと考えております。', 'Tôi nghĩ mình có thể phát huy kinh nghiệm ở công ty cũ.', 3),
(4013, 362, 'LISTENING', NULL, 'Người phỏng vấn', '具体的にはどのような業務を担当されていましたか。', 'Cụ thể anh đã phụ trách công việc như thế nào?', 4),
(4014, 362, 'LISTENING', NULL, 'Linh', '日本側とベトナム側の間に立って、仕様の調整を行っておりました。', 'Tôi đứng giữa phía Nhật và phía Việt Nam để điều chỉnh yêu cầu kỹ thuật.', 5),
(4015, 362, 'LISTENING', NULL, 'Người phỏng vấn', 'では、認識の食い違いが起きた際はどう対応されましたか。', 'Vậy khi xảy ra khác biệt trong cách hiểu, anh xử lý thế nào?', 6),
(4016, 362, 'LISTENING', NULL, 'Linh', '曖昧な表現を残さないよう、必ず文書で確認するようにしていました。', 'Tôi luôn xác nhận bằng văn bản để không còn cách diễn đạt mơ hồ.', 7),
(4017, 362, 'LISTENING', NULL, 'Người phỏng vấn', 'なるほど。最後に、何かご質問はありますか。', 'Ra vậy. Cuối cùng, anh có câu hỏi gì không?', 8),
(4018, 363, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4019, 365, 'GRAMMAR', 427, 'Ví dụ 1', 'この件に関しては後日ご連絡します。', 'Về việc này chúng tôi sẽ liên hệ sau.', 1),
(4020, 365, 'GRAMMAR', 427, 'Ví dụ 2', '日本経済に関する本を読んでいます。', 'Tôi đang đọc sách liên quan đến kinh tế Nhật Bản.', 2),
(4021, 365, 'GRAMMAR', 428, 'Ví dụ 3', 'そんな運転では事故を起こしかねない。', 'Lái xe kiểu đó có thể gây tai nạn.', 3),
(4022, 365, 'GRAMMAR', 428, 'Ví dụ 4', '無理をすると体を壊しかねない。', 'Gắng sức quá có thể hỏng sức khoẻ.', 4),
(4023, 365, 'GRAMMAR', 429, 'Ví dụ 5', '犯人はこの部屋にいたに相違ない。', 'Hung thủ chắc chắn đã ở trong phòng này.', 5),
(4024, 365, 'GRAMMAR', 429, 'Ví dụ 6', '彼が書いたに相違ない。', 'Chắc chắn là anh ta viết.', 6),
(4025, 365, 'GRAMMAR', 430, 'Ví dụ 7', '高いものが必ずしもいいとは限らない。', 'Đồ đắt chưa chắc đã tốt.', 7),
(4026, 365, 'GRAMMAR', 430, 'Ví dụ 8', '日本人だから漢字が書けるとは限らない。', 'Là người Nhật chưa chắc đã viết được chữ Hán.', 8),
(4027, 365, 'GRAMMAR', 431, 'Ví dụ 9', '京都といえば、お寺が有名ですね。', 'Nhắc đến Kyoto thì chùa chiền nổi tiếng nhỉ.', 9),
(4028, 365, 'GRAMMAR', 431, 'Ví dụ 10', 'そういえば、明日は休みだ。', 'Nhắc mới nhớ, mai được nghỉ.', 10),
(4029, 366, 'LISTENING', NULL, 'Linh', '部長、進捗についてご報告したいことがございます。', 'Thưa trưởng phòng, em có việc muốn báo cáo về tiến độ ạ.', 1),
(4030, 366, 'LISTENING', NULL, 'Trưởng phòng', 'どうぞ。', 'Cứ nói đi.', 2),
(4031, 366, 'LISTENING', NULL, 'Linh', '仕様変更の影響で、納期に間に合わないおそれがあります。', 'Do ảnh hưởng của việc đổi yêu cầu, có nguy cơ không kịp hạn giao.', 3),
(4032, 366, 'LISTENING', NULL, 'Trưởng phòng', 'どのくらい遅れる見込みだ。', 'Dự kiến chậm bao lâu?', 4),
(4033, 366, 'LISTENING', NULL, 'Linh', '現時点では一週間ほどですが、テスト次第では延びる可能性もあります。', 'Hiện tại khoảng một tuần, nhưng tuỳ kết quả kiểm thử có thể còn kéo dài.', 5),
(4034, 366, 'LISTENING', NULL, 'Trưởng phòng', '原因は把握できているのか。', 'Đã nắm được nguyên nhân chưa?', 6),
(4035, 366, 'LISTENING', NULL, 'Linh', 'はい。要件の確定が遅れたことが主な原因です。', 'Vâng ạ. Nguyên nhân chính là việc chốt yêu cầu bị chậm.', 7),
(4036, 366, 'LISTENING', NULL, 'Trưởng phòng', '分かった。対策案を明日までにまとめて出してくれ。', 'Tôi hiểu rồi. Ngày mai tổng hợp phương án đối phó rồi nộp cho tôi.', 8),
(4037, 367, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4038, 369, 'GRAMMAR', 432, 'Ví dụ 1', '卒業に際して、一言申し上げます。', 'Nhân dịp tốt nghiệp, tôi xin nói vài lời.', 1),
(4039, 369, 'GRAMMAR', 432, 'Ví dụ 2', '契約に際して、書類が必要です。', 'Khi ký hợp đồng cần có giấy tờ.', 2),
(4040, 369, 'GRAMMAR', 433, 'Ví dụ 3', 'その件についてはお答えしかねます。', 'Về việc đó tôi khó lòng trả lời được ạ.', 3),
(4041, 369, 'GRAMMAR', 433, 'Ví dụ 4', 'ご要望には応じかねます。', 'Chúng tôi không thể đáp ứng yêu cầu của quý khách.', 4),
(4042, 369, 'GRAMMAR', 434, 'Ví dụ 5', '助け合うのが友達というものだ。', 'Giúp đỡ nhau, thế mới gọi là bạn.', 5),
(4043, 369, 'GRAMMAR', 434, 'Ví dụ 6', '金があれば幸せというものではない。', 'Không phải cứ có tiền là hạnh phúc.', 6),
(4044, 369, 'GRAMMAR', 435, 'Ví dụ 7', '食べられないことはないが、好きではない。', 'Không phải là không ăn được, nhưng tôi không thích.', 7),
(4045, 369, 'GRAMMAR', 435, 'Ví dụ 8', '行けないことはない。', 'Không phải là không đi được.', 8),
(4046, 369, 'GRAMMAR', 436, 'Ví dụ 9', '日本の食べ物というと、寿司を思い出す。', 'Nói đến món Nhật là tôi nghĩ ngay đến sushi.', 9),
(4047, 369, 'GRAMMAR', 436, 'Ví dụ 10', 'というと、中止ということですか。', 'Tức là huỷ, đúng không ạ?', 10),
(4048, 370, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4049, 372, 'GRAMMAR', 437, 'Ví dụ 1', '新年を迎えるに当たって、目標を立てた。', 'Trước thềm năm mới, tôi đặt ra mục tiêu.', 1),
(4050, 372, 'GRAMMAR', 437, 'Ví dụ 2', '開店に当たり、ご挨拶申し上げます。', 'Nhân dịp khai trương, xin gửi lời chào.', 2),
(4051, 372, 'GRAMMAR', 438, 'Ví dụ 3', '誰にでも起こり得ることです。', 'Đó là việc có thể xảy ra với bất kỳ ai.', 3),
(4052, 372, 'GRAMMAR', 438, 'Ví dụ 4', 'そんなことはあり得ない。', 'Chuyện đó không thể nào có.', 4),
(4053, 372, 'GRAMMAR', 439, 'Ví dụ 5', 'そんな話、嘘に決まっている。', 'Chuyện đó chắc chắn là bịa rồi.', 5),
(4054, 372, 'GRAMMAR', 439, 'Ví dụ 6', '今から行っても間に合わないに決まっている。', 'Giờ mới đi thì chắc chắn không kịp.', 6),
(4055, 372, 'GRAMMAR', 440, 'Ví dụ 7', '会議は毎週月曜に開かれることになっている。', 'Theo quy định họp được tổ chức vào thứ hai hằng tuần.', 7),
(4056, 372, 'GRAMMAR', 440, 'Ví dụ 8', 'ここでは靴を脱ぐことになっています。', 'Ở đây theo quy định là phải cởi giày.', 8),
(4057, 372, 'GRAMMAR', 441, 'Ví dụ 9', '初めてにしては上手だ。', 'So với lần đầu thì làm tốt đấy.', 9),
(4058, 372, 'GRAMMAR', 441, 'Ví dụ 10', '子供にしては大人びている。', 'So với trẻ con thì nó già dặn.', 10),
(4059, 373, 'LISTENING', NULL, 'Nhân viên hỗ trợ', 'お電話ありがとうございます。ご用件を承ります。', 'Cảm ơn quý khách đã gọi. Xin quý khách cho biết nội dung ạ.', 1),
(4060, 373, 'LISTENING', NULL, 'Linh', '先週購入した洗濯機が、二日目から動かなくなったのですが。', 'Máy giặt tôi mua tuần trước, từ ngày thứ hai đã không chạy nữa ạ.', 2),
(4061, 373, 'LISTENING', NULL, 'Nhân viên hỗ trợ', 'ご不便をおかけし、申し訳ございません。型番をお伺いできますか。', 'Thành thật xin lỗi vì đã gây bất tiện. Xin cho hỏi mã sản phẩm ạ.', 3),
(4062, 373, 'LISTENING', NULL, 'Linh', 'はい、本体の裏に書いてあります。少々お待ちください。', 'Vâng, có ghi ở mặt sau thân máy. Xin đợi tôi một chút.', 4),
(4063, 373, 'LISTENING', NULL, 'Nhân viên hỗ trợ', '確認いたしました。保証期間内ですので、無償で修理いたします。', 'Tôi đã xác nhận. Vẫn trong thời hạn bảo hành nên chúng tôi sẽ sửa miễn phí ạ.', 5),
(4064, 373, 'LISTENING', NULL, 'Linh', '修理ではなく、交換していただくことはできませんか。', 'Không phải sửa mà đổi máy mới cho tôi có được không ạ?', 6),
(4065, 373, 'LISTENING', NULL, 'Nhân viên hỗ trợ', '初期不良と判断された場合は、交換も可能でございます。', 'Nếu được xác định là lỗi ban đầu thì đổi máy cũng được ạ.', 7),
(4066, 373, 'LISTENING', NULL, 'Linh', 'では、点検をお願いします。今週中に来ていただけますか。', 'Vậy nhờ anh cho kiểm tra ạ. Trong tuần này đến được không ạ?', 8),
(4067, 374, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4068, 376, 'GRAMMAR', 442, 'Ví dụ 1', '開会に先立って、写真撮影を行います。', 'Trước khi khai mạc, chúng ta chụp ảnh.', 1),
(4069, 376, 'GRAMMAR', 442, 'Ví dụ 2', '発売に先立ち、試写会が開かれた。', 'Trước khi phát hành, buổi chiếu thử đã diễn ra.', 2),
(4070, 376, 'GRAMMAR', 443, 'Ví dụ 3', '彼の話は信じがたい。', 'Chuyện của anh ta khó mà tin được.', 3),
(4071, 376, 'GRAMMAR', 443, 'Ví dụ 4', '忘れがたい思い出になりました。', 'Đó đã thành kỷ niệm khó quên.', 4),
(4072, 376, 'GRAMMAR', 444, 'Ví dụ 5', 'そんな難しい問題、分かりっこないよ。', 'Bài khó thế thì làm gì hiểu nổi.', 5),
(4073, 376, 'GRAMMAR', 444, 'Ví dụ 6', '一日でできっこない。', 'Một ngày thì làm gì xong được.', 6),
(4074, 376, 'GRAMMAR', 445, 'Ví dụ 7', '彼の演奏には心を打つものがある。', 'Tiếng đàn của anh ấy có cái gì đó lay động lòng người.', 7),
(4075, 376, 'GRAMMAR', 445, 'Ví dụ 8', 'この作品には見るべきものがある。', 'Tác phẩm này có chỗ đáng xem.', 8),
(4076, 376, 'GRAMMAR', 446, 'Ví dụ 9', '宝くじが当たったとしたら、何を買いますか。', 'Nếu trúng số bạn sẽ mua gì?', 9),
(4077, 376, 'GRAMMAR', 446, 'Ví dụ 10', '本当だとすれば大問題だ。', 'Nếu là thật thì là vấn đề lớn.', 10),
(4078, 377, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4079, 379, 'GRAMMAR', 447, 'Ví dụ 1', '新しい法律をめぐって議論が続いている。', 'Tranh luận vẫn tiếp diễn xoay quanh luật mới.', 1),
(4080, 379, 'GRAMMAR', 447, 'Ví dụ 2', '遺産をめぐる争いが起きた。', 'Đã xảy ra tranh chấp xoay quanh di sản.', 2),
(4081, 379, 'GRAMMAR', 448, 'Ví dụ 3', '最後まで走り抜いた。', 'Tôi đã chạy đến cùng.', 3),
(4082, 379, 'GRAMMAR', 448, 'Ví dụ 4', 'よく考え抜いて決めた。', 'Tôi đã suy nghĩ thấu đáo rồi mới quyết.', 4),
(4083, 379, 'GRAMMAR', 449, 'Ví dụ 5', '風邪気味なので早退します。', 'Tôi hơi bị cảm nên xin về sớm.', 5),
(4084, 379, 'GRAMMAR', 449, 'Ví dụ 6', '最近太り気味だ。', 'Dạo này tôi hơi tăng cân.', 6),
(4085, 379, 'GRAMMAR', 450, 'Ví dụ 7', 'そんなに休むようでは、合格できないよ。', 'Nghỉ nhiều như thế thì không đỗ được đâu.', 7),
(4086, 379, 'GRAMMAR', 450, 'Ví dụ 8', 'これぐらいで諦めるようでは困る。', 'Mới thế này mà đã bỏ cuộc thì gay.', 8),
(4087, 379, 'GRAMMAR', 451, 'Ví dụ 9', '会社を辞めるつもりはありません。', 'Tôi hoàn toàn không có ý định nghỉ việc.', 9),
(4088, 379, 'GRAMMAR', 451, 'Ví dụ 10', '言い訳するつもりはない。', 'Tôi không định biện hộ.', 10),
(4089, 380, 'LISTENING', NULL, 'Nam', '来月の案件について、役割を決めておきたいんだけど。', 'Về dự án tháng sau, tớ muốn phân vai trước.', 1),
(4090, 380, 'LISTENING', NULL, 'Yuki', '設計は私がやります。前回も担当したので。', 'Phần thiết kế để tớ làm. Lần trước tớ cũng phụ trách rồi.', 2),
(4091, 380, 'LISTENING', NULL, 'Linh', '私はテストを担当したいです。ただ、量が多いようなら手伝ってもらえると助かります。', 'Tớ muốn phụ trách phần kiểm thử. Có điều nếu khối lượng nhiều thì nhờ hỗ trợ giúp tớ.', 3),
(4092, 380, 'LISTENING', NULL, 'Nam', '分かった。じゃあ、テストは二人で分担しよう。', 'Được. Vậy phần kiểm thử hai người chia nhau nhé.', 4),
(4093, 380, 'LISTENING', NULL, 'Yuki', 'スケジュールはどうしますか。', 'Lịch trình thì tính sao?', 5),
(4094, 380, 'LISTENING', NULL, 'Nam', '初週に設計を終わらせて、二週目からテストに入る形でどうかな。', 'Tuần đầu xong thiết kế, từ tuần hai vào kiểm thử, thấy sao?', 6),
(4095, 380, 'LISTENING', NULL, 'Linh', '少しきついかもしれませんが、やってみる価値はあると思います。', 'Có thể hơi gấp, nhưng tớ nghĩ đáng để thử.', 7),
(4096, 380, 'LISTENING', NULL, 'Nam', 'じゃあ、その方向で進めよう。何かあればすぐ共有して。', 'Vậy triển khai theo hướng đó. Có gì thì chia sẻ ngay nhé.', 8),
(4097, 381, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4098, 383, 'GRAMMAR', 452, 'Ví dụ 1', '若者を中心に人気が広がっている。', 'Sự yêu thích đang lan rộng, chủ yếu trong giới trẻ.', 1),
(4099, 383, 'GRAMMAR', 452, 'Ví dụ 2', '東京を中心に店舗を展開する。', 'Mở rộng cửa hàng lấy Tokyo làm trung tâm.', 2),
(4100, 383, 'GRAMMAR', 453, 'Ví dụ 3', '景気は回復しつつある。', 'Kinh tế đang dần hồi phục.', 3),
(4101, 383, 'GRAMMAR', 453, 'Ví dụ 4', 'その習慣は消えつつある。', 'Tập quán đó đang dần mất đi.', 4),
(4102, 383, 'GRAMMAR', 454, 'Ví dụ 5', '彼女は寂しげな表情をしていた。', 'Cô ấy mang vẻ mặt buồn bã.', 5),
(4103, 383, 'GRAMMAR', 454, 'Ví dụ 6', '子供たちが楽しげに遊んでいる。', 'Bọn trẻ đang chơi ra chiều vui vẻ.', 6),
(4104, 383, 'GRAMMAR', 455, 'Ví dụ 7', 'あんな人に頼むくらいなら、自分でやる。', 'Thà tự làm còn hơn nhờ người như thế.', 7),
(4105, 383, 'GRAMMAR', 455, 'Ví dụ 8', '待たされるくらいなら、帰ったほうがましだ。', 'Thà về còn hơn phải đứng chờ.', 8),
(4106, 383, 'GRAMMAR', 456, 'Ví dụ 9', 'こうしてはいられない、急ごう。', 'Không thể cứ đứng đây, nhanh lên thôi.', 9),
(4107, 383, 'GRAMMAR', 456, 'Ví dụ 10', 'のんびりしてはいられない。', 'Không thể thong thả được nữa.', 10),
(4108, 384, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4109, 386, 'GRAMMAR', 457, 'Ví dụ 1', '実話をもとに映画が作られた。', 'Bộ phim được làm dựa trên chuyện có thật.', 1),
(4110, 386, 'GRAMMAR', 457, 'Ví dụ 2', 'アンケートをもとに分析します。', 'Chúng tôi phân tích dựa trên phiếu khảo sát.', 2),
(4111, 386, 'GRAMMAR', 458, 'Ví dụ 3', '結果を気にしつつ、待っている。', 'Tôi vừa chờ vừa lo về kết quả.', 3),
(4112, 386, 'GRAMMAR', 458, 'Ví dụ 4', '体に悪いと知りつつも、やめられない。', 'Biết là hại sức khoẻ mà vẫn không bỏ được.', 4),
(4113, 386, 'GRAMMAR', 459, 'Ví dụ 5', '冗談は抜きにして、本題に入ろう。', 'Thôi đùa đủ rồi, vào việc chính đi.', 5),
(4114, 386, 'GRAMMAR', 459, 'Ví dụ 6', '今日は朝食抜きで来た。', 'Hôm nay tôi đến mà chưa ăn sáng.', 6),
(4115, 386, 'GRAMMAR', 460, 'Ví dụ 7', '五十歳にして初めて絵を習い始めた。', 'Mãi đến năm mươi tuổi ông mới bắt đầu học vẽ.', 7),
(4116, 386, 'GRAMMAR', 460, 'Ví dụ 8', '彼は学者にして詩人でもある。', 'Ông vừa là học giả vừa là nhà thơ.', 8),
(4117, 386, 'GRAMMAR', 461, 'Ví dụ 9', '退屈でしようがない。', 'Chán không chịu nổi.', 9),
(4118, 386, 'GRAMMAR', 461, 'Ví dụ 10', '気になってしようがない。', 'Tôi bận tâm quá đỗi.', 10),
(4119, 387, 'LISTENING', NULL, 'Linh', '今後のことでご相談したいことがあるのですが、お時間よろしいでしょうか。', 'Em có việc muốn xin ý kiến về hướng đi sắp tới, anh có thời gian không ạ?', 1),
(4120, 387, 'LISTENING', NULL, 'Trưởng phòng', 'いいよ。どうした。', 'Được. Có chuyện gì?', 2),
(4121, 387, 'LISTENING', NULL, 'Linh', '来期から開発のほうに携わらせていただけないかと考えております。', 'Em đang nghĩ từ kỳ sau liệu có được tham gia mảng phát triển không ạ.', 3),
(4122, 387, 'LISTENING', NULL, 'Trưởng phòng', '理由を聞かせてもらえるかな。', 'Cho tôi nghe lý do được không?', 4),
(4123, 387, 'LISTENING', NULL, 'Linh', '今の業務で得た知識を、より上流の工程で生かしたいと思ったからです。', 'Vì em muốn vận dụng kiến thức có được ở công việc hiện tại vào công đoạn đầu nguồn hơn.', 5),
(4124, 387, 'LISTENING', NULL, 'Trưởng phòng', '気持ちは分かった。ただ、今の担当を引き継ぐ人がいないのが問題だな。', 'Tôi hiểu nguyện vọng. Chỉ có điều vấn đề là chưa có ai nhận bàn giao phần cậu đang làm.', 6),
(4125, 387, 'LISTENING', NULL, 'Linh', '引き継ぎ資料は今月中に整えるつもりです。', 'Em định hoàn thiện tài liệu bàn giao trong tháng này ạ.', 7),
(4126, 387, 'LISTENING', NULL, 'Trưởng phòng', '分かった。上と相談してみるから、少し時間をくれ。', 'Được. Tôi sẽ bàn với cấp trên, cho tôi chút thời gian.', 8),
(4127, 388, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4128, 390, 'GRAMMAR', 462, 'Ví dụ 1', '法律に基づいて処理します。', 'Xử lý căn cứ theo pháp luật.', 1),
(4129, 390, 'GRAMMAR', 462, 'Ví dụ 2', 'データに基づく判断が必要だ。', 'Cần có phán đoán dựa trên dữ liệu.', 2),
(4130, 390, 'GRAMMAR', 463, 'Ví dụ 3', '物価は上がる一方だ。', 'Vật giá cứ tăng mãi.', 3),
(4131, 390, 'GRAMMAR', 463, 'Ví dụ 4', '彼の病気は悪くなる一方だ。', 'Bệnh của ông ấy ngày một nặng thêm.', 4),
(4132, 390, 'GRAMMAR', 464, 'Ví dụ 5', '心を込めて手紙を書いた。', 'Tôi viết bức thư với tất cả tấm lòng.', 5),
(4133, 390, 'GRAMMAR', 464, 'Ví dụ 6', '感謝を込めて贈ります。', 'Tôi xin tặng với lòng biết ơn.', 6),
(4134, 390, 'GRAMMAR', 465, 'Ví dụ 7', 'わざわざ来ていただくほどのことではありません。', 'Không đến mức phải phiền anh đến tận nơi ạ.', 7),
(4135, 390, 'GRAMMAR', 465, 'Ví dụ 8', '心配するほどのことではない。', 'Không đến mức phải lo.', 8),
(4136, 390, 'GRAMMAR', 466, 'Ví dụ 9', 'さすが十年練習しただけのことはある。', 'Quả nhiên luyện mười năm có khác.', 9),
(4137, 390, 'GRAMMAR', 466, 'Ví dụ 10', '高いだけのことはある味だ。', 'Vị này xứng với cái giá đắt.', 10),
(4138, 391, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4139, 393, 'GRAMMAR', 467, 'Ví dụ 1', '川に沿って道が続いている。', 'Con đường chạy dọc theo dòng sông.', 1),
(4140, 393, 'GRAMMAR', 467, 'Ví dụ 2', '計画に沿って作業を進めます。', 'Tiến hành công việc theo đúng kế hoạch.', 2),
(4141, 393, 'GRAMMAR', 468, 'Ví dụ 3', '彼は厳しい一方で、優しいところもある。', 'Anh ấy nghiêm khắc nhưng mặt khác cũng có chỗ dịu dàng.', 3),
(4142, 393, 'GRAMMAR', 468, 'Ví dụ 4', '収入が増える一方で、支出も増えた。', 'Thu nhập tăng nhưng mặt khác chi tiêu cũng tăng.', 4),
(4143, 393, 'GRAMMAR', 469, 'Ví dụ 5', '年齢を問わず応募できます。', 'Bất kể tuổi tác đều có thể ứng tuyển.', 5),
(4144, 393, 'GRAMMAR', 469, 'Ví dụ 6', '昼夜を問わず働いている。', 'Làm việc bất kể ngày đêm.', 6),
(4145, 393, 'GRAMMAR', 470, 'Ví dụ 7', '親になってはじめて、親の気持ちが分かった。', 'Làm cha mẹ rồi tôi mới hiểu lòng cha mẹ.', 7),
(4146, 393, 'GRAMMAR', 470, 'Ví dụ 8', '失ってはじめて大切さに気づく。', 'Mất đi rồi mới nhận ra giá trị.', 8),
(4147, 393, 'GRAMMAR', 471, 'Ví dụ 9', '雨に加えて風も強くなった。', 'Ngoài mưa ra, gió cũng mạnh lên.', 9),
(4148, 393, 'GRAMMAR', 471, 'Ví dụ 10', '経験に加えて語学力も求められる。', 'Ngoài kinh nghiệm còn đòi hỏi năng lực ngoại ngữ.', 10),
(4149, 394, 'LISTENING', NULL, 'Linh', '健太くん、ちょっといい。先週の件なんだけど。', 'Kenta, rảnh một chút không? Chuyện tuần trước ấy.', 1),
(4150, 394, 'LISTENING', NULL, 'Kenta', 'はい、報告が遅れた件ですよね。申し訳ありませんでした。', 'Vâng, chuyện em báo cáo muộn phải không ạ. Em xin lỗi ạ.', 2),
(4151, 394, 'LISTENING', NULL, 'Linh', '責めるつもりはないよ。ただ、早めに言ってくれれば対応できたと思うんだ。', 'Anh không định trách đâu. Chỉ là nếu em nói sớm thì anh nghĩ đã xử lý được.', 3),
(4152, 394, 'LISTENING', NULL, 'Kenta', '自分で解決しようとして、かえって遅くなってしまいました。', 'Em định tự giải quyết nên hoá ra lại thành muộn hơn ạ.', 4),
(4153, 394, 'LISTENING', NULL, 'Linh', 'その気持ちは分かる。でも、判断に迷ったら早い段階で相談してほしい。', 'Anh hiểu tâm lý đó. Nhưng nếu phân vân thì anh mong em hỏi sớm.', 5),
(4154, 394, 'LISTENING', NULL, 'Kenta', 'はい。次からは途中でも共有するようにします。', 'Vâng ạ. Từ lần sau em sẽ chia sẻ cả khi đang làm dở.', 6),
(4155, 394, 'LISTENING', NULL, 'Linh', 'うん、それでいい。困ったときはいつでも声をかけて。', 'Ừ, thế là được. Có gì khó thì cứ gọi anh bất cứ lúc nào.', 7),
(4156, 394, 'LISTENING', NULL, 'Kenta', 'ありがとうございます。助かります。', 'Em cảm ơn anh ạ. Đỡ cho em nhiều.', 8),
(4157, 395, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4158, 397, 'GRAMMAR', 472, 'Ví dụ 1', '工事は三年にわたって続いた。', 'Công trình kéo dài suốt ba năm.', 1),
(4159, 397, 'GRAMMAR', 472, 'Ví dụ 2', '広い範囲にわたる調査が行われた。', 'Cuộc điều tra được tiến hành trên phạm vi rộng.', 2),
(4160, 397, 'GRAMMAR', 473, 'Ví dụ 3', '便利な反面、危険も多い。', 'Tiện lợi nhưng mặt trái là cũng nhiều nguy hiểm.', 3),
(4161, 397, 'GRAMMAR', 473, 'Ví dụ 4', '給料がいい反面、残業が多い。', 'Lương tốt nhưng bù lại tăng ca nhiều.', 4),
(4162, 397, 'GRAMMAR', 474, 'Ví dụ 5', '上司に確認してからでないと、返事できません。', 'Chưa xác nhận với cấp trên thì tôi chưa thể trả lời.', 5),
(4163, 397, 'GRAMMAR', 474, 'Ví dụ 6', '登録してからでないと利用できない。', 'Chưa đăng ký thì không dùng được.', 6),
(4164, 397, 'GRAMMAR', 475, 'Ví dụ 7', '日本で働くには、ビザが必要です。', 'Để làm việc ở Nhật thì cần visa.', 7),
(4165, 397, 'GRAMMAR', 475, 'Ví dụ 8', '健康を保つには運動が欠かせない。', 'Để giữ sức khoẻ thì không thể thiếu vận động.', 8),
(4166, 397, 'GRAMMAR', 476, 'Ví dụ 9', '日曜を除いて毎日営業しています。', 'Chúng tôi mở cửa hằng ngày trừ chủ nhật.', 9),
(4167, 397, 'GRAMMAR', 476, 'Ví dụ 10', '一部を除き、全員が賛成した。', 'Trừ một số ít, tất cả đều tán thành.', 10),
(4168, 398, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4169, 400, 'GRAMMAR', 477, 'Ví dụ 1', 'インターネットを通じて世界とつながる。', 'Kết nối với thế giới thông qua Internet.', 1),
(4170, 400, 'GRAMMAR', 477, 'Ví dụ 2', 'この地方は一年を通して雨が多い。', 'Vùng này mưa nhiều suốt cả năm.', 2),
(4171, 400, 'GRAMMAR', 478, 'Ví dụ 3', '予想に反して、彼が勝った。', 'Trái với dự đoán, anh ấy đã thắng.', 3),
(4172, 400, 'GRAMMAR', 478, 'Ví dụ 4', '期待に反する結果になった。', 'Kết quả trái với kỳ vọng.', 4),
(4173, 400, 'GRAMMAR', 479, 'Ví dụ 5', '日本に来て以来、彼に会っていない。', 'Kể từ khi sang Nhật tôi chưa gặp anh ấy.', 5),
(4174, 400, 'GRAMMAR', 479, 'Ví dụ 6', '卒業して以来、連絡がない。', 'Từ khi tốt nghiệp đến giờ không liên lạc gì.', 6),
(4175, 400, 'GRAMMAR', 480, 'Ví dụ 7', 'これで三回目ということになる。', 'Vậy là thành lần thứ ba.', 7),
(4176, 400, 'GRAMMAR', 480, 'Ví dụ 8', '彼の話が本当なら、私が間違っていたことになる。', 'Nếu lời anh ta đúng thì hoá ra tôi đã sai.', 8),
(4177, 400, 'GRAMMAR', 481, 'Ví dụ 9', '彼以外に知っている人はいない。', 'Ngoài anh ấy ra không ai biết.', 9),
(4178, 400, 'GRAMMAR', 481, 'Ví dụ 10', '英語以外にも二か国語話せる。', 'Ngoài tiếng Anh tôi còn nói được hai thứ tiếng.', 10),
(4179, 401, 'LISTENING', NULL, 'Linh', 'このたびは納品数に誤りがあり、誠に申し訳ございませんでした。', 'Lần này số lượng giao hàng có sai sót, chúng tôi thành thật xin lỗi.', 1),
(4180, 401, 'LISTENING', NULL, 'Chị Ishida', 'こちらも急いでいたので、正直かなり困りました。', 'Bên tôi cũng đang gấp nên thật lòng là khá khổ.', 2),
(4181, 401, 'LISTENING', NULL, 'Linh', 'ご迷惑をおかけしたこと、重ねてお詫び申し上げます。', 'Việc gây phiền toái cho quý vị, chúng tôi xin lỗi một lần nữa.', 3),
(4182, 401, 'LISTENING', NULL, 'Chị Ishida', '不足分はいつ届くのでしょうか。', 'Phần còn thiếu bao giờ thì tới ạ?', 4),
(4183, 401, 'LISTENING', NULL, 'Linh', '本日中に発送し、明日午前中にはお届けできる見込みです。', 'Chúng tôi gửi trong hôm nay, dự kiến sáng mai sẽ giao tới ạ.', 5),
(4184, 401, 'LISTENING', NULL, 'Chị Ishida', '分かりました。再発防止だけはお願いしますね。', 'Tôi hiểu rồi. Chỉ mong bên anh ngăn không để tái diễn.', 6),
(4185, 401, 'LISTENING', NULL, 'Linh', 'はい。出荷前の二重チェックを徹底いたします。', 'Vâng ạ. Chúng tôi sẽ thực hiện triệt để việc kiểm tra kép trước khi xuất hàng.', 7),
(4186, 401, 'LISTENING', NULL, 'Chị Ishida', 'よろしくお願いします。今後とも期待していますので。', 'Vậy nhờ anh. Từ nay tôi vẫn kỳ vọng ở bên anh.', 8),
(4187, 402, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4188, 404, 'GRAMMAR', 482, 'Ví dụ 1', '到着次第、ご連絡します。', 'Vừa đến nơi là tôi sẽ liên lạc ngay.', 1),
(4189, 404, 'GRAMMAR', 482, 'Ví dụ 2', '準備ができ次第、始めましょう。', 'Chuẩn bị xong là bắt đầu luôn.', 2),
(4190, 404, 'GRAMMAR', 483, 'Ví dụ 3', '雨にもかかわらず、大勢の人が集まった。', 'Mặc dù trời mưa, rất đông người vẫn tụ họp.', 3),
(4191, 404, 'GRAMMAR', 483, 'Ví dụ 4', '努力したにもかかわらず、失敗した。', 'Dù đã nỗ lực nhưng vẫn thất bại.', 4),
(4192, 404, 'GRAMMAR', 484, 'Ví dụ 5', 'この写真を見るにつけ、母を思い出す。', 'Mỗi lần nhìn tấm ảnh này tôi lại nhớ mẹ.', 5),
(4193, 404, 'GRAMMAR', 484, 'Ví dụ 6', '何かにつけ文句を言う。', 'Cứ động chuyện gì là lại kêu ca.', 6),
(4194, 404, 'GRAMMAR', 485, 'Ví dụ 7', '契約内容を確認した上で、署名してください。', 'Xin ký sau khi đã xác nhận nội dung hợp đồng.', 7),
(4195, 404, 'GRAMMAR', 485, 'Ví dụ 8', '両親と相談した上で返事します。', 'Tôi sẽ trả lời sau khi bàn với bố mẹ.', 8),
(4196, 404, 'GRAMMAR', 486, 'Ví dụ 9', '命にかけても守ります。', 'Dù đánh đổi mạng sống tôi cũng bảo vệ.', 9),
(4197, 404, 'GRAMMAR', 486, 'Ví dụ 10', '社の名誉にかけても成功させる。', 'Lấy danh dự công ty ra, nhất định phải thành công.', 10),
(4198, 405, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4199, 407, 'GRAMMAR', 487, 'Ví dụ 1', '成功するかどうかは努力次第だ。', 'Thành công hay không là tuỳ ở nỗ lực.', 1),
(4200, 407, 'GRAMMAR', 487, 'Ví dụ 2', '天気次第で予定を変更します。', 'Tuỳ thời tiết mà thay đổi kế hoạch.', 2),
(4201, 407, 'GRAMMAR', 488, 'Ví dụ 3', '冗談にしても、言い過ぎだ。', 'Dù là đùa thì cũng nói quá lời.', 3),
(4202, 407, 'GRAMMAR', 488, 'Ví dụ 4', '行くにしても行かないにしても、早く決めて。', 'Dù đi hay không thì cũng quyết định sớm đi.', 4),
(4203, 407, 'GRAMMAR', 489, 'Ví dụ 5', '人口の増加に伴って、住宅が不足している。', 'Cùng với dân số tăng, nhà ở đang thiếu.', 5),
(4204, 407, 'GRAMMAR', 489, 'Ví dụ 6', '経済成長に伴う環境問題。', 'Vấn đề môi trường kéo theo tăng trưởng kinh tế.', 6),
(4205, 407, 'GRAMMAR', 490, 'Ví dụ 7', 'これは仕事の上での付き合いです。', 'Đây là quan hệ trong công việc.', 7),
(4206, 407, 'GRAMMAR', 490, 'Ví dụ 8', '生活する上での不便はありません。', 'Không có bất tiện gì trong sinh hoạt.', 8),
(4207, 407, 'GRAMMAR', 491, 'Ví dụ 9', '道が混んでいたものですから、遅れました。', 'Là vì đường đông nên tôi đến muộn ạ.', 9),
(4208, 407, 'GRAMMAR', 491, 'Ví dụ 10', '急いでいたものですから、失礼しました。', 'Vì đang vội nên tôi thất lễ ạ.', 10),
(4209, 408, 'LISTENING', NULL, 'Linh', '承認の流れについて、一点ご提案があります。', 'Về luồng phê duyệt, em có một đề xuất ạ.', 1),
(4210, 408, 'LISTENING', NULL, 'Trưởng phòng', 'どうぞ。聞かせて。', 'Cứ nói. Cho tôi nghe.', 2),
(4211, 408, 'LISTENING', NULL, 'Linh', '現在は四人の承認が必要ですが、二人に減らせないでしょうか。', 'Hiện cần bốn người phê duyệt, liệu có giảm xuống hai được không ạ?', 3),
(4212, 408, 'LISTENING', NULL, 'Trưởng phòng', '理由は。', 'Lý do?', 4),
(4213, 408, 'LISTENING', NULL, 'Linh', '平均で三日かかっており、その大半が待ち時間だからです。', 'Vì trung bình mất ba ngày, mà phần lớn trong đó là thời gian chờ.', 5),
(4214, 408, 'LISTENING', NULL, 'Trưởng phòng', 'ただ、チェックが甘くなるリスクもあるだろう。', 'Nhưng cũng có rủi ro là việc kiểm tra bị lỏng đi chứ.', 6),
(4215, 408, 'LISTENING', NULL, 'Linh', '金額が一定以上の案件だけ四人のままにすれば、リスクは抑えられると考えます。', 'Nếu chỉ giữ bốn người với dự án trên một mức tiền nhất định thì em nghĩ kiểm soát được rủi ro.', 7),
(4216, 408, 'LISTENING', NULL, 'Trưởng phòng', 'なるほど。それなら試す価値はあるな。案をまとめてくれ。', 'Ra vậy. Thế thì đáng thử đấy. Tổng hợp phương án đi.', 8),
(4217, 409, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4218, 411, 'GRAMMAR', 492, 'Ví dụ 1', '健康上の理由で退職しました。', 'Tôi nghỉ việc vì lý do sức khoẻ.', 1),
(4219, 411, 'GRAMMAR', 492, 'Ví dụ 2', '規則上、それは認められません。', 'Về mặt quy định, điều đó không được chấp nhận.', 2),
(4220, 411, 'GRAMMAR', 493, 'Ví dụ 3', '理由が何にせよ、遅刻は遅刻だ。', 'Dù lý do là gì thì muộn vẫn là muộn.', 3),
(4221, 411, 'GRAMMAR', 493, 'Ví dụ 4', 'いずれにしろ、連絡は必要だ。', 'Dù sao thì cũng cần liên lạc.', 4),
(4222, 411, 'GRAMMAR', 494, 'Ví dụ 5', '年をとるとともに、体力が落ちる。', 'Cùng với tuổi tác, thể lực giảm sút.', 5),
(4223, 411, 'GRAMMAR', 494, 'Ví dụ 6', '家族とともに暮らしています。', 'Tôi sống cùng gia đình.', 6),
(4224, 411, 'GRAMMAR', 495, 'Ví dụ 7', '転んだはずみで手をついた。', 'Lỡ đà ngã nên tôi chống tay xuống.', 7),
(4225, 411, 'GRAMMAR', 495, 'Ví dụ 8', '何かのはずみで口が滑った。', 'Trong lúc vô ý tôi lỡ miệng.', 8),
(4226, 411, 'GRAMMAR', 496, 'Ví dụ 9', '彼のことだから、また遅れるだろう。', 'Tính anh ta thì chắc lại đến muộn thôi.', 9),
(4227, 411, 'GRAMMAR', 496, 'Ví dụ 10', 'まじめな彼女のことだから、きっとやり遂げる。', 'Cô ấy nghiêm túc thế thì chắc chắn làm xong.', 10),
(4228, 412, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4229, 414, 'GRAMMAR', 497, 'Ví dụ 1', '約束した以上、守らなければならない。', 'Đã hứa thì phải giữ lời.', 1),
(4230, 414, 'GRAMMAR', 497, 'Ví dụ 2', '学生である以上、勉強が本分だ。', 'Đã là sinh viên thì việc chính là học.', 2),
(4231, 414, 'GRAMMAR', 498, 'Ví dụ 3', '問い合わせたところ、在庫があるとのことだった。', 'Khi tôi hỏi thì họ bảo còn hàng.', 3),
(4232, 414, 'GRAMMAR', 498, 'Ví dụ 4', '開けてみたところ、中は空だった。', 'Mở ra xem thì bên trong trống không.', 4),
(4233, 414, 'GRAMMAR', 499, 'Ví dụ 5', '山を登るにしたがって、気温が下がった。', 'Càng lên núi nhiệt độ càng giảm.', 5),
(4234, 414, 'GRAMMAR', 499, 'Ví dụ 6', '説明書にしたがって組み立てた。', 'Tôi lắp theo đúng hướng dẫn.', 6),
(4235, 414, 'GRAMMAR', 500, 'Ví dụ 7', 'ついに完成した。', 'Cuối cùng cũng hoàn thành.', 7),
(4236, 414, 'GRAMMAR', 500, 'Ví dụ 8', 'ついに彼は現れなかった。', 'Cuối cùng anh ta vẫn không xuất hiện.', 8),
(4237, 414, 'GRAMMAR', 501, 'Ví dụ 9', '行けません。というのは急用ができたからです。', 'Tôi không đi được. Sở dĩ vậy là vì có việc gấp.', 9),
(4238, 414, 'GRAMMAR', 501, 'Ví dụ 10', '努力というのは続けることだ。', 'Cái gọi là nỗ lực chính là sự kiên trì.', 10),
(4239, 415, 'LISTENING', NULL, 'Trưởng phòng', '昨日の資料だけど、正直に言うと少し分かりにくかった。', 'Tài liệu hôm qua ấy, nói thật là hơi khó hiểu.', 1),
(4240, 415, 'LISTENING', NULL, 'Linh', 'ご指摘ありがとうございます。どのあたりでしょうか。', 'Cảm ơn anh đã chỉ ra ạ. Là chỗ nào ạ?', 2),
(4241, 415, 'LISTENING', NULL, 'Trưởng phòng', '結論が最後に来ているから、読む側は途中で迷ってしまう。', 'Kết luận nằm ở cuối nên người đọc bị lạc ở giữa chừng.', 3),
(4242, 415, 'LISTENING', NULL, 'Linh', 'なるほど。先に結論を出して、根拠を後ろに回すということですね。', 'Ra vậy. Tức là đưa kết luận trước rồi dồn căn cứ xuống sau, đúng không ạ.', 4),
(4243, 415, 'LISTENING', NULL, 'Trưởng phòng', 'そう。あとは図を一枚入れるだけでも印象が変わるよ。', 'Đúng. Với lại chỉ cần thêm một hình thôi cũng khác hẳn ấn tượng.', 5),
(4244, 415, 'LISTENING', NULL, 'Linh', '承知しました。今日中に直して、もう一度見ていただけますか。', 'Em hiểu rồi ạ. Em sửa trong hôm nay, anh xem lại giúp em được không ạ?', 6),
(4245, 415, 'LISTENING', NULL, 'Trưởng phòng', 'いいよ。直した理由も一緒に書いておいて。', 'Được. Ghi kèm cả lý do sửa nữa nhé.', 7),
(4246, 415, 'LISTENING', NULL, 'Linh', 'はい、そうします。ありがとうございました。', 'Vâng, em sẽ làm vậy. Em cảm ơn anh ạ.', 8),
(4247, 416, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4248, 418, 'GRAMMAR', 502, 'Ví dụ 1', '引き受けたからには、最後までやる。', 'Đã nhận thì tôi làm đến cùng.', 1),
(4249, 418, 'GRAMMAR', 502, 'Ví dụ 2', '日本へ来たからには、日本語を覚えたい。', 'Đã sang Nhật thì tôi muốn học tiếng Nhật.', 2),
(4250, 418, 'GRAMMAR', 503, 'Ví dụ 3', 'ドアを開けたとたん、猫が飛び出した。', 'Vừa mở cửa là con mèo phóng ra.', 3),
(4251, 418, 'GRAMMAR', 503, 'Ví dụ 4', '立ち上がったとたん、めまいがした。', 'Vừa đứng dậy là tôi thấy chóng mặt.', 4),
(4252, 418, 'GRAMMAR', 504, 'Ví dụ 5', '時間がたつにつれて、痛みは和らいだ。', 'Thời gian trôi qua, cơn đau dịu dần.', 5),
(4253, 418, 'GRAMMAR', 504, 'Ví dụ 6', '経験を積むにつれて自信がついた。', 'Càng tích luỹ kinh nghiệm càng tự tin.', 6),
(4254, 418, 'GRAMMAR', 505, 'Ví dụ 7', '人によっては辛く感じるかもしれない。', 'Tuỳ người, có khi sẽ thấy cay.', 7),
(4255, 418, 'GRAMMAR', 505, 'Ví dụ 8', '場合によっては中止もありうる。', 'Tuỳ trường hợp cũng có thể huỷ.', 8),
(4256, 418, 'GRAMMAR', 506, 'Ví dụ 9', '苦労してこそ、喜びも大きい。', 'Có vất vả thì niềm vui mới lớn.', 9),
(4257, 418, 'GRAMMAR', 506, 'Ví dụ 10', '実行してこそ意味がある。', 'Có thực hiện thì mới có ý nghĩa.', 10),
(4258, 419, 'LISTENING', NULL, 'Linh', 'お忙しいところすみません。テスト開始日のことでご相談が。', 'Xin lỗi đã làm phiền lúc chị bận. Em có việc muốn bàn về ngày bắt đầu kiểm thử ạ.', 1),
(4259, 419, 'LISTENING', NULL, 'Chị Kawai', 'もしかして、遅れそうですか。', 'Chẳng lẽ là sắp bị chậm à?', 2),
(4260, 419, 'LISTENING', NULL, 'Linh', 'はい。仕様変更の影響で、二日ほど後ろにずらしていただけないかと。', 'Vâng ạ. Do ảnh hưởng của việc đổi yêu cầu, em muốn xin lùi khoảng hai ngày.', 3),
(4261, 419, 'LISTENING', NULL, 'Chị Kawai', 'うーん、こちらも後ろの案件が詰まっているんですよね。', 'Ừm, bên tôi cũng đang kín lịch dự án phía sau đấy.', 4),
(4262, 419, 'LISTENING', NULL, 'Linh', 'でしたら、主要機能だけ先に渡すという形はいかがでしょうか。', 'Vậy thì bàn giao trước phần tính năng chính thôi, chị thấy sao ạ?', 5),
(4263, 419, 'LISTENING', NULL, 'Chị Kawai', 'それなら助かります。残りはいつになりますか。', 'Thế thì đỡ cho tôi. Phần còn lại bao giờ?', 6),
(4264, 419, 'LISTENING', NULL, 'Linh', '水曜の夕方までには必ずお渡しします。', 'Chậm nhất chiều thứ tư em nhất định bàn giao ạ.', 7),
(4265, 419, 'LISTENING', NULL, 'Chị Kawai', '分かりました。では、その前提でスケジュールを組み直します。', 'Được rồi. Vậy tôi sắp lại lịch dựa trên tiền đề đó.', 8),
(4266, 420, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4267, 422, 'GRAMMAR', 507, 'Ví dụ 1', '期待していただけに、残念だ。', 'Chính vì đã kỳ vọng nên càng thất vọng.', 1),
(4268, 422, 'GRAMMAR', 507, 'Ví dụ 2', '経験があるだけに、仕事が早い。', 'Vì có kinh nghiệm nên làm việc nhanh.', 2),
(4269, 422, 'GRAMMAR', 508, 'Ví dụ 3', 'ベルが鳴るか鳴らないかのうちに、彼は教室を出た。', 'Chuông còn chưa dứt cậu ta đã ra khỏi lớp.', 3),
(4270, 422, 'GRAMMAR', 508, 'Ví dụ 4', '座るか座らないかのうちに眠ってしまった。', 'Vừa ngồi xuống chưa kịp gì đã ngủ mất.', 4),
(4271, 422, 'GRAMMAR', 509, 'Ví dụ 5', '高いからといって、いいとは限らない。', 'Không phải cứ đắt là tốt.', 5),
(4272, 422, 'GRAMMAR', 509, 'Ví dụ 6', '失敗したからといって、諦める必要はない。', 'Thất bại không có nghĩa là phải bỏ cuộc.', 6),
(4273, 422, 'GRAMMAR', 510, 'Ví dụ 7', '足が痛くて歩けないほどだ。', 'Chân đau đến mức không đi nổi.', 7),
(4274, 422, 'GRAMMAR', 510, 'Ví dụ 8', '信じられないほどの美しさだった。', 'Đó là vẻ đẹp đến mức khó tin.', 8),
(4275, 423, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4276, 425, 'GRAMMAR', 511, 'Ví dụ 1', 'さすが専門家だけあって、説明が分かりやすい。', 'Quả không hổ là chuyên gia, giải thích rất dễ hiểu.', 1),
(4277, 425, 'GRAMMAR', 511, 'Ví dụ 2', '高いだけあって、品質がいい。', 'Đắt có khác, chất lượng tốt thật.', 2),
(4278, 425, 'GRAMMAR', 512, 'Ví dụ 3', '彼は家に着くやいなや、寝てしまった。', 'Anh ta vừa về đến nhà là ngủ luôn.', 3),
(4279, 425, 'GRAMMAR', 512, 'Ví dụ 4', '発表するやいなや、質問が集まった。', 'Vừa công bố xong là câu hỏi dồn tới.', 4),
(4280, 425, 'GRAMMAR', 513, 'Ví dụ 5', '名前からして怪しい店だ。', 'Ngay cái tên đã thấy quán đáng ngờ.', 5),
(4281, 425, 'GRAMMAR', 513, 'Ví dụ 6', 'あの様子からして、うまくいったようだ。', 'Xét dáng vẻ đó thì có vẻ đã suôn sẻ.', 6),
(4282, 425, 'GRAMMAR', 514, 'Ví dụ 7', '彼は日本語ばかりでなく韓国語も話す。', 'Anh ấy không chỉ nói tiếng Nhật mà cả tiếng Hàn.', 7),
(4283, 425, 'GRAMMAR', 514, 'Ví dụ 8', '値段ばかりでなく品質も大切だ。', 'Không chỉ giá mà chất lượng cũng quan trọng.', 8),
(4284, 426, 'LISTENING', NULL, 'Linh', '本日はご足労いただき、ありがとうございます。', 'Hôm nay cảm ơn ngài đã bỏ công đến đây ạ.', 1),
(4285, 426, 'LISTENING', NULL, 'Ông Hayashi', 'こちらこそ、お時間をいただき恐縮です。', 'Tôi mới phải cảm ơn, thật ngại vì đã lấy thời gian của ông.', 2),
(4286, 426, 'LISTENING', NULL, 'Linh', '弊社は創業以来、教育分野に特化してまいりました。', 'Công ty chúng tôi từ khi thành lập đã chuyên sâu vào lĩnh vực giáo dục.', 3),
(4287, 426, 'LISTENING', NULL, 'Ông Hayashi', '従業員数はどのくらいでいらっしゃいますか。', 'Số nhân viên của quý công ty khoảng bao nhiêu ạ?', 4),
(4288, 426, 'LISTENING', NULL, 'Linh', '現在は八十名ほどで、そのうち半数が開発に携わっております。', 'Hiện khoảng tám mươi người, trong đó một nửa làm về phát triển ạ.', 5),
(4289, 426, 'LISTENING', NULL, 'Ông Hayashi', '海外展開についてはいかがですか。', 'Còn về việc mở rộng ra nước ngoài thì sao ạ?', 6),
(4290, 426, 'LISTENING', NULL, 'Linh', 'ベトナムに拠点を設け、共同開発を進めているところです。', 'Chúng tôi đã lập cơ sở tại Việt Nam và đang triển khai phát triển chung ạ.', 7),
(4291, 426, 'LISTENING', NULL, 'Ông Hayashi', 'それは心強いですね。ぜひ一度、現場も拝見したいものです。', 'Thế thì yên tâm nhỉ. Tôi rất muốn được xem tận nơi một lần.', 8),
(4292, 427, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4293, 429, 'GRAMMAR', 515, 'Ví dụ 1', '道が込んでいたものだから、遅れました。', 'Là tại đường tắc nên tôi đến muộn.', 1),
(4294, 429, 'GRAMMAR', 515, 'Ví dụ 2', 'あまりに安かったものだから、つい買ってしまった。', 'Tại nó rẻ quá nên tôi trót mua mất.', 2),
(4295, 429, 'GRAMMAR', 516, 'Ví dụ 3', '戻れるものなら、学生時代に戻りたい。', 'Nếu mà quay lại được, tôi muốn về thời sinh viên.', 3),
(4296, 429, 'GRAMMAR', 516, 'Ví dụ 4', '行けるものなら行きたい。', 'Nếu đi được thì tôi muốn đi.', 4),
(4297, 429, 'GRAMMAR', 517, 'Ví dụ 5', 'あの成績からすると、合格は難しい。', 'Xét thành tích đó thì đỗ là khó.', 5),
(4298, 429, 'GRAMMAR', 517, 'Ví dụ 6', '親からすれば、心配なのは当然だ。', 'Đứng ở góc độ cha mẹ thì lo lắng là đương nhiên.', 6),
(4299, 429, 'GRAMMAR', 518, 'Ví dụ 7', '料理にかけては彼女の右に出る者はいない。', 'Về khoản nấu ăn thì không ai qua được cô ấy.', 7),
(4300, 429, 'GRAMMAR', 518, 'Ví dụ 8', '記憶力にかけては自信がある。', 'Về trí nhớ thì tôi tự tin.', 8),
(4301, 430, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4302, 432, 'GRAMMAR', 519, 'Ví dụ 1', '買ったものの、一度も使っていない。', 'Tuy đã mua nhưng chưa dùng lần nào.', 1),
(4303, 432, 'GRAMMAR', 519, 'Ví dụ 2', '約束したものの、自信がない。', 'Tuy đã hứa nhưng tôi không tự tin.', 2),
(4304, 432, 'GRAMMAR', 520, 'Ví dụ 3', 'さんざん迷ったあげく、何も買わなかった。', 'Phân vân mãi rốt cuộc chẳng mua gì.', 3),
(4305, 432, 'GRAMMAR', 520, 'Ví dụ 4', '口論のあげく、彼は出て行った。', 'Sau một hồi cãi vã, anh ta bỏ đi.', 4),
(4306, 432, 'GRAMMAR', 521, 'Ví dụ 5', '私にとって家族が一番大切だ。', 'Đối với tôi gia đình là quan trọng nhất.', 5),
(4307, 432, 'GRAMMAR', 521, 'Ví dụ 6', '学生にとってこの本は難しい。', 'Với sinh viên thì cuốn sách này khó.', 6),
(4308, 432, 'GRAMMAR', 522, 'Ví dụ 7', '収入に応じて税金が決まる。', 'Thuế được tính tuỳ theo thu nhập.', 7),
(4309, 432, 'GRAMMAR', 522, 'Ví dụ 8', '状況に応じた対応が必要だ。', 'Cần ứng phó phù hợp với tình huống.', 8),
(4310, 433, 'LISTENING', NULL, 'Linh', '来月、一週間ほどお休みをいただきたいのですが。', 'Tháng sau em muốn xin nghỉ khoảng một tuần ạ.', 1),
(4311, 433, 'LISTENING', NULL, 'Trưởng phòng', '長いね。何かあるの。', 'Dài đấy. Có việc gì à?', 2),
(4312, 433, 'LISTENING', NULL, 'Linh', 'はい、家族の用事で帰国することになりまして。', 'Vâng ạ, em phải về nước vì việc gia đình.', 3),
(4313, 433, 'LISTENING', NULL, 'Trưởng phòng', '時期はいつごろ。月末は避けてほしいんだけど。', 'Khoảng thời gian nào? Tôi mong cậu tránh cuối tháng.', 4),
(4314, 433, 'LISTENING', NULL, 'Linh', '十日から十六日を考えております。月末は出社できます。', 'Em đang tính từ ngày mười đến mười sáu. Cuối tháng em vẫn đi làm được ạ.', 5),
(4315, 433, 'LISTENING', NULL, 'Trưởng phòng', 'その間の対応はどうする。', 'Trong khoảng đó thì xử lý công việc thế nào?', 6),
(4316, 433, 'LISTENING', NULL, 'Linh', '緊急時は連絡が取れるようにし、定例対応は健太くんに引き継ぎます。', 'Khi khẩn cấp em vẫn liên lạc được, còn việc định kỳ em bàn giao cho Kenta ạ.', 7),
(4317, 433, 'LISTENING', NULL, 'Trưởng phòng', '分かった。じゃあ、引き継ぎ表を来週までに出して。', 'Được. Vậy nộp bảng bàn giao trước tuần sau nhé.', 8),
(4318, 434, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4319, 436, 'GRAMMAR', 523, 'Ví dụ 1', '上手になりたければ、毎日練習することだ。', 'Muốn giỏi thì phải luyện tập mỗi ngày.', 1),
(4320, 436, 'GRAMMAR', 523, 'Ví dụ 2', '無理をしないことだ。', 'Đừng gắng sức quá.', 2),
(4321, 436, 'GRAMMAR', 524, 'Ví dụ 3', 'よく考えた末に、留学を決めた。', 'Sau khi suy nghĩ kỹ, tôi quyết định du học.', 3),
(4322, 436, 'GRAMMAR', 524, 'Ví dụ 4', '長い議論の末に結論が出た。', 'Sau cuộc tranh luận dài đã có kết luận.', 4),
(4323, 436, 'GRAMMAR', 525, 'Ví dụ 5', '驚きのあまり、声も出なかった。', 'Vì quá kinh ngạc mà không thốt nên lời.', 5),
(4324, 436, 'GRAMMAR', 525, 'Ví dụ 6', '心配するあまり、眠れなかった。', 'Lo quá đến mức không ngủ được.', 6),
(4325, 436, 'GRAMMAR', 526, 'Ví dụ 7', '皆様のご期待にこたえて、新商品を発売します。', 'Đáp lại kỳ vọng của quý vị, chúng tôi ra mắt sản phẩm mới.', 7),
(4326, 436, 'GRAMMAR', 526, 'Ví dụ 8', '要望にこたえて営業時間を延長した。', 'Đáp lại yêu cầu, chúng tôi kéo dài giờ mở cửa.', 8),
(4327, 437, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4328, 439, 'GRAMMAR', 527, 'Ví dụ 1', 'そんなに心配することはないよ。', 'Cậu không cần lo đến thế đâu.', 1),
(4329, 439, 'GRAMMAR', 527, 'Ví dụ 2', 'わざわざ来ることはありません。', 'Anh không cần phải mất công đến.', 2),
(4330, 439, 'GRAMMAR', 528, 'Ví dụ 3', '体が丈夫なかぎり、働き続けたい。', 'Chừng nào còn khoẻ tôi vẫn muốn làm việc.', 3),
(4331, 439, 'GRAMMAR', 528, 'Ví dụ 4', '謝らないかぎり、許さない。', 'Chừng nào chưa xin lỗi thì tôi không tha.', 4),
(4332, 439, 'GRAMMAR', 529, 'Ví dụ 5', '二度と嘘はつくまいと決めた。', 'Tôi quyết không nói dối lần nữa.', 5),
(4333, 439, 'GRAMMAR', 529, 'Ví dụ 6', '彼はもう来るまい。', 'Chắc anh ta không đến nữa đâu.', 6),
(4334, 439, 'GRAMMAR', 530, 'Ví dụ 7', '留学をきっかけに、考え方が変わった。', 'Từ chuyến du học, cách nghĩ của tôi thay đổi.', 7),
(4335, 439, 'GRAMMAR', 530, 'Ví dụ 8', '病気をきっかけに酒をやめた。', 'Nhân trận ốm tôi bỏ rượu.', 8),
(4336, 440, 'LISTENING', NULL, 'Linh', 'お世話になっております。打ち合わせの日程でご連絡いたしました。', 'Kính chào chị. Tôi gọi để liên hệ về lịch cuộc họp ạ.', 1),
(4337, 440, 'LISTENING', NULL, 'Chị Ueda', 'はい、来週水曜でしたよね。', 'Vâng, là thứ tư tuần sau nhỉ.', 2),
(4338, 440, 'LISTENING', NULL, 'Linh', '大変申し訳ないのですが、別件と重なってしまいまして。', 'Thật sự rất xin lỗi, nhưng bị trùng với một việc khác ạ.', 3),
(4339, 440, 'LISTENING', NULL, 'Chị Ueda', 'そうですか。では、別の日を探しましょうか。', 'Vậy à. Thế mình tìm ngày khác nhé?', 4),
(4340, 440, 'LISTENING', NULL, 'Linh', 'ご迷惑をおかけします。木曜か金曜でご都合はいかがでしょうか。', 'Xin lỗi đã làm phiền chị. Thứ năm hoặc thứ sáu chị có tiện không ạ?', 5),
(4341, 440, 'LISTENING', NULL, 'Chị Ueda', '金曜の午後なら空いています。二時からでよろしいですか。', 'Chiều thứ sáu thì tôi trống. Từ hai giờ được không?', 6),
(4342, 440, 'LISTENING', NULL, 'Linh', 'はい、大丈夫です。改めて招待状をお送りいたします。', 'Vâng, được ạ. Tôi sẽ gửi lại thư mời ạ.', 7),
(4343, 440, 'LISTENING', NULL, 'Chị Ueda', '承知しました。よろしくお願いします。', 'Tôi rõ rồi. Nhờ anh nhé.', 8),
(4344, 441, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4345, 443, 'GRAMMAR', 531, 'Ví dụ 1', '窓が割れていることから、泥棒が入ったと分かった。', 'Từ việc cửa sổ bị vỡ mà biết có trộm vào.', 1),
(4346, 443, 'GRAMMAR', 531, 'Ví dụ 2', '桜が多いことから、桜町と名付けられた。', 'Vì có nhiều hoa anh đào nên được đặt tên là Sakuramachi.', 2),
(4347, 443, 'GRAMMAR', 532, 'Ví dụ 3', '私が知るかぎりでは、彼は正直な人だ。', 'Theo như tôi biết thì anh ấy là người thật thà.', 3),
(4348, 443, 'GRAMMAR', 532, 'Ví dụ 4', '調べたかぎりでは問題はなかった。', 'Theo như tôi kiểm tra thì không có vấn đề.', 4),
(4349, 443, 'GRAMMAR', 533, 'Ví dụ 5', '連絡先が分からないので、知らせようがない。', 'Không biết địa chỉ liên lạc nên chẳng có cách nào báo.', 5),
(4350, 443, 'GRAMMAR', 533, 'Ví dụ 6', '壊れすぎて直しようがない。', 'Hỏng quá không còn cách nào sửa.', 6),
(4351, 443, 'GRAMMAR', 534, 'Ví dụ 7', 'この事故を契機に、安全基準が見直された。', 'Lấy vụ tai nạn này làm bước ngoặt, tiêu chuẩn an toàn được rà soát.', 7),
(4352, 443, 'GRAMMAR', 534, 'Ví dụ 8', '創立百周年を契機に改革を進める。', 'Nhân dịp một trăm năm thành lập, tiến hành cải cách.', 8),
(4353, 444, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4354, 446, 'GRAMMAR', 535, 'Ví dụ 1', '驚いたことに、彼は全部知っていた。', 'Thật bất ngờ, anh ta biết hết mọi chuyện.', 1),
(4355, 446, 'GRAMMAR', 535, 'Ví dụ 2', '残念なことに、試合は中止になった。', 'Thật đáng tiếc, trận đấu bị huỷ.', 2),
(4356, 446, 'GRAMMAR', 536, 'Ví dụ 3', '急いでいる時に限って、電車が遅れる。', 'Cứ đúng lúc vội là tàu lại trễ.', 3),
(4357, 446, 'GRAMMAR', 536, 'Ví dụ 4', 'うちの子に限って嘘はつかない。', 'Riêng con tôi thì không nói dối.', 4),
(4358, 446, 'GRAMMAR', 537, 'Ví dụ 5', 'この話を聞くと、笑わずにはいられない。', 'Nghe chuyện này thì không nhịn cười được.', 5),
(4359, 446, 'GRAMMAR', 537, 'Ví dụ 6', '心配せずにはいられない。', 'Tôi không thể không lo.', 6),
(4360, 446, 'GRAMMAR', 538, 'Ví dụ 7', '表面上は問題ないように見える。', 'Về mặt bề ngoài thì trông không có vấn đề.', 7),
(4361, 446, 'GRAMMAR', 538, 'Ví dụ 8', '規則上は許可が必要だ。', 'Về mặt quy định thì cần xin phép.', 8),
(4362, 447, 'LISTENING', NULL, 'Nam', '今回の案件、まずはよかった点から挙げていきましょう。', 'Dự án lần này, trước hết mình nêu những điểm tốt đi.', 1),
(4363, 447, 'LISTENING', NULL, 'Linh', '毎朝の短い共有が効いたと思います。問題が早く見つかりました。', 'Tôi nghĩ việc chia sẻ ngắn mỗi sáng có hiệu quả. Vấn đề được phát hiện sớm.', 2),
(4364, 447, 'LISTENING', NULL, 'Yuki', '私も同感です。一方で、資料の版管理は混乱しました。', 'Tôi cũng đồng ý. Mặt khác, việc quản lý phiên bản tài liệu thì rối.', 3),
(4365, 447, 'LISTENING', NULL, 'Nam', '具体的にはどのあたりが。', 'Cụ thể là chỗ nào?', 4),
(4366, 447, 'LISTENING', NULL, 'Yuki', '同じ名前のファイルが三つあって、どれが最新か分かりませんでした。', 'Có ba tệp cùng tên nên không biết cái nào mới nhất.', 5),
(4367, 447, 'LISTENING', NULL, 'Linh', '次回からは日付を入れる決まりにしてはどうでしょうか。', 'Từ lần sau đặt quy định thêm ngày tháng vào thì thế nào ạ?', 6),
(4368, 447, 'LISTENING', NULL, 'Nam', 'いいですね。では、それをルールとして文書に残しましょう。', 'Hay đấy. Vậy mình ghi điều đó thành quy tắc vào văn bản nhé.', 7),
(4369, 447, 'LISTENING', NULL, 'Yuki', '私がまとめて、明日までに共有します。', 'Tôi sẽ tổng hợp và chia sẻ trước ngày mai.', 8),
(4370, 448, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4371, 450, 'GRAMMAR', 539, 'Ví dụ 1', '漢字どころか、ひらがなも読めない。', 'Đừng nói chữ Hán, đến hiragana cũng không đọc được.', 1),
(4372, 450, 'GRAMMAR', 539, 'Ví dụ 2', '楽になるどころか、忙しくなった。', 'Chẳng những không nhàn đi mà còn bận hơn.', 2),
(4373, 450, 'GRAMMAR', 540, 'Ví dụ 3', '日本に限らず、世界中で問題になっている。', 'Không chỉ riêng Nhật, cả thế giới đều thành vấn đề.', 3),
(4374, 450, 'GRAMMAR', 540, 'Ví dụ 4', '週末に限らず平日も混む。', 'Không chỉ cuối tuần, ngày thường cũng đông.', 4),
(4375, 450, 'GRAMMAR', 541, 'Ví dụ 5', '暑くてたまらない。', 'Nóng không chịu nổi.', 5),
(4376, 450, 'GRAMMAR', 541, 'Ví dụ 6', '国へ帰りたくてたまらない。', 'Tôi thèm về nước đến phát điên.', 6),
(4377, 450, 'GRAMMAR', 542, 'Ví dụ 7', '今日着くはずだったのに、まだ届かない。', 'Lẽ ra hôm nay phải tới mà vẫn chưa thấy.', 7),
(4378, 450, 'GRAMMAR', 542, 'Ví dụ 8', '彼も来るはずだった。', 'Lẽ ra anh ấy cũng phải đến.', 8),
(4379, 451, 'READING', NULL, 'Danh sách từ vựng', '68 từ.', NULL, 1),
(4380, 453, 'GRAMMAR', 543, 'Ví dụ 1', '忙しくて、旅行どころではない。', 'Bận quá, không phải lúc đi du lịch.', 1),
(4381, 453, 'GRAMMAR', 543, 'Ví dụ 2', '試験前で、遊んでいるどころではない。', 'Sắp thi rồi, không phải lúc chơi bời.', 2),
(4382, 453, 'GRAMMAR', 544, 'Ví dụ 3', '彼は学者のみならず、実業家でもある。', 'Ông ấy không những là học giả mà còn là doanh nhân.', 3),
(4383, 453, 'GRAMMAR', 544, 'Ví dụ 4', '本人のみならず家族も苦しんだ。', 'Không chỉ bản thân mà cả gia đình cũng khổ.', 4),
(4384, 453, 'GRAMMAR', 545, 'Ví dụ 5', '残念でならない。', 'Tôi tiếc không sao nguôi được.', 5),
(4385, 453, 'GRAMMAR', 545, 'Ví dụ 6', '何かおかしい気がしてならない。', 'Tôi cứ có cảm giác có gì đó không ổn.', 6),
(4386, 453, 'GRAMMAR', 546, 'Ví dụ 7', '早く帰るつもりだったが、残業になった。', 'Tôi đã định về sớm nhưng phải tăng ca.', 7),
(4387, 453, 'GRAMMAR', 546, 'Ví dụ 8', '怒らせるつもりはなかった。', 'Tôi không hề có ý làm anh giận.', 8),
(4388, 454, 'LISTENING', NULL, 'Linh', '今日から三か月間、よろしくお願いします。', 'Ba tháng từ hôm nay, mong em cố gắng nhé.', 1),
(4389, 454, 'LISTENING', NULL, 'Thực tập sinh', 'こちらこそ、ご指導よろしくお願いいたします。', 'Em mới phải, mong anh chỉ bảo ạ.', 2),
(4390, 454, 'LISTENING', NULL, 'Linh', 'まずは勤怠の入力方法から説明しますね。', 'Trước hết anh giải thích cách nhập chấm công nhé.', 3),
(4391, 454, 'LISTENING', NULL, 'Thực tập sinh', 'はい。遅刻しそうなときはどうすればよろしいですか。', 'Vâng ạ. Lúc có vẻ sẽ đến muộn thì em nên làm gì ạ?', 4),
(4392, 454, 'LISTENING', NULL, 'Linh', '始業前に必ず電話を入れてください。連絡がないのが一番困ります。', 'Trước giờ làm nhất định phải gọi điện. Không liên lạc mới là điều phiền nhất.', 5),
(4393, 454, 'LISTENING', NULL, 'Thực tập sinh', '承知しました。分からないことが多いと思うのですが。', 'Em rõ rồi ạ. Em nghĩ sẽ có nhiều điều em không biết ạ.', 6),
(4394, 454, 'LISTENING', NULL, 'Linh', '遠慮なく聞いてください。自分で悩む時間がもったいないので。', 'Cứ hỏi thoải mái. Vì thời gian ngồi tự loay hoay thì phí lắm.', 7),
(4395, 454, 'LISTENING', NULL, 'Thực tập sinh', 'ありがとうございます。頑張ります。', 'Em cảm ơn ạ. Em sẽ cố gắng.', 8),
(4396, 455, 'READING', NULL, 'Danh sách từ vựng', '67 từ.', NULL, 1),
(4397, 457, 'GRAMMAR', 547, 'Ví dụ 1', '彼は英語ばかりか、フランス語も話せる。', 'Anh ấy không những nói tiếng Anh mà cả tiếng Pháp.', 1),
(4398, 457, 'GRAMMAR', 547, 'Ví dụ 2', '失敗したばかりか、信用まで失った。', 'Không những thất bại mà còn mất cả uy tín.', 2),
(4399, 457, 'GRAMMAR', 548, 'Ví dụ 3', '子供はもとより大人も楽しめる。', 'Trẻ con đã đành, người lớn cũng thấy vui.', 3),
(4400, 457, 'GRAMMAR', 548, 'Ví dụ 4', '平日はもとより休日も営業しています。', 'Ngày thường khỏi nói, ngày nghỉ cũng mở cửa.', 4),
(4401, 457, 'GRAMMAR', 549, 'Ví dụ 5', '眠くてしかたがない。', 'Buồn ngủ hết chịu nổi.', 5),
(4402, 457, 'GRAMMAR', 549, 'Ví dụ 6', '結果が気になってしかたがない。', 'Tôi sốt ruột về kết quả quá đỗi.', 6),
(4403, 457, 'GRAMMAR', 550, 'Ví dụ 7', '死んだつもりで頑張ります。', 'Tôi sẽ cố như thể sống lại lần nữa.', 7),
(4404, 457, 'GRAMMAR', 550, 'Ví dụ 8', '旅行のつもりで貯金した。', 'Tôi để dành tiền coi như để đi du lịch.', 8),
(4405, 458, 'READING', NULL, 'Danh sách từ vựng', '67 từ.', NULL, 1),
(4406, 460, 'GRAMMAR', 551, 'Ví dụ 1', '一言言わなかったばかりに、誤解された。', 'Chỉ vì không nói một câu mà bị hiểu lầm.', 1),
(4407, 460, 'GRAMMAR', 551, 'Ví dụ 2', 'お金がないばかりに、進学できなかった。', 'Chỉ vì không có tiền mà không học lên được.', 2),
(4408, 460, 'GRAMMAR', 552, 'Ví dụ 3', '味はともかく、量は多い。', 'Khoan nói về vị, lượng thì nhiều.', 3),
(4409, 460, 'GRAMMAR', 552, 'Ví dụ 4', '結果はともかく、よく頑張った。', 'Kết quả tạm gác lại, em đã rất cố gắng.', 4),
(4410, 460, 'GRAMMAR', 553, 'Ví dụ 5', '電車が止まったので、歩くよりほかない。', 'Tàu dừng nên chỉ còn cách đi bộ.', 5),
(4411, 460, 'GRAMMAR', 553, 'Ví dụ 6', '諦めるほかなかった。', 'Tôi chỉ còn cách từ bỏ.', 6),
(4412, 460, 'GRAMMAR', 554, 'Ví dụ 7', 'そんな計画では話にもならない。', 'Kế hoạch như thế thì chẳng ra gì.', 7),
(4413, 460, 'GRAMMAR', 554, 'Ví dụ 8', '苦労したのに一円にもならなかった。', 'Vất vả vậy mà chẳng được đồng nào.', 8),
(4414, 461, 'LISTENING', NULL, 'Trưởng phòng', '今期の評価だけど、全体としてはよくやってくれたと思う。', 'Đánh giá kỳ này ấy, nhìn chung tôi thấy cậu làm tốt.', 1),
(4415, 461, 'LISTENING', NULL, 'Linh', 'ありがとうございます。課題も感じております。', 'Em cảm ơn anh ạ. Em cũng thấy có điểm cần khắc phục ạ.', 2),
(4416, 461, 'LISTENING', NULL, 'Trưởng phòng', 'どんな点。', 'Điểm nào?', 3),
(4417, 461, 'LISTENING', NULL, 'Linh', '一人で抱え込む傾向があり、周りを巻き込むのが遅れました。', 'Em có xu hướng ôm việc một mình, nên lôi kéo mọi người vào bị chậm ạ.', 4),
(4418, 461, 'LISTENING', NULL, 'Trưởng phòng', '自覚があるなら心配ない。来期は何を目標にする。', 'Tự nhận ra được thì không lo. Kỳ sau cậu đặt mục tiêu gì?', 5),
(4419, 461, 'LISTENING', NULL, 'Linh', '後輩の育成に関わりたいと考えております。', 'Em muốn tham gia vào việc đào tạo đàn em ạ.', 6),
(4420, 461, 'LISTENING', NULL, 'Trưởng phòng', 'いいね。では、次の新人研修を任せてみようか。', 'Hay đấy. Vậy giao cho cậu khoá đào tạo nhân viên mới tới nhé?', 7),
(4421, 461, 'LISTENING', NULL, 'Linh', 'ぜひやらせてください。準備を進めます。', 'Xin anh cứ để em làm ạ. Em sẽ chuẩn bị.', 8),
(4422, 462, 'READING', NULL, 'Danh sách từ vựng', '67 từ.', NULL, 1),
(4423, 464, 'GRAMMAR', 555, 'Ví dụ 1', '大事な会議だから、休むわけにはいかない。', 'Họp quan trọng nên tôi không thể nghỉ.', 1),
(4424, 464, 'GRAMMAR', 555, 'Ví dụ 2', '約束したから、行かないわけにはいかない。', 'Đã hứa rồi nên không thể không đi.', 2),
(4425, 464, 'GRAMMAR', 556, 'Ví dụ 3', 'これは言い訳にすぎない。', 'Đây chẳng qua chỉ là lời biện hộ.', 3),
(4426, 464, 'GRAMMAR', 556, 'Ví dụ 4', '私はただの学生にすぎません。', 'Tôi chỉ là một sinh viên bình thường thôi.', 4),
(4427, 464, 'GRAMMAR', 557, 'Ví dụ 5', '上司の命令なので、従わざるを得ない。', 'Lệnh của cấp trên nên buộc phải tuân theo.', 5),
(4428, 464, 'GRAMMAR', 557, 'Ví dụ 6', '事実だと認めざるを得ない。', 'Buộc phải thừa nhận đó là sự thật.', 6),
(4429, 464, 'GRAMMAR', 558, 'Ví dụ 7', 'うれしいやら悲しいやら、複雑な気持ちだ。', 'Vừa vui vừa buồn, cảm xúc thật phức tạp.', 7),
(4430, 464, 'GRAMMAR', 558, 'Ví dụ 8', '書類やら荷物やらで机がいっぱいだ。', 'Bàn đầy nào giấy tờ nào đồ đạc.', 8),
(4431, 465, 'READING', NULL, 'Danh sách từ vựng', '70 từ.', NULL, 1),
(4432, 467, 'GRAMMAR', 559, 'Ví dụ 1', 'この仕事を任せられるのは、彼をおいてほかにいない。', 'Giao việc này thì ngoài anh ấy ra không còn ai.', 1),
(4433, 467, 'GRAMMAR', 559, 'Ví dụ 2', '彼女をおいて適任者はいない。', 'Ngoài cô ấy ra không có người nào phù hợp.', 2),
(4434, 467, 'GRAMMAR', 560, 'Ví dụ 3', '前回の反省を踏まえて計画を練り直した。', 'Dựa trên rút kinh nghiệm lần trước, chúng tôi làm lại kế hoạch.', 3),
(4435, 467, 'GRAMMAR', 560, 'Ví dụ 4', '調査結果を踏まえた提案です。', 'Đây là đề xuất dựa trên kết quả khảo sát.', 4),
(4436, 467, 'GRAMMAR', 561, 'Ví dụ 5', '柄にもなく緊張してしまった。', 'Chẳng giống tôi chút nào, tôi lại hồi hộp.', 5),
(4437, 467, 'GRAMMAR', 561, 'Ví dụ 6', '彼らしくもない発言だ。', 'Đó là phát ngôn chẳng giống anh ấy.', 6),
(4438, 468, 'LISTENING', NULL, 'Ông Kimura', '納期につきましては、当初のご提案から二週間の前倒しをお願いしたく存じます。', 'Về thời hạn giao hàng, chúng tôi mong được đẩy lên sớm hai tuần so với đề xuất ban đầu.', 1),
(4439, 468, 'LISTENING', NULL, 'Linh', 'ご要望は承知いたしました。ただ、品質を担保する上では容易ではございません。', 'Tôi đã nắm được yêu cầu. Chỉ có điều, để đảm bảo chất lượng thì không dễ ạ.', 2),
(4440, 468, 'LISTENING', NULL, 'Ông Kimura', 'とはいえ、市場投入の時期を逃すわけにはまいりません。', 'Tuy vậy, chúng tôi không thể để lỡ thời điểm tung ra thị trường.', 3),
(4441, 468, 'LISTENING', NULL, 'Linh', 'でしたら、機能を二段階に分けて納品する案はいかがでしょうか。', 'Vậy thì phương án chia tính năng thành hai giai đoạn để bàn giao thì sao ạ?', 4),
(4442, 468, 'LISTENING', NULL, 'Ông Kimura', 'なるほど。第一段階に必須機能が含まれるのであれば、検討の余地はあります。', 'Ra vậy. Nếu giai đoạn một bao gồm các tính năng thiết yếu thì còn chỗ để cân nhắc.', 5),
(4443, 468, 'LISTENING', NULL, 'Linh', 'では、対象範囲を整理した資料を明日までにご提出いたします。', 'Vậy tôi xin nộp tài liệu sắp xếp phạm vi đối tượng trước ngày mai ạ.', 6),
(4444, 468, 'LISTENING', NULL, 'Ông Kimura', '遅延した場合の取り扱いについても、併せてご提示願えますか。', 'Xin trình bày luôn cả cách xử lý trong trường hợp chậm trễ được không?', 7),
(4445, 468, 'LISTENING', NULL, 'Linh', '承知いたしました。双方にとって無理のない条件をご提案申し上げます。', 'Tôi đã rõ ạ. Tôi sẽ đề xuất điều kiện hợp lý cho cả hai bên.', 8),
(4446, 469, 'READING', NULL, 'Danh sách từ vựng', '70 từ.', NULL, 1),
(4447, 471, 'GRAMMAR', 562, 'Ví dụ 1', '親の心配をよそに、彼は一人で旅に出た。', 'Mặc kệ nỗi lo của cha mẹ, cậu ấy một mình lên đường.', 1),
(4448, 471, 'GRAMMAR', 562, 'Ví dụ 2', '住民の反対をよそに工事が始まった。', 'Bất chấp phản đối của dân cư, công trình vẫn khởi công.', 2),
(4449, 471, 'GRAMMAR', 563, 'Ví dụ 3', '実情に即した対策が必要だ。', 'Cần biện pháp bám sát thực tế.', 3),
(4450, 471, 'GRAMMAR', 563, 'Ví dụ 4', '法律に即して処理します。', 'Xử lý theo đúng luật.', 4),
(4451, 471, 'GRAMMAR', 564, 'Ví dụ 5', '私とて同じ気持ちだ。', 'Ngay cả tôi cũng cùng tâm trạng ấy.', 5),
(4452, 471, 'GRAMMAR', 564, 'Ví dụ 6', '子供とて例外ではない。', 'Dù là trẻ con cũng không ngoại lệ.', 6),
(4453, 472, 'READING', NULL, 'Danh sách từ vựng', '70 từ.', NULL, 1),
(4454, 474, 'GRAMMAR', 565, 'Ví dụ 1', 'けがをものともせず、最後まで走り切った。', 'Bất chấp chấn thương, anh đã chạy đến đích.', 1),
(4455, 474, 'GRAMMAR', 565, 'Ví dụ 2', '嵐をものともせず船は進んだ。', 'Con tàu tiến lên bất chấp bão tố.', 2),
(4456, 474, 'GRAMMAR', 566, 'Ví dụ 3', '規定に照らして判断する。', 'Phán xét khi đối chiếu với quy định.', 3),
(4457, 474, 'GRAMMAR', 566, 'Ví dụ 4', '過去の例に照らせば妥当だ。', 'Đối chiếu tiền lệ thì là hợp lý.', 4),
(4458, 474, 'GRAMMAR', 567, 'Ví dụ 5', '眼鏡なしでは何も見えない。', 'Không có kính thì tôi chẳng nhìn thấy gì.', 5),
(4459, 474, 'GRAMMAR', 567, 'Ví dụ 6', '彼なしではこの仕事は無理だ。', 'Thiếu anh ấy thì việc này không xong.', 6),
(4460, 475, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4461, 477, 'GRAMMAR', 568, 'Ví dụ 1', '台風で試合は中止を余儀なくされた。', 'Vì bão, trận đấu buộc phải huỷ.', 1),
(4462, 477, 'GRAMMAR', 568, 'Ví dụ 2', '病気で退学を余儀なくされた。', 'Vì bệnh mà đành phải thôi học.', 2),
(4463, 477, 'GRAMMAR', 569, 'Ví dụ 3', '今日を限りにたばこをやめる。', 'Kể từ hôm nay tôi bỏ thuốc.', 3),
(4464, 477, 'GRAMMAR', 569, 'Ví dụ 4', '今季を限りに引退します。', 'Tôi giải nghệ sau mùa giải này.', 4),
(4465, 477, 'GRAMMAR', 570, 'Ví dụ 5', 'いくら貯金しても、病気になればそれまでだ。', 'Để dành bao nhiêu mà ốm một cái là hết.', 5),
(4466, 477, 'GRAMMAR', 570, 'Ví dụ 6', '断られればそれまでだ。', 'Bị từ chối thì coi như xong.', 6),
(4467, 478, 'LISTENING', NULL, 'Anh Sato', '率直に申し上げて、この事業からは撤退すべきかと存じます。', 'Nói thẳng ra, tôi cho rằng nên rút khỏi dự án này ạ.', 1),
(4468, 478, 'LISTENING', NULL, 'Anh Sato', '赤字が三期連続で続いており、回復の見込みは薄いと言わざるを得ません。', 'Thua lỗ đã ba kỳ liên tiếp, phải nói là khả năng phục hồi rất mong manh.', 2),
(4469, 478, 'LISTENING', NULL, 'Chị Mori', 'おっしゃることはもっともですが、市場自体は拡大しつつあります。', 'Điều anh nói là có lý, nhưng bản thân thị trường đang dần mở rộng.', 3),
(4470, 478, 'LISTENING', NULL, 'Chị Mori', 'ここで手を引けば、これまでの投資が無駄になりかねません。', 'Nếu rút tay lúc này, khoản đầu tư từ trước có thể thành công cốc.', 4),
(4471, 478, 'LISTENING', NULL, 'Anh Sato', 'しかし、過去の投資に引きずられて判断を誤るのは避けるべきです。', 'Nhưng bị khoản đầu tư quá khứ kéo theo rồi phán đoán sai thì nên tránh.', 5),
(4472, 478, 'LISTENING', NULL, 'Giám đốc', '双方の意見はよく分かった。', 'Ý kiến hai bên tôi đã rõ.', 6),
(4473, 478, 'LISTENING', NULL, 'Giám đốc', 'ただ、感情論ではなく、数字をもって判断したい。', 'Chỉ có điều, tôi muốn phán đoán bằng con số chứ không phải cảm tính.', 7),
(4474, 478, 'LISTENING', NULL, 'Giám đốc', '来週までに、撤退と継続それぞれの試算を出してくれ。', 'Trước tuần sau, đưa tôi bảng tính thử cho cả phương án rút và phương án tiếp tục.', 8),
(4475, 479, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4476, 481, 'GRAMMAR', 571, 'Ví dụ 1', 'その話を聞いて涙を禁じ得なかった。', 'Nghe chuyện đó tôi không kìm được nước mắt.', 1),
(4477, 481, 'GRAMMAR', 571, 'Ví dụ 2', '彼の態度には怒りを禁じ得ない。', 'Trước thái độ của anh ta tôi không nén nổi giận.', 2),
(4478, 481, 'GRAMMAR', 572, 'Ví dụ 3', '社長をはじめ、全社員が参加した。', 'Đứng đầu là giám đốc, toàn thể nhân viên đều tham gia.', 3),
(4479, 481, 'GRAMMAR', 572, 'Ví dụ 4', '日本をはじめとするアジア諸国。', 'Các nước châu Á mà tiêu biểu là Nhật Bản.', 4),
(4480, 481, 'GRAMMAR', 573, 'Ví dụ 5', '被害は国内にとどまらず、海外にも及んだ。', 'Thiệt hại không dừng ở trong nước mà lan cả ra nước ngoài.', 5),
(4481, 481, 'GRAMMAR', 573, 'Ví dụ 6', '問題は一社にとどまらない。', 'Vấn đề không chỉ dừng ở một công ty.', 6),
(4482, 482, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4483, 484, 'GRAMMAR', 574, 'Ví dụ 1', 'この不況にあって、売上を伸ばすのは難しい。', 'Trong thời suy thoái này, tăng doanh thu là khó.', 1),
(4484, 484, 'GRAMMAR', 574, 'Ví dụ 2', '非常時にあっても冷静さを失わない。', 'Ngay trong tình huống khẩn cấp vẫn không mất bình tĩnh.', 2),
(4485, 484, 'GRAMMAR', 575, 'Ví dụ 3', '子供は子供なりに考えている。', 'Trẻ con cũng suy nghĩ theo cách của chúng.', 3),
(4486, 484, 'GRAMMAR', 575, 'Ví dụ 4', '私なりに努力したつもりです。', 'Tôi đã cố gắng theo cách của mình.', 4),
(4487, 484, 'GRAMMAR', 576, 'Ví dụ 5', '三年の準備期間を経て開店した。', 'Sau ba năm chuẩn bị, cửa hàng đã khai trương.', 5),
(4488, 484, 'GRAMMAR', 576, 'Ví dụ 6', '面接を経て採用が決まる。', 'Qua phỏng vấn rồi mới quyết định tuyển.', 6),
(4489, 485, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4490, 487, 'GRAMMAR', 577, 'Ví dụ 1', '交渉は決裂するに至った。', 'Đàm phán đã đi đến chỗ đổ vỡ.', 1),
(4491, 487, 'GRAMMAR', 577, 'Ví dụ 2', '服装から髪型に至るまで規則がある。', 'Có quy định từ trang phục cho đến tận kiểu tóc.', 2),
(4492, 487, 'GRAMMAR', 578, 'Ví dụ 3', '駅の前を行きつ戻りつしていた。', 'Anh ta cứ đi tới đi lui trước ga.', 3),
(4493, 487, 'GRAMMAR', 578, 'Ví dụ 4', '持ちつ持たれつの関係だ。', 'Đó là quan hệ nương tựa lẫn nhau.', 4),
(4494, 487, 'GRAMMAR', 579, 'Ví dụ 5', 'それにつけても彼のことが思い出される。', 'Cứ nghĩ đến chuyện đó là tôi lại nhớ anh ấy.', 5),
(4495, 487, 'GRAMMAR', 579, 'Ví dụ 6', '何を見るにつけても故郷を思う。', 'Nhìn thứ gì tôi cũng nhớ quê.', 6),
(4496, 488, 'LISTENING', NULL, 'Linh', 'このたびは多大なご迷惑をおかけし、深くお詫び申し上げます。', 'Lần này chúng tôi đã gây phiền phức lớn, xin thành thật tạ lỗi.', 1),
(4497, 488, 'LISTENING', NULL, 'Ông Ota', '原因の究明は済んでいるのでしょうか。', 'Việc truy tìm nguyên nhân đã xong chưa?', 2),
(4498, 488, 'LISTENING', NULL, 'Linh', 'はい。設定変更の手順に不備があったことが判明いたしました。', 'Vâng ạ. Chúng tôi đã xác định được là quy trình thay đổi cấu hình có sơ hở.', 3),
(4499, 488, 'LISTENING', NULL, 'Ông Ota', '再発防止策についてはいかがですか。', 'Còn biện pháp ngăn tái diễn thì thế nào?', 4),
(4500, 488, 'LISTENING', NULL, 'Linh', '作業前の二重確認を義務化し、記録を残す運用に改めます。', 'Chúng tôi sẽ bắt buộc kiểm tra kép trước khi thao tác và chuyển sang vận hành có lưu nhật ký.', 5);
INSERT INTO content_item (id, section_id, content_type, grammar_point_id, title, content, translated_text, order_index) VALUES
(4501, 488, 'LISTENING', NULL, 'Ông Ota', '形だけの対策では困ります。実効性をどう担保されますか。', 'Biện pháp chỉ có hình thức thì không được. Ông đảm bảo tính hiệu lực bằng cách nào?', 6),
(4502, 488, 'LISTENING', NULL, 'Linh', '月次で監査を実施し、結果を御社にもご報告いたします。', 'Chúng tôi sẽ kiểm toán hằng tháng và báo cáo kết quả cho quý công ty.', 7),
(4503, 488, 'LISTENING', NULL, 'Ông Ota', '分かりました。次回同様のことがあれば、契約を見直さざるを得ません。', 'Tôi đã rõ. Nếu lần sau còn xảy ra chuyện tương tự, chúng tôi buộc phải xem lại hợp đồng.', 8),
(4504, 489, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4505, 491, 'GRAMMAR', 580, 'Ví dụ 1', '彼の苦労は想像に難くない。', 'Không khó để hình dung nỗi vất vả của anh ấy.', 1),
(4506, 491, 'GRAMMAR', 580, 'Ví dụ 2', '落胆したことは察するに難くない。', 'Không khó đoán là anh ấy đã thất vọng.', 2),
(4507, 491, 'GRAMMAR', 581, 'Ví dụ 3', '原因は配線の不具合によるものと思われる。', 'Nguyên nhân được cho là do lỗi đường dây.', 3),
(4508, 491, 'GRAMMAR', 581, 'Ví dụ 4', '影響は限定的なものとみられる。', 'Ảnh hưởng được cho là hạn chế.', 4),
(4509, 491, 'GRAMMAR', 582, 'Ví dụ 5', '費用は甲が負担するものとする。', 'Chi phí được quy định do bên A chịu.', 5),
(4510, 491, 'GRAMMAR', 582, 'Ví dụ 6', '本契約は一年間有効とする。', 'Hợp đồng này được quy định có hiệu lực một năm.', 6),
(4511, 492, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4512, 494, 'GRAMMAR', 583, 'Ví dụ 1', 'その光景は見るに堪えなかった。', 'Cảnh tượng đó tôi không nỡ nhìn.', 1),
(4513, 494, 'GRAMMAR', 583, 'Ví dụ 2', 'ご支援に感謝の念に堪えません。', 'Tôi vô cùng biết ơn sự giúp đỡ của ngài.', 2),
(4514, 494, 'GRAMMAR', 584, 'Ví dụ 3', '簡単だと思いきや、意外に難しかった。', 'Tưởng dễ ai ngờ lại khó bất ngờ.', 3),
(4515, 494, 'GRAMMAR', 584, 'Ví dụ 4', '怒られると思いきや、褒められた。', 'Tưởng bị mắng, ai ngờ được khen.', 4),
(4516, 494, 'GRAMMAR', 585, 'Ví dụ 5', '彼の努力は賞賛に値する。', 'Nỗ lực của anh ấy xứng đáng được ca ngợi.', 5),
(4517, 494, 'GRAMMAR', 585, 'Ví dụ 6', '議論するに値しない。', 'Không đáng để tranh luận.', 6),
(4518, 495, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4519, 497, 'GRAMMAR', 586, 'Ví dụ 1', '彼は信頼するに足る人物だ。', 'Anh ấy là người xứng đáng để tin cậy.', 1),
(4520, 497, 'GRAMMAR', 586, 'Ví dụ 2', '取るに足りない問題だ。', 'Đó là vấn đề không đáng bận tâm.', 2),
(4521, 497, 'GRAMMAR', 587, 'Ví dụ 3', '彼は天才だと言っても過言ではない。', 'Nói anh ấy là thiên tài cũng không ngoa.', 3),
(4522, 497, 'GRAMMAR', 587, 'Ví dụ 4', '命綱だと言っても過言ではない。', 'Nói đó là sợi dây sinh mệnh cũng không quá.', 4),
(4523, 497, 'GRAMMAR', 588, 'Ví dụ 5', '年齢にかかわらず応募できます。', 'Bất kể tuổi tác đều có thể ứng tuyển.', 5),
(4524, 497, 'GRAMMAR', 588, 'Ví dụ 6', '晴雨にかかわらず開催します。', 'Mưa hay nắng vẫn tổ chức.', 6),
(4525, 498, 'LISTENING', NULL, 'Người chất vấn', '興味深いご発表でした。一点確認させていただきたいのですが。', 'Bài trình bày rất thú vị. Tôi xin phép xác nhận một điểm ạ.', 1),
(4526, 498, 'LISTENING', NULL, 'Người trình bày', 'はい、どうぞ。', 'Vâng, xin mời.', 2),
(4527, 498, 'LISTENING', NULL, 'Người chất vấn', 'サンプル数が百名では、一般化するには少ないのではないでしょうか。', 'Với cỡ mẫu một trăm người, chẳng phải là quá ít để khái quát hoá sao ạ?', 3),
(4528, 498, 'LISTENING', NULL, 'Người trình bày', 'ご指摘のとおりです。今回はあくまで予備調査と位置づけております。', 'Đúng như ông chỉ ra. Lần này chúng tôi chỉ xác định đây là khảo sát sơ bộ.', 4),
(4529, 498, 'LISTENING', NULL, 'Người chất vấn', 'とはいえ、結論部分の書き方はやや踏み込みすぎている印象を受けました。', 'Tuy vậy, cách viết ở phần kết luận cho tôi cảm giác hơi đi quá xa.', 5),
(4530, 498, 'LISTENING', NULL, 'Người trình bày', '貴重なご意見として受け止め、表現を改めたいと存じます。', 'Tôi xin tiếp thu như một ý kiến quý báu và sẽ chỉnh lại cách diễn đạt.', 6),
(4531, 498, 'LISTENING', NULL, 'Người chất vấn', '今後、対象を拡大されるご予定はおありでしょうか。', 'Sắp tới ông có dự định mở rộng đối tượng không ạ?', 7),
(4532, 498, 'LISTENING', NULL, 'Người trình bày', '来年度に千名規模での実施を計画しております。', 'Chúng tôi đang lên kế hoạch thực hiện quy mô một nghìn người vào năm sau.', 8),
(4533, 499, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4534, 501, 'GRAMMAR', 589, 'Ví dụ 1', '兄にひきかえ、弟はよく勉強する。', 'Trái hẳn với anh, cậu em rất chăm học.', 1),
(4535, 501, 'GRAMMAR', 589, 'Ví dụ 2', '去年の猛暑にひきかえ、今年は涼しい。', 'Trái hẳn cái nóng năm ngoái, năm nay mát mẻ.', 2),
(4536, 501, 'GRAMMAR', 590, 'Ví dụ 3', '努力なくして成功はない。', 'Không có nỗ lực thì không có thành công.', 3),
(4537, 501, 'GRAMMAR', 590, 'Ví dụ 4', '皆様のご支援なくしては実現できませんでした。', 'Không có sự ủng hộ của quý vị thì đã không thực hiện được.', 4),
(4538, 501, 'GRAMMAR', 591, 'Ví dụ 5', '昔ながらの製法を守っている。', 'Chúng tôi giữ cách làm truyền thống từ xưa.', 5),
(4539, 501, 'GRAMMAR', 591, 'Ví dụ 6', '生まれながらの才能だ。', 'Đó là tài năng bẩm sinh.', 6),
(4540, 502, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4541, 504, 'GRAMMAR', 592, 'Ví dụ 1', '今年は去年にもまして暑い。', 'Năm nay còn nóng hơn cả năm ngoái.', 1),
(4542, 504, 'GRAMMAR', 592, 'Ví dụ 2', '何にもまして健康が大切だ。', 'Hơn hết thảy, sức khoẻ là quan trọng.', 2),
(4543, 504, 'GRAMMAR', 593, 'Ví dụ 3', '好天と相まって、来場者は過去最多となった。', 'Cộng hưởng với thời tiết đẹp, lượng khách đông kỷ lục.', 3),
(4544, 504, 'GRAMMAR', 593, 'Ví dụ 4', '努力が才能と相まって花開いた。', 'Nỗ lực cộng với tài năng đã đơm hoa.', 4),
(4545, 504, 'GRAMMAR', 594, 'Ví dụ 5', '感謝こそすれ、恨むことはない。', 'Tôi chỉ có biết ơn chứ không hề oán trách.', 5),
(4546, 504, 'GRAMMAR', 594, 'Ví dụ 6', '増えこそすれ、減ることはない。', 'Chỉ có tăng chứ không giảm.', 6),
(4547, 505, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4548, 507, 'GRAMMAR', 595, 'Ví dụ 1', 'これは職人ならではの技だ。', 'Đây là kỹ thuật chỉ nghệ nhân mới có.', 1),
(4549, 507, 'GRAMMAR', 595, 'Ví dụ 2', '地元ならではの味を楽しめる。', 'Có thể thưởng thức hương vị chỉ nơi này mới có.', 2),
(4550, 507, 'GRAMMAR', 596, 'Ví dụ 3', '考え方ひとつで人生は変わる。', 'Chỉ một cách nghĩ thôi cũng đổi cả đời người.', 3),
(4551, 507, 'GRAMMAR', 596, 'Ví dụ 4', '言い方ひとつで印象が違う。', 'Chỉ cách nói thôi cũng khác hẳn ấn tượng.', 4),
(4552, 507, 'GRAMMAR', 597, 'Ví dụ 5', '誰であろうと規則は守るべきだ。', 'Dù là ai cũng phải tuân thủ quy tắc.', 5),
(4553, 507, 'GRAMMAR', 597, 'Ví dụ 6', 'どこであろうと行く。', 'Dù ở đâu tôi cũng đi.', 6),
(4554, 508, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4555, 510, 'GRAMMAR', 598, 'Ví dụ 1', '彼女は涙ながらに事情を語った。', 'Cô ấy vừa khóc vừa kể lại sự tình.', 1),
(4556, 510, 'GRAMMAR', 598, 'Ví dụ 2', '生まれながらに才能があった。', 'Anh ấy có tài năng bẩm sinh.', 2),
(4557, 510, 'GRAMMAR', 599, 'Ví dụ 3', '彼が辞めるとは思わなかった。', 'Không ngờ anh ấy lại nghỉ việc.', 3),
(4558, 510, 'GRAMMAR', 599, 'Ví dụ 4', '幸せとは何だろうか。', 'Cái gọi là hạnh phúc là gì nhỉ?', 4),
(4559, 511, 'LISTENING', NULL, 'Ông Mori', '率直に申し上げて、この見積もりでは社内を通すのが難しい状況です。', 'Nói thẳng ra, với báo giá này thì tình hình là khó thông qua nội bộ.', 1),
(4560, 511, 'LISTENING', NULL, 'Linh', 'ご事情は重々承知しております。', 'Chúng tôi hiểu rất rõ hoàn cảnh của quý vị ạ.', 2),
(4561, 511, 'LISTENING', NULL, 'Linh', 'ただ、これ以上お値引きいたしますと、品質の維持が困難になりかねません。', 'Chỉ có điều nếu giảm giá thêm nữa thì việc duy trì chất lượng có thể trở nên khó khăn.', 3),
(4562, 511, 'LISTENING', NULL, 'Ông Mori', 'とはいえ、他社はもっと低い価格を提示してきております。', 'Tuy vậy, các công ty khác đang chào giá thấp hơn nhiều.', 4),
(4563, 511, 'LISTENING', NULL, 'Linh', '価格面で見劣りするのは事実です。その点は否定いたしません。', 'Việc thua kém về mặt giá là sự thật. Điểm đó chúng tôi không phủ nhận.', 5),
(4564, 511, 'LISTENING', NULL, 'Linh', 'その代わり、保守対応の範囲を広げるという形でご提案できないでしょうか。', 'Đổi lại, chúng tôi đề xuất theo hướng mở rộng phạm vi bảo trì, được không ạ?', 6),
(4565, 511, 'LISTENING', NULL, 'Ông Mori', 'なるほど。総額ではなく、内容で折り合うということですね。', 'Ra vậy. Tức là không thoả hiệp ở tổng giá mà ở nội dung, đúng không.', 7),
(4566, 511, 'LISTENING', NULL, 'Linh', 'はい。具体的な条件は改めて書面でお出しいたします。', 'Vâng ạ. Điều kiện cụ thể chúng tôi sẽ trình bày lại bằng văn bản.', 8),
(4567, 512, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4568, 514, 'GRAMMAR', 600, 'Ví dụ 1', '努力なしには成功はあり得ない。', 'Không nỗ lực thì không thể thành công.', 1),
(4569, 514, 'GRAMMAR', 600, 'Ví dụ 2', '彼の協力なしには完成しなかった。', 'Không có sự hợp tác của anh ấy thì đã không hoàn thành.', 2),
(4570, 514, 'GRAMMAR', 601, 'Ví dụ 3', '努力があればこそ、今の成功がある。', 'Chính vì có nỗ lực mới có thành công hôm nay.', 3),
(4571, 514, 'GRAMMAR', 601, 'Ví dụ 4', '信頼していればこそ任せるのだ。', 'Chính vì tin tưởng nên tôi mới giao.', 4),
(4572, 515, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4573, 517, 'GRAMMAR', 602, 'Ví dụ 1', '彼は泣かんばかりの顔をしていた。', 'Anh ta mang bộ mặt như sắp khóc.', 1),
(4574, 517, 'GRAMMAR', 602, 'Ví dụ 2', '店は溢れんばかりの人だった。', 'Cửa hàng đông như sắp vỡ tung.', 2),
(4575, 517, 'GRAMMAR', 603, 'Ví dụ 3', '断られたら、他を当たるまでだ。', 'Bị từ chối thì tìm chỗ khác thôi.', 3),
(4576, 517, 'GRAMMAR', 603, 'Ví dụ 4', 'できないなら自分でやるまでのことだ。', 'Không làm được thì tôi tự làm vậy.', 4),
(4577, 518, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4578, 520, 'GRAMMAR', 604, 'Ví dụ 1', 'もう帰れとばかりに、彼は時計を見た。', 'Anh ta nhìn đồng hồ như ngầm bảo về đi.', 1),
(4579, 520, 'GRAMMAR', 604, 'Ví dụ 2', 'ここぞとばかりに攻めた。', 'Nhân đúng lúc này mà tấn công dồn dập.', 2),
(4580, 520, 'GRAMMAR', 605, 'Ví dụ 3', '言うまでもなく、健康が第一だ。', 'Khỏi phải nói, sức khoẻ là trên hết.', 3),
(4581, 520, 'GRAMMAR', 605, 'Ví dụ 4', 'わざわざ確認するまでもない。', 'Không cần phải mất công xác nhận.', 4),
(4582, 521, 'LISTENING', NULL, 'Thành viên ban giám đốc', 'これまでのご経験を踏まえ、当社で何を実現されたいとお考えですか。', 'Dựa trên kinh nghiệm từ trước, anh muốn hiện thực hoá điều gì tại công ty chúng tôi?', 1),
(4583, 521, 'LISTENING', NULL, 'Linh', '開発と顧客の間にある認識のずれを、仕組みとして解消したいと考えております。', 'Tôi muốn giải quyết khoảng cách nhận thức giữa bộ phận phát triển và khách hàng bằng cơ chế.', 2),
(4584, 521, 'LISTENING', NULL, 'Thành viên ban giám đốc', '仕組みと申しますと、具体的にはどのようなものでしょうか。', 'Nói là cơ chế, cụ thể là thế nào ạ?', 3),
(4585, 521, 'LISTENING', NULL, 'Linh', '要件を文章だけでなく、動く画面で早期に確認する流れを定着させることです。', 'Là việc thiết lập quy trình xác nhận yêu cầu sớm bằng màn hình chạy được, chứ không chỉ bằng văn bản.', 4),
(4586, 521, 'LISTENING', NULL, 'Thành viên ban giám đốc', 'しかし、現場からは工数が増えるとの反発も予想されます。', 'Nhưng dự kiến sẽ có phản đối từ hiện trường rằng khối lượng công việc tăng lên.', 5),
(4587, 521, 'LISTENING', NULL, 'Linh', 'ご指摘のとおりです。まずは小規模な案件で効果を示すほかないと考えます。', 'Đúng như ngài chỉ ra. Tôi cho rằng chỉ còn cách chứng minh hiệu quả ở dự án nhỏ trước.', 6),
(4588, 521, 'LISTENING', NULL, 'Thành viên ban giám đốc', '部下の育成についてはどのようにお考えですか。', 'Còn về việc đào tạo cấp dưới, anh nghĩ thế nào?', 7),
(4589, 521, 'LISTENING', NULL, 'Linh', '任せきりにも抱え込みにもせず、判断の理由を共有することを心がけます。', 'Tôi chú trọng việc chia sẻ lý do của mỗi quyết định, không phó mặc cũng không ôm hết.', 8),
(4590, 522, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4591, 524, 'GRAMMAR', 606, 'Ví dụ 1', '彼はベルが鳴るが早いか、教室を飛び出した。', 'Chuông vừa reo là cậu ta lao khỏi lớp.', 1),
(4592, 524, 'GRAMMAR', 606, 'Ví dụ 2', '横になるが早いか、いびきをかき始めた。', 'Vừa nằm xuống là ngáy ngay.', 2),
(4593, 524, 'GRAMMAR', 607, 'Ví dụ 3', '用心するに越したことはない。', 'Cẩn thận vẫn hơn.', 3),
(4594, 524, 'GRAMMAR', 607, 'Ví dụ 4', '安いに越したことはない。', 'Rẻ thì tốt hơn cả.', 4),
(4595, 525, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4596, 527, 'GRAMMAR', 608, 'Ví dụ 1', '片付けるそばから子供が散らかす。', 'Vừa dọn xong là bọn trẻ lại bày ra.', 1),
(4597, 527, 'GRAMMAR', 608, 'Ví dụ 2', '覚えるそばから忘れてしまう。', 'Vừa học xong là quên ngay.', 2),
(4598, 527, 'GRAMMAR', 609, 'Ví dụ 3', '多少なりともお役に立てれば幸いです。', 'Nếu giúp được dù chỉ chút ít thì tôi rất mừng.', 3),
(4599, 527, 'GRAMMAR', 609, 'Ví dụ 4', '少しなりとも慰めになれば。', 'Mong an ủi được phần nào.', 4),
(4600, 528, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4601, 530, 'GRAMMAR', 610, 'Ví dụ 1', '彼は部屋に入るなり、電気を消した。', 'Anh ta vừa vào phòng là tắt đèn ngay.', 1),
(4602, 530, 'GRAMMAR', 610, 'Ví dụ 2', '彼女は顔を見るなり泣き出した。', 'Vừa nhìn thấy mặt là cô ấy oà khóc.', 2),
(4603, 530, 'GRAMMAR', 611, 'Ví dụ 3', '彼に貸したが最後、返ってこない。', 'Một khi đã cho anh ta mượn là mất luôn.', 3),
(4604, 530, 'GRAMMAR', 611, 'Ví dụ 4', '眠ったが最後、朝まで起きない。', 'Một khi ngủ rồi là đến sáng mới dậy.', 4),
(4605, 531, 'LISTENING', NULL, 'Linh', '本日は申し上げにくいご報告があり、お時間を頂戴いたしました。', 'Hôm nay tôi có một báo cáo khó nói nên đã xin thời gian của ngài.', 1),
(4606, 531, 'LISTENING', NULL, 'Ông Kondo', 'おっしゃってください。', 'Ông cứ nói đi.', 2),
(4607, 531, 'LISTENING', NULL, 'Linh', '第二フェーズにつきまして、弊社としてお受けすることが難しい状況となりました。', 'Về giai đoạn hai, phía chúng tôi đã rơi vào tình huống khó nhận.', 3),
(4608, 531, 'LISTENING', NULL, 'Ông Kondo', 'それは困りましたね。理由を伺っても。', 'Chuyện này gay đấy. Tôi hỏi lý do được chứ?', 4),
(4609, 531, 'LISTENING', NULL, 'Linh', '主力の技術者が長期離脱することになり、品質を保てる体制が組めません。', 'Kỹ sư chủ lực phải nghỉ dài hạn, chúng tôi không lập được đội hình giữ được chất lượng.', 5),
(4610, 531, 'LISTENING', NULL, 'Ông Kondo', '無理に引き受けて失敗されるよりはましですが、時期が時期です。', 'Còn hơn là gượng nhận rồi làm hỏng, nhưng thời điểm thì quá bất lợi.', 6),
(4611, 531, 'LISTENING', NULL, 'Linh', '代替案として、信頼できる協力会社をご紹介させていただけないでしょうか。', 'Thay vào đó, xin phép cho tôi giới thiệu một công ty đối tác đáng tin cậy.', 7),
(4612, 531, 'LISTENING', NULL, 'Ông Kondo', '分かりました。引き継ぎまで責任を持っていただけるなら、検討します。', 'Tôi hiểu. Nếu ông chịu trách nhiệm đến khi bàn giao xong thì tôi sẽ cân nhắc.', 8),
(4613, 532, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4614, 534, 'GRAMMAR', 612, 'Ví dụ 1', 'お礼かたがたご挨拶に伺いました。', 'Tôi đến thăm để chào hỏi kết hợp cảm ơn ạ.', 1),
(4615, 534, 'GRAMMAR', 612, 'Ví dụ 2', '報告かたがたお伺いします。', 'Tôi xin đến vừa để báo cáo vừa để thăm hỏi.', 2),
(4616, 534, 'GRAMMAR', 613, 'Ví dụ 3', 'あの日の暑さといったらなかった。', 'Cái nóng hôm đó thì không gì tả nổi.', 3),
(4617, 534, 'GRAMMAR', 613, 'Ví dụ 4', 'うれしいといったらない。', 'Vui không gì bằng.', 4),
(4618, 535, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4619, 537, 'GRAMMAR', 614, 'Ví dụ 1', '彼は仕事のかたわら小説を書いている。', 'Bên cạnh công việc, anh ấy còn viết tiểu thuyết.', 1),
(4620, 537, 'GRAMMAR', 614, 'Ví dụ 2', '教師のかたわら、ボランティアもしている。', 'Ngoài dạy học, cô ấy còn làm tình nguyện.', 2),
(4621, 537, 'GRAMMAR', 615, 'Ví dụ 3', '見るともなくテレビを見ていた。', 'Tôi xem tivi mà chẳng để tâm.', 3),
(4622, 537, 'GRAMMAR', 615, 'Ví dụ 4', 'どこからともなく音楽が聞こえてきた。', 'Từ đâu đó vọng lại tiếng nhạc.', 4),
(4623, 538, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4624, 540, 'GRAMMAR', 616, 'Ví dụ 1', '散歩がてら郵便局に寄った。', 'Tiện đi dạo tôi ghé bưu điện.', 1),
(4625, 540, 'GRAMMAR', 616, 'Ví dụ 2', '買い物がてら友人を訪ねた。', 'Tiện đi mua sắm tôi ghé thăm bạn.', 2),
(4626, 540, 'GRAMMAR', 617, 'Ví dụ 3', 'この年齢にして初めて分かることがある。', 'Có những điều phải đến tuổi này mới hiểu.', 3),
(4627, 540, 'GRAMMAR', 617, 'Ví dụ 4', '彼にして初めてできる技だ。', 'Kỹ thuật này phải là anh ấy mới làm được.', 4),
(4628, 541, 'LISTENING', NULL, 'Chị Mori', '来期の予算は今期比で二割削減となります。', 'Ngân sách kỳ sau bị cắt hai mươi phần trăm so với kỳ này.', 1),
(4629, 541, 'LISTENING', NULL, 'Linh', 'それですと、外部委託の部分を見直さざるを得ません。', 'Nếu vậy thì chúng ta buộc phải xem lại phần thuê ngoài.', 2),
(4630, 541, 'LISTENING', NULL, 'Chị Mori', 'ただ、内製に切り替えれば人員の負荷が一気に高まります。', 'Nhưng chuyển sang tự làm thì tải của nhân sự sẽ tăng vọt.', 3),
(4631, 541, 'LISTENING', NULL, 'Linh', 'おっしゃるとおりです。ですが、削るなら機能そのものを絞るほうが現実的かと。', 'Đúng như chị nói. Nhưng nếu phải cắt thì tôi thấy thu hẹp chính tính năng sẽ thực tế hơn.', 4),
(4632, 541, 'LISTENING', NULL, 'Giám đốc', '機能を削れば顧客から反発が出るのは避けられまい。', 'Cắt tính năng thì khó tránh khỏi phản ứng từ khách hàng.', 5),
(4633, 541, 'LISTENING', NULL, 'Linh', 'はい。ですので、利用率の低い機能に限って段階的に外す案を考えております。', 'Vâng ạ. Vì vậy tôi đang tính phương án chỉ gỡ dần những tính năng ít được dùng.', 6),
(4634, 541, 'LISTENING', NULL, 'Chị Mori', '利用率のデータはそろっているのですか。', 'Dữ liệu tỷ lệ sử dụng đã có đủ chưa?', 7),
(4635, 541, 'LISTENING', NULL, 'Giám đốc', 'データがあるなら話は早い。来週までに候補ではなく具体案を出してくれ。', 'Có dữ liệu thì dễ bàn. Trước tuần sau đưa tôi phương án cụ thể chứ không phải danh sách ứng viên.', 8),
(4636, 542, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4637, 544, 'GRAMMAR', 618, 'Ví dụ 1', '黒ずくめの男が立っていた。', 'Một người đàn ông mặc toàn đồ đen đang đứng đó.', 1),
(4638, 544, 'GRAMMAR', 618, 'Ví dụ 2', '今年はいいことずくめだった。', 'Năm nay toàn chuyện tốt.', 2),
(4639, 544, 'GRAMMAR', 619, 'Ví dụ 3', 'もはや他人事にあらず。', 'Đây không còn là chuyện của người khác nữa.', 3),
(4640, 544, 'GRAMMAR', 619, 'Ví dụ 4', 'これは偶然にあらず。', 'Đây không phải là ngẫu nhiên.', 4),
(4641, 545, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4642, 547, 'GRAMMAR', 620, 'Ví dụ 1', '汗まみれになって働いた。', 'Tôi làm việc đến mồ hôi bê bết.', 1),
(4643, 547, 'GRAMMAR', 620, 'Ví dụ 2', '子供は泥まみれで帰ってきた。', 'Bọn trẻ về nhà người dính đầy bùn.', 2),
(4644, 547, 'GRAMMAR', 621, 'Ví dụ 3', '真相は知るべくもない。', 'Sự thật thì không thể nào biết được.', 3),
(4645, 547, 'GRAMMAR', 621, 'Ví dụ 4', '勝利は望むべくもなかった。', 'Chiến thắng thì không thể nào mong đợi.', 4),
(4646, 548, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4647, 550, 'GRAMMAR', 622, 'Ví dụ 1', 'ようやく春めいてきた。', 'Cuối cùng cũng đã ngả sang không khí mùa xuân.', 1),
(4648, 550, 'GRAMMAR', 622, 'Ví dụ 2', '彼は謎めいた笑みを浮かべた。', 'Anh ta nở nụ cười đầy bí ẩn.', 2),
(4649, 550, 'GRAMMAR', 623, 'Ví dụ 3', '春とはいえ、まだ寒い。', 'Tuy nói là xuân nhưng vẫn lạnh.', 3),
(4650, 550, 'GRAMMAR', 623, 'Ví dụ 4', '忙しいとはいえ、休みは必要だ。', 'Tuy bận nhưng vẫn cần nghỉ.', 4),
(4651, 551, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4652, 553, 'GRAMMAR', 624, 'Ví dụ 1', '彼の態度は失礼極まりない。', 'Thái độ của anh ta vô lễ hết mức.', 1),
(4653, 553, 'GRAMMAR', 624, 'Ví dụ 2', '危険極まる作業だ。', 'Đó là công việc nguy hiểm tột cùng.', 2),
(4654, 553, 'GRAMMAR', 625, 'Ví dụ 3', '狭いながらも楽しい我が家。', 'Nhà tôi tuy chật mà vui.', 3),
(4655, 553, 'GRAMMAR', 625, 'Ví dụ 4', '彼は小さいながらも力持ちだ。', 'Cậu ấy tuy bé mà khoẻ.', 4),
(4656, 554, 'LISTENING', NULL, 'Trưởng phòng kinh doanh', '率直に申し上げて、技術側の見積もりは保守的すぎるのではありませんか。', 'Nói thẳng ra, chẳng phải ước lượng của bên kỹ thuật là quá dè dặt sao?', 1),
(4657, 554, 'LISTENING', NULL, 'Trưởng phòng kỹ thuật', '過去に無理な約束をして現場が疲弊した経緯がございます。', 'Trước đây đã có chuyện hứa quá sức khiến hiện trường kiệt quệ.', 2),
(4658, 554, 'LISTENING', NULL, 'Linh', 'お二方のご懸念はどちらももっともかと存じます。', 'Tôi nghĩ mối lo của cả hai vị đều có lý ạ.', 3),
(4659, 554, 'LISTENING', NULL, 'Linh', '争点は納期そのものではなく、前提の置き方にあるように見受けられます。', 'Điểm tranh chấp dường như không phải bản thân thời hạn mà là cách đặt tiền đề.', 4),
(4660, 554, 'LISTENING', NULL, 'Trưởng phòng kinh doanh', 'と申しますと。', 'Ý ông là sao?', 5),
(4661, 554, 'LISTENING', NULL, 'Linh', '要件がどこまで固まったかについて、双方の認識が異なっているようです。', 'Có vẻ hai bên đang hiểu khác nhau về việc yêu cầu đã chốt tới đâu.', 6),
(4662, 554, 'LISTENING', NULL, 'Trưởng phòng kỹ thuật', '確かに、確定した部分と未確定の部分を分けて議論すべきでした。', 'Đúng là lẽ ra nên tách phần đã chốt và phần chưa chốt ra để bàn.', 7),
(4663, 554, 'LISTENING', NULL, 'Linh', 'では、その切り分けを明日までに整理し、改めてお諮りいたします。', 'Vậy tôi sẽ sắp xếp việc phân tách đó trước ngày mai rồi xin ý kiến lại ạ.', 8),
(4664, 555, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4665, 557, 'GRAMMAR', 626, 'Ví dụ 1', 'これは贅沢の極みだ。', 'Đây là sự xa xỉ tột đỉnh.', 1),
(4666, 557, 'GRAMMAR', 626, 'Ví dụ 2', '感激の極みです。', 'Tôi vô cùng cảm kích.', 2),
(4667, 557, 'GRAMMAR', 627, 'Ví dụ 3', '専門家といえども間違うことはある。', 'Dù là chuyên gia cũng có lúc sai.', 3),
(4668, 557, 'GRAMMAR', 627, 'Ví dụ 4', '一日といえども休めない。', 'Dù chỉ một ngày cũng không nghỉ được.', 4),
(4669, 558, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4670, 560, 'GRAMMAR', 628, 'Ví dụ 1', 'お招きいただき光栄の至りです。', 'Được mời tôi thật vô cùng vinh dự.', 1),
(4671, 560, 'GRAMMAR', 628, 'Ví dụ 2', '若気の至りでした。', 'Đó là sự bồng bột của tuổi trẻ.', 2),
(4672, 560, 'GRAMMAR', 629, 'Ví dụ 3', '彼は謝りもしなかった。', 'Anh ta đến cả xin lỗi cũng không thèm.', 3),
(4673, 560, 'GRAMMAR', 629, 'Ví dụ 4', 'こちらを見向きもしない。', 'Chẳng thèm ngoái nhìn về phía này.', 4),
(4674, 561, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4675, 563, 'GRAMMAR', 630, 'Ví dụ 1', '教師たるもの、学生の模範であるべきだ。', 'Đã là giáo viên thì phải làm gương cho học sinh.', 1),
(4676, 563, 'GRAMMAR', 630, 'Ví dụ 2', '社会人たるもの、時間を守るべきだ。', 'Đã đi làm thì phải giữ đúng giờ.', 2),
(4677, 563, 'GRAMMAR', 631, 'Ví dụ 3', 'これは命に関わる問題だ。', 'Đây là vấn đề liên quan đến tính mạng.', 3),
(4678, 563, 'GRAMMAR', 631, 'Ví dụ 4', '会社の信用に関わる。', 'Việc này ảnh hưởng đến uy tín công ty.', 4),
(4679, 564, 'LISTENING', NULL, 'Cổ đông', '減益の主たる要因は何であるとご認識でしょうか。', 'Ban lãnh đạo nhận định nguyên nhân chủ yếu của việc giảm lợi nhuận là gì?', 1),
(4680, 564, 'LISTENING', NULL, 'Giám đốc điều hành', '原材料費の高騰が最大の要因でございます。', 'Việc giá nguyên vật liệu tăng vọt là nguyên nhân lớn nhất ạ.', 2),
(4681, 564, 'LISTENING', NULL, 'Cổ đông', 'しかし、同業他社は増益を確保しております。外部要因だけで説明がつくのでしょうか。', 'Nhưng các công ty cùng ngành vẫn giữ được tăng lợi nhuận. Chỉ bằng yếu tố bên ngoài thì giải thích nổi sao?', 3),
(4682, 564, 'LISTENING', NULL, 'Giám đốc điều hành', 'ご指摘は真摯に受け止めております。価格転嫁の遅れも一因と考えております。', 'Chúng tôi tiếp thu nghiêm túc điều quý vị chỉ ra. Chúng tôi cho rằng việc chuyển giá chậm cũng là một nguyên nhân.', 4),
(4683, 564, 'LISTENING', NULL, 'Cổ đông', 'では、来期に向けた具体的な打ち手をお示しいただきたい。', 'Vậy xin quý vị trình bày các nước đi cụ thể hướng tới kỳ sau.', 5),
(4684, 564, 'LISTENING', NULL, 'Giám đốc điều hành', '第一に価格改定、第二に不採算事業の整理を予定しております。', 'Thứ nhất là điều chỉnh giá, thứ hai là sắp xếp lại các mảng kinh doanh thua lỗ ạ.', 6),
(4685, 564, 'LISTENING', NULL, 'Cổ đông', '整理の対象と時期は明示されるのでしょうか。', 'Đối tượng và thời điểm sắp xếp lại có được nêu rõ không ạ?', 7),
(4686, 564, 'LISTENING', NULL, 'Giám đốc điều hành', '次回の決算発表の場で、具体的にご説明申し上げます。', 'Tại buổi công bố kết quả kinh doanh lần tới, chúng tôi xin giải thích cụ thể ạ.', 8),
(4687, 565, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4688, 567, 'GRAMMAR', 632, 'Ví dụ 1', '医者ともあろう人がそんなミスをするとは。', 'Đường đường là bác sĩ mà lại mắc lỗi như vậy.', 1),
(4689, 567, 'GRAMMAR', 632, 'Ví dụ 2', '大臣ともあろう者が嘘をつくとは。', 'Đường đường là bộ trưởng mà lại nói dối.', 2),
(4690, 567, 'GRAMMAR', 633, 'Ví dụ 3', '皆様お元気のことと存じます。', 'Kính mong quý vị vẫn mạnh khoẻ.', 3),
(4691, 567, 'GRAMMAR', 633, 'Ví dụ 4', 'ご多忙のことと存じますが、よろしくお願いいたします。', 'Biết quý vị bận rộn nhưng kính mong giúp đỡ.', 4),
(4692, 568, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4693, 570, 'GRAMMAR', 634, 'Ví dụ 1', '理由が何であれ、遅刻は許されない。', 'Dù lý do là gì, đến muộn cũng không được tha.', 1),
(4694, 570, 'GRAMMAR', 634, 'Ví dụ 2', '子供であれ大人であれ、ルールは同じだ。', 'Dù là trẻ con hay người lớn, quy tắc vẫn như nhau.', 2),
(4695, 570, 'GRAMMAR', 635, 'Ví dụ 3', '先生のもとで研究を続けている。', 'Tôi tiếp tục nghiên cứu dưới sự hướng dẫn của thầy.', 3),
(4696, 570, 'GRAMMAR', 635, 'Ví dụ 4', '厳しい条件のもとに契約した。', 'Chúng tôi ký hợp đồng dưới điều kiện khắt khe.', 4),
(4697, 571, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4698, 573, 'GRAMMAR', 636, 'Ví dụ 1', '理由のいかんによらず、返品はできません。', 'Bất kể lý do gì cũng không đổi trả được.', 1),
(4699, 573, 'GRAMMAR', 636, 'Ví dụ 2', '結果いかんで方針を変える。', 'Tuỳ kết quả mà đổi phương châm.', 2),
(4700, 573, 'GRAMMAR', 637, 'Ví dụ 3', '彼にしてみれば、当然の反応だろう。', 'Đứng ở vị trí anh ấy thì đó là phản ứng đương nhiên.', 3),
(4701, 573, 'GRAMMAR', 637, 'Ví dụ 4', '親にしてみれば心配なのだ。', 'Với cha mẹ thì đó là nỗi lo.', 4),
(4702, 574, 'LISTENING', NULL, 'Phóng viên', '今回の製品は従来品とどのように異なるのでしょうか。', 'Sản phẩm lần này khác với sản phẩm cũ như thế nào ạ?', 1),
(4703, 574, 'LISTENING', NULL, 'Linh', '操作性を根本から見直した点が最大の違いでございます。', 'Điểm khác biệt lớn nhất là chúng tôi đã xem lại tính thao tác từ gốc ạ.', 2),
(4704, 574, 'LISTENING', NULL, 'Phóng viên', '一方で、価格が上がることへの懸念も聞かれますが。', 'Mặt khác, cũng nghe nói có lo ngại về việc giá tăng?', 3),
(4705, 574, 'LISTENING', NULL, 'Linh', 'ご指摘のとおり、値上げは避けられませんでした。', 'Đúng như ông chỉ ra, việc tăng giá là không tránh khỏi ạ.', 4),
(4706, 574, 'LISTENING', NULL, 'Linh', 'ただ、耐用年数が延びたことを考えれば、長期的には割安かと存じます。', 'Chỉ có điều, xét việc tuổi thọ tăng lên thì về dài hạn tôi nghĩ là rẻ hơn ạ.', 5),
(4707, 574, 'LISTENING', NULL, 'Phóng viên', '発売後に不具合が生じた場合の対応方針は。', 'Phương châm ứng phó nếu phát sinh lỗi sau khi ra mắt là gì ạ?', 6),
(4708, 574, 'LISTENING', NULL, 'Linh', '速やかに公表し、無償での交換を原則といたします。', 'Chúng tôi sẽ công bố nhanh chóng và lấy việc đổi miễn phí làm nguyên tắc ạ.', 7),
(4709, 574, 'LISTENING', NULL, 'Phóng viên', '貴重なお話をありがとうございました。', 'Cảm ơn ông vì những chia sẻ quý báu ạ.', 8),
(4710, 575, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4711, 577, 'GRAMMAR', 638, 'Ví dụ 1', '本日をもって閉店いたします。', 'Chúng tôi đóng cửa kể từ hôm nay.', 1),
(4712, 577, 'GRAMMAR', 638, 'Ví dụ 2', '身をもって体験した。', 'Tôi đã trải nghiệm bằng chính bản thân mình.', 2),
(4713, 577, 'GRAMMAR', 639, 'Ví dụ 3', '取るに足りない問題だ。', 'Đó là vấn đề không đáng bận tâm.', 3),
(4714, 577, 'GRAMMAR', 639, 'Ví dụ 4', '恐れるに足りない相手だ。', 'Đối thủ không đáng sợ.', 4),
(4715, 578, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4716, 580, 'GRAMMAR', 640, 'Ví dụ 1', '努力することなしに成功はない。', 'Không nỗ lực thì không có thành công.', 1),
(4717, 580, 'GRAMMAR', 640, 'Ví dụ 2', '誰にも相談することなしに決めた。', 'Tôi quyết định mà không bàn với ai.', 2),
(4718, 580, 'GRAMMAR', 641, 'Ví dụ 3', 'あんな店、二度と行くものか。', 'Quán đó thì tôi không bao giờ quay lại.', 3),
(4719, 580, 'GRAMMAR', 641, 'Ví dụ 4', '負けるものか。', 'Làm gì có chuyện thua.', 4),
(4720, 581, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4721, 583, 'GRAMMAR', 642, 'Ví dụ 1', 'ここにゴミを捨てるべからず。', 'Cấm vứt rác ở đây.', 1),
(4722, 583, 'GRAMMAR', 642, 'Ví dụ 2', '許すべからざる行為だ。', 'Đó là hành vi không thể tha thứ.', 2),
(4723, 583, 'GRAMMAR', 643, 'Ví dụ 3', '忙しいどころの話ではない。', 'Bận thì còn là nhẹ.', 3),
(4724, 583, 'GRAMMAR', 643, 'Ví dụ 4', '疲れたどころの話ではなかった。', 'Nói mệt thì còn quá nhẹ.', 4),
(4725, 584, 'LISTENING', NULL, 'Linh', '引き継ぎに当たって、まず押さえていただきたい点からお話しします。', 'Nhân việc bàn giao, tôi xin nói từ những điểm mong anh nắm trước.', 1),
(4726, 584, 'LISTENING', NULL, 'Anh Sakai', 'お願いします。特に注意すべきことはありますか。', 'Nhờ anh ạ. Có điều gì đặc biệt cần lưu ý không?', 2),
(4727, 584, 'LISTENING', NULL, 'Linh', 'この案件は、決定権が先方の本社にある点が厄介です。', 'Dự án này rắc rối ở chỗ quyền quyết định nằm ở trụ sở chính bên đối tác.', 3),
(4728, 584, 'LISTENING', NULL, 'Anh Sakai', '窓口の方に話を通しても、決まらないということでしょうか。', 'Tức là nói qua người đầu mối cũng không chốt được à?', 4),
(4729, 584, 'LISTENING', NULL, 'Linh', 'そのとおりです。ですから、要望は必ず文書で残すようにしてきました。', 'Đúng vậy. Nên tôi vẫn luôn để lại yêu cầu bằng văn bản.', 5),
(4730, 584, 'LISTENING', NULL, 'Anh Sakai', '過去のやり取りはどこにまとまっていますか。', 'Các trao đổi trước đây được tổng hợp ở đâu ạ?', 6),
(4731, 584, 'LISTENING', NULL, 'Linh', '共有フォルダに時系列で整理してあります。今日中に権限をお渡しします。', 'Tôi đã sắp xếp theo trình tự thời gian trong thư mục chung. Trong hôm nay tôi chuyển quyền truy cập cho anh.', 7),
(4732, 584, 'LISTENING', NULL, 'Anh Sakai', '助かります。分からないことがあれば、後日ご連絡してもよろしいですか。', 'Đỡ cho tôi quá. Nếu có gì chưa rõ, sau này tôi liên lạc lại được không ạ?', 8),
(4733, 585, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4734, 587, 'GRAMMAR', 644, 'Ví dụ 1', '真相を確かめるべく調査を始めた。', 'Họ bắt đầu điều tra để làm rõ sự thật.', 1),
(4735, 587, 'GRAMMAR', 644, 'Ví dụ 2', '目標を達成すべく努力している。', 'Tôi đang nỗ lực để đạt mục tiêu.', 2),
(4736, 587, 'GRAMMAR', 645, 'Ví dụ 3', '経験不足ゆえのミスだった。', 'Đó là lỗi do thiếu kinh nghiệm.', 3),
(4737, 587, 'GRAMMAR', 645, 'Ví dụ 4', '愛情ゆえの厳しさだ。', 'Đó là sự nghiêm khắc xuất phát từ tình thương.', 4),
(4738, 588, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4739, 590, 'GRAMMAR', 646, 'Ví dụ 1', '経験不足ゆえに失敗した。', 'Do thiếu kinh nghiệm nên đã thất bại.', 1),
(4740, 590, 'GRAMMAR', 646, 'Ví dụ 2', '若さゆえの過ちだった。', 'Đó là sai lầm do tuổi trẻ.', 2),
(4741, 590, 'GRAMMAR', 647, 'Ví dụ 3', '夏はビールに限る。', 'Mùa hè thì bia là nhất.', 3),
(4742, 590, 'GRAMMAR', 647, 'Ví dụ 4', '疲れたときは寝るに限る。', 'Mệt thì ngủ là nhất.', 4),
(4743, 591, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4744, 593, 'GRAMMAR', 648, 'Ví dụ 1', '連休とあって、道路は混んでいる。', 'Vì là kỳ nghỉ dài nên đường đông.', 1),
(4745, 593, 'GRAMMAR', 648, 'Ví dụ 2', '人気店とあって、行列ができていた。', 'Vì là quán nổi tiếng nên xếp hàng dài.', 2),
(4746, 593, 'GRAMMAR', 649, 'Ví dụ 3', '彼は休むことなく働き続けた。', 'Anh ấy làm việc không nghỉ.', 3),
(4747, 593, 'GRAMMAR', 649, 'Ví dụ 4', '三十年間変わることなく続いている。', 'Ba mươi năm nay vẫn tiếp diễn không đổi.', 4),
(4748, 594, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4749, 596, 'GRAMMAR', 650, 'Ví dụ 1', '子供のためとあれば、何でもする。', 'Nếu là vì con thì tôi làm bất cứ gì.', 1),
(4750, 596, 'GRAMMAR', 650, 'Ví dụ 2', '必要とあれば、すぐ伺います。', 'Nếu cần thì tôi đến ngay.', 2),
(4751, 596, 'GRAMMAR', 651, 'Ví dụ 3', '彼は危険をかえりみず川に飛び込んだ。', 'Anh ấy bất chấp nguy hiểm nhảy xuống sông.', 3),
(4752, 596, 'GRAMMAR', 651, 'Ví dụ 4', '仕事に追われ、家庭をかえりみなかった。', 'Bị công việc cuốn đi, anh ta không đoái hoài gia đình.', 4),
(4753, 597, 'LISTENING', NULL, 'Linh', '先方から提示された秘密保持条項について、ご意見を伺えますか。', 'Về điều khoản bảo mật phía đối tác đưa ra, tôi xin ý kiến của chị được không?', 1),
(4754, 597, 'LISTENING', NULL, 'Chị Nakamura', '拝見しました。範囲が広すぎる点が気になります。', 'Tôi đã xem. Tôi bận tâm ở chỗ phạm vi quá rộng.', 2),
(4755, 597, 'LISTENING', NULL, 'Linh', '具体的にはどの部分でしょうか。', 'Cụ thể là phần nào ạ?', 3),
(4756, 597, 'LISTENING', NULL, 'Chị Nakamura', '業務上知り得た一切の情報とありますが、これでは公知の情報も含まれかねません。', 'Ghi là mọi thông tin biết được trong công việc, thế này thì có thể bao gồm cả thông tin công khai.', 4),
(4757, 597, 'LISTENING', NULL, 'Linh', 'では、除外規定を追記していただくよう求めるべきでしょうか。', 'Vậy chúng ta nên yêu cầu họ bổ sung quy định loại trừ à?', 5),
(4758, 597, 'LISTENING', NULL, 'Chị Nakamura', 'そうですね。あわせて、有効期間の上限も設けたいところです。', 'Đúng vậy. Đồng thời tôi cũng muốn đặt giới hạn trên cho thời hạn hiệu lực.', 6),
(4759, 597, 'LISTENING', NULL, 'Linh', '先方が難色を示した場合はいかがいたしましょう。', 'Nếu phía đối tác tỏ ra khó chịu thì mình làm thế nào ạ?', 7),
(4760, 597, 'LISTENING', NULL, 'Chị Nakamura', 'その際は私も同席します。条件を詰めるのは早いほうがいいですから。', 'Lúc đó tôi sẽ cùng dự. Vì chốt điều kiện sớm thì tốt hơn.', 8),
(4761, 598, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4762, 600, 'GRAMMAR', 652, 'Ví dụ 1', '社会人ともなると、責任が重くなる。', 'Đã đi làm thì trách nhiệm nặng hơn.', 1),
(4763, 600, 'GRAMMAR', 652, 'Ví dụ 2', '夏ともなれば、海は人でいっぱいだ。', 'Cứ đến hè là biển đầy người.', 2),
(4764, 600, 'GRAMMAR', 653, 'Ví dụ 3', '自由と引き換えに安定を得た。', 'Đổi lấy tự do, anh ta có được sự ổn định.', 3),
(4765, 600, 'GRAMMAR', 653, 'Ví dụ 4', 'チケットと引き換えに商品をお渡しします。', 'Chúng tôi giao hàng đổi lấy phiếu.', 4),
(4766, 601, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4767, 603, 'GRAMMAR', 654, 'Ví dụ 1', '一日たりとも忘れたことはない。', 'Chưa một ngày nào tôi quên.', 1),
(4768, 603, 'GRAMMAR', 654, 'Ví dụ 2', '一円たりとも無駄にできない。', 'Không thể phí dù chỉ một yên.', 2),
(4769, 603, 'GRAMMAR', 655, 'Ví dụ 3', '結果いかんによっては計画を見直す。', 'Tuỳ kết quả mà có thể xem lại kế hoạch.', 3),
(4770, 603, 'GRAMMAR', 655, 'Ví dụ 4', '状況いかんによっては中止もある。', 'Tuỳ tình hình cũng có thể huỷ.', 4),
(4771, 604, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4772, 606, 'GRAMMAR', 656, 'Ví dụ 1', '想像するだに恐ろしい。', 'Chỉ tưởng tượng thôi đã thấy kinh hoàng.', 1),
(4773, 606, 'GRAMMAR', 656, 'Ví dụ 2', '彼は微動だにしなかった。', 'Anh ta không hề nhúc nhích.', 2),
(4774, 606, 'GRAMMAR', 657, 'Ví dụ 3', 'ご心配には及びません。', 'Ngài không cần phải lo ạ.', 3),
(4775, 606, 'GRAMMAR', 657, 'Ví dụ 4', '私など彼の足元にも及ばない。', 'Tôi không đáng xách dép cho anh ấy.', 4),
(4776, 607, 'LISTENING', NULL, 'Linh', '初期費用は高額ですが、三年で回収できる見込みでございます。', 'Chi phí ban đầu là lớn, nhưng dự kiến ba năm sẽ thu hồi được ạ.', 1),
(4777, 607, 'LISTENING', NULL, 'Trưởng phòng tài chính', 'その試算の前提は何に基づいていますか。', 'Tiền đề của bảng tính đó dựa trên cái gì?', 2),
(4778, 607, 'LISTENING', NULL, 'Linh', '過去二年の作業時間の実績値をもとに算出しております。', 'Tôi tính dựa trên số liệu thực tế về thời gian làm việc của hai năm qua ạ.', 3),
(4779, 607, 'LISTENING', NULL, 'Trưởng phòng tài chính', 'しかし、導入後すぐに効果が出るとは限らないでしょう。', 'Nhưng chưa chắc đưa vào là hiệu quả có ngay chứ.', 4),
(4780, 607, 'LISTENING', NULL, 'Linh', 'おっしゃるとおりです。習熟期間として半年を見込んでおります。', 'Đúng như ngài nói. Tôi đã tính nửa năm cho giai đoạn làm quen ạ.', 5),
(4781, 607, 'LISTENING', NULL, 'Trưởng phòng tài chính', '仮に効果が想定を下回った場合、どうされますか。', 'Giả sử hiệu quả thấp hơn dự tính thì ông làm thế nào?', 6),
(4782, 607, 'LISTENING', NULL, 'Linh', '一年目の時点で継続の可否を判断する条件を、あらかじめ定めております。', 'Tôi đã định sẵn điều kiện để phán xét có tiếp tục hay không tại mốc năm thứ nhất ạ.', 7),
(4783, 607, 'LISTENING', NULL, 'Trưởng phòng tài chính', 'なるほど。撤退基準まで示されているのであれば、検討に値します。', 'Ra vậy. Nếu đã nêu cả tiêu chí rút lui thì đáng để cân nhắc.', 8),
(4784, 608, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4785, 610, 'GRAMMAR', 658, 'Ví dụ 1', '自分の名前すら書けない。', 'Đến cả tên mình cũng không viết được.', 1),
(4786, 610, 'GRAMMAR', 658, 'Ví dụ 2', '専門家ですら判断できなかった。', 'Đến cả chuyên gia cũng không phán đoán được.', 2),
(4787, 610, 'GRAMMAR', 659, 'Ví dụ 3', '借金までして車を買った。', 'Anh ta vay nợ đến mức đó chỉ để mua xe.', 3),
(4788, 610, 'GRAMMAR', 659, 'Ví dụ 4', '徹夜までして仕上げた。', 'Tôi thức trắng đêm để làm cho xong.', 4),
(4789, 611, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4790, 613, 'GRAMMAR', 660, 'Ví dụ 1', '百キロからある荷物を運んだ。', 'Tôi khuân kiện hàng nặng tới cả trăm ký.', 1),
(4791, 613, 'GRAMMAR', 660, 'Ví dụ 2', 'この時計は百万円からするそうだ。', 'Nghe nói chiếc đồng hồ này giá tới cả triệu yên.', 2),
(4792, 613, 'GRAMMAR', 661, 'Ví dụ 3', '来るはずの人がまだ来ない。', 'Người lẽ ra phải đến vẫn chưa đến.', 3),
(4793, 613, 'GRAMMAR', 661, 'Ví dụ 4', 'あるはずの書類が見つからない。', 'Tài liệu lẽ ra phải có mà không tìm thấy.', 4),
(4794, 614, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4795, 616, 'GRAMMAR', 662, 'Ví dụ 1', '言ってくれれば手伝ったものを。', 'Nói với tôi thì tôi đã giúp rồi.', 1),
(4796, 616, 'GRAMMAR', 662, 'Ví dụ 2', '早く医者に行けばよかったものを。', 'Đáng lẽ đi bác sĩ sớm thì đã tốt.', 2),
(4797, 616, 'GRAMMAR', 663, 'Ví dụ 3', 'これが奇跡でなくてなんだろう。', 'Nếu đây không phải phép màu thì là gì.', 3),
(4798, 616, 'GRAMMAR', 663, 'Ví dụ 4', 'これが幸せでなくてなんだろうか。', 'Nếu đây không phải hạnh phúc thì là gì.', 4),
(4799, 617, 'LISTENING', NULL, 'Ông Fujita', '契約更新に当たり、条件を見直したいと考えております。', 'Nhân dịp gia hạn hợp đồng, chúng tôi muốn xem lại các điều kiện.', 1),
(4800, 617, 'LISTENING', NULL, 'Linh', 'ご要望を承りたく存じます。どの点でしょうか。', 'Chúng tôi xin được lắng nghe yêu cầu. Là điểm nào ạ?', 2),
(4801, 617, 'LISTENING', NULL, 'Ông Fujita', '対応時間を平日夜間まで広げていただきたいのです。', 'Chúng tôi muốn quý vị mở rộng giờ hỗ trợ tới cả buổi tối ngày thường.', 3),
(4802, 617, 'LISTENING', NULL, 'Linh', '人員体制を考えますと、現行の料金では難しいのが実情です。', 'Xét về đội hình nhân sự, thực tế là với mức phí hiện hành thì khó ạ.', 4),
(4803, 617, 'LISTENING', NULL, 'Ông Fujita', '増額もやむを得ないとは思っておりますが、上限がございます。', 'Chúng tôi cũng nghĩ tăng phí là không tránh khỏi, nhưng có giới hạn trên.', 5),
(4804, 617, 'LISTENING', NULL, 'Linh', 'でしたら、夜間は一次受付のみとする案はいかがでしょうか。', 'Vậy thì phương án buổi tối chỉ tiếp nhận sơ bộ, quý vị thấy sao ạ?', 6),
(4805, 617, 'LISTENING', NULL, 'Ông Fujita', '緊急時の対応さえ確保されるなら、それで結構です。', 'Chỉ cần đảm bảo được xử lý khi khẩn cấp thì thế là được.', 7),
(4806, 617, 'LISTENING', NULL, 'Linh', '承知いたしました。改定案を今週中にお持ちいたします。', 'Chúng tôi đã rõ ạ. Trong tuần này chúng tôi sẽ mang bản sửa đổi tới ạ.', 8),
(4807, 618, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4808, 620, 'GRAMMAR', 664, 'Ví dụ 1', 'お忙しいところをありがとうございます。', 'Cảm ơn ngài đã dành thời gian dù đang bận.', 1),
(4809, 620, 'GRAMMAR', 664, 'Ví dụ 2', 'お休みのところを申し訳ありません。', 'Xin lỗi đã làm phiền lúc ngài nghỉ.', 2),
(4810, 620, 'GRAMMAR', 665, 'Ví dụ 3', 'この作品は鑑賞に堪える。', 'Tác phẩm này đáng để thưởng lãm.', 3),
(4811, 620, 'GRAMMAR', 665, 'Ví dụ 4', '読むに堪える文章ではない。', 'Đây không phải bài viết đáng đọc.', 4),
(4812, 621, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4813, 623, 'GRAMMAR', 666, 'Ví dụ 1', '何度も注意したのに、とうとう喧嘩する始末だ。', 'Nhắc bao lần rồi mà rốt cuộc còn đánh nhau.', 1),
(4814, 623, 'GRAMMAR', 666, 'Ví dụ 2', '借金までする始末だった。', 'Rốt cuộc đến mức phải đi vay nợ.', 2),
(4815, 623, 'GRAMMAR', 667, 'Ví dụ 3', '理由のいかんにかかわらず返金はできません。', 'Bất kể lý do gì cũng không hoàn tiền.', 3),
(4816, 623, 'GRAMMAR', 667, 'Ví dụ 4', '天候のいかんにかかわらず決行する。', 'Bất kể thời tiết thế nào cũng tiến hành.', 4),
(4817, 624, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4818, 626, 'GRAMMAR', 668, 'Ví dụ 1', 'ご成功を願ってやみません。', 'Tôi tha thiết chúc ngài thành công.', 1),
(4819, 626, 'GRAMMAR', 668, 'Ví dụ 2', '彼が愛してやまない故郷だ。', 'Đó là quê hương mà anh ấy yêu tha thiết.', 2),
(4820, 626, 'GRAMMAR', 669, 'Ví dụ 3', '彼の実力をもってすれば、優勝も可能だ。', 'Với thực lực của anh ấy thì vô địch cũng khả thi.', 3),
(4821, 626, 'GRAMMAR', 669, 'Ví dụ 4', '現代の技術をもってすれば解決できる。', 'Với công nghệ hiện đại thì giải quyết được.', 4),
(4822, 627, 'LISTENING', NULL, 'Linh', '三年後に売上を一・五倍とする計画をご説明いたします。', 'Tôi xin trình bày kế hoạch đưa doanh thu lên gấp một phẩy năm lần sau ba năm.', 1),
(4823, 627, 'LISTENING', NULL, 'Thành viên ban lãnh đạo', 'その根拠となる市場予測は、どこの数字ですか。', 'Dự báo thị trường làm căn cứ cho điều đó là số liệu của đâu?', 2),
(4824, 627, 'LISTENING', NULL, 'Linh', '外部調査会社の公開資料と、自社の受注実績を突き合わせております。', 'Tôi đối chiếu tài liệu công khai của công ty khảo sát bên ngoài với số liệu đơn hàng của ta.', 3),
(4825, 627, 'LISTENING', NULL, 'Thành viên ban lãnh đạo', '人員の増強なくして、その数字は達成し得ないのではないですか。', 'Không tăng cường nhân sự thì chẳng phải con số đó không thể đạt được sao?', 4),
(4826, 627, 'LISTENING', NULL, 'Linh', 'ご指摘のとおりです。二年目に十名の増員を織り込んでおります。', 'Đúng như ngài chỉ ra. Tôi đã tính vào việc tăng mười người ở năm thứ hai ạ.', 5),
(4827, 627, 'LISTENING', NULL, 'Thành viên ban lãnh đạo', '採用が計画どおりに進まない可能性もあるでしょう。', 'Cũng có khả năng tuyển dụng không diễn ra đúng kế hoạch chứ.', 6),
(4828, 627, 'LISTENING', NULL, 'Linh', 'その場合に備え、外部委託を併用する案も用意しております。', 'Phòng cho trường hợp đó, tôi cũng chuẩn bị phương án dùng kèm thuê ngoài ạ.', 7),
(4829, 627, 'LISTENING', NULL, 'Thành viên ban lãnh đạo', '分かりました。次回は資金繰りの見通しも併せて示してください。', 'Tôi hiểu rồi. Lần tới hãy trình bày kèm cả dự báo dòng tiền.', 8),
(4830, 628, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4831, 630, 'GRAMMAR', 670, 'Ví dụ 1', 'お会いできてうれしい限りです。', 'Được gặp ngài tôi thật vô cùng vui.', 1),
(4832, 630, 'GRAMMAR', 670, 'Ví dụ 2', '一人で心細い限りだ。', 'Một mình thật là bất an vô cùng.', 2),
(4833, 630, 'GRAMMAR', 671, 'Ví dụ 3', '子供ではあるまいし、自分でやりなさい。', 'Đâu còn là trẻ con, tự làm đi.', 3),
(4834, 630, 'GRAMMAR', 671, 'Ví dụ 4', '初めてではあるまいし、落ち着いて。', 'Đâu phải lần đầu, bình tĩnh nào.', 4),
(4835, 631, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4836, 633, 'GRAMMAR', 672, 'Ví dụ 1', '彼は物事を悲観的に考えるきらいがある。', 'Anh ấy có khuynh hướng nghĩ bi quan về mọi việc.', 1),
(4837, 633, 'GRAMMAR', 672, 'Ví dụ 2', '最近の若者は本を読まないきらいがある。', 'Giới trẻ gần đây có xu hướng không đọc sách.', 2),
(4838, 633, 'GRAMMAR', 673, 'Ví dụ 3', '参加者はせいぜい十人といったところだ。', 'Cùng lắm cũng chỉ khoảng mười người.', 3),
(4839, 633, 'GRAMMAR', 673, 'Ví dụ 4', '収入は月二十万といったところです。', 'Thu nhập cùng lắm khoảng hai mươi vạn một tháng.', 4),
(4840, 634, 'READING', NULL, 'Danh sách từ vựng', '69 từ.', NULL, 1),
(4841, 636, 'GRAMMAR', 674, 'Ví dụ 1', '東京公演を皮切りに、全国ツアーが始まった。', 'Mở màn bằng buổi diễn ở Tokyo, tour toàn quốc bắt đầu.', 1),
(4842, 636, 'GRAMMAR', 674, 'Ví dụ 2', '彼の発言を皮切りに議論が白熱した。', 'Từ phát biểu của anh ta, tranh luận nóng lên.', 2),
(4843, 636, 'GRAMMAR', 675, 'Ví dụ 3', '思い出の品なので捨てるに忍びない。', 'Là kỷ vật nên tôi không nỡ vứt.', 3),
(4844, 636, 'GRAMMAR', 675, 'Ví dụ 4', 'その姿は見るに忍びなかった。', 'Cảnh ấy tôi không nỡ nhìn.', 4),
(4845, 637, 'READING', NULL, 'Danh sách từ vựng', '20 từ thuộc nhóm Yêu cầu & thiết kế.', NULL, 1),
(4846, 638, 'READING', NULL, 'Danh sách từ vựng', '30 từ thuộc nhóm Phát triển & lập trình.', NULL, 1),
(4847, 639, 'READING', NULL, 'Danh sách từ vựng', '18 từ thuộc nhóm Kiểm thử.', NULL, 1),
(4848, 640, 'READING', NULL, 'Danh sách từ vựng', '17 từ thuộc nhóm Lỗi & chất lượng.', NULL, 1),
(4849, 641, 'READING', NULL, 'Danh sách từ vựng', '18 từ thuộc nhóm Môi trường & vận hành.', NULL, 1),
(4850, 642, 'READING', NULL, 'Danh sách từ vựng', '17 từ thuộc nhóm Quản lý dự án.', NULL, 1),
(4851, 643, 'READING', NULL, 'Danh sách từ vựng', '20 từ thuộc nhóm Giao tiếp công việc.', NULL, 1),
(4852, 644, 'LISTENING', NULL, 'グエン', '初めまして。VJソリューションズのグエンと申します。本プロジェクトでブリッジSEを担当いたします。', 'Xin chào, rất vui được gặp anh. Tôi là Nguyễn của VJ Solutions. Tôi sẽ phụ trách vai trò BrSE cho dự án này.', 1),
(4853, 644, 'LISTENING', NULL, 'グエン', 'こちら、私の名刺です。どうぞよろしくお願いいたします。', 'Đây là danh thiếp của tôi. Rất mong được anh giúp đỡ.', 2),
(4854, 644, 'LISTENING', NULL, '田中', 'ご丁寧にありがとうございます。ミライテックの田中です。こちらこそ、よろしくお願いします。', 'Cảm ơn anh đã chu đáo. Tôi là Tanaka của Miraitech. Tôi cũng mong được hợp tác.', 3),
(4855, 644, 'LISTENING', NULL, '田中', 'グエンさんは日本語がお上手ですね。日本にいらっしゃったことはありますか。', 'Anh Nguyễn nói tiếng Nhật giỏi quá. Anh đã từng sang Nhật chưa?', 4),
(4856, 644, 'LISTENING', NULL, 'グエン', 'ありがとうございます。まだまだ勉強中です。以前、日本のお客様向けのプロジェクトに参加しておりました。', 'Cảm ơn anh. Tôi vẫn còn đang học. Trước đây tôi từng tham gia dự án cho khách hàng Nhật.', 5),
(4857, 644, 'LISTENING', NULL, '田中', 'そうですか。心強いです。開発チームはダナンにあるんですよね。', 'Vậy à, thế thì yên tâm quá. Đội phát triển ở Đà Nẵng phải không?', 6),
(4858, 644, 'LISTENING', NULL, 'グエン', 'はい、ダナンに十名のチームがおります。私が窓口となって、仕様の確認や進捗のご報告をさせていただきます。', 'Vâng, ở Đà Nẵng có đội 10 người. Tôi sẽ làm đầu mối, xác nhận đặc tả và báo cáo tiến độ cho anh.', 7),
(4859, 644, 'LISTENING', NULL, '田中', 'わかりました。では、今後の連絡はグエンさんにお願いすればいいですね。', 'Tôi hiểu rồi. Vậy từ giờ tôi liên lạc với anh Nguyễn là được nhỉ.', 8),
(4860, 644, 'LISTENING', NULL, 'グエン', 'はい。何かございましたら、いつでもご連絡ください。', 'Vâng. Nếu có việc gì, anh cứ liên lạc với tôi bất cứ lúc nào.', 9),
(4861, 646, 'LISTENING', NULL, 'グエン', 'お電話ありがとうございます。VJソリューションズのグエンでございます。', 'Cảm ơn quý khách đã gọi. Nguyễn của VJ Solutions xin nghe.', 1),
(4862, 646, 'LISTENING', NULL, '田中', 'ミライテックの田中です。いつもお世話になっております。', 'Tôi là Tanaka của Miraitech. Cảm ơn anh vì sự hỗ trợ thường ngày.', 2),
(4863, 646, 'LISTENING', NULL, 'グエン', 'こちらこそ、いつもお世話になっております。', 'Chúng tôi mới là người phải cảm ơn anh.', 3),
(4864, 646, 'LISTENING', NULL, '田中', 'プロジェクトマネージャーのファムさんはいらっしゃいますか。', 'Anh Phạm, quản lý dự án, có ở đó không?', 4),
(4865, 646, 'LISTENING', NULL, 'グエン', '申し訳ございません。ファムはただいま会議中でございます。11時には終わる予定です。', 'Thành thật xin lỗi, anh Phạm hiện đang họp. Dự kiến 11 giờ sẽ xong.', 5),
(4866, 646, 'LISTENING', NULL, 'グエン', '会議が終わり次第、折り返しお電話を差し上げるよう、申し伝えましょうか。', 'Tôi nhắn anh ấy họp xong sẽ gọi lại cho anh nhé?', 6),
(4867, 646, 'LISTENING', NULL, '田中', 'はい、お願いします。明日のリリースの件でご相談したいことがあると伝えてください。', 'Vâng, nhờ anh. Anh nhắn giúp là tôi muốn trao đổi về đợt release ngày mai.', 7),
(4868, 646, 'LISTENING', NULL, 'グエン', 'かしこまりました。明日のリリースの件ですね。念のため、お電話番号をお伺いしてもよろしいでしょうか。', 'Tôi hiểu rồi. Về đợt release ngày mai ạ. Để chắc chắn, cho tôi xin số điện thoại của anh được không?', 8),
(4869, 646, 'LISTENING', NULL, '田中', '03-1234-5678です。', 'Số của tôi là 03-1234-5678.', 9),
(4870, 646, 'LISTENING', NULL, 'グエン', '03-1234-5678、ミライテックの田中様ですね。確かに申し伝えます。私、グエンが承りました。', '03-1234-5678, anh Tanaka của Miraitech. Tôi chắc chắn sẽ chuyển lời. Tôi là Nguyễn đã nhận lời nhắn.', 10),
(4871, 646, 'LISTENING', NULL, '田中', 'よろしくお願いします。', 'Nhờ anh nhé.', 11),
(4872, 646, 'LISTENING', NULL, 'グエン', '失礼いたします。', 'Xin phép anh.', 12),
(4873, 648, 'LISTENING', NULL, 'グエン', '田中様、仕様書の件で一点確認させていただきたいのですが、今お時間よろしいでしょうか。', 'Anh Tanaka, tôi muốn xác nhận một điểm trong tài liệu đặc tả, bây giờ anh có tiện không ạ?', 1),
(4874, 648, 'LISTENING', NULL, '田中', 'はい、どうぞ。', 'Vâng, anh cứ nói.', 2),
(4875, 648, 'LISTENING', NULL, 'グエン', '画面設計書の3ページ目、ログイン画面についてです。パスワードを5回間違えるとアカウントをロックすると書かれていますが、ロックの解除方法について記載がございません。', 'Về màn hình đăng nhập ở trang 3 của tài liệu thiết kế màn hình. Tài liệu ghi nhập sai mật khẩu 5 lần sẽ khóa tài khoản, nhưng không ghi cách mở khóa.', 3),
(4876, 648, 'LISTENING', NULL, '田中', 'ああ、そこは抜けていましたね。', 'À, chỗ đó bị sót thật.', 4),
(4877, 648, 'LISTENING', NULL, 'グエン', '一定時間が経過したら自動で解除する方式と、管理者が手動で解除する方式が考えられますが、どちらをご想定でしょうか。', 'Có thể tự động mở khóa sau một khoảng thời gian, hoặc để quản trị viên mở khóa thủ công. Anh đang hình dung theo cách nào ạ?', 5),
(4878, 648, 'LISTENING', NULL, '田中', '30分後に自動で解除する形でお願いします。管理者による解除も、念のため入れておいてください。', 'Làm theo kiểu tự động mở khóa sau 30 phút. Cho thêm cả chức năng quản trị viên mở khóa để phòng hờ.', 6),
(4879, 648, 'LISTENING', NULL, 'グエン', '承知いたしました。30分後の自動解除と、管理者による手動解除の両方を実装する、ということでよろしいでしょうか。', 'Tôi hiểu rồi. Vậy là triển khai cả tự động mở khóa sau 30 phút lẫn quản trị viên mở khóa thủ công, đúng không ạ?', 7),
(4880, 648, 'LISTENING', NULL, '田中', 'はい、それで結構です。', 'Vâng, như vậy là được.', 8),
(4881, 648, 'LISTENING', NULL, 'グエン', 'ありがとうございます。認識齟齬を防ぐため、本日中にQ&A表に記載してお送りいたします。', 'Cảm ơn anh. Để tránh hiểu sai, trong hôm nay tôi sẽ ghi vào bảng Q&A và gửi anh.', 9),
(4882, 648, 'LISTENING', NULL, '田中', '助かります。', 'Vậy thì tốt quá.', 10),
(4883, 650, 'LISTENING', NULL, 'グエン', 'それでは、今週の進捗をご報告いたします。', 'Sau đây tôi xin báo cáo tiến độ tuần này.', 1),
(4884, 650, 'LISTENING', NULL, 'グエン', '会員登録機能は予定どおり完了し、現在、単体テストを実施中です。', 'Chức năng đăng ký thành viên đã hoàn thành đúng kế hoạch, hiện đang chạy unit test.', 2),
(4885, 650, 'LISTENING', NULL, 'グエン', '一方、決済機能については、外部APIの仕様確認に時間がかかったため、進捗は予定の70%程度にとどまっております。', 'Ngược lại, chức năng thanh toán mất thời gian xác nhận đặc tả API bên ngoài nên tiến độ mới đạt khoảng 70% kế hoạch.', 3),
(4886, 650, 'LISTENING', NULL, '田中', '全体のスケジュールには影響がありそうですか。', 'Có ảnh hưởng tới lịch trình tổng thể không?', 4),
(4887, 650, 'LISTENING', NULL, 'グエン', '現時点では、来週の作業で遅れを取り戻せる見込みです。ただ、APIの接続テストで問題が出た場合は、2日ほど遅れる可能性がございます。', 'Hiện tại dự kiến tuần sau sẽ bắt kịp. Tuy nhiên, nếu test kết nối API phát sinh vấn đề thì có khả năng chậm khoảng 2 ngày.', 5),
(4888, 650, 'LISTENING', NULL, '田中', 'わかりました。リスクがはっきりした時点で、早めに教えてください。', 'Tôi hiểu rồi. Khi rủi ro rõ ràng thì báo sớm cho tôi nhé.', 6),
(4889, 650, 'LISTENING', NULL, 'グエン', '承知いたしました。水曜日の時点で状況を確認し、改めてご報告いたします。', 'Vâng. Đến thứ Tư tôi sẽ kiểm tra tình hình và báo cáo lại.', 7),
(4890, 652, 'LISTENING', NULL, 'グエン', '田中様、大変申し上げにくいのですが、テスト工程の件でご報告がございます。', 'Anh Tanaka, thật khó nói nhưng tôi có việc cần báo cáo về giai đoạn test.', 1),
(4891, 652, 'LISTENING', NULL, '田中', '何かありましたか。', 'Có chuyện gì vậy?', 2),
(4892, 652, 'LISTENING', NULL, 'グエン', '結合テストで想定以上の不具合が見つかり、修正に時間を要しております。そのため、納品日を当初の15日から18日に変更させていただけないでしょうか。', 'Test tích hợp phát hiện nhiều lỗi hơn dự kiến, việc sửa đang tốn thời gian. Vì vậy, cho phép chúng tôi lùi ngày bàn giao từ ngày 15 như ban đầu sang ngày 18 được không ạ?', 3),
(4893, 652, 'LISTENING', NULL, '田中', '3日遅れですか。こちらもユーザーへの説明があるので、正直困りますね。', 'Chậm 3 ngày à. Bên tôi còn phải giải thích với người dùng, nói thật là khó xử.', 4),
(4894, 652, 'LISTENING', NULL, 'グエン', 'ご迷惑をおかけして、誠に申し訳ございません。', 'Chúng tôi thành thật xin lỗi vì đã gây phiền phức.', 5),
(4895, 652, 'LISTENING', NULL, 'グエン', '原因は、仕様変更の影響範囲の調査が不十分だったことです。今後は、変更のたびに影響範囲をチェックリストで確認するよう、チームで徹底いたします。', 'Nguyên nhân là việc khảo sát phạm vi ảnh hưởng của thay đổi đặc tả chưa đầy đủ. Từ nay, mỗi lần thay đổi, cả đội sẽ kiểm tra phạm vi ảnh hưởng bằng checklist một cách triệt để.', 6),
(4896, 652, 'LISTENING', NULL, '田中', '15日に一部だけでも納品することはできますか。', 'Ngày 15 có thể bàn giao dù chỉ một phần được không?', 7),
(4897, 652, 'LISTENING', NULL, 'グエン', 'はい、ログイン機能と会員管理機能であれば、15日に納品可能です。残りの機能を18日に納品する形でいかがでしょうか。', 'Vâng, nếu là chức năng đăng nhập và quản lý thành viên thì ngày 15 có thể bàn giao. Phần còn lại bàn giao ngày 18, anh thấy thế nào ạ?', 8),
(4898, 652, 'LISTENING', NULL, '田中', 'では、それでお願いします。修正の状況は毎日共有してください。', 'Vậy làm như thế. Tình hình sửa lỗi thì chia sẻ cho tôi hằng ngày nhé.', 9),
(4899, 652, 'LISTENING', NULL, 'グエン', 'かしこまりました。毎日夕方に進捗をメールでご報告いたします。', 'Vâng. Chiều nào tôi cũng sẽ báo cáo tiến độ qua email.', 10),
(4900, 654, 'LISTENING', NULL, '田中', 'グエンさん、検証環境で確認していたら、検索結果が正しく表示されないんですが。', 'Anh Nguyễn, tôi kiểm tra trên môi trường staging thì thấy kết quả tìm kiếm hiển thị không đúng.', 1),
(4901, 654, 'LISTENING', NULL, 'グエン', 'ご報告ありがとうございます。恐れ入りますが、再現手順を教えていただけますか。', 'Cảm ơn anh đã báo. Phiền anh cho tôi biết các bước tái hiện lỗi được không ạ?', 2),
(4902, 654, 'LISTENING', NULL, '田中', '商品名に長音記号の「ー」を含むキーワードで検索すると、結果が0件になります。', 'Tìm bằng từ khóa có dấu trường âm 「ー」 trong tên sản phẩm thì kết quả ra 0.', 3),
(4903, 654, 'LISTENING', NULL, 'グエン', '長音を含む場合ですね。ほかの条件では正常に表示されますか。', 'Trường hợp có trường âm ạ. Với điều kiện khác thì hiển thị bình thường chứ ạ?', 4),
(4904, 654, 'LISTENING', NULL, '田中', 'はい、それ以外は問題ありません。', 'Vâng, ngoài trường hợp đó thì không có vấn đề gì.', 5),
(4905, 654, 'LISTENING', NULL, 'グエン', '承知いたしました。すぐに開発チームに調査を依頼し、本日の17時までに原因と対応方針をご連絡いたします。', 'Tôi hiểu rồi. Tôi sẽ nhờ đội phát triển điều tra ngay, trước 17 giờ hôm nay sẽ báo anh nguyên nhân và hướng xử lý.', 6),
(4906, 654, 'LISTENING', NULL, '田中', '本番リリースに影響はありますか。', 'Có ảnh hưởng tới release production không?', 7),
(4907, 654, 'LISTENING', NULL, 'グエン', '原因が判明した段階で、影響の有無も含めてご報告いたします。お急ぎのところ恐縮ですが、少々お待ちいただけますでしょうか。', 'Khi xác định được nguyên nhân, tôi sẽ báo cáo cả việc có ảnh hưởng hay không. Biết anh đang gấp nhưng mong anh chờ một chút ạ.', 8),
(4908, 654, 'LISTENING', NULL, '田中', 'わかりました。お願いします。', 'Được rồi, nhờ anh.', 9),
(4909, 656, 'LISTENING', NULL, '田中', '実は、ユーザーから要望があって、CSVでデータを出力する機能を追加してほしいんです。', 'Thật ra người dùng có yêu cầu, tôi muốn thêm chức năng xuất dữ liệu ra CSV.', 1),
(4910, 656, 'LISTENING', NULL, 'グエン', 'CSV出力機能の追加ですね。対象となる画面とデータの項目を教えていただけますか。', 'Thêm chức năng xuất CSV ạ. Anh cho tôi biết màn hình và các trường dữ liệu cần xuất được không?', 2),
(4911, 656, 'LISTENING', NULL, '田中', '注文一覧の画面で、表示されている項目をそのまま出力できればいいです。', 'Ở màn hình danh sách đơn hàng, xuất nguyên các cột đang hiển thị là được.', 3),
(4912, 656, 'LISTENING', NULL, 'グエン', '承知いたしました。ただ、現在の開発範囲外の作業となりますので、工数とスケジュールへの影響を見積もらせていただきたいと思います。', 'Tôi hiểu rồi. Tuy nhiên đây là công việc ngoài phạm vi phát triển hiện tại, nên chúng tôi xin phép ước tính công số và ảnh hưởng tới lịch trình.', 4),
(4913, 656, 'LISTENING', NULL, '田中', 'どのくらいかかりそうですか。', 'Có vẻ mất khoảng bao lâu?', 5),
(4914, 656, 'LISTENING', NULL, 'グエン', '開発チームと確認のうえ、明日中に見積もりをご提出いたします。あわせて、今回のリリースに含めるか、次回に回すかもご相談させてください。', 'Sau khi trao đổi với đội phát triển, trong ngày mai tôi sẽ gửi bản ước tính. Đồng thời cho tôi trao đổi luôn việc đưa vào đợt release này hay dời sang đợt sau.', 6),
(4915, 656, 'LISTENING', NULL, '田中', 'わかりました。見積もりを見てから判断します。', 'Được. Tôi xem bản ước tính rồi sẽ quyết định.', 7),
(4916, 658, 'LISTENING', NULL, 'グエン', '来週、要件定義のレビュー会議をお願いしたいのですが、ご都合はいかがでしょうか。', 'Tuần sau tôi muốn xin một buổi họp review định nghĩa yêu cầu, lịch của anh thế nào ạ?', 1),
(4917, 658, 'LISTENING', NULL, '田中', '来週ですか。火曜と木曜の午後なら空いています。', 'Tuần sau à. Chiều thứ Ba và thứ Năm thì tôi rảnh.', 2),
(4918, 658, 'LISTENING', NULL, 'グエン', 'ありがとうございます。では、木曜日の15時からはいかがでしょうか。1時間ほどを予定しております。', 'Cảm ơn anh. Vậy từ 15 giờ thứ Năm có được không ạ? Dự kiến khoảng 1 tiếng.', 3),
(4919, 658, 'LISTENING', NULL, '田中', '木曜の15時ですね。大丈夫です。', '15 giờ thứ Năm nhỉ. Được.', 4),
(4920, 658, 'LISTENING', NULL, 'グエン', '日本時間の15時ですと、ベトナムは13時になりますので、開発チームも参加できます。', '15 giờ giờ Nhật là 13 giờ ở Việt Nam, nên đội phát triển cũng tham gia được.', 5),
(4921, 658, 'LISTENING', NULL, 'グエン', '後ほど、会議のURLと資料をお送りいたします。', 'Lát nữa tôi sẽ gửi anh link họp và tài liệu.', 6),
(4922, 658, 'LISTENING', NULL, '田中', '資料は事前にいただけると助かります。', 'Nếu gửi tài liệu trước thì tốt quá.', 7),
(4923, 658, 'LISTENING', NULL, 'グエン', 'かしこまりました。前日までにお送りいたします。', 'Vâng. Tôi sẽ gửi trước một ngày.', 8),
(4924, 660, 'LISTENING', NULL, 'グエン', '田中様、一つお願いがあるのですが。', 'Anh Tanaka, tôi có một việc muốn nhờ.', 1),
(4925, 660, 'LISTENING', NULL, '田中', 'はい、何でしょう。', 'Vâng, việc gì vậy?', 2),
(4926, 660, 'LISTENING', NULL, 'グエン', '来週から結合テストを始める予定なのですが、テスト用のアカウントがまだ発行されておりません。', 'Tuần sau chúng tôi dự định bắt đầu test tích hợp, nhưng tài khoản test vẫn chưa được cấp.', 3),
(4927, 660, 'LISTENING', NULL, 'グエン', 'お忙しいところ恐縮ですが、金曜日までに5名分発行していただくことは可能でしょうか。', 'Biết anh đang bận, nhưng trước thứ Sáu anh có thể cấp giúp 5 tài khoản được không ạ?', 4),
(4928, 660, 'LISTENING', NULL, '田中', 'ああ、すみません、忘れていました。今日中に手配します。', 'À, xin lỗi, tôi quên mất. Trong hôm nay tôi sẽ sắp xếp.', 5),
(4929, 660, 'LISTENING', NULL, 'グエン', 'ありがとうございます。お手数をおかけしますが、よろしくお願いいたします。', 'Cảm ơn anh. Làm phiền anh, rất mong anh giúp đỡ.', 6),
(4930, 662, 'LISTENING', NULL, 'グエン', '最後に、本日の決定事項を確認させていただきます。', 'Cuối cùng, cho phép tôi xác nhận lại các nội dung đã quyết định hôm nay.', 1),
(4931, 662, 'LISTENING', NULL, 'グエン', '一点目、アカウントのロックは30分後に自動で解除します。二点目、CSV出力機能の見積もりを、明日中に弊社から提出いたします。', 'Thứ nhất, tài khoản bị khóa sẽ tự động mở sau 30 phút. Thứ hai, trong ngày mai công ty chúng tôi sẽ gửi bản ước tính chức năng xuất CSV.', 2),
(4932, 662, 'LISTENING', NULL, '田中', 'はい、それで合っています。', 'Vâng, đúng như vậy.', 3),
(4933, 662, 'LISTENING', NULL, 'グエン', '議事録は本日中に作成して共有いたします。内容に相違がございましたら、ご指摘ください。', 'Trong hôm nay tôi sẽ soạn biên bản họp và chia sẻ. Nếu nội dung có chỗ sai lệch, mong anh chỉ ra giúp.', 4),
(4934, 662, 'LISTENING', NULL, '田中', 'お願いします。', 'Nhờ anh.', 5),
(4935, 662, 'LISTENING', NULL, 'グエン', '本日はお忙しいところ、お時間をいただきありがとうございました。', 'Cảm ơn anh hôm nay đã dành thời gian dù rất bận.', 6),
(4936, 662, 'LISTENING', NULL, '田中', 'こちらこそ、ありがとうございました。', 'Tôi cũng cảm ơn anh.', 7),
(4937, 664, 'LISTENING', NULL, '田中', 'プルリクエストを確認しました。何点か指摘があります。', 'Tôi đã xem pull request. Có vài điểm cần góp ý.', 1),
(4938, 664, 'LISTENING', NULL, 'グエン', 'ありがとうございます。お願いいたします。', 'Cảm ơn anh. Anh cứ nói ạ.', 2),
(4939, 664, 'LISTENING', NULL, '田中', 'まず、ログイン処理で例外が発生した場合、エラーログが出力されていません。', 'Trước tiên, khi xử lý đăng nhập phát sinh ngoại lệ thì không có log lỗi nào được ghi ra.', 3),
(4940, 664, 'LISTENING', NULL, 'グエン', 'ご指摘ありがとうございます。例外処理の中でログを出力するよう修正いたします。', 'Cảm ơn anh đã chỉ ra. Tôi sẽ sửa để ghi log trong phần xử lý ngoại lệ.', 4),
(4941, 664, 'LISTENING', NULL, '田中', 'それから、同じ入力チェックが3つの画面に書かれていますね。共通化できませんか。', 'Ngoài ra, cùng một đoạn kiểm tra đầu vào được viết ở 3 màn hình. Gom lại dùng chung được không?', 5),
(4942, 664, 'LISTENING', NULL, 'グエン', 'おっしゃるとおりです。共通のバリデーションクラスにまとめます。影響範囲を確認したうえで、既存画面の回帰テストも実施いたします。', 'Anh nói đúng ạ. Tôi sẽ gom vào một class validation dùng chung. Sau khi xác nhận phạm vi ảnh hưởng, tôi sẽ chạy cả test hồi quy cho các màn hình hiện có.', 6),
(4943, 664, 'LISTENING', NULL, '田中', 'お願いします。修正が終わったら、再レビューを依頼してください。', 'Nhờ anh. Sửa xong thì gửi yêu cầu review lại nhé.', 7),
(4944, 664, 'LISTENING', NULL, 'グエン', '承知いたしました。本日中に修正して、再レビューを依頼いたします。', 'Vâng. Trong hôm nay tôi sẽ sửa xong và gửi yêu cầu review lại.', 8),
(4945, 666, 'LISTENING', NULL, 'グエン', '結合テストの結果をご報告いたします。', 'Tôi xin báo cáo kết quả test tích hợp.', 1),
(4946, 666, 'LISTENING', NULL, 'グエン', 'テストケース全420件のうち412件を消化し、合格は398件、不合格は14件でした。', 'Trong tổng số 420 test case, đã thực hiện 412 case, đạt 398 case và không đạt 14 case.', 2),
(4947, 666, 'LISTENING', NULL, '田中', '残りの8件はどうなっていますか。', 'Còn 8 case còn lại thì sao?', 3),
(4948, 666, 'LISTENING', NULL, 'グエン', '外部システムとの接続が必要なケースで、先方の検証環境が準備でき次第、実施する予定です。', 'Đó là các case cần kết nối với hệ thống bên ngoài, chúng tôi sẽ thực hiện ngay khi môi trường staging phía đối tác sẵn sàng.', 4),
(4949, 666, 'LISTENING', NULL, '田中', '不合格の14件の内訳を教えてください。', 'Cho tôi biết chi tiết 14 case không đạt.', 5),
(4950, 666, 'LISTENING', NULL, 'グエン', '重大度「高」が2件、「中」が5件、「低」が7件です。「高」の2件は明日までに修正し、再テストいたします。', 'Mức độ nghiêm trọng ''cao'' 2 case, ''trung bình'' 5 case, ''thấp'' 7 case. 2 case mức ''cao'' sẽ được sửa và test lại trước ngày mai.', 6),
(4951, 666, 'LISTENING', NULL, '田中', 'わかりました。エビデンスも一緒に送ってください。', 'Tôi hiểu rồi. Gửi kèm cả bằng chứng test nhé.', 7),
(4952, 666, 'LISTENING', NULL, 'グエン', 'かしこまりました。テスト結果報告書とエビデンスをまとめて、本日中にお送りいたします。', 'Vâng. Trong hôm nay tôi sẽ tổng hợp báo cáo kết quả test và bằng chứng rồi gửi anh.', 8),
(4953, 668, 'LISTENING', NULL, 'グエン', '田中様、至急ご報告いたします。本日10時頃から、本番環境で決済処理がエラーになる障害が発生しております。', 'Anh Tanaka, tôi xin báo cáo gấp. Từ khoảng 10 giờ hôm nay, môi trường production đang gặp sự cố xử lý thanh toán bị lỗi.', 1),
(4954, 668, 'LISTENING', NULL, '田中', 'えっ、ユーザーへの影響はどのくらいですか。', 'Hả, ảnh hưởng tới người dùng cỡ nào?', 2),
(4955, 668, 'LISTENING', NULL, 'グエン', '現時点で、決済を試みたユーザーのうち約3割がエラーになっております。', 'Hiện tại, khoảng 30% người dùng thực hiện thanh toán bị lỗi.', 3),
(4956, 668, 'LISTENING', NULL, 'グエン', '原因は調査中ですが、今朝のリリースで更新した設定ファイルが関係している可能性が高いと見ております。', 'Nguyên nhân đang được điều tra, nhưng chúng tôi cho rằng khả năng cao liên quan tới file cấu hình được cập nhật trong đợt release sáng nay.', 4),
(4957, 668, 'LISTENING', NULL, '田中', 'すぐに戻せますか。', 'Quay lại ngay được không?', 5),
(4958, 668, 'LISTENING', NULL, 'グエン', 'はい。暫定対応として、30分以内にリリース前の状態に戻す予定です。ご承認いただけますでしょうか。', 'Vâng. Để xử lý tạm thời, chúng tôi dự định đưa về trạng thái trước release trong vòng 30 phút. Anh có thể phê duyệt được không ạ?', 6),
(4959, 668, 'LISTENING', NULL, '田中', 'お願いします。すぐに進めてください。', 'Nhờ anh. Tiến hành ngay đi.', 7),
(4960, 668, 'LISTENING', NULL, 'グエン', '承知いたしました。復旧を確認しましたら、改めてご連絡いたします。恒久対応と再発防止策は、原因が判明した段階でご報告いたします。', 'Vâng. Khi xác nhận đã khôi phục, tôi sẽ liên lạc lại. Hướng xử lý triệt để và biện pháp phòng tái phát sẽ báo cáo khi xác định được nguyên nhân.', 8),
(4961, 670, 'LISTENING', NULL, 'グエン', '明日のリリースに向けて、最終確認をさせていただきます。', 'Tôi xin xác nhận lần cuối cho đợt release ngày mai.', 1),
(4962, 670, 'LISTENING', NULL, 'グエン', 'リリース手順書は昨日お送りしたとおりで、作業は明日の22時から24時を予定しております。', 'Tài liệu thao tác release như đã gửi hôm qua, dự kiến làm từ 22 giờ đến 24 giờ ngày mai.', 2),
(4963, 670, 'LISTENING', NULL, '田中', '作業中、サービスは止まりますか。', 'Trong lúc làm, dịch vụ có bị dừng không?', 3),
(4964, 670, 'LISTENING', NULL, 'グエン', 'はい、22時から約1時間、サービスを停止いたします。停止のお知らせを、本日中にユーザーへ掲載していただけますでしょうか。', 'Vâng, dịch vụ sẽ dừng khoảng 1 tiếng từ 22 giờ. Anh có thể đăng thông báo dừng dịch vụ tới người dùng trong hôm nay được không ạ?', 4),
(4965, 670, 'LISTENING', NULL, '田中', 'わかりました。こちらで対応します。', 'Được. Bên tôi sẽ lo.', 5),
(4966, 670, 'LISTENING', NULL, 'グエン', '万が一問題が発生した場合は、切り戻し手順に従って元のバージョンに戻します。判断の期限は23時30分とさせていただきます。', 'Nếu chẳng may có vấn đề, chúng tôi sẽ quay về phiên bản cũ theo quy trình rollback. Thời hạn ra quyết định là 23 giờ 30.', 6),
(4967, 670, 'LISTENING', NULL, '田中', '了解です。何かあったら、夜中でも連絡してください。', 'Rõ. Có chuyện gì thì nửa đêm cũng cứ liên lạc.', 7),
(4968, 670, 'LISTENING', NULL, 'グエン', 'かしこまりました。作業完了後、結果をメールでご報告いたします。', 'Vâng. Làm xong tôi sẽ báo kết quả qua email.', 8),
(4969, 672, 'READING', NULL, 'Danh sách từ vựng', '20 từ thuộc nhóm Sân bay & xuất nhập cảnh.', NULL, 1),
(4970, 673, 'READING', NULL, 'Danh sách từ vựng', '18 từ thuộc nhóm Tàu xe & di chuyển.', NULL, 1),
(4971, 674, 'READING', NULL, 'Danh sách từ vựng', '15 từ thuộc nhóm Lưu trú.', NULL, 1),
(4972, 675, 'READING', NULL, 'Danh sách từ vựng', '14 từ thuộc nhóm Ăn uống.', NULL, 1),
(4973, 676, 'READING', NULL, 'Danh sách từ vựng', '13 từ thuộc nhóm Mua sắm.', NULL, 1),
(4974, 677, 'READING', NULL, 'Danh sách từ vựng', '14 từ thuộc nhóm Hỏi đường & sự cố.', NULL, 1),
(4975, 678, 'LISTENING', NULL, '係員', 'おはようございます。パスポートと予約番号をお願いします。', 'Chào anh. Cho tôi xin hộ chiếu và mã đặt chỗ ạ.', 1),
(4976, 678, 'LISTENING', NULL, 'リン', 'はい、これです。窓側の席は空いていますか。', 'Vâng, đây ạ. Còn ghế cạnh cửa sổ không ạ?', 2),
(4977, 678, 'LISTENING', NULL, '係員', '前方でしたら一席ご用意できます。', 'Nếu ở phía trước thì tôi có thể sắp một ghế ạ.', 3),
(4978, 678, 'LISTENING', NULL, 'リン', 'お願いします。預ける荷物は一つです。', 'Cho tôi ghế đó ạ. Tôi gửi một kiện hành lý.', 4),
(4979, 678, 'LISTENING', NULL, '係員', '重さを量りますので、こちらに載せてください。', 'Tôi cân hành lý nên anh đặt lên đây ạ.', 5),
(4980, 678, 'LISTENING', NULL, 'リン', '超過していますか。', 'Có quá cân không ạ?', 6),
(4981, 678, 'LISTENING', NULL, '係員', '二キロ超えております。追加料金がかかりますが、よろしいですか。', 'Quá hai ký ạ. Sẽ mất phí phụ thu, anh thấy được không ạ?', 7),
(4982, 678, 'LISTENING', NULL, 'リン', '分かりました。搭乗口はどこですか。', 'Tôi hiểu rồi. Cửa lên máy bay ở đâu ạ?', 8),
(4983, 678, 'LISTENING', NULL, '係員', '十五番です。三十分前までにお越しください。', 'Cửa số mười lăm ạ. Xin anh đến trước ba mươi phút.', 9),
(4984, 680, 'LISTENING', NULL, 'リン', 'すみません、横浜へ行きたいんですが。', 'Xin lỗi, tôi muốn đi Yokohama ạ.', 1),
(4985, 680, 'LISTENING', NULL, '駅員', 'ここからですと、品川で乗り換えになります。', 'Từ đây thì anh phải đổi tàu ở Shinagawa ạ.', 2),
(4986, 680, 'LISTENING', NULL, 'リン', '特急と各駅停車、どちらが早いですか。', 'Tàu tốc hành và tàu thường, cái nào nhanh hơn ạ?', 3),
(4987, 680, 'LISTENING', NULL, '駅員', '特急のほうが二十分ほど早く着きます。', 'Tàu tốc hành tới sớm hơn khoảng hai mươi phút ạ.', 4),
(4988, 680, 'LISTENING', NULL, 'リン', '追加料金は要りますか。', 'Có cần trả thêm phí không ạ?', 5),
(4989, 680, 'LISTENING', NULL, '駅員', 'はい、特急券が別に必要です。', 'Có ạ, cần thêm vé tốc hành riêng.', 6),
(4990, 680, 'LISTENING', NULL, 'リン', 'では普通ので大丈夫です。何番線ですか。', 'Vậy tàu thường cũng được ạ. Ở đường ray số mấy ạ?', 7),
(4991, 680, 'LISTENING', NULL, '駅員', '三番線です。あと五分で発車します。', 'Đường ray số ba ạ. Còn năm phút nữa là chạy.', 8),
(4992, 682, 'LISTENING', NULL, 'リン', '予約したグエンです。', 'Tôi là Nguyễn, đã đặt phòng ạ.', 1),
(4993, 682, 'LISTENING', NULL, 'フロント', 'お待ちしておりました。二泊、朝食付きでございますね。', 'Chúng tôi đã chờ ngài. Hai đêm, kèm bữa sáng phải không ạ.', 2),
(4994, 682, 'LISTENING', NULL, 'リン', 'はい。朝食は何時からですか。', 'Vâng. Bữa sáng từ mấy giờ ạ?', 3),
(4995, 682, 'LISTENING', NULL, 'フロント', '七時から十時まで、二階のレストランでご用意しております。', 'Từ bảy giờ đến mười giờ, ở nhà hàng tầng hai ạ.', 4),
(4996, 682, 'LISTENING', NULL, 'リン', 'チェックアウトは何時までですか。', 'Trả phòng muộn nhất mấy giờ ạ?', 5),
(4997, 682, 'LISTENING', NULL, 'フロント', '十一時でございます。延長も承ります。', 'Mười một giờ ạ. Chúng tôi cũng nhận gia hạn.', 6),
(4998, 682, 'LISTENING', NULL, 'リン', '荷物を先に預かってもらえますか。', 'Anh giữ hành lý giúp tôi trước được không ạ?', 7),
(4999, 682, 'LISTENING', NULL, 'フロント', 'かしこまりました。こちらの札をお持ちください。', 'Vâng ạ. Xin ngài giữ thẻ này.', 8),
(5000, 684, 'LISTENING', NULL, '店員', 'ご注文はお決まりですか。', 'Quý khách đã chọn món chưa ạ?', 1);
INSERT INTO content_item (id, section_id, content_type, grammar_point_id, title, content, translated_text, order_index) VALUES
(5001, 684, 'LISTENING', NULL, 'リン', 'この定食には何が付きますか。', 'Suất cơm này gồm những gì ạ?', 2),
(5002, 684, 'LISTENING', NULL, '店員', 'ご飯とみそ汁、小鉢が二つ付きます。', 'Có cơm, canh miso và hai món nhỏ ạ.', 3),
(5003, 684, 'LISTENING', NULL, 'リン', '豚肉は入っていますか。食べられないんです。', 'Có thịt lợn không ạ? Tôi không ăn được.', 4),
(5004, 684, 'LISTENING', NULL, '店員', 'こちらは鶏肉ですので、ご安心ください。', 'Món này là thịt gà nên quý khách yên tâm ạ.', 5),
(5005, 684, 'LISTENING', NULL, 'リン', 'では、これをお願いします。辛くできますか。', 'Vậy cho tôi món này. Làm cay được không ạ?', 6),
(5006, 684, 'LISTENING', NULL, '店員', '辛口に変更できます。少々お待ちください。', 'Chúng tôi đổi sang vị cay được ạ. Xin quý khách đợi chút.', 7),
(5007, 686, 'LISTENING', NULL, 'リン', 'これ、免税になりますか。', 'Cái này được miễn thuế không ạ?', 1),
(5008, 686, 'LISTENING', NULL, '店員', '五千円以上のお買い上げで対象になります。', 'Mua từ năm nghìn yên trở lên là thuộc diện được ạ.', 2),
(5009, 686, 'LISTENING', NULL, 'リン', '今いくらですか。', 'Bây giờ là bao nhiêu ạ?', 3),
(5010, 686, 'LISTENING', NULL, '店員', '税込みで六千二百円でございます。', 'Gồm thuế là sáu nghìn hai trăm yên ạ.', 4),
(5011, 686, 'LISTENING', NULL, 'リン', 'では免税でお願いします。パスポートが要りますよね。', 'Vậy cho tôi miễn thuế ạ. Cần hộ chiếu đúng không ạ?', 5),
(5012, 686, 'LISTENING', NULL, '店員', 'はい、お預かりいたします。包装はいかがなさいますか。', 'Vâng, cho tôi mượn ạ. Quý khách có cần gói quà không ạ?', 6),
(5013, 686, 'LISTENING', NULL, 'リン', '土産なので、分けて包んでください。', 'Là quà nên anh gói riêng từng phần giúp tôi.', 7),
(5014, 686, 'LISTENING', NULL, '店員', 'かしこまりました。少々お時間をいただきます。', 'Vâng ạ. Xin quý khách cho chút thời gian.', 8),
(5015, 688, 'LISTENING', NULL, 'リン', 'すみません、美術館へはどう行けばいいですか。', 'Xin lỗi, đi tới bảo tàng mỹ thuật thế nào ạ?', 1),
(5016, 688, 'LISTENING', NULL, '通行人', 'ここをまっすぐ行って、二つ目の信号を左です。', 'Đi thẳng đây, tới đèn thứ hai thì rẽ trái.', 2),
(5017, 688, 'LISTENING', NULL, 'リン', '歩いてどのくらいですか。', 'Đi bộ khoảng bao lâu ạ?', 3),
(5018, 688, 'LISTENING', NULL, '通行人', '十分くらいかな。突き当たりに大きな時計がありますよ。', 'Chắc khoảng mười phút. Cuối đường có cái đồng hồ lớn đấy.', 4),
(5019, 688, 'LISTENING', NULL, 'リン', 'それが目印ですね。助かりました。', 'Đó là dấu mốc nhỉ. Đỡ cho tôi quá.', 5),
(5020, 688, 'LISTENING', NULL, '通行人', 'いえいえ。今日は休館日じゃないといいけど。', 'Không có gì. Mong hôm nay không phải ngày đóng cửa.', 6),
(5021, 688, 'LISTENING', NULL, 'リン', 'え、確認したほうがいいですね。ありがとうございます。', 'Ơ, nên kiểm tra lại nhỉ. Cảm ơn bác ạ.', 7),
(5022, 690, 'LISTENING', NULL, 'リン', '電車に鞄を忘れてしまったんですが。', 'Tôi lỡ để quên túi trên tàu ạ.', 1),
(5023, 690, 'LISTENING', NULL, '駅員', '何時ごろの、どの路線でしょうか。', 'Khoảng mấy giờ, tuyến nào ạ?', 2),
(5024, 690, 'LISTENING', NULL, 'リン', '三時ごろ、山手線です。黒いリュックです。', 'Khoảng ba giờ, tuyến Yamanote. Là ba lô màu đen.', 3),
(5025, 690, 'LISTENING', NULL, '駅員', '中身で分かるものはございますか。', 'Có thứ gì bên trong để nhận dạng không ạ?', 4),
(5026, 690, 'LISTENING', NULL, 'リン', 'ノートパソコンと、名刺入れが入っています。', 'Có máy tính xách tay và hộp danh thiếp ạ.', 5),
(5027, 690, 'LISTENING', NULL, '駅員', 'お調べしますので、こちらの用紙にご記入ください。', 'Tôi sẽ tra giúp, xin anh điền vào tờ này.', 6),
(5028, 690, 'LISTENING', NULL, 'リン', '見つかったらどう連絡がありますか。', 'Nếu tìm thấy thì báo cho tôi thế nào ạ?', 7),
(5029, 690, 'LISTENING', NULL, '駅員', 'お電話を差し上げます。数日かかる場合もございます。', 'Chúng tôi sẽ gọi điện. Cũng có trường hợp mất vài ngày ạ.', 8),
(5030, 692, 'LISTENING', NULL, 'リン', 'すみません、少し具合が悪くて。', 'Xin lỗi, tôi thấy hơi khó chịu trong người.', 1),
(5031, 692, 'LISTENING', NULL, 'フロント', '大丈夫ですか。どのような症状でしょうか。', 'Ngài không sao chứ? Triệu chứng thế nào ạ?', 2),
(5032, 692, 'LISTENING', NULL, 'リン', '熱があって、頭が痛いんです。', 'Tôi bị sốt và đau đầu ạ.', 3),
(5033, 692, 'LISTENING', NULL, 'フロント', '近くの病院をお調べしましょうか。', 'Để tôi tra bệnh viện gần đây giúp ngài nhé?', 4),
(5034, 692, 'LISTENING', NULL, 'リン', 'お願いします。日本語があまり分からなくて。', 'Nhờ chị ạ. Tôi không rành tiếng Nhật lắm.', 5),
(5035, 692, 'LISTENING', NULL, 'フロント', '英語が通じる医院がございます。予約を取りましょうか。', 'Có phòng khám nói được tiếng Anh ạ. Tôi đặt hẹn nhé?', 6),
(5036, 692, 'LISTENING', NULL, 'リン', 'ありがとうございます。保険は使えますか。', 'Cảm ơn chị. Bảo hiểm dùng được không ạ?', 7),
(5037, 692, 'LISTENING', NULL, 'フロント', '旅行保険の書類をお持ちでしたら、窓口でご提示ください。', 'Nếu ngài có giấy tờ bảo hiểm du lịch thì xuất trình ở quầy ạ.', 8),
(5038, 694, 'READING', NULL, 'Danh sách từ vựng', '17 từ thuộc nhóm Nhà cửa.', NULL, 1),
(5039, 695, 'READING', NULL, 'Danh sách từ vựng', '15 từ thuộc nhóm Đi chợ & bữa ăn.', NULL, 1),
(5040, 696, 'READING', NULL, 'Danh sách từ vựng', '15 từ thuộc nhóm Hành chính & ngân hàng.', NULL, 1),
(5041, 697, 'READING', NULL, 'Danh sách từ vựng', '14 từ thuộc nhóm Sức khoẻ & bệnh viện.', NULL, 1),
(5042, 698, 'READING', NULL, 'Danh sách từ vựng', '14 từ thuộc nhóm Trường học & học tập.', NULL, 1),
(5043, 699, 'READING', NULL, 'Danh sách từ vựng', '13 từ thuộc nhóm Quan hệ xã hội.', NULL, 1),
(5044, 700, 'READING', NULL, 'Danh sách từ vựng', '12 từ thuộc nhóm Thời gian & thời tiết.', NULL, 1),
(5045, 701, 'LISTENING', NULL, 'リン', '初期費用は全部でいくらになりますか。', 'Chi phí ban đầu tổng cộng là bao nhiêu ạ?', 1),
(5046, 701, 'LISTENING', NULL, '不動産', '家賃、敷金一か月、礼金なしで、合計十四万円ほどです。', 'Tiền thuê, đặt cọc một tháng, không tiền lễ, tổng khoảng mười bốn vạn ạ.', 2),
(5047, 701, 'LISTENING', NULL, 'リン', '礼金がないのは助かります。共益費は別ですか。', 'Không có tiền lễ thì đỡ quá. Phí quản lý tính riêng ạ?', 3),
(5048, 701, 'LISTENING', NULL, '不動産', 'はい、月三千円が別途かかります。', 'Vâng, mỗi tháng thêm ba nghìn yên ạ.', 4),
(5049, 701, 'LISTENING', NULL, 'リン', '日当たりはどうですか。', 'Phòng có nắng không ạ?', 5),
(5050, 701, 'LISTENING', NULL, '不動産', '南向きですので、昼間は明るいですよ。', 'Hướng nam nên ban ngày sáng lắm ạ.', 6),
(5051, 701, 'LISTENING', NULL, 'リン', '騒音は気になりませんか。', 'Có ồn không ạ?', 7),
(5052, 701, 'LISTENING', NULL, '不動産', '大通りから離れていますので、静かなほうです。', 'Xa đường lớn nên thuộc loại yên tĩnh ạ.', 8),
(5053, 703, 'LISTENING', NULL, 'リン', 'この空き缶はどのごみですか。', 'Cái lon rỗng này thuộc loại rác nào ạ?', 1),
(5054, 703, 'LISTENING', NULL, '近所の人', 'それは資源ごみ。水曜の朝に出すのよ。', 'Cái đó là rác tái chế. Đem ra sáng thứ tư nhé.', 2),
(5055, 703, 'LISTENING', NULL, 'リン', '洗ってから出すんですか。', 'Phải rửa rồi mới đem ra ạ?', 3),
(5056, 703, 'LISTENING', NULL, '近所の人', 'そう。中をゆすいで、つぶさずにね。', 'Đúng. Tráng bên trong, và đừng bóp bẹp nhé.', 4),
(5057, 703, 'LISTENING', NULL, 'リン', '古い椅子はどうすればいいですか。', 'Cái ghế cũ thì làm thế nào ạ?', 5),
(5058, 703, 'LISTENING', NULL, '近所の人', 'あれは粗大ごみ。市役所に申し込んで、シールを買うの。', 'Cái đó là rác cồng kềnh. Đăng ký với thành phố rồi mua tem.', 6),
(5059, 703, 'LISTENING', NULL, 'リン', '手続きが要るんですね。教えてくださってありがとうございます。', 'Phải làm thủ tục nhỉ. Cảm ơn cô đã chỉ cho cháu.', 7),
(5060, 705, 'LISTENING', NULL, 'リン', 'すみません、この惣菜の消費期限はいつまでですか。', 'Xin lỗi, món ăn sẵn này hạn dùng đến bao giờ ạ?', 1),
(5061, 705, 'LISTENING', NULL, '店員', '本日中でございます。夕方から半額になります。', 'Trong hôm nay ạ. Từ chiều sẽ giảm nửa giá.', 2),
(5062, 705, 'LISTENING', NULL, 'リン', '何時ごろからですか。', 'Khoảng mấy giờ ạ?', 3),
(5063, 705, 'LISTENING', NULL, '店員', '七時過ぎには値引きシールを貼ります。', 'Sau bảy giờ chúng tôi dán tem giảm giá ạ.', 4),
(5064, 705, 'LISTENING', NULL, 'リン', '分かりました。牛乳はどこにありますか。', 'Tôi hiểu rồi. Sữa ở đâu ạ?', 5),
(5065, 705, 'LISTENING', NULL, '店員', '一番奥の冷蔵コーナーです。ご案内しましょうか。', 'Ở khu tủ lạnh trong cùng ạ. Để tôi dẫn đi nhé?', 6),
(5066, 705, 'LISTENING', NULL, 'リン', '大丈夫です。ありがとうございます。', 'Không cần đâu ạ. Cảm ơn anh.', 7),
(5067, 707, 'LISTENING', NULL, 'リン', '振込をしたいのですが。', 'Tôi muốn chuyển khoản ạ.', 1),
(5068, 707, 'LISTENING', NULL, '行員', '他行宛てでしょうか。', 'Là chuyển sang ngân hàng khác phải không ạ?', 2),
(5069, 707, 'LISTENING', NULL, 'リン', 'はい。手数料はいくらかかりますか。', 'Vâng. Phí là bao nhiêu ạ?', 3),
(5070, 707, 'LISTENING', NULL, '行員', '窓口ですと四百四十円、ATMですと二百二十円です。', 'Ở quầy là bốn trăm bốn mươi yên, ở máy ATM là hai trăm hai mươi yên ạ.', 4),
(5071, 707, 'LISTENING', NULL, 'リン', '思ったより違うんですね。ATMでもできますか。', 'Chênh nhiều hơn tôi tưởng nhỉ. Ở máy ATM cũng làm được ạ?', 5),
(5072, 707, 'LISTENING', NULL, '行員', 'はい。ただ、通帳とキャッシュカードが必要です。', 'Vâng ạ. Chỉ có điều cần sổ ngân hàng và thẻ.', 6),
(5073, 707, 'LISTENING', NULL, 'リン', '持っています。操作を教えていただけますか。', 'Tôi có mang. Chị hướng dẫn thao tác giúp tôi được không ạ?', 7),
(5074, 707, 'LISTENING', NULL, '行員', 'もちろんです。ご案内いたします。', 'Tất nhiên rồi ạ. Tôi xin dẫn ngài đi.', 8),
(5075, 709, 'LISTENING', NULL, '医師', '今日はどうされましたか。', 'Hôm nay chị thấy sao?', 1),
(5076, 709, 'LISTENING', NULL, 'リン', '三日前から咳が止まらなくて、夜眠れないんです。', 'Từ ba hôm trước tôi ho không dứt, đêm không ngủ được ạ.', 2),
(5077, 709, 'LISTENING', NULL, '医師', '熱は測りましたか。', 'Chị đo nhiệt độ chưa?', 3),
(5078, 709, 'LISTENING', NULL, 'リン', '朝は三十七度五分でした。', 'Sáng nay là ba mươi bảy độ rưỡi ạ.', 4),
(5079, 709, 'LISTENING', NULL, '医師', '喉を見せてください。少し赤いですね。', 'Cho tôi xem họng nào. Hơi đỏ nhỉ.', 5),
(5080, 709, 'LISTENING', NULL, 'リン', '薬をもらえますか。仕事があるので早く治したいです。', 'Tôi xin thuốc được không ạ? Tôi có việc nên muốn khỏi sớm.', 6),
(5081, 709, 'LISTENING', NULL, '医師', '咳止めを五日分出します。眠くなる成分が入っています。', 'Tôi kê thuốc ho năm ngày. Trong thuốc có thành phần gây buồn ngủ.', 7),
(5082, 709, 'LISTENING', NULL, 'リン', '分かりました。運転は避けます。', 'Tôi hiểu rồi. Tôi sẽ tránh lái xe.', 8),
(5083, 711, 'LISTENING', NULL, 'リン', '不在票が入っていたので、再配達をお願いしたいのですが。', 'Tôi nhận được phiếu báo vắng nên muốn xin giao lại ạ.', 1),
(5084, 711, 'LISTENING', NULL, '係員', '伝票番号をお願いいたします。', 'Xin cho tôi mã vận đơn ạ.', 2),
(5085, 711, 'LISTENING', NULL, 'リン', 'はい、一二三四の五六七八です。', 'Vâng, là một hai ba bốn năm sáu bảy tám ạ.', 3),
(5086, 711, 'LISTENING', NULL, '係員', '本日の夜間でしたらお届けできます。', 'Nếu là buổi tối hôm nay thì chúng tôi giao được ạ.', 4),
(5087, 711, 'LISTENING', NULL, 'リン', '何時から何時までですか。', 'Từ mấy giờ đến mấy giờ ạ?', 5),
(5088, 711, 'LISTENING', NULL, '係員', '七時から九時の間でございます。', 'Trong khoảng bảy giờ đến chín giờ ạ.', 6),
(5089, 711, 'LISTENING', NULL, 'リン', 'その時間で大丈夫です。呼び鈴を鳴らしてください。', 'Khung giờ đó được ạ. Anh bấm chuông giúp tôi nhé.', 7),
(5090, 711, 'LISTENING', NULL, '係員', '承知いたしました。よろしくお願いいたします。', 'Tôi đã rõ ạ. Xin cảm ơn quý khách.', 8),
(5091, 713, 'LISTENING', NULL, 'リン', 'おはようございます。二年のグエンです。', 'Chào cô ạ. Em là Nguyễn lớp hai ạ.', 1),
(5092, 713, 'LISTENING', NULL, '事務', 'どうしましたか。', 'Có chuyện gì thế em?', 2),
(5093, 713, 'LISTENING', NULL, 'リン', '熱があるので、今日は休ませていただきたいです。', 'Em bị sốt nên hôm nay xin phép nghỉ ạ.', 3),
(5094, 713, 'LISTENING', NULL, '事務', '分かりました。病院には行きましたか。', 'Cô hiểu rồi. Em đi bệnh viện chưa?', 4),
(5095, 713, 'LISTENING', NULL, 'リン', '午後に行く予定です。', 'Chiều nay em định đi ạ.', 5),
(5096, 713, 'LISTENING', NULL, '事務', '診断書が出たら持ってきてください。', 'Có giấy khám thì em mang đến nhé.', 6),
(5097, 713, 'LISTENING', NULL, 'リン', 'はい。今日の課題はどうすればいいですか。', 'Vâng ạ. Bài tập hôm nay em làm thế nào ạ?', 7),
(5098, 713, 'LISTENING', NULL, '事務', 'クラスの掲示板に出ますので、確認してください。', 'Sẽ đăng trên bảng tin lớp, em kiểm tra nhé.', 8),
(5099, 715, 'LISTENING', NULL, 'リン', '昨日は引っ越しで騒がしくて、すみませんでした。', 'Hôm qua chuyển nhà ồn ào, cháu xin lỗi ạ.', 1),
(5100, 715, 'LISTENING', NULL, '隣人', 'いえいえ、お互い様ですよ。', 'Không sao đâu, ai cũng có lúc thế mà.', 2),
(5101, 715, 'LISTENING', NULL, 'リン', 'これ、少しですがどうぞ。', 'Đây, chút quà nhỏ, cô nhận cho ạ.', 3),
(5102, 715, 'LISTENING', NULL, '隣人', 'あら、気を使わせてしまって。ありがとう。', 'Ôi, làm cháu phải bận tâm rồi. Cảm ơn nhé.', 4),
(5103, 715, 'LISTENING', NULL, 'リン', 'ごみ出しのことなど、また教えてください。', 'Chuyện đổ rác các thứ, cô chỉ thêm cho cháu với ạ.', 5),
(5104, 715, 'LISTENING', NULL, '隣人', 'いつでも聞いてね。町内会の集まりも月に一度あるのよ。', 'Cứ hỏi bất cứ lúc nào. Tổ dân phố mỗi tháng họp một lần đấy.', 6),
(5105, 715, 'LISTENING', NULL, 'リン', '参加したほうがいいでしょうか。', 'Cháu có nên tham gia không ạ?', 7),
(5106, 715, 'LISTENING', NULL, '隣人', '顔を覚えてもらえるから、一度来てみるといいわ。', 'Để mọi người nhớ mặt, thử đến một lần là tốt đấy.', 8);
